def _normalize_maintenance_mode(raw_mode, *, raw_scope=""):
    mode = str(raw_mode or "").strip().lower()
    scope = str(raw_scope or "").strip().lower()
    if mode in {"", "0", "off", "false", "no"}:
        return "off"
    if mode in {"partial", "full"}:
        return mode
    if mode in {"1", "true", "yes", "on"}:
        return scope if scope in {"partial", "full"} else "partial"
    return "off"


def _maintenance_env_override_mode():
    raw_mode = os.getenv("MAINTENANCE_MODE")
    raw_scope = os.getenv("MAINTENANCE_SCOPE")
    if raw_mode is None:
        return None
    if str(raw_mode).strip() == "":
        return None
    override_mode = _normalize_maintenance_mode(raw_mode, raw_scope=raw_scope)
    if override_mode in {"partial", "full"}:
        return override_mode
    return None


def _seed_maintenance_state(db):
    db.execute(
        """
        INSERT INTO maintenance_state (id, mode, updated_at, updated_by_user_id)
        VALUES (1, 'off', 0, NULL)
        ON CONFLICT(id) DO NOTHING
        """
    )


def _maintenance_state_row(db):
    _seed_maintenance_state(db)
    row = db.execute(
        """
        SELECT ms.mode, ms.updated_at, ms.updated_by_user_id,
               u.username, u.display_name, u.is_admin
        FROM maintenance_state ms
        LEFT JOIN users u ON u.id = ms.updated_by_user_id
        WHERE ms.id = 1
        LIMIT 1
        """
    ).fetchone()
    mode = _normalize_maintenance_mode(row["mode"] if row else "off")
    updated_by_label = ""
    if row and row["updated_by_user_id"]:
        updated_by_label = _display_username(
            row["username"],
            display_name=(row["display_name"] if "display_name" in row.keys() else None),
            is_admin=bool(int(row["is_admin"] or 0)) if "is_admin" in row.keys() else False,
        )
    return {
        "mode": mode,
        "updated_at": int(row["updated_at"] or 0) if row else 0,
        "updated_text": (_format_jst_ts(row["updated_at"]) if row and int(row["updated_at"] or 0) > 0 else "未変更"),
        "updated_by_user_id": int(row["updated_by_user_id"]) if row and row["updated_by_user_id"] else None,
        "updated_by_label": updated_by_label,
    }


def _maintenance_mode(db=None):
    override_mode = _maintenance_env_override_mode()
    if override_mode in {"partial", "full"}:
        return override_mode
    if db is None:
        if not has_request_context():
            return "off"
        db = get_db()
    return _maintenance_state_row(db)["mode"]


def _is_maintenance_mode():
    return _maintenance_mode() != "off"


def _maintenance_control_view(db):
    stored = _maintenance_state_row(db)
    override_mode = _maintenance_env_override_mode()
    effective_mode = override_mode or stored["mode"]
    return {
        "effective_mode": effective_mode,
        "effective_label": MAINTENANCE_MODE_LABELS.get(effective_mode, MAINTENANCE_MODE_LABELS["off"]),
        "stored_mode": stored["mode"],
        "stored_label": MAINTENANCE_MODE_LABELS.get(stored["mode"], MAINTENANCE_MODE_LABELS["off"]),
        "stored_updated_text": stored["updated_text"],
        "stored_updated_by_label": stored["updated_by_label"] or "未設定",
        "is_env_override": bool(override_mode),
        "env_override_mode": override_mode,
        "env_override_label": MAINTENANCE_MODE_LABELS.get(override_mode or "", ""),
        "mode_options": list(MAINTENANCE_MODE_OPTION_ROWS),
    }


def _maintenance_banner_text():
    return "現在アップデート中です。一部機能を停止しています。閲覧は可能ですが、出撃・育成・購入などの操作は一時停止中です。"


def _maintenance_is_admin_viewer():
    user_id = session.get("user_id")
    if not user_id:
        return False
    try:
        return _is_admin_user(int(user_id))
    except Exception:
        app.logger.exception("maintenance.admin_lookup_failed user_id=%s", user_id)
        return False


def _maintenance_should_allow_full_request():
    if request.endpoint == "static" or request.path.startswith("/static/"):
        return True
    if request.endpoint in MAINTENANCE_FULL_ALLOWED_ENDPOINTS:
        if request.endpoint in {"login", "register", "index"} and request.method not in MAINTENANCE_SAFE_METHODS:
            return False
        return True
    return False


def _maintenance_should_block_partial_request():
    if request.method in MAINTENANCE_SAFE_METHODS:
        return False
    endpoint = request.endpoint or ""
    if endpoint in MAINTENANCE_PARTIAL_ALLOWED_MUTATION_ENDPOINTS:
        return False
    return True


def _maintenance_block_response(mode):
    status_code = 503
    return render_template("maintenance.html", maintenance_page_mode=mode), status_code


def _audit_maintenance_block(db, mode):
    user_id = session.get("user_id")
    audit_log(
        db,
        AUDIT_EVENT_TYPES["SYSTEM_MAINTENANCE_BLOCK"],
        user_id=user_id,
        request_id=getattr(g, "request_id", None),
        action_key=(request.endpoint or "unknown"),
        payload={
            "path": request.path,
            "method": request.method,
            "mode": str(mode or "off"),
            "endpoint": request.endpoint or "unknown",
            "user_id": int(user_id) if user_id else None,
        },
        ip=request.remote_addr,
    )


def _jst_day_key_to_bounds(day_key):
    day_dt = datetime.strptime(day_key, "%Y-%m-%d").replace(tzinfo=JST)
    start_ts = int(day_dt.timestamp())
    end_ts = int((day_dt + timedelta(days=1)).timestamp())
    return start_ts, end_ts


def _collect_daily_metrics(db, day_key):
    start_ts, end_ts = _jst_day_key_to_bounds(day_key)
    dau_count = db.execute(
        """
        SELECT COUNT(DISTINCT user_id) AS c
        FROM world_events_log
        WHERE user_id IS NOT NULL
          AND created_at >= ? AND created_at < ?
        """,
        (start_ts, end_ts),
    ).fetchone()["c"]
    new_users = db.execute(
        "SELECT COUNT(*) AS c FROM users WHERE created_at >= ? AND created_at < ?",
        (start_ts, end_ts),
    ).fetchone()["c"]
    explore_count = db.execute(
        "SELECT COUNT(*) AS c FROM world_events_log WHERE event_type = ? AND created_at >= ? AND created_at < ?",
        (AUDIT_EVENT_TYPES["EXPLORE_END"], start_ts, end_ts),
    ).fetchone()["c"]
    boss_encounters = db.execute(
        "SELECT COUNT(*) AS c FROM world_events_log WHERE event_type = ? AND created_at >= ? AND created_at < ?",
        (AUDIT_EVENT_TYPES["BOSS_ENCOUNTER"], start_ts, end_ts),
    ).fetchone()["c"]
    boss_defeats = db.execute(
        "SELECT COUNT(*) AS c FROM world_events_log WHERE event_type = ? AND created_at >= ? AND created_at < ?",
        (AUDIT_EVENT_TYPES["BOSS_DEFEAT"], start_ts, end_ts),
    ).fetchone()["c"]
    fuse_count = db.execute(
        "SELECT COUNT(*) AS c FROM world_events_log WHERE event_type = ? AND created_at >= ? AND created_at < ?",
        (AUDIT_EVENT_TYPES["FUSE"], start_ts, end_ts),
    ).fetchone()["c"]
    row = {
        "day_key": day_key,
        "dau_count": int(dau_count or 0),
        "new_users": int(new_users or 0),
        "explore_count": int(explore_count or 0),
        "boss_encounters": int(boss_encounters or 0),
        "boss_defeats": int(boss_defeats or 0),
        "fuse_count": int(fuse_count or 0),
    }
    db.execute(
        """
        INSERT INTO daily_metrics
        (day_key, dau_count, new_users, explore_count, boss_encounters, boss_defeats, fuse_count)
        VALUES (?, ?, ?, ?, ?, ?, ?)
        ON CONFLICT(day_key) DO UPDATE SET
            dau_count = excluded.dau_count,
            new_users = excluded.new_users,
            explore_count = excluded.explore_count,
            boss_encounters = excluded.boss_encounters,
            boss_defeats = excluded.boss_defeats,
            fuse_count = excluded.fuse_count
        """,
        (
            row["day_key"],
            row["dau_count"],
            row["new_users"],
            row["explore_count"],
            row["boss_encounters"],
            row["boss_defeats"],
            row["fuse_count"],
        ),
    )
    return row


def _collect_recent_daily_metrics(db, days=7):
    rows = []
    today = datetime.now(JST).date()
    for i in range(max(1, int(days))):
        day_key = (today - timedelta(days=i)).strftime("%Y-%m-%d")
        rows.append(_collect_daily_metrics(db, day_key))
    rows.sort(key=lambda x: x["day_key"], reverse=True)
    return rows


ADMIN_METRICS_FUNNEL_DAYS = 7
ADMIN_METRICS_NEW_USER_DAYS = 7
ADMIN_METRICS_REVISIT_COHORT_DAYS = 30
ADMIN_METRICS_FUNNEL_STEPS = (
    {"key": "login", "label": "ログイン", "accent": "purple"},
    {"key": "home_view", "label": "ホーム表示", "accent": "purple"},
    {"key": "explore_start", "label": "出撃開始", "accent": "cyan"},
    {"key": "explore_end", "label": "探索完了", "accent": "cyan"},
    {"key": "strengthen", "label": "パーツ強化", "accent": "green"},
    {"key": "evolve", "label": "進化", "accent": "green"},
    {"key": "build", "label": "編成完了", "accent": "gold"},
    {"key": "boss_encounter", "label": "ボス遭遇", "accent": "gold"},
    {"key": "boss_defeat", "label": "ボス撃破", "accent": "gold"},
    {"key": "next_day_return", "label": "翌日再訪", "accent": "purple"},
)
ADMIN_METRICS_FUNNEL_STEP_LABELS = {
    item["key"]: item["label"]
    for item in ADMIN_METRICS_FUNNEL_STEPS
}
ADMIN_METRICS_FUNNEL_STEP_ACCENTS = {
    item["key"]: item["accent"]
    for item in ADMIN_METRICS_FUNNEL_STEPS
}
ADMIN_METRICS_WORLD_EVENT_TO_STEP = {
    AUDIT_EVENT_TYPES["HOME_VIEW"]: "home_view",
    AUDIT_EVENT_TYPES["EXPLORE_START"]: "explore_start",
    AUDIT_EVENT_TYPES["EXPLORE_END"]: "explore_end",
    AUDIT_EVENT_TYPES["FUSE"]: "strengthen",
    AUDIT_EVENT_TYPES["PART_EVOLVE"]: "evolve",
    AUDIT_EVENT_TYPES["BUILD_CONFIRM"]: "build",
    AUDIT_EVENT_TYPES["BOSS_ENCOUNTER"]: "boss_encounter",
    AUDIT_EVENT_TYPES["BOSS_DEFEAT"]: "boss_defeat",
}


def _parse_login_log_created_at(value):
    raw = str(value or "").strip()
    if not raw:
        return 0
    try:
        return int(datetime.strptime(raw, "%Y-%m-%d %H:%M:%S").replace(tzinfo=JST).timestamp())
    except ValueError:
        try:
            return int(float(raw))
        except (TypeError, ValueError):
            return 0


def _jst_day_key_from_ts(ts):
    return datetime.fromtimestamp(int(ts), JST).strftime("%Y-%m-%d")


def _jst_date_from_ts(ts):
    return datetime.fromtimestamp(int(ts), JST).date()


def _has_next_day_return(day_set, *, window_start=None):
    if not day_set:
        return False
    for day in sorted(day_set):
        next_day = day + timedelta(days=1)
        if next_day in day_set:
            if window_start is None or next_day >= window_start:
                return True
    return False


def _admin_behavior_events(db, since_ts):
    since_ts = int(since_ts or 0)
    since_login_text = datetime.fromtimestamp(since_ts, JST).strftime("%Y-%m-%d %H:%M:%S")
    items = []

    login_rows = db.execute(
        """
        SELECT id, user_id, created_at
        FROM login_logs
        WHERE user_id IS NOT NULL
          AND created_at >= ?
        ORDER BY created_at ASC, id ASC
        """,
        (since_login_text,),
    ).fetchall()
    for row in login_rows:
        created_ts = _parse_login_log_created_at(row["created_at"])
        if created_ts < since_ts:
            continue
        items.append(
            {
                "user_id": int(row["user_id"]),
                "ts": int(created_ts),
                "step_key": "login",
            }
        )

    tracked_event_types = tuple(ADMIN_METRICS_WORLD_EVENT_TO_STEP.keys())
    audit_rows = db.execute(
        f"""
        SELECT id, user_id, created_at, event_type
        FROM world_events_log
        WHERE user_id IS NOT NULL
          AND created_at >= ?
          AND event_type IN ({",".join(["?"] * len(tracked_event_types))})
        ORDER BY created_at ASC, id ASC
        """,
        (since_ts, *tracked_event_types),
    ).fetchall()
    for row in audit_rows:
        step_key = ADMIN_METRICS_WORLD_EVENT_TO_STEP.get(str(row["event_type"] or ""))
        if not step_key:
            continue
        items.append(
            {
                "user_id": int(row["user_id"]),
                "ts": int(row["created_at"] or 0),
                "step_key": step_key,
            }
        )

    items.sort(key=lambda item: (int(item["ts"]), str(item["step_key"]), int(item["user_id"])))
    return items


def _admin_metrics_behavior_snapshot(db, *, window_days=ADMIN_METRICS_FUNNEL_DAYS):
    window_days = max(3, int(window_days or ADMIN_METRICS_FUNNEL_DAYS))
    now_ts = _now_ts()
    window_start_ts = int(now_ts - (window_days * 86400))
    lookback_days = max(
        int(window_days) + 1,
        int(ADMIN_METRICS_NEW_USER_DAYS) + 2,
        int(ADMIN_METRICS_REVISIT_COHORT_DAYS) + 4,
    )
    all_events = _admin_behavior_events(db, now_ts - lookback_days * 86400)
    events_in_window = [item for item in all_events if int(item["ts"]) >= window_start_ts]

    funnel_sets = {item["key"]: set() for item in ADMIN_METRICS_FUNNEL_STEPS}
    activity_days_by_user = {}
    for event in events_in_window:
        user_id = int(event["user_id"])
        step_key = str(event["step_key"])
        if step_key in funnel_sets:
            funnel_sets[step_key].add(user_id)
        activity_days_by_user.setdefault(user_id, set()).add(_jst_date_from_ts(event["ts"]))

    window_start_day = _jst_date_from_ts(window_start_ts)
    next_day_return_users = {
        int(user_id)
        for user_id, day_set in activity_days_by_user.items()
        if _has_next_day_return(day_set, window_start=window_start_day)
    }
    funnel_sets["next_day_return"] = next_day_return_users

    funnel_base = max(1, len(funnel_sets["login"]), len(funnel_sets["home_view"]))
    funnel_rows = []
    for item in ADMIN_METRICS_FUNNEL_STEPS:
        key = item["key"]
        count = len(funnel_sets.get(key, set()))
        funnel_rows.append(
            {
                "key": key,
                "label": item["label"],
                "count": int(count),
                "pct_of_base": (float(count) / float(funnel_base)) * 100.0,
                "accent": item["accent"],
            }
        )
    funnel_max = max((item["count"] for item in funnel_rows), default=0)
    for item in funnel_rows:
        item["bar_pct"] = (float(item["count"]) / float(funnel_max) * 100.0) if funnel_max else 0.0

    last_action_by_user = {}
    for event in events_in_window:
        user_id = int(event["user_id"])
        prev = last_action_by_user.get(user_id)
        if (not prev) or int(event["ts"]) >= int(prev["ts"]):
            last_action_by_user[user_id] = event
    dropoff_counts = Counter(
        str(item["step_key"])
        for item in last_action_by_user.values()
        if str(item["step_key"])
    )
    dropoff_rows = []
    for item in ADMIN_METRICS_FUNNEL_STEPS:
        key = item["key"]
        count = int(dropoff_counts.get(key, 0))
        if count <= 0:
            continue
        dropoff_rows.append(
            {
                "key": key,
                "label": item["label"],
                "count": count,
                "accent": item["accent"],
            }
        )
    dropoff_rows.sort(key=lambda item: item["count"], reverse=True)
    dropoff_max = max((item["count"] for item in dropoff_rows), default=0)
    dropoff_total = max(1, sum(int(item["count"]) for item in dropoff_rows))
    for item in dropoff_rows:
        item["bar_pct"] = (float(item["count"]) / float(dropoff_max) * 100.0) if dropoff_max else 0.0
        item["pct"] = (float(item["count"]) / float(dropoff_total)) * 100.0

    new_user_since_ts = int(now_ts - (ADMIN_METRICS_NEW_USER_DAYS * 86400))
    new_user_rows = db.execute(
        """
        SELECT id, created_at
        FROM users
        WHERE created_at >= ?
        ORDER BY created_at DESC, id DESC
        """,
        (new_user_since_ts,),
    ).fetchall()
    new_user_ids = {int(row["id"]) for row in new_user_rows}
    new_user_events_by_user = {}
    for event in all_events:
        user_id = int(event["user_id"])
        if user_id not in new_user_ids:
            continue
        new_user_events_by_user.setdefault(user_id, []).append(event)

    new_user_funnel_sets = {item["key"]: set() for item in ADMIN_METRICS_FUNNEL_STEPS}
    new_user_next_day_eligible = 0
    today_jst = datetime.fromtimestamp(now_ts, JST).date()
    for row in new_user_rows:
        user_id = int(row["id"])
        created_ts = int(row["created_at"] or 0)
        day_start_ts, day_end_ts = _jst_day_bounds(created_ts)
        created_day = _jst_date_from_ts(created_ts)
        user_events = new_user_events_by_user.get(user_id, [])
        user_days = set()
        for event in user_events:
            event_ts = int(event["ts"])
            user_days.add(_jst_date_from_ts(event_ts))
            if day_start_ts <= event_ts < day_end_ts:
                step_key = str(event["step_key"])
                if step_key in new_user_funnel_sets:
                    new_user_funnel_sets[step_key].add(user_id)
        if created_day + timedelta(days=1) <= today_jst:
            new_user_next_day_eligible += 1
            if (created_day + timedelta(days=1)) in user_days:
                new_user_funnel_sets["next_day_return"].add(user_id)

    new_user_base = max(1, len(new_user_rows))
    new_user_funnel_rows = []
    for item in ADMIN_METRICS_FUNNEL_STEPS:
        key = item["key"]
        count = len(new_user_funnel_sets.get(key, set()))
        pct_base = new_user_next_day_eligible if key == "next_day_return" and new_user_next_day_eligible > 0 else new_user_base
        new_user_funnel_rows.append(
            {
                "key": key,
                "label": item["label"],
                "count": int(count),
                "pct_of_new_users": (float(count) / float(max(1, pct_base))) * 100.0,
                "accent": item["accent"],
            }
        )
    new_user_funnel_max = max((item["count"] for item in new_user_funnel_rows), default=0)
    for item in new_user_funnel_rows:
        item["bar_pct"] = (float(item["count"]) / float(new_user_funnel_max) * 100.0) if new_user_funnel_max else 0.0

    revisit_since_ts = int(now_ts - (ADMIN_METRICS_REVISIT_COHORT_DAYS * 86400))
    revisit_users = db.execute(
        """
        SELECT id, created_at
        FROM users
        WHERE created_at >= ?
        ORDER BY created_at DESC, id DESC
        """,
        (revisit_since_ts,),
    ).fetchall()
    activity_days_full = {}
    for event in all_events:
        activity_days_full.setdefault(int(event["user_id"]), set()).add(_jst_date_from_ts(event["ts"]))

    d1_eligible = 0
    d1_returned = 0
    d3_eligible = 0
    d3_returned = 0
    for row in revisit_users:
        user_id = int(row["id"])
        created_day = _jst_date_from_ts(int(row["created_at"] or 0))
        user_days = activity_days_full.get(user_id, set())
        d1_day = created_day + timedelta(days=1)
        d3_day = created_day + timedelta(days=3)
        if d1_day <= today_jst:
            d1_eligible += 1
            if d1_day in user_days:
                d1_returned += 1
        if d3_day <= today_jst:
            d3_eligible += 1
            if d3_day in user_days:
                d3_returned += 1

    return {
        "window_days": int(window_days),
        "funnel_rows": funnel_rows,
        "dropoff_rows": dropoff_rows,
        "dropoff_total": int(len(last_action_by_user)),
        "new_user_window_days": int(ADMIN_METRICS_NEW_USER_DAYS),
        "new_user_count": int(len(new_user_rows)),
        "new_user_next_day_eligible": int(new_user_next_day_eligible),
        "new_user_funnel_rows": new_user_funnel_rows,
        "revisit_cohort_days": int(ADMIN_METRICS_REVISIT_COHORT_DAYS),
        "d1": {
            "eligible": int(d1_eligible),
            "returned": int(d1_returned),
            "rate_pct": (float(d1_returned) / float(max(1, d1_eligible))) * 100.0,
        },
        "d3": {
            "eligible": int(d3_eligible),
            "returned": int(d3_returned),
            "rate_pct": (float(d3_returned) / float(max(1, d3_eligible))) * 100.0,
        },
    }


def _admin_progression_snapshot(db):
    user_rows = db.execute(
        """
        SELECT id, username, display_name, is_admin, is_banned, created_at, last_seen_at, max_unlocked_layer
        FROM users
        ORDER BY is_admin ASC, id ASC
        """
    ).fetchall()
    progression_rows_by_user = {}
    for row in user_rows:
        user_id = int(row["id"])
        progression_rows_by_user[user_id] = {
            "user_id": user_id,
            "username": str(row["username"] or "").strip(),
            "display_username": _display_username_for_user_row(db, row),
            "is_admin": bool(int(row["is_admin"] or 0)),
            "is_banned": bool(int(row["is_banned"] or 0)),
            "created_at": int(row["created_at"] or 0),
            "last_seen_at": int(row["last_seen_at"] or 0),
            "max_unlocked_layer_field": _user_max_unlocked_layer(row),
            "max_unlocked_layer_log": 0,
            "max_explore_layer": 0,
            "furthest_area_key": None,
            "furthest_area_layer": 0,
            "furthest_area_ts": 0,
            "latest_progress_at": 0,
            "progress_event_count": 0,
            "layer2_family_sorties": 0,
            "fixed_boss_area_keys": set(),
        }

    progress_rows = db.execute(
        """
        SELECT
            user_id,
            event_type,
            COALESCE(CAST(json_extract(payload_json, '$.area_key') AS TEXT), '') AS area_key,
            LOWER(COALESCE(CAST(json_extract(payload_json, '$.boss_kind') AS TEXT), 'fixed')) AS boss_kind,
            MAX(CAST(COALESCE(json_extract(payload_json, '$.unlocked_layer'), 0) AS INTEGER)) AS max_unlocked_layer,
            MAX(created_at) AS latest_created_at,
            COUNT(*) AS event_count
        FROM world_events_log
        WHERE user_id IS NOT NULL
          AND event_type IN (?, ?)
        GROUP BY user_id, event_type, area_key, boss_kind
        ORDER BY user_id ASC
        """,
        (AUDIT_EVENT_TYPES["EXPLORE_END"], AUDIT_EVENT_TYPES["BOSS_DEFEAT"]),
    ).fetchall()

    for row in progress_rows:
        user_id = int(row["user_id"] or 0)
        item = progression_rows_by_user.get(user_id)
        if not item:
            continue
        latest_created_at = int(row["latest_created_at"] or 0)
        event_count = int(row["event_count"] or 0)
        event_type = str(row["event_type"] or "").strip()
        area_key = str(row["area_key"] or "").strip()
        item["latest_progress_at"] = max(int(item["latest_progress_at"]), latest_created_at)
        item["progress_event_count"] += event_count
        if area_key:
            area_layer = _area_layer(area_key)
            if area_layer > int(item["furthest_area_layer"]) or (
                area_layer == int(item["furthest_area_layer"]) and latest_created_at >= int(item["furthest_area_ts"])
            ):
                item["furthest_area_key"] = area_key
                item["furthest_area_layer"] = area_layer
                item["furthest_area_ts"] = latest_created_at
        if event_type == AUDIT_EVENT_TYPES["EXPLORE_END"]:
            if area_key:
                item["max_explore_layer"] = max(int(item["max_explore_layer"]), _area_layer(area_key))
                if area_key in LAYER2_FAMILY_AREA_KEYS:
                    item["layer2_family_sorties"] += event_count
            continue
        if event_type == AUDIT_EVENT_TYPES["BOSS_DEFEAT"]:
            item["max_unlocked_layer_log"] = max(int(item["max_unlocked_layer_log"]), int(row["max_unlocked_layer"] or 0))
            if area_key and str(row["boss_kind"] or "fixed") == "fixed":
                item["fixed_boss_area_keys"].add(area_key)

    progression_boss_area_by_layer = {
        1: "layer_1",
        2: "layer_2",
        3: "layer_3",
        4: LAYER4_FINAL_AREA_KEY,
        5: LAYER5_FINAL_AREA_KEY,
    }

    listed_rows = []
    analysis_rows = []
    boss_block_counts = Counter()
    stop_counts = Counter()
    for item in progression_rows_by_user.values():
        highest_layer = max(
            1,
            int(item["max_unlocked_layer_field"] or 1),
            int(item["max_unlocked_layer_log"] or 0),
            int(item["max_explore_layer"] or 0),
        )
        highest_layer = max(1, min(MAX_UNLOCKABLE_LAYER, highest_layer))
        item["highest_layer"] = int(highest_layer)
        item["highest_layer_label"] = _layer_label(highest_layer)
        default_area_key = HOME_PRIMARY_AREA_BY_LAYER.get(highest_layer)
        furthest_area_key = str(item.get("furthest_area_key") or "").strip() or str(default_area_key or "").strip()
        if furthest_area_key and _area_layer(furthest_area_key) < highest_layer and default_area_key:
            furthest_area_key = str(default_area_key)
        item["furthest_area_key"] = furthest_area_key or None
        item["furthest_area_label"] = _boss_area_label(furthest_area_key) if furthest_area_key else item["highest_layer_label"]
        last_activity_at = max(
            int(item.get("last_seen_at") or 0),
            int(item.get("latest_progress_at") or 0),
            int(item.get("created_at") or 0),
        )
        item["last_activity_at"] = int(last_activity_at)
        item["last_activity_text"] = _format_jst_ts(last_activity_at)

        fixed_boss_area_keys = item["fixed_boss_area_keys"]
        boss_blocker_layer = None
        if highest_layer == 4:
            trial_clears = sum(1 for key in LAYER4_SUBAREA_KEYS if key in fixed_boss_area_keys)
            if LAYER4_FINAL_AREA_KEY in fixed_boss_area_keys:
                boss_status = "第4層最終試験撃破済み"
            elif trial_clears < len(LAYER4_SUBAREA_KEYS):
                boss_status = f"第4層試験ボス {trial_clears}/{len(LAYER4_SUBAREA_KEYS)} 撃破"
                boss_blocker_layer = 4
            else:
                boss_status = "第4層最終試験未撃破"
                boss_blocker_layer = 4
        elif highest_layer == 5:
            trial_clears = sum(1 for key in LAYER5_SUBAREA_KEYS if key in fixed_boss_area_keys)
            if LAYER5_FINAL_AREA_KEY in fixed_boss_area_keys:
                boss_status = "第5層最終試験撃破済み"
            elif trial_clears < len(LAYER5_SUBAREA_KEYS):
                boss_status = f"第5層試験ボス {trial_clears}/{len(LAYER5_SUBAREA_KEYS)} 撃破"
                boss_blocker_layer = 5
            else:
                boss_status = "第5層最終試験未撃破"
                boss_blocker_layer = 5
        else:
            boss_area_key = progression_boss_area_by_layer.get(highest_layer)
            has_fixed_boss_clear = bool(boss_area_key and boss_area_key in fixed_boss_area_keys)
            if (
                highest_layer == 2
                and has_fixed_boss_clear
                and int(item["max_unlocked_layer_field"] or 1) < 3
                and int(item["max_unlocked_layer_log"] or 0) < 3
                and int(item["layer2_family_sorties"] or 0) < int(LAYER3_UNLOCK_LAYER2_SORTIES_REQUIRED)
            ):
                boss_status = (
                    f"第2層ボス撃破済み / 周回 {int(item['layer2_family_sorties'])}/{int(LAYER3_UNLOCK_LAYER2_SORTIES_REQUIRED)}"
                )
            elif has_fixed_boss_clear:
                boss_status = f"第{highest_layer}層ボス撃破済み"
            else:
                boss_status = f"第{highest_layer}層ボス未撃破"
                boss_blocker_layer = int(highest_layer)
        item["boss_status"] = boss_status
        item["boss_blocker_layer"] = boss_blocker_layer
        item["role_label"] = ("管理者" if item["is_admin"] else "一般")

        if not item["is_banned"]:
            listed_rows.append(item)
        if item["is_admin"] or item["is_banned"]:
            continue
        analysis_rows.append(item)
        stop_counts[int(highest_layer)] += 1
        if boss_blocker_layer:
            boss_block_counts[int(boss_blocker_layer)] += 1

    total_users = int(len(analysis_rows))
    admin_only_count = int(sum(1 for item in listed_rows if item["is_admin"]))
    layer_reach_rows = []
    layer_stop_rows = []
    previous_reach_count = total_users
    for layer in range(1, MAX_UNLOCKABLE_LAYER + 1):
        reach_count = int(sum(1 for item in analysis_rows if int(item["highest_layer"]) >= layer))
        stop_count = int(stop_counts.get(layer, 0))
        next_reach_count = int(sum(1 for item in analysis_rows if int(item["highest_layer"]) >= (layer + 1)))
        drop_count = max(0, reach_count - next_reach_count)
        reach_pct = (float(reach_count) / float(max(1, total_users))) * 100.0
        stop_pct = (float(stop_count) / float(max(1, total_users))) * 100.0
        convert_pct = (float(reach_count) / float(max(1, previous_reach_count))) * 100.0 if layer > 1 else 100.0
        layer_reach_rows.append(
            {
                "layer": layer,
                "label": _layer_label(layer),
                "count": reach_count,
                "pct": reach_pct,
                "bar_pct": reach_pct,
                "drop_count": drop_count,
                "convert_pct": convert_pct,
            }
        )
        layer_stop_rows.append(
            {
                "layer": layer,
                "label": f"{_layer_label(layer)}で停止",
                "count": stop_count,
                "pct": stop_pct,
                "bar_pct": stop_pct,
            }
        )
        previous_reach_count = max(1, reach_count)

    boss_block_rows = []
    boss_block_max = max((int(v) for v in boss_block_counts.values()), default=0)
    for layer in range(1, MAX_UNLOCKABLE_LAYER + 1):
        count = int(boss_block_counts.get(layer, 0))
        if count <= 0:
            continue
        boss_block_rows.append(
            {
                "layer": layer,
                "label": f"{_layer_label(layer)}ボス未撃破",
                "count": count,
                "pct": (float(count) / float(max(1, total_users))) * 100.0,
                "bar_pct": (float(count) / float(max(1, boss_block_max))) * 100.0 if boss_block_max else 0.0,
            }
        )

    listed_rows.sort(
        key=lambda item: (
            1 if item["is_admin"] else 0,
            int(item["highest_layer"]),
            0 if item.get("boss_blocker_layer") else 1,
            -int(item["last_activity_at"] or 0),
            int(item["user_id"]),
        )
    )

    return {
        "total_users": total_users,
        "listed_user_count": int(len(listed_rows)),
        "admin_only_count": admin_only_count,
        "boss_blocker_total": int(sum(int(v) for v in boss_block_counts.values())),
        "deepest_layer": int(max((item["highest_layer"] for item in analysis_rows), default=1)),
        "layer_reach_rows": layer_reach_rows,
        "layer_stop_rows": layer_stop_rows,
        "boss_block_rows": boss_block_rows,
        "user_rows": listed_rows,
    }


def _roll_evolution_core_drop(rng=None, drop_rate=None):
    """Single gateway for evolution-core drop RNG.
    Keep current behavior (flat probability), and allow pity extension later.
    """
    rng = rng or random
    rate = float(EVOLUTION_CORE_DROP_RATE if drop_rate is None else drop_rate)
    rate = _clamp(rate, 0.0, 1.0)
    return bool(rng.random() < rate)


def _evolution_core_drop_rate_for_area(area_key):
    key = str(area_key or "").strip()
    if key in EVOLUTION_CORE_DROP_RATE_BY_AREA:
        return float(EVOLUTION_CORE_DROP_RATE_BY_AREA[key])
    return float(EVOLUTION_CORE_DROP_RATE)


def _series_drop_rate_for_area(area_key):
    key = str(area_key or "").strip()
    if key == "layer_1":
        return 0.05
    if key in {"layer_2", "layer_2_mist", "layer_2_rush"}:
        return 0.09
    if key == "layer_3":
        return 0.15
    if key in {"layer_4_forge", "layer_4_haze", "layer_4_burst", "layer_4_final"}:
        return 0.28
    if key in {"layer_5_labyrinth", "layer_5_pinnacle", "layer_5_final"}:
        return 0.38
    return 0.0


def _dinosaur_debut_campaign_active(area_key=None):
    campaign = DINOSAUR_DEBUT_CAMPAIGN
    if not campaign.get("enabled"):
        return False
    key = str(area_key or "").strip()
    allowed = set(campaign.get("area_keys") or ())
    return not allowed or key in allowed


def _pick_dinosaur_campaign_part_master(db):
    series_keys = tuple(DINOSAUR_DEBUT_CAMPAIGN.get("series_keys") or ())
    if not series_keys:
        return None
    placeholders = ",".join(["?"] * len(series_keys))
    return db.execute(
        f"""
        SELECT rp.*
        FROM robot_parts rp
        WHERE rp.is_active = 1
          AND UPPER(COALESCE(rp.rarity, '')) = 'N'
          AND COALESCE(rp.is_admin_only, 0) = 0
          AND COALESCE(rp.frame_type, 'normal') = 'dinosaur'
          AND COALESCE(rp.series_key, rp.series, '') IN ({placeholders})
          AND rp.part_type IN ('HEAD', 'RIGHT_ARM', 'LEFT_ARM', 'LEGS')
        ORDER BY RANDOM()
        LIMIT 1
        """,
        series_keys,
    ).fetchone()


def _pick_drop_part_master(db, *, rarity=None, area_key=None, user_id=None):
    profile = EXPLORE_DROP_PROFILE_BY_AREA.get(str(area_key or "").strip(), {})
    series_enabled = _series_system_enabled_for_user(db, user_id=user_id)
    rarity_weights = profile.get("rarity_weights") or {}
    effective_rarity = (rarity or "").upper().strip()
    if not effective_rarity and rarity_weights:
        keys = list(rarity_weights.keys())
        weights = [float(rarity_weights[k]) for k in keys]
        effective_rarity = str(random.choices(keys, weights=weights, k=1)[0])
    if not effective_rarity:
        effective_rarity = "N"

    if effective_rarity == "R":
        rows = db.execute(
            """
            SELECT rp.*, COALESCE(sm.is_active, 0) AS series_active
            FROM robot_parts rp
            LEFT JOIN series_master sm ON sm.series_key = rp.series
            WHERE rp.is_active = 1
              AND UPPER(COALESCE(rp.rarity, '')) = 'R'
              AND rp.is_unlocked = 1
              AND COALESCE(rp.is_admin_only, 0) = 0
              AND NOT (
                    COALESCE(rp.frame_type, 'normal') = 'insect'
                    OR COALESCE(rp.series_key, rp.series, '') LIKE 'insect_%'
                    OR COALESCE(rp.frame_type, 'normal') = 'dinosaur'
                    OR COALESCE(rp.series_key, rp.series, '') LIKE 'dino_%'
              )
              AND (
                    COALESCE(TRIM(rp.series), '') = ''
                    OR rp.series IN ('S1', 'n1')
                    OR sm.series_key IS NULL
                    OR sm.is_active = 1
              )
            """,
        ).fetchall()
    else:
        rows = db.execute(
            """
            SELECT rp.*, COALESCE(sm.is_active, 0) AS series_active
            FROM robot_parts rp
            LEFT JOIN series_master sm ON sm.series_key = rp.series
            WHERE rp.is_active = 1
              AND UPPER(COALESCE(rp.rarity, '')) = UPPER(?)
              AND COALESCE(rp.is_admin_only, 0) = 0
              AND NOT (
                    COALESCE(rp.frame_type, 'normal') = 'dinosaur'
                    OR COALESCE(rp.series_key, rp.series, '') LIKE 'dino_%'
              )
              AND (
                    COALESCE(TRIM(rp.series), '') = ''
                    OR rp.series IN ('S1', 'n1')
                    OR sm.series_key IS NULL
                    OR sm.is_active = 1
              )
            """,
            (effective_rarity,),
        ).fetchall()
    if not rows:
        return None
    series_rows = []
    generic_rows = []
    for row in rows:
        series_key = str(row["series"] or "").strip()
        if series_key and series_key not in LEGACY_GENERIC_SERIES_KEYS and int(row["series_active"] or 0) == 1:
            series_rows.append(row)
        else:
            generic_rows.append(row)
    series_rate = _series_drop_rate_for_area(area_key) if series_enabled else 0.0
    if series_rows and generic_rows and series_rate > 0 and random.random() < series_rate:
        rows = series_rows
    elif generic_rows:
        rows = generic_rows
    elif series_rows:
        rows = series_rows

    element_weights = profile.get("element_weights") or {}
    bias = float(profile.get("exception_bias") or 0.0)
    weighted_rows = []
    weighted_values = []
    for row in rows:
        element_key = str(row["element"] or "NORMAL").strip().upper()
        base = float(element_weights.get(element_key, 1.0))
        w = max(0.01, base + bias)
        weighted_rows.append(row)
        weighted_values.append(w)
    return random.choices(weighted_rows, weights=weighted_values, k=1)[0]


def _core_drop_observability(db, sample_size=500, days=14, user_day_limit=200):
    sample_size = max(50, min(5000, int(sample_size or 500)))
    days = max(1, min(90, int(days or 14)))
    user_day_limit = max(20, min(1000, int(user_day_limit or 200)))

    explore_rows = db.execute(
        """
        SELECT id, payload_json
        FROM world_events_log
        WHERE event_type = ?
        ORDER BY id DESC
        LIMIT ?
        """,
        (AUDIT_EVENT_TYPES["EXPLORE_END"], sample_size),
    ).fetchall()

    explores = len(explore_rows)
    wins = 0
    battles_total = 0
    core_total = 0
    core_hit_explores = 0
    for row in explore_rows:
        try:
            payload = json.loads(row["payload_json"] or "{}")
        except Exception:
            payload = {}
        if not isinstance(payload, dict):
            payload = {}
        result = payload.get("result") if isinstance(payload.get("result"), dict) else {}
        rewards = payload.get("rewards") if isinstance(payload.get("rewards"), dict) else {}
        if bool(result.get("win")):
            wins += 1
        battles_total += int(result.get("battle_count") or 1)
        cores = int(rewards.get("cores") or 0)
        if cores > 0:
            core_hit_explores += 1
            core_total += cores

    avg_battles_per_explore = (float(battles_total) / float(explores)) if explores else 0.0
    core_per_explore = (float(core_total) / float(explores)) if explores else 0.0
    core_hit_rate_explore = (float(core_hit_explores) / float(explores)) if explores else 0.0
    core_per_battle_trial = (float(core_total) / float(battles_total)) if battles_total else 0.0
    expected_hit_per_explore = (
        1.0 - math.pow(1.0 - float(EVOLUTION_CORE_DROP_RATE), avg_battles_per_explore)
        if avg_battles_per_explore > 0
        else 0.0
    )

    since_ts = int(time.time()) - days * 86400
    user_day_rows = db.execute(
        """
        SELECT
            date(datetime(wel.created_at, 'unixepoch', 'localtime')) AS day_key,
            wel.user_id,
            u.username,
            SUM(COALESCE(CAST(json_extract(wel.payload_json, '$.quantity') AS INTEGER), 0)) AS core_qty
        FROM world_events_log wel
        LEFT JOIN users u ON u.id = wel.user_id
        WHERE wel.event_type = ?
          AND wel.user_id IS NOT NULL
          AND wel.created_at >= ?
        GROUP BY day_key, wel.user_id, u.username
        ORDER BY day_key DESC, core_qty DESC, wel.user_id ASC
        LIMIT ?
        """,
        (AUDIT_EVENT_TYPES["CORE_DROP"], since_ts, user_day_limit),
    ).fetchall()
    user_day = []
    for row in user_day_rows:
        user_day.append(
            {
                "day_key": row["day_key"],
                "user_id": int(row["user_id"]),
                "username": row["username"] or f"user#{int(row['user_id'])}",
                "core_qty": int(row["core_qty"] or 0),
            }
        )

    return {
        "configured_drop_rate": float(EVOLUTION_CORE_DROP_RATE),
        "sample_size": int(sample_size),
        "explores": int(explores),
        "wins": int(wins),
        "battles_total": int(battles_total),
        "core_total": int(core_total),
        "core_hit_explores": int(core_hit_explores),
        "avg_battles_per_explore": float(avg_battles_per_explore),
        "core_per_explore": float(core_per_explore),
        "core_hit_rate_explore": float(core_hit_rate_explore),
        "core_per_battle_trial": float(core_per_battle_trial),
        "expected_hit_per_explore": float(expected_hit_per_explore),
        "days": int(days),
        "user_day": user_day,
    }


def _world_week_key(ts=None):
    dt = datetime.now(JST) if ts is None else datetime.fromtimestamp(ts, JST)
    iso = dt.isocalendar()
    return f"{iso.year}-W{iso.week:02d}"


def _world_week_bounds(week_key):
    year_s, week_s = week_key.split("-W")
    year = int(year_s)
    week = int(week_s)
    start = datetime.fromisocalendar(year, week, 1).replace(tzinfo=JST)
    end = start + timedelta(days=7)
    return start, end


def _jst_day_bounds(ts=None):
    dt = datetime.now(JST) if ts is None else datetime.fromtimestamp(ts, JST)
    start = datetime(dt.year, dt.month, dt.day, tzinfo=JST)
    end = start + timedelta(days=1)
    return int(start.timestamp()), int(end.timestamp())


def _world_event_log(db, event_type, payload):
    db.execute(
        """
        INSERT INTO world_events_log (created_at, event_type, payload_json)
        VALUES (?, ?, ?)
        """,
        (int(time.time()), event_type, json.dumps(payload, ensure_ascii=False)),
    )


def _now_ts():
    if has_request_context():
        cached = getattr(g, "_now_ts", None)
        if cached is None:
            cached = int(time.time())
            g._now_ts = cached
        return int(cached)
    return int(time.time())


def _research_part_type_for_stage(stage):
    idx = int(stage) - 1
    if 0 <= idx < len(RESEARCH_UNLOCK_ORDER):
        return RESEARCH_UNLOCK_ORDER[idx]
    return None


def _ensure_world_research_rows(db):
    now_ts = int(time.time())
    for element, _ in ELEMENTS:
        db.execute(
            """
            INSERT INTO world_research_progress (element, progress, unlocked_stage, updated_at)
            VALUES (?, 0, 0, ?)
            ON CONFLICT(element) DO NOTHING
            """,
            (element, now_ts),
        )


def _research_winning_element(db, week_key):
    order = {element: idx for idx, (element, _) in enumerate(ELEMENTS)}
    scores = []
    for element, _ in ELEMENTS:
        kills = _world_counter_get(db, week_key, f"kills_{element}")
        builds = _world_counter_get(db, week_key, f"builds_{element}")
        scores.append((element, int(kills) + int(builds), int(kills), int(builds)))
    best = max(scores, key=lambda x: (x[1], x[2], x[3], -order.get(x[0], 999)))
    if best[1] <= 0:
        return None
    return best[0]


def _advance_world_research(db, current_week_key):
    advance_seen = db.execute(
        """
        SELECT 1
        FROM world_events_log
        WHERE event_type = 'RESEARCH_ADVANCE'
          AND payload_json LIKE ?
        LIMIT 1
        """,
        (f'%"week_key": "{current_week_key}"%',),
    ).fetchone()
    if advance_seen:
        return {
            "week_key": current_week_key,
            "skipped": True,
            "reason": "already_advanced",
        }

    _ensure_world_research_rows(db)
    prev_start = _world_week_bounds(current_week_key)[0] - timedelta(days=7)
    prev_week_key = _world_week_key(prev_start.timestamp())
    winner = _research_winning_element(db, prev_week_key)
    if not winner:
        result = {
            "week_key": current_week_key,
            "source_week_key": prev_week_key,
            "winner_element": None,
            "progress_added": 0,
            "unlocked": False,
            "skipped": False,
        }
        _world_event_log(db, "RESEARCH_ADVANCE", result)
        return result

    now_ts = int(time.time())
    row = db.execute(
        "SELECT progress, unlocked_stage FROM world_research_progress WHERE element = ?",
        (winner,),
    ).fetchone()
    prev_progress = int(row["progress"] or 0) if row else 0
    prev_stage = int(row["unlocked_stage"] or 0) if row else 0
    new_progress = prev_progress + 50
    new_stage = prev_stage
    unlocked_part_type = None
    unlocked_count = 0

    if new_progress >= 100 and prev_stage < len(RESEARCH_UNLOCK_ORDER):
        new_stage = prev_stage + 1
        new_progress = 0
        unlocked_part_type = _research_part_type_for_stage(new_stage)
        if unlocked_part_type:
            unlocked_count = db.execute(
                """
                UPDATE robot_parts
                SET is_unlocked = 1
                WHERE UPPER(COALESCE(rarity, '')) = 'R'
                  AND UPPER(COALESCE(element, '')) = ?
                  AND part_type = ?
                  AND is_unlocked = 0
                """,
                (winner, unlocked_part_type),
            ).rowcount
        unlock_payload = {
            "week_key": current_week_key,
            "source_week_key": prev_week_key,
            "element": winner,
            "stage": new_stage,
            "part_type": unlocked_part_type,
            "updated_parts": int(unlocked_count),
        }
        _world_event_log(db, "RESEARCH_UNLOCK", unlock_payload)
        db.execute(
            """
            INSERT INTO world_research_unlocks (created_at, week_key, element, stage, part_type, payload_json)
            VALUES (?, ?, ?, ?, ?, ?)
            """,
            (
                now_ts,
                current_week_key,
                winner,
                new_stage,
                unlocked_part_type or "",
                json.dumps(unlock_payload, ensure_ascii=False),
            ),
        )

    db.execute(
        """
        INSERT INTO world_research_progress (element, progress, unlocked_stage, updated_at)
        VALUES (?, ?, ?, ?)
        ON CONFLICT(element) DO UPDATE SET
            progress = excluded.progress,
            unlocked_stage = excluded.unlocked_stage,
            updated_at = excluded.updated_at
        """,
        (winner, int(new_progress), int(new_stage), now_ts),
    )
    result = {
        "week_key": current_week_key,
        "winner_element": winner,
        "progress_added": 50,
        "source_week_key": prev_week_key,
        "stage_before": prev_stage,
        "stage_after": new_stage,
        "progress_before": prev_progress,
        "progress_after": new_progress,
        "unlocked": bool(unlocked_part_type),
        "part_type": unlocked_part_type,
    }
    _world_event_log(db, "RESEARCH_ADVANCE", result)
    return result


def _load_user_area_streaks(db, user_id):
    rows = db.execute(
        """
        SELECT area_key, win_streak
        FROM user_area_streaks
        WHERE user_id = ?
        """,
        (user_id,),
    ).fetchall()
    return {r["area_key"]: int(r["win_streak"] or 0) for r in rows}


def _update_user_area_streak(db, user_id, area_key, won, updated_at):
    row = db.execute(
        "SELECT win_streak FROM user_area_streaks WHERE user_id = ? AND area_key = ?",
        (user_id, area_key),
    ).fetchone()
    prev_streak = int(row["win_streak"] or 0) if row else 0
    new_streak = (prev_streak + 1) if bool(won) else 0
    db.execute(
        """
        INSERT INTO user_area_streaks (user_id, area_key, win_streak, updated_at)
        VALUES (?, ?, ?, ?)
        ON CONFLICT(user_id, area_key) DO UPDATE
        SET win_streak = excluded.win_streak,
            updated_at = excluded.updated_at
        """,
        (user_id, area_key, int(new_streak), int(updated_at)),
    )
    db.execute(
        """
        UPDATE user_area_streaks
        SET win_streak = 0,
            updated_at = ?
        WHERE user_id = ? AND area_key != ? AND win_streak != 0
        """,
        (int(updated_at), user_id, area_key),
    )
    return int(new_streak)


def _area_layer(area_key):
    key = str(area_key or "").strip()
    if key in EXPLORE_AREA_LAYER_BY_KEY:
        return int(EXPLORE_AREA_LAYER_BY_KEY.get(key, 1))
    match = re.match(r"^layer_(\d+)(?:_|$)", key)
    if match:
        return int(match.group(1))
    return 1


def _stat_mult_applied(base_value, multiplier):
    base = int(base_value or 0)
    mult = float(multiplier or 1.0)
    return max(1, int(round(base * mult)))


def _pct_text(multiplier):
    delta = int(round((float(multiplier or 1.0) - 1.0) * 100))
    if delta == 0:
        return None
    sign = "+" if delta > 0 else ""
    return f"{sign}{delta}%"


def _stage_modifier_for_area(area_key, is_admin=False):
    if not STAGE_MODIFIERS_ENABLED or bool(is_admin):
        return None
    raw = STAGE_MODIFIERS_BY_AREA.get(area_key)
    if not raw:
        return None
    player_raw = raw.get("player_mult") or {}
    enemy_raw = raw.get("enemy_mult") or {}
    player_mult = {
        "atk": float(player_raw.get("atk", 1.0)),
        "def": float(player_raw.get("def", 1.0)),
        "acc": float(player_raw.get("acc", 1.0)),
    }
    enemy_mult = {
        "atk": float(enemy_raw.get("atk", 1.0)),
        "def": float(enemy_raw.get("def", 1.0)),
        "acc": float(enemy_raw.get("acc", 1.0)),
        "spd": float(enemy_raw.get("spd", 1.0)),
        "cri": float(enemy_raw.get("cri", 1.0)),
        "hp": float(enemy_raw.get("hp", 1.0)),
    }
    return {
        "area_key": area_key,
        "tendency": (raw.get("tendency") or "標準"),
        "player_mult": player_mult,
        "enemy_mult": enemy_mult,
    }


def _stage_modifier_summary_line(stage_modifier):
    if not stage_modifier:
        return None
    pm = stage_modifier["player_mult"]
    parts = []
    atk = _pct_text(pm.get("atk", 1.0))
    deff = _pct_text(pm.get("def", 1.0))
    acc = _pct_text(pm.get("acc", 1.0))
    if atk:
        parts.append(f"{_stat_label('atk')}{atk}")
    if deff:
        parts.append(f"{_stat_label('def')}{deff}")
    if acc:
        parts.append(f"{_stat_label('acc')}{acc}")
    if not parts:
        return f"傾向：{stage_modifier['tendency']}（補正なし）"
    return f"傾向：{stage_modifier['tendency']}（{'/'.join(parts)}）"


def _user_max_unlocked_layer(user_row):
    if not user_row:
        return 1
    current = int(user_row["max_unlocked_layer"] or 1) if "max_unlocked_layer" in user_row.keys() else 1
    if "layer2_unlocked" in user_row.keys() and int(user_row["layer2_unlocked"] or 0) == 1:
        current = max(current, 2)
    return max(1, min(MAX_UNLOCKABLE_LAYER, current))


def _seed_release_flags(db):
    for item in RELEASE_FLAG_DEFS:
        db.execute(
            """
            INSERT INTO release_flags (key, is_public, updated_at)
            VALUES (?, 0, 0)
            ON CONFLICT(key) DO NOTHING
            """,
            (item["key"],),
        )


def _release_flag_is_public(db, feature_key):
    key = str(feature_key or "").strip().lower()
    if not key:
        return True
    row = db.execute("SELECT is_public FROM release_flags WHERE key = ? LIMIT 1", (key,)).fetchone()
    return bool(row and int(row["is_public"] or 0) == 1)


def _release_gate_testing_bypass_enabled():
    return bool(app.config.get("TESTING")) and bool(app.config.get("BYPASS_RELEASE_GATES_IN_TESTS", True))


def _viewer_is_admin_for_release(db, *, user_row=None, user_id=None, is_admin=None):
    if is_admin is not None:
        return bool(is_admin)
    if user_row is not None and "is_admin" in user_row.keys():
        return bool(int(user_row["is_admin"] or 0) == 1)
    uid = int(user_id or 0)
    if uid <= 0 or not db:
        return False
    row = db.execute("SELECT is_admin FROM users WHERE id = ?", (uid,)).fetchone()
    return bool(row and int(row["is_admin"] or 0) == 1)


def _release_open_for_viewer(db, feature_key, *, user_row=None, user_id=None, is_admin=None):
    key = str(feature_key or "").strip().lower()
    if not key:
        return True
    if _release_gate_testing_bypass_enabled():
        return True
    if _viewer_is_admin_for_release(db, user_row=user_row, user_id=user_id, is_admin=is_admin):
        return True
    return _release_flag_is_public(db, key)


def _series_system_enabled_for_user(db, *, user_row=None, user_id=None, is_admin=None):
    return _release_open_for_viewer(
        db,
        SERIES_SYSTEM_FEATURE_KEY,
        user_row=user_row,
        user_id=user_id,
        is_admin=is_admin,
    )


def _insect_r_parts_open_for_viewer(db, *, user_row=None, user_id=None, is_admin=None):
    return _release_open_for_viewer(
        db,
        INSECT_R_PARTS_FEATURE_KEY,
        user_row=user_row,
        user_id=user_id,
        is_admin=is_admin,
    )


def _release_feature_for_area(area_key):
    key = str(area_key or "").strip()
    if key in {*LAYER4_SUBAREA_KEYS, LAYER4_FINAL_AREA_KEY}:
        return "layer4"
    if key in {*LAYER5_SUBAREA_KEYS, LAYER5_FINAL_AREA_KEY}:
        return "layer5"
    return None


def _area_visible_for_viewer(db, area_key, *, user_row=None, user_id=None, is_admin=None):
    return _release_open_for_viewer(
        db,
        _release_feature_for_area(area_key),
        user_row=user_row,
        user_id=user_id,
        is_admin=is_admin,
    )


def _release_layer_cap_for_viewer(db, *, user_row=None, user_id=None, is_admin=None):
    if _release_gate_testing_bypass_enabled():
        return MAX_UNLOCKABLE_LAYER
    if _viewer_is_admin_for_release(db, user_row=user_row, user_id=user_id, is_admin=is_admin):
        return MAX_UNLOCKABLE_LAYER
    if _release_flag_is_public(db, "layer5"):
        return MAX_UNLOCKABLE_LAYER
    if _release_flag_is_public(db, "layer4"):
        return 4
    return PUBLIC_RELEASED_BASE_LAYER


def _visible_user_max_unlocked_layer(user_row, db=None):
    actual = _user_max_unlocked_layer(user_row)
    if not db or not user_row:
        return actual
    return max(1, min(actual, _release_layer_cap_for_viewer(db, user_row=user_row)))


def _event_release_feature(event_type, payload):
    text = str(event_type or "").strip()
    if text.startswith("TOWER_") or text.startswith("audit.tower."):
        return "tower"
    if text.startswith("audit.lab.") or text.startswith("LAB_RACE_") or text.startswith("LAB_SUBMISSION_"):
        return "lab"
    if text in {"CHAMPION_SELECTED", "CHAMPION_DEFEATED", "CHAMP_DEFEAT_FIRST", "CHAMP_DEFEAT_DAILY", "CHAMP_DEFEAT_UPSET"} or text.startswith("audit.champion.") or text.startswith("audit.champ."):
        return "weekly_champion"
    unlocked_layer = int((payload or {}).get("unlocked_layer") or 0)
    if unlocked_layer >= 5:
        return "layer5"
    if unlocked_layer >= 4:
        return "layer4"
    area_key = str((payload or {}).get("area_key") or "").strip()
    return _release_feature_for_area(area_key)


def _event_visible_for_viewer(db, event_type, payload, *, user_row=None, user_id=None, is_admin=None):
    return _release_open_for_viewer(
        db,
        _event_release_feature(event_type, payload),
        user_row=user_row,
        user_id=user_id,
        is_admin=is_admin,
    )


def _release_gate_redirect(db, feature_key, *, user_row=None, user_id=None, is_admin=None, next_endpoint="home"):
    if _release_open_for_viewer(db, feature_key, user_row=user_row, user_id=user_id, is_admin=is_admin):
        return None
    flash("まだ公開準備中です。公開まで少し待ってください。", "notice")
    return redirect(url_for(next_endpoint))


def _battle_short_replay_open_for_viewer(db, *, user_row=None, user_id=None, is_admin=None):
    if not BATTLE_SHORT_REPLAY_ENABLED:
        return False
    return _release_open_for_viewer(
        db,
        "battle_short_replay",
        user_row=user_row,
        user_id=user_id,
        is_admin=is_admin,
    )


def _release_flag_rows(db):
    _seed_release_flags(db)
    rows = {
        row["key"]: row
        for row in db.execute("SELECT key, is_public, updated_at FROM release_flags").fetchall()
    }
    items = []
    for item in RELEASE_FLAG_DEFS:
        row = rows.get(item["key"])
        items.append(
            {
                "key": item["key"],
                "label": item["label"],
                "summary": item["summary"],
                "is_public": bool(row and int(row["is_public"] or 0) == 1),
                "updated_at": int(row["updated_at"] or 0) if row else 0,
                "updated_text": (_format_jst_ts(row["updated_at"]) if row and int(row["updated_at"] or 0) > 0 else "未変更"),
            }
        )
    return items


def _save_maintenance_mode(db, mode, *, actor_user_id):
    normalized = str(mode or "").strip().lower()
    if normalized not in MAINTENANCE_MODE_VALUES:
        raise ValueError(f"invalid maintenance mode: {mode}")
    now_ts = int(time.time())
    db.execute(
        """
        INSERT INTO maintenance_state (id, mode, updated_at, updated_by_user_id)
        VALUES (1, ?, ?, ?)
        ON CONFLICT(id) DO UPDATE SET
            mode = excluded.mode,
            updated_at = excluded.updated_at,
            updated_by_user_id = excluded.updated_by_user_id
        """,
        (normalized, now_ts, int(actor_user_id)),
    )
    return now_ts


def _layer4_trial_bosses_cleared(db, user_id):
    uid = int(user_id or 0)
    if uid <= 0:
        return False
    return all(_has_fixed_boss_defeat_in_area(db, uid, area_key) for area_key in LAYER4_SUBAREA_KEYS)


def _is_layer4_warning_area(area_key):
    return str(area_key or "").strip() in LAYER4_WARNING_TARGET_AREAS


def _layer4_warning_phase(progress_count):
    count = max(0, int(progress_count or 0))
    if count >= 75:
        return {"phase": "critical", "label": "臨界", "helper_text": "次回、試験ボス反応が最大です"}
    if count >= 50:
        return {"phase": "strong", "label": "強", "helper_text": "試験ボス反応が強まっています"}
    if count >= 40:
        return {"phase": "high", "label": "高まり", "helper_text": ""}
    if count >= 30:
        return {"phase": "rising", "label": "上昇中", "helper_text": ""}
    return {"phase": "weak", "label": "微弱", "helper_text": ""}


def _layer4_warning_spawn_profile(progress_count):
    count = max(0, int(progress_count or 0))
    if count >= 75:
        return {"probability": 1.0, "guaranteed": True, "threshold": 75}
    if count >= 50:
        return {"probability": 0.10, "guaranteed": False, "threshold": 50}
    if count >= 40:
        return {"probability": 0.02, "guaranteed": False, "threshold": 40}
    if count >= 30:
        return {"probability": 0.01, "guaranteed": False, "threshold": 30}
    return {"probability": 0.005, "guaranteed": False, "threshold": 0}


def _get_layer4_warning_progress(db, user_id, area_key):
    if not _is_layer4_warning_area(area_key):
        return 0
    row = db.execute(
        """
        SELECT progress_count
        FROM layer4_warning_progress
        WHERE user_id = ? AND area_key = ?
        """,
        (int(user_id), str(area_key)),
    ).fetchone()
    return max(0, int(row["progress_count"] or 0)) if row else 0


def _set_layer4_warning_progress(db, user_id, area_key, progress_count, *, now_ts=None):
    if not _is_layer4_warning_area(area_key):
        return 0
    now = int(now_ts or time.time())
    count = max(0, int(progress_count or 0))
    db.execute(
        """
        INSERT INTO layer4_warning_progress (user_id, area_key, progress_count, updated_at, created_at)
        VALUES (?, ?, ?, ?, ?)
        ON CONFLICT(user_id, area_key) DO UPDATE
        SET progress_count = excluded.progress_count,
            updated_at = excluded.updated_at
        """,
        (int(user_id), str(area_key), count, now, now),
    )
    return count


def _advance_layer4_warning_progress(db, user_id, area_key, *, request_id=None, ip=None, now_ts=None):
    if not _is_layer4_warning_area(area_key):
        return None
    if _layer4_trial_bosses_cleared(db, user_id):
        return None
    before = _get_layer4_warning_progress(db, user_id, area_key)
    after = min(LAYER4_WARNING_MAX_COUNT, before + 1)
    _set_layer4_warning_progress(db, user_id, area_key, after, now_ts=now_ts)
    phase = _layer4_warning_phase(after)
    audit_log(
        db,
        AUDIT_EVENT_TYPES["LAYER4_WARNING_PROGRESS"],
        user_id=int(user_id),
        request_id=request_id,
        action_key="explore",
        entity_type="explore_area",
        entity_id=None,
        delta_count=1,
        payload={
            "user_id": int(user_id),
            "area_key": str(area_key),
            "progress_before": int(before),
            "progress_after": int(after),
            "threshold": int(LAYER4_WARNING_MAX_COUNT),
            "phase": phase["phase"],
            "reason": "normal_win",
        },
        ip=ip,
    )
    return {"before": before, "after": after, **phase}


def _reset_layer4_warning_progress(
    db,
    user_id,
    area_key,
    *,
    request_id=None,
    ip=None,
    now_ts=None,
    encounter_source="natural",
):
    if not _is_layer4_warning_area(area_key):
        return None
    before = _get_layer4_warning_progress(db, user_id, area_key)
    _set_layer4_warning_progress(db, user_id, area_key, 0, now_ts=now_ts)
    audit_log(
        db,
        AUDIT_EVENT_TYPES["LAYER4_WARNING_RESET"],
        user_id=int(user_id),
        request_id=request_id,
        action_key="explore",
        entity_type="explore_area",
        entity_id=None,
        payload={
            "user_id": int(user_id),
            "area_key": str(area_key),
            "progress_before": int(before),
            "progress_after": 0,
            "threshold": int(LAYER4_WARNING_MAX_COUNT),
            "reason": "boss_encounter",
            "encounter_source": str(encounter_source or "natural"),
        },
        ip=ip,
    )
    return {"before": before, "after": 0}


def _layer5_trial_bosses_cleared(db, user_id):
    uid = int(user_id or 0)
    if uid <= 0:
        return False
    return all(_has_fixed_boss_defeat_in_area(db, uid, area_key) for area_key in LAYER5_SUBAREA_KEYS)


def _special_area_unlock_reason(area_key):
    key = str(area_key or "").strip()
    if key == LAYER4_FINAL_AREA_KEY:
        return "第4層3ボス撃破で解放"
    if key == LAYER5_FINAL_AREA_KEY:
        return "第5層2ボス撃破で解放"
    layer = _area_layer(key)
    if layer <= 1:
        return "未解放"
    return f"第{layer - 1}層ボス撃破で解放"


def _is_special_area_unlocked(db, user_id, area_key):
    if db and _is_main_admin_user_id(db, user_id):
        return True
    key = str(area_key or "").strip()
    if key == LAYER4_FINAL_AREA_KEY:
        return _layer4_trial_bosses_cleared(db, user_id)
    if key == LAYER5_FINAL_AREA_KEY:
        return _layer5_trial_bosses_cleared(db, user_id)
    return True


def _is_area_unlocked(user_row, area_key, db=None):
    if db and not _area_visible_for_viewer(db, area_key, user_row=user_row):
        return False
    visible_max = _visible_user_max_unlocked_layer(user_row, db=db)
    if _area_layer(area_key) > visible_max:
        return False
    key = str(area_key or "").strip()
    if key not in SPECIAL_EXPLORE_AREA_KEYS:
        return True
    if not db or not user_row or "id" not in user_row.keys():
        return False
    return _is_special_area_unlocked(db, int(user_row["id"]), key)


def _saved_explore_area_key(user_row, available_areas=None, db=None):
    if not user_row or "last_explore_area_key" not in user_row.keys():
        return None
    area_key = str(user_row["last_explore_area_key"] or "").strip()
    if not area_key or area_key not in EXPLORE_AREA_LAYER_BY_KEY:
        return None
    if not _is_area_unlocked(user_row, area_key, db=db):
        return None
    if available_areas is not None:
        available_keys = {str(area.get("key") or "").strip() for area in available_areas}
        if area_key not in available_keys:
            return None
    return area_key


def _default_explore_area_key(user_row, available_areas, db=None):
    saved = _saved_explore_area_key(user_row, available_areas, db=db)
    if saved:
        return saved
    if not available_areas:
        return None
    return str(available_areas[0].get("key") or "").strip() or None


def _find_explore_area(available_areas, area_key):
    key = str(area_key or "").strip()
    if not key:
        return None
    return next((area for area in (available_areas or ()) if str(area.get("key") or "").strip() == key), None)


def _area_home_desc_line(area_key):
    info = EXPLORE_AREA_MAP_INFO.get(str(area_key or "").strip()) or {}
    desc = info.get("desc") or []
    if not desc:
        return ""
    return str(desc[0] or "").strip()


def _build_home_primary_explore_cta(
    *,
    has_any_robot,
    is_admin,
    ct_remain,
    total_explores,
    available_areas,
    selected_area_key,
    saved_area_key,
    next_action_card=None,
):
    if not has_any_robot:
        return {
            "title": "最初の出撃準備",
            "destination_label": "ロボを組み立てる",
            "helper_text": "これから一緒に出撃するロボを1体完成させよう。",
            "status_text": "出撃準備中",
            "button_label": "組み立てる",
            "button_current_label": "組み立てる",
            "is_post": False,
            "cta_url": url_for("build"),
            "area_key": None,
            "boss_enter": False,
            "disabled": False,
            "show_map_link": False,
            "map_link_label": "",
            "map_href": "",
            "context_line": "完成後はそのまま第1層へ出撃できます。",
        }

    ready = bool(is_admin or int(ct_remain or 0) <= 0)
    if next_action_card and next_action_card.get("home_primary") and not next_action_card.get("is_post"):
        return {
            "title": str(next_action_card.get("title") or "次の行動"),
            "destination_label": str(next_action_card.get("destination_label") or "パーツ強化"),
            "helper_text": str(next_action_card.get("desc") or "").strip(),
            "status_text": "準備OK",
            "button_label": str(next_action_card.get("cta_label") or "開く"),
            "button_current_label": str(next_action_card.get("cta_label") or "開く"),
            "is_post": False,
            "cta_url": str(next_action_card.get("cta_url") or url_for("home")),
            "area_key": None,
            "boss_enter": False,
            "disabled": False,
            "show_map_link": False,
            "map_link_label": "",
            "map_href": "",
            "context_line": str(next_action_card.get("context_line") or "次の目標を優先表示しています。"),
        }
    selected_area = _find_explore_area(available_areas, selected_area_key)
    saved_area = _find_explore_area(available_areas, saved_area_key)
    use_next_action = bool(
        next_action_card
        and next_action_card.get("is_post")
        and str(next_action_card.get("cta_url") or "") == url_for("explore")
        and str(next_action_card.get("area_key") or "").strip()
    )
    next_action_area_key = (
        str(next_action_card.get("area_key") or "").strip() if use_next_action else ""
    )
    next_action_priority = bool(
        use_next_action
        and (
            bool(next_action_card.get("boss_enter"))
            or next_action_area_key in {LAYER4_FINAL_AREA_KEY, LAYER5_FINAL_AREA_KEY}
        )
    )
    if next_action_priority:
        area = _find_explore_area(available_areas, next_action_card.get("area_key")) or selected_area or saved_area
        button_label = str(next_action_card.get("cta_label") or "出撃する")
        helper_text = str(next_action_card.get("desc") or "").strip() or _area_home_desc_line(area["key"] if area else "")
        title = str(next_action_card.get("title") or "次の出撃")
        context_line = "ボス警報や解放直後の目標を優先表示しています。"
        boss_enter = bool(next_action_card.get("boss_enter"))
        area_key = str(next_action_card.get("area_key") or (area["key"] if area else "")).strip() or None
    elif saved_area:
        area = saved_area
        button_label = "前回の出撃先で出撃"
        helper_text = _area_home_desc_line(area["key"]) or "前回の探索先から、そのまま再出撃できます。"
        title = "前回の出撃先"
        context_line = "前回の探索先を覚えています。"
        boss_enter = False
        area_key = area["key"]
    elif int(total_explores or 0) <= 0:
        area = _find_explore_area(available_areas, "layer_1") or selected_area or saved_area
        button_label = "第1層へ出撃"
        helper_text = "まずは1勝してパーツを持ち帰ろう。"
        title = "最初の出撃"
        context_line = "最初の1勝までは、このボタンだけ見れば大丈夫です。"
        boss_enter = False
        area_key = area["key"] if area else "layer_1"
    elif use_next_action:
        area = _find_explore_area(available_areas, next_action_card.get("area_key")) or selected_area or saved_area
        button_label = str(next_action_card.get("cta_label") or "出撃する")
        helper_text = str(next_action_card.get("desc") or "").strip() or _area_home_desc_line(area["key"] if area else "")
        title = str(next_action_card.get("title") or "次の出撃")
        context_line = "ボス警報や解放直後の目標を優先表示しています。"
        boss_enter = bool(next_action_card.get("boss_enter"))
        area_key = str(next_action_card.get("area_key") or (area["key"] if area else "")).strip() or None
    else:
        area = selected_area or (available_areas[0] if available_areas else None)
        button_label = "出撃する"
        helper_text = _area_home_desc_line(area["key"] if area else "") or "次の探索先を決めて出撃しよう。"
        title = "次の出撃"
        context_line = "探索先はあとでマップから変えられます。"
        boss_enter = False
        area_key = area["key"] if area else None

    current_label = button_label if ready else f"クールタイム中 あと{int(ct_remain)}秒"
    status_text = "出撃可能" if ready else f"クールタイム中 あと{int(ct_remain)}秒"
    map_link_label = "マップで出撃先を変える" if not use_next_action else "いったんマップを見る"
    return {
        "title": title,
        "destination_label": area["label"] if area else "探索先未設定",
        "helper_text": helper_text,
        "status_text": status_text,
        "button_label": button_label,
        "button_current_label": current_label,
        "is_post": True,
        "cta_url": url_for("explore"),
        "area_key": area_key,
        "boss_enter": boss_enter,
        "disabled": not ready,
        "show_map_link": True,
        "map_link_label": map_link_label,
        "map_href": url_for("map_view"),
        "context_line": context_line,
    }


def _locked_layer_lines(user_row, db=None):
    max_layer = _visible_user_max_unlocked_layer(user_row, db=db)
    release_cap = _release_layer_cap_for_viewer(db, user_row=user_row) if db and user_row else MAX_UNLOCKABLE_LAYER
    lines = []
    for layer in range(max_layer + 1, min(MAX_UNLOCKABLE_LAYER, release_cap) + 1):
        lines.append(f"🔒 第{layer}層（第{layer - 1}層ボス撃破で解放）")
    if (
        release_cap >= 4
        and max_layer >= 4
        and (not db or not user_row or "id" not in user_row.keys() or not _is_special_area_unlocked(db, int(user_row["id"]), LAYER4_FINAL_AREA_KEY))
    ):
        lines.append("🔒 第4層最終試験（Forge / Haze / Burst の3ボス撃破で解放）")
    if (
        release_cap >= 5
        and max_layer >= 5
        and (not db or not user_row or "id" not in user_row.keys() or not _is_special_area_unlocked(db, int(user_row["id"]), LAYER5_FINAL_AREA_KEY))
    ):
        lines.append("🔒 第5層最終試験（Labyrinth / Pinnacle の2ボス撃破で解放）")
    return lines


def _build_map_nodes(user_row, area_streaks=None, db=None):
    nodes = []
    max_layer = _visible_user_max_unlocked_layer(user_row, db=db)
    streaks = area_streaks or {}
    is_admin = bool(user_row and "is_admin" in user_row.keys() and int(user_row["is_admin"] or 0) == 1)
    for area in EXPLORE_AREAS:
        key = area["key"]
        layer = _area_layer(key)
        if layer > max_layer or (db and not _is_area_unlocked(user_row, key, db=db)):
            continue
        info = EXPLORE_AREA_MAP_INFO.get(
            key,
            {
                "desc": [
                    "詳細情報は未登録です。",
                    "推奨: 出撃機体の長所を活かす構成。",
                    "注意: 事前にステータスを確認してください。",
                ],
                "recommended_archetype": "自由",
            },
        )
        stage_modifier = _stage_modifier_for_area(key, is_admin=is_admin)
        tendency_line = _area_growth_tendency_line(key, context="map")
        if not tendency_line:
            tendency_line = str(_stage_modifier_summary_line(stage_modifier) or "")
        archetype_label = str(info.get("recommended_archetype") or "自由")
        if archetype_label in {"sniper", "swift", "fortress"}:
            archetype_label = {
                "sniper": "狙撃型",
                "swift": "疾風型",
                "fortress": "鉄壁型",
            }.get(archetype_label, archetype_label)
        nodes.append(
            {
                "key": key,
                "label": area["label"],
                "layer": layer,
                "description_lines": info["desc"][:3],
                "growth_tendency_label": _area_growth_tendency_label(key),
                "tendency_line": tendency_line,
                "recommended_archetype": archetype_label,
                "win_streak": int(streaks.get(key, 0)),
            }
        )
    return nodes


def _battle_log_mode_for_user(user_row):
    mode = ""
    if user_row and "battle_log_mode" in user_row.keys():
        mode = (user_row["battle_log_mode"] or "").strip().lower()
    return "expanded" if mode == "expanded" else "collapsed"


def _layer1_boss_spawn_check(explore_meter, win_meter, rng=None):
    explore = int(explore_meter or 0)
    wins = int(win_meter or 0)
    if explore < L1_BOSS_MIN_EXPLORE or wins < L1_BOSS_MIN_WINS:
        return False, 0.0
    if explore >= L1_BOSS_PITY_EXPLORE or wins >= L1_BOSS_PITY_WINS:
        return True, 1.0
    prog_e = _clamp((explore - L1_BOSS_MIN_EXPLORE) / (L1_BOSS_PITY_EXPLORE - L1_BOSS_MIN_EXPLORE), 0.0, 1.0)
    prog_w = _clamp((wins - L1_BOSS_MIN_WINS) / (L1_BOSS_PITY_WINS - L1_BOSS_MIN_WINS), 0.0, 1.0)
    prog = max(prog_e, prog_w)
    p = 0.10 + 0.80 * prog
    roller = rng or random
    return bool(roller.random() < p), float(p)


def _build_layer1_boss_enemy(db):
    tier1 = db.execute(
        """
        SELECT AVG(hp) AS avg_hp, AVG(atk) AS avg_atk, AVG(def) AS avg_def, AVG(spd) AS avg_spd, AVG(acc) AS avg_acc, AVG(cri) AS avg_cri
        FROM enemies
        WHERE is_active = 1 AND tier = 1
        """
    ).fetchone()
    avg_hp = float(tier1["avg_hp"] or 22.0)
    avg_atk = float(tier1["avg_atk"] or 8.0)
    avg_def = float(tier1["avg_def"] or 8.0)
    avg_spd = float(tier1["avg_spd"] or 8.0)
    avg_acc = float(tier1["avg_acc"] or 8.0)
    avg_cri = float(tier1["avg_cri"] or 6.0)
    return {
        "id": -1001,
        "key": "boss_layer1_guardian",
        "name_ja": "試作型ガーディアン",
        "image_path": "assets/placeholder_enemy.png",
        "tier": 1,
        "element": "NORMAL",
        "faction": "neutral",
        "hp": max(1, int(round(avg_hp * 2.5))),
        "atk": max(1, int(round(avg_atk * 1.20))),
        "def": max(1, int(round(avg_def * 1.60))),
        "spd": max(1, int(round(avg_spd * 0.70))),
        "acc": max(1, int(round(avg_acc * 1.05))),
        "cri": max(1, int(round(avg_cri))),
        "_is_layer1_boss": True,
        "_crit_multiplier": 1.2,
    }


def _boss_area_label(area_key):
    return AREA_BOSS_LABELS.get(area_key, area_key)


def _area_supports_boss_alert(area_key):
    return area_key in AREA_BOSS_ALERT_AREAS


def _boss_area_key_for_route(area_key):
    layer = _area_layer(area_key)
    if layer in (1, 2, 3):
        return f"layer_{layer}"
    return area_key


def _boss_reward_area_key(area_key):
    key = str(area_key or "").strip()
    if not key:
        return ""
    if key in AREA_BOSS_DECOR_REWARD_KEYS:
        return key
    return _boss_area_key_for_route(key)


def _is_npc_boss_alert_id(enemy_id):
    try:
        value = int(enemy_id)
    except Exception:
        return False
    return value <= -int(NPC_BOSS_ALERT_ID_OFFSET)


def _encode_npc_boss_alert_id(template_id):
    return -int(NPC_BOSS_ALERT_ID_OFFSET) - int(template_id)


def _decode_npc_boss_alert_id(enemy_id):
    if not _is_npc_boss_alert_id(enemy_id):
        return None
    return abs(int(enemy_id)) - int(NPC_BOSS_ALERT_ID_OFFSET)


def _resolve_npc_faction(raw_faction):
    key = _normalize_faction_key(raw_faction)
    return key if key in NPC_BOSS_IMAGE_BY_FACTION else "aurix"


def _npc_boss_special_line(faction_key):
    faction = _resolve_npc_faction(faction_key)
    if faction == "ignis":
        return "未知の戦闘データをもつ侵食機"
    if faction == "ventra":
        return "他機体由来の模倣戦闘体"
    return "残響データを再構成した模倣機"


def _build_npc_boss_enemy_payload(template_row):
    if not template_row:
        return None
    row = dict(template_row)
    faction_key = _resolve_npc_faction(row.get("source_faction"))
    image_path = row.get("image_path") or NPC_BOSS_IMAGE_BY_FACTION.get(faction_key) or "assets/placeholder_enemy.png"
    tier = 2 if str(row.get("boss_area_key") or "layer_2") == "layer_2" else 3
    return {
        "id": None,
        "key": row.get("enemy_key"),
        "name_ja": row.get("enemy_name_ja") or "侵食機",
        "image_path": image_path,
        "tier": int(tier),
        "element": "NORMAL",
        "hp": int(row.get("hp") or 1),
        "atk": int(row.get("atk") or 1),
        "def": int(row.get("def") or 0),
        "spd": int(row.get("spd") or 1),
        "acc": int(row.get("acc") or 1),
        "cri": int(row.get("cri") or 1),
        "faction": faction_key,
        "trait": None,
        "is_boss": 1,
        "boss_area_key": row.get("boss_area_key"),
        "_boss_kind": "npc",
        "_npc_boss_template_id": int(row.get("id") or 0),
        "_source_robot_instance_id": int(row.get("source_robot_instance_id") or 0),
        "_source_user_id": int(row.get("source_user_id") or 0),
        "_source_faction": faction_key,
        "_special_line": _npc_boss_special_line(faction_key),
        "_alert_enemy_id": _encode_npc_boss_alert_id(int(row.get("id") or 0)),
    }


def pick_npc_boss_for_area(db, area_key):
    area = str(area_key or "").strip()
    if area not in NPC_BOSS_ALLOWED_AREAS:
        return None
    rows = db.execute(
        """
        SELECT *
        FROM npc_boss_templates
        WHERE is_active = 1
          AND boss_area_key = ?
        ORDER BY updated_at DESC, id DESC
        """,
        (area,),
    ).fetchall()
    if not rows:
        return None
    weights = [max(0.01, float(r["spawn_weight"] or 1.0)) for r in rows]
    picked = random.choices(rows, weights=weights, k=1)[0]
    return _build_npc_boss_enemy_payload(picked)


def create_npc_boss_from_active_robot(user_id, defeated_boss_area_key):
    area_key = str(defeated_boss_area_key or "").strip()
    if area_key not in NPC_BOSS_ALLOWED_AREAS:
        return None
    db = get_db()
    user_state = db.execute("SELECT active_robot_id, faction FROM users WHERE id = ?", (int(user_id),)).fetchone()
    if not user_state or not user_state["active_robot_id"]:
        return None
    active = db.execute(
        "SELECT id, name FROM robot_instances WHERE id = ? AND user_id = ? AND status = 'active' LIMIT 1",
        (int(user_state["active_robot_id"]), int(user_id)),
    ).fetchone()
    if not active:
        return None
    active = dict(active)
    stats_payload = _compute_robot_stats_for_instance(db, int(active["id"]))
    if not stats_payload:
        return None
    stats = stats_payload.get("stats") or {}
    player_hp = max(1, int(stats.get("hp") or 1))
    player_atk = max(1, int(stats.get("atk") or 1))
    player_def = max(0, int(stats.get("def") or 0))
    player_spd = max(1, int(stats.get("spd") or 1))
    player_acc = max(1, int(stats.get("acc") or 1))
    player_cri = max(1, int(stats.get("cri") or 1))
    source_faction = _resolve_npc_faction(user_state["faction"] if "faction" in user_state.keys() else None)
    enemy_key = f"npc_boss_r{int(active['id'])}_{area_key}"
    enemy_name = NPC_BOSS_NAME_BY_FACTION.get(source_faction, "侵食機")
    image_path = NPC_BOSS_IMAGE_BY_FACTION.get(source_faction, "assets/placeholder_enemy.png")
    now_ts = int(time.time())
    existing = db.execute(
        "SELECT id FROM npc_boss_templates WHERE source_robot_instance_id = ? AND boss_area_key = ? LIMIT 1",
        (int(active["id"]), area_key),
    ).fetchone()
    if existing:
        db.execute(
            """
            UPDATE npc_boss_templates
            SET source_user_id = ?,
                source_faction = ?,
                source_robot_name = ?,
                enemy_key = ?,
                enemy_name_ja = ?,
                image_path = ?,
                hp = ?,
                atk = ?,
                def = ?,
                spd = ?,
                acc = ?,
                cri = ?,
                spawn_weight = 1.0,
                is_active = 1,
                updated_at = ?
            WHERE id = ?
            """,
            (
                int(user_id),
                source_faction,
                str(active.get("name") or ""),
                enemy_key,
                enemy_name,
                image_path,
                int(round(player_hp * 1.35)),
                max(1, int(round(player_atk * 0.90))),
                max(0, int(round(player_def * 0.90))),
                player_spd,
                player_acc,
                player_cri,
                now_ts,
                int(existing["id"]),
            ),
        )
        template_id = int(existing["id"])
    else:
        cur = db.execute(
            """
            INSERT INTO npc_boss_templates
            (source_user_id, source_robot_instance_id, source_faction, source_robot_name, boss_area_key, enemy_key, enemy_name_ja, image_path, hp, atk, def, spd, acc, cri, spawn_weight, is_active, created_at, updated_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 1.0, 1, ?, ?)
            """,
            (
                int(user_id),
                int(active["id"]),
                source_faction,
                str(active.get("name") or ""),
                area_key,
                enemy_key,
                enemy_name,
                image_path,
                int(round(player_hp * 1.35)),
                max(1, int(round(player_atk * 0.90))),
                max(0, int(round(player_def * 0.90))),
                player_spd,
                player_acc,
                player_cri,
                now_ts,
                now_ts,
            ),
        )
        template_id = int(cur.lastrowid)
    return db.execute("SELECT * FROM npc_boss_templates WHERE id = ?", (template_id,)).fetchone()


def _layer_label(layer_no):
    n = int(layer_no or 1)
    return AREA_BOSS_LABELS.get(f"layer_{n}", f"第{n}層")


def _boss_battle_bg_path(enemy_row, is_area_boss):
    if not is_area_boss or not enemy_row:
        return None
    faction = ((enemy_row["faction"] if "faction" in enemy_row.keys() else "") or "").strip().lower()
    faction_map = {
        "aurix": "backgrounds/boss/aurix.png",
        "ventra": "backgrounds/boss/ventra.png",
        "ignis": "backgrounds/boss/ignis.png",
    }
    if faction in faction_map:
        return faction_map[faction]
    key = ((enemy_row["key"] if "key" in enemy_row.keys() else "") or "").strip().lower()
    for token in ("aurix", "ventra", "ignis"):
        if token in key:
            return f"backgrounds/boss/{token}.png"
    return None


def _battle_replay_bias(value, *, low, high):
    score = int(value or 0)
    if score >= int(high):
        return "high"
    if score <= int(low):
        return "low"
    return "normal"


def _battle_replay_theme(area_key, is_boss=False):
    if is_boss:
        return "boss"
    key = str(area_key or "").strip().lower()
    if "mist" in key:
        return "mist"
    if "forge" in key or key.startswith("layer_4"):
        return "forge"
    if "lab" in key or "maze" in key or key.startswith("layer_5"):
        return "lab"
    if "goal" in key:
        return "goal"
    if key.startswith("layer_2"):
        return "mist"
    if key.startswith("layer_3"):
        return "scrap"
    if key.startswith("layer_1"):
        return "workshop"
    return "hangar"


def _battle_replay_visual_traits(player_stats, robot_style=None):
    stats = player_stats or {}
    hp = max(1, int(stats.get("hp") or 0))
    atk = max(1, int(stats.get("atk") or 0))
    defn = max(1, int(stats.get("def") or 0))
    spd = max(1, int(stats.get("spd") or 0))
    acc = max(1, int(stats.get("acc") or 0))
    cri = max(1, int(stats.get("cri") or 0))
    defense_score = int(round((hp + defn * 2) / 3.0))
    burst_score = int(round((atk * 2 + cri) / 3.0))
    style_key = ((robot_style or {}).get("style_key") or "stable").strip().lower()
    return {
        "style_key": style_key,
        "speed_bias": _battle_replay_bias(spd, low=8, high=13),
        "accuracy_bias": _battle_replay_bias(acc, low=8, high=13),
        "burst_bias": _battle_replay_bias(burst_score, low=8, high=13),
        "defense_bias": _battle_replay_bias(defense_score, low=9, high=14),
    }


def _battle_replay_is_miss(action_name, damage_value):
    action = str(action_name or "").strip()
    if action in {"", "行動不能", "追撃不要"}:
        return False
    return int(damage_value or 0) <= 0


def _battle_replay_event(
    event_type,
    label,
    *,
    actor=None,
    target=None,
    projectile=None,
    reaction=None,
    player_hp=None,
    player_hp_max=None,
    enemy_hp=None,
    enemy_hp_max=None,
    duration_ms=None,
    crit=False,
    heavy=False,
):
    return {
        "type": str(event_type or "").strip(),
        "label": str(label or "").strip(),
        "actor": (str(actor or "").strip() or None),
        "target": (str(target or "").strip() or None),
        "projectile": (str(projectile or "").strip() or None),
        "reaction": (str(reaction or "").strip() or None),
        "player_hp": (int(player_hp) if player_hp is not None else None),
        "player_hp_max": (int(player_hp_max) if player_hp_max is not None else None),
        "enemy_hp": (int(enemy_hp) if enemy_hp is not None else None),
        "enemy_hp_max": (int(enemy_hp_max) if enemy_hp_max is not None else None),
        "duration_ms": (int(duration_ms) if duration_ms is not None else None),
        "crit": bool(crit),
        "heavy": bool(heavy),
    }


BATTLE_CINEMATIC_STATE_META = {
    "armor_crack": {
        "label": "装甲亀裂",
        "tactical": "装甲が揺らいだ",
        "priority": 20,
    },
    "sensor_glitch": {
        "label": "センサー異常",
        "tactical": "補足精度が乱れた",
        "priority": 30,
    },
    "drive_drop": {
        "label": "駆動低下",
        "tactical": "機動が鈍った",
        "priority": 40,
    },
    "weapon_unstable": {
        "label": "武装不安定",
        "tactical": "出力が安定しない",
        "priority": 50,
    },
    "output_surge": {
        "label": "出力暴走",
        "tactical": "高出力へ移行",
        "priority": 60,
    },
    "stance_hold": {
        "label": "体勢維持",
        "tactical": "体勢を崩していない",
        "priority": 10,
    },
}


def _build_battle_replay_summary(
    *,
    area_key,
    area_label,
    enemy_name,
    enemy_image_url,
    player_name,
    player_image_url,
    player_stats,
    enemy_stats,
    robot_style,
    turn_logs,
    outcome,
    is_boss=False,
):
    logs = [dict(item) for item in (turn_logs or []) if isinstance(item, dict) and not item.get("separator_line")]
    if not logs:
        return None

    outcome_text = str(outcome or "").strip()
    player_won = outcome_text in {"win", "勝利", "判定勝ち"}
    outcome_sub_label = (
        outcome_text
        if outcome_text in {"判定勝ち", "判定負け"}
        else ("勝利" if player_won else "敗北")
    )
    player_traits = _battle_replay_visual_traits(player_stats, robot_style)
    enemy_trait = _normalize_enemy_trait((enemy_stats or {}).get("trait"))
    enemy_speed = int((enemy_stats or {}).get("spd") or 0)
    player_speed = int((player_stats or {}).get("spd") or 0)
    player_first = player_speed >= enemy_speed
    first_row = logs[0]
    player_hp_max = max(1, int(first_row.get("player_max") or player_stats.get("hp") or 1))
    enemy_hp_max = max(1, int(first_row.get("enemy_max") or enemy_stats.get("hp") or 1))
    player_hp_start = int(first_row.get("player_before") or player_hp_max)
    enemy_hp_start = int(first_row.get("enemy_before") or enemy_hp_max)
    enemy_speed_bias = _battle_replay_bias(enemy_speed, low=8, high=13)

    def _ratio(hp_value, hp_max):
        return max(0.0, min(1.0, float(int(hp_value or 0)) / max(1, int(hp_max or 1))))

    def _effect_meta(effect_key):
        return BATTLE_CINEMATIC_STATE_META.get(str(effect_key or "").strip(), {})

    def _effect_priority(effect_key):
        return int(_effect_meta(effect_key).get("priority") or 0)

    def _row_has_action(side, row):
        action = str((row or {}).get(f"{side}_action") or "").strip()
        return action not in {"", "行動不能", "追撃不要"}

    def _action_family(action_name):
        action = str(action_name or "").strip()
        if any(token in action for token in ("砲", "射", "バースト", "ビーム")):
            return "shot"
        if any(token in action for token in ("斬", "スラッシュ", "ブレード")):
            return "slash"
        if any(token in action for token in ("防", "ガード", "受け")):
            return "guard"
        return "strike"

    def _action_label(side, action_name, hit_type, *, crit=False, finisher=False):
        family = _action_family(action_name)
        if hit_type == "miss":
            return "補足失敗"
        if hit_type == "block":
            return "防壁で軽減"
        if finisher and crit:
            return "会心で制圧"
        if finisher:
            return "決着の一撃"
        if crit:
            return "高出力攻撃"
        if family == "shot":
            return "砲撃命中"
        if family == "slash":
            return "斬撃命中"
        if family == "guard":
            return "防御姿勢"
        return "攻撃命中"

    def _result_label(hit_type, damage_value, *, actor, target):
        damage = int(damage_value or 0)
        if hit_type == "miss":
            return f"{target} は回避"
        if hit_type == "block":
            return f"{target} が受け切った"
        if hit_type == "crit":
            return f"{target} に会心 -{damage}"
        if damage > 0:
            return f"{target} に -{damage}"
        return f"{actor} が仕掛けた"

    def _value_label(hit_type, damage_value):
        damage = int(damage_value or 0)
        if hit_type == "miss":
            return "MISS"
        if hit_type == "block":
            return "BLOCK"
        if damage > 0:
            return f"-{damage}"
        return ""

    def _row_int(row, key, fallback=0):
        row = row or {}
        value = row.get(key)
        if value in (None, ""):
            return int(fallback)
        return int(value)

    def _laser_element(raw_value):
        raw = str(raw_value or "").strip().upper()
        if raw in {"FIRE", "FLAME"}:
            return "fire"
        if raw in {"WATER", "ICE"}:
            return "water"
        if raw in {"THUNDER", "LIGHTNING", "ELECTRIC"}:
            return "thunder"
        if raw == "WIND":
            return "wind"
        if raw == "DARK":
            return "dark"
        if raw == "LIGHT":
            return "light"
        return "neutral"

    def _stats_element(stats):
        stats = stats or {}
        for key in ("attack_element", "element", "set_bonus", "robot_element"):
            value = stats.get(key)
            if value:
                return value
        parts = [part for part in (stats.get("parts") or []) if isinstance(part, dict)]
        part_elements = [str(part.get("element") or "").strip().upper() for part in parts if part.get("element")]
        if part_elements and len(set(part_elements)) == 1:
            return part_elements[0]
        if part_elements:
            counts = {}
            for element in part_elements:
                if element in {"", "NORMAL", "NEUTRAL"}:
                    continue
                counts[element] = counts.get(element, 0) + 1
            if counts:
                return sorted(counts.items(), key=lambda item: (-item[1], item[0]))[0][0]
        return None

    player_laser_element = _laser_element(_stats_element(player_stats))
    enemy_laser_element = _laser_element(_stats_element(enemy_stats))

    def _step_element(side, row):
        row = row or {}
        for key in (f"{side}_attack_element", "attack_element", f"{side}_element"):
            value = row.get(key)
            if value:
                return _laser_element(value)
        return player_laser_element if side == "player" else enemy_laser_element

    def _infer_step_effect(*, side, row, damage, hit_type, crit, target_side, target_after, target_max):
        row = row or {}
        if hit_type == "miss":
            return "sensor_glitch", side, _effect_meta("sensor_glitch").get("tactical")
        if crit and damage > 0:
            return "output_surge", side, _effect_meta("output_surge").get("tactical")
        if side == "enemy" and enemy_trait == "unstable" and damage > 0:
            return "weapon_unstable", side, _effect_meta("weapon_unstable").get("tactical")
        if side == "enemy" and enemy_trait == "berserk" and damage > 0 and _row_int(row, "enemy_before", enemy_hp_start) * 2 <= enemy_hp_max:
            return "output_surge", side, _effect_meta("output_surge").get("tactical")
        damage_ratio = float(damage) / max(1, int(target_max or 1))
        if damage_ratio >= 0.34 or (damage > 0 and int(target_after or 0) <= 0):
            return "armor_crack", target_side, _effect_meta("armor_crack").get("tactical")
        if target_side == "enemy" and enemy_speed_bias == "high" and damage > 0:
            return "drive_drop", target_side, _effect_meta("drive_drop").get("tactical")
        if hit_type == "block":
            return "stance_hold", target_side, _effect_meta("stance_hold").get("tactical")
        if damage > 0 and int(target_after or 0) > 0 and _ratio(target_after, target_max) <= 0.12:
            return "stance_hold", target_side, "体勢を崩さず踏みとどまった"
        return None, None, None

    def _infer_turn_brace(row):
        row = row or {}
        damage = int(row.get("enemy_damage") or 0)
        player_after = _row_int(row, "player_after", 0)
        if damage <= 0 or player_after <= 0:
            return None
        player_before = _row_int(row, "player_before", player_hp_start)
        severe_drop = (player_before - player_after) >= max(4, int(math.ceil(player_hp_max * 0.22)))
        near_break = player_after <= max(1, int(math.ceil(player_hp_max * 0.1)))
        if severe_drop or near_break:
            return {
                "effect": "stance_hold",
                "target": "player",
                "tactical": "体勢維持で踏みとどまった",
            }
        return None

    def _turn_tactical(row, step_effect):
        if step_effect and step_effect.get("tactical"):
            return str(step_effect.get("tactical"))
        player_damage = int((row or {}).get("player_damage") or 0)
        enemy_damage = int((row or {}).get("enemy_damage") or 0)
        player_missed = _battle_replay_is_miss((row or {}).get("player_action"), player_damage)
        enemy_missed = _battle_replay_is_miss((row or {}).get("enemy_action"), enemy_damage)
        if player_damage > enemy_damage:
            return "制圧を維持"
        if enemy_damage > player_damage:
            return "押し返されている"
        if player_missed or enemy_missed:
            return "補足差を探っている"
        return "体勢を探り合っている"

    def _turn_duration(turn_payload):
        steps = list(turn_payload.get("steps") or [])
        has_status = bool(turn_payload.get("status_effect"))
        has_crit = any(str(step.get("hit_type") or "") == "crit" for step in steps)
        has_finisher = any(bool(step.get("is_finisher")) for step in steps)
        base_standard = 1420 if not is_boss else 1820
        standard_duration = base_standard + len(steps) * 240
        if has_status:
            standard_duration += 200
        if has_crit:
            standard_duration += 220
        if has_finisher:
            standard_duration += 320
        standard_duration = int(
            max(
                1550 if not is_boss else 2100,
                min(
                    2050 if not is_boss else 2750,
                    standard_duration,
                ),
            )
        )
        fast_duration = int(max(760 if not is_boss else 980, min(1650, round(standard_duration * 0.58))))
        return standard_duration, fast_duration

    def _summary_label():
        player_total_damage = sum(max(0, int(row.get("player_damage") or 0)) for row in logs)
        enemy_total_damage = sum(max(0, int(row.get("enemy_damage") or 0)) for row in logs)
        player_miss_count = sum(
            1 for row in logs if _battle_replay_is_miss(row.get("player_action"), row.get("player_damage"))
        )
        enemy_miss_count = sum(
            1 for row in logs if _battle_replay_is_miss(row.get("enemy_action"), row.get("enemy_damage"))
        )
        player_crit_count = sum(1 for row in logs if bool(row.get("critical")))
        if player_won:
            if player_traits.get("burst_bias") == "high" or player_crit_count >= 1:
                return "爆発力で押し切った"
            if player_traits.get("accuracy_bias") == "high" or enemy_miss_count >= 1:
                return "命中安定で崩した"
            if player_traits.get("defense_bias") == "high" or enemy_total_damage <= int(math.ceil(player_hp_max * 0.35)):
                return "体勢維持で受け切った"
            if player_first and player_traits.get("speed_bias") == "high":
                return "先手制圧で押し切った"
            return "装甲差で競り勝った"
        if enemy_total_damage >= int(math.ceil(player_hp_max * 0.6)):
            return "火力差を受け切れなかった"
        if player_miss_count >= 2:
            return "命中差を返せなかった"
        if not player_first and enemy_miss_count == 0:
            return "先手を失って崩れた"
        return "崩れから立て直せなかった"

    def _step_payload(side, row):
        row = row or {}
        if not _row_has_action(side, row):
            return None
        actor_name = player_name if side == "player" else enemy_name
        target_side = "enemy" if side == "player" else "player"
        target_name = enemy_name if side == "player" else player_name
        damage = int(row.get(f"{side}_damage") or 0)
        note = str(row.get(f"{side}_attack_note") or "")
        crit = bool(row.get("critical")) if side == "player" else False
        hit_type = "hit"
        if _battle_replay_is_miss(row.get(f"{side}_action"), damage):
            hit_type = "miss"
        elif damage <= 0:
            hit_type = "block" if any(token in note for token in ("防", "軽減", "受け", "遮断")) else "block"
        elif crit:
            hit_type = "crit"

        player_before = _row_int(row, "player_before", player_hp_start)
        enemy_before = _row_int(row, "enemy_before", enemy_hp_start)
        player_after_turn = _row_int(row, "player_after", player_before)
        enemy_after_turn = _row_int(row, "enemy_after", enemy_before)

        if player_first:
            if side == "player":
                step_player_after = player_before
                step_enemy_after = enemy_after_turn
            else:
                step_player_after = player_after_turn
                step_enemy_after = enemy_after_turn
        else:
            if side == "enemy":
                step_player_after = player_after_turn
                step_enemy_after = enemy_after_turn if not _row_has_action("player", row) else enemy_before
            else:
                step_player_after = player_after_turn
                step_enemy_after = enemy_after_turn

        target_after = step_enemy_after if target_side == "enemy" else step_player_after
        target_max = enemy_hp_max if target_side == "enemy" else player_hp_max
        is_finisher = damage > 0 and int(target_after or 0) <= 0
        status_effect, status_target, tactical_label = _infer_step_effect(
            side=side,
            row=row,
            damage=damage,
            hit_type=hit_type,
            crit=crit,
            target_side=target_side,
            target_after=target_after,
            target_max=target_max,
        )
        return {
            "actor": side,
            "actor_name": actor_name,
            "target": target_side,
            "target_name": target_name,
            "action_name": str(row.get(f"{side}_action") or "攻撃"),
            "action_label": _action_label(side, row.get(f"{side}_action"), hit_type, crit=crit, finisher=is_finisher),
            "result_label": _result_label(hit_type, damage, actor=actor_name, target=target_name),
            "value_label": _value_label(hit_type, damage),
            "element": _step_element(side, row),
            "hit_type": hit_type,
            "is_finisher": bool(is_finisher),
            "projectile": ("shot" if hit_type != "block" else "guard"),
            "status_effect": status_effect,
            "status_target": status_target,
            "tactical_label": tactical_label,
            "player_hp_after": int(step_player_after),
            "enemy_hp_after": int(step_enemy_after),
            "player_hp_ratio_after": _ratio(step_player_after, player_hp_max),
            "enemy_hp_ratio_after": _ratio(step_enemy_after, enemy_hp_max),
            "critical": bool(crit),
        }

    flattened_steps = []
    turns = []
    ordered_sides = ("player", "enemy") if player_first else ("enemy", "player")
    for index, row in enumerate(logs, start=1):
        steps = []
        turn_effect = None
        turn_tactical = None
        for side in ordered_sides:
            step = _step_payload(side, row)
            if not step:
                continue
            steps.append(step)
            flattened_steps.append(step)
            if step.get("status_effect") and _effect_priority(step.get("status_effect")) >= _effect_priority(
                (turn_effect or {}).get("effect")
            ):
                turn_effect = {
                    "effect": step.get("status_effect"),
                    "target": step.get("status_target"),
                    "tactical": step.get("tactical_label"),
                }
            if step.get("is_finisher"):
                break
        brace_effect = _infer_turn_brace(row)
        if brace_effect and _effect_priority(brace_effect.get("effect")) >= _effect_priority((turn_effect or {}).get("effect")):
            turn_effect = brace_effect
        turn_tactical = _turn_tactical(row, turn_effect)
        effect_meta = _effect_meta((turn_effect or {}).get("effect"))
        turn_payload = {
            "turn": index,
            "opening_actor": ordered_sides[0],
            "opening_label": f"{player_name if ordered_sides[0] == 'player' else enemy_name} が先手",
            "steps": steps,
            "status_effect": (turn_effect or {}).get("effect"),
            "status_label": effect_meta.get("label"),
            "status_target": (turn_effect or {}).get("target"),
            "tactical_label": turn_tactical,
            "player_hp_ratio_after": _ratio(_row_int(row, "player_after", player_hp_start), player_hp_max),
            "enemy_hp_ratio_after": _ratio(_row_int(row, "enemy_after", enemy_hp_start), enemy_hp_max),
            "player_hp_after": _row_int(row, "player_after", player_hp_start),
            "enemy_hp_after": _row_int(row, "enemy_after", enemy_hp_start),
        }
        standard_duration, fast_duration = _turn_duration(turn_payload)
        turn_payload["standard_duration_ms"] = int(standard_duration)
        turn_payload["fast_duration_ms"] = int(fast_duration)
        turns.append(turn_payload)
        if turn_payload["player_hp_after"] <= 0 or turn_payload["enemy_hp_after"] <= 0:
            break

    summary_label = _summary_label()
    summary_heading = "今回の勝ち筋" if player_won else "今回の崩れ筋"
    intro_delay_ms = 520 if not is_boss else 760
    outro_hold_ms = 860 if not is_boss else 1320
    fast_intro_delay_ms = 220 if not is_boss else 340
    fast_outro_hold_ms = 380 if not is_boss else 520
    return {
        "version": "v1",
        "battle_type": ("boss" if is_boss else "normal"),
        "is_boss": bool(is_boss),
        "player_won": bool(player_won),
        "stage_theme": _battle_replay_theme(area_key, is_boss=is_boss),
        "area_key": str(area_key or ""),
        "area_label": str(area_label or ""),
        "turn_count": int(len(turns)),
        "winner": ("player" if player_won else "enemy"),
        "summary_heading": summary_heading,
        "summary_label": summary_label,
        "result_label": ("BOSS DEFEATED" if is_boss and player_won else ("WIN" if player_won else "LOSE")),
        "result_sub_label": outcome_sub_label,
        "player_name": str(player_name or "あなた"),
        "enemy_name": str(enemy_name or "謎の敵"),
        "player_image_url": player_image_url,
        "enemy_image_url": enemy_image_url,
        "player_hp_start": int(player_hp_start),
        "player_hp_max": int(player_hp_max),
        "enemy_hp_start": int(enemy_hp_start),
        "enemy_hp_max": int(enemy_hp_max),
        "player_element": player_laser_element,
        "enemy_element": enemy_laser_element,
        "player_visual_traits": player_traits,
        "enemy_visual_traits": {
            "trait": enemy_trait or "normal",
            "speed_bias": enemy_speed_bias,
        },
        "events": list(flattened_steps),
        "turns": turns,
        "intro_delay_ms": int(intro_delay_ms),
        "outro_hold_ms": int(outro_hold_ms),
        "fast_intro_delay_ms": int(fast_intro_delay_ms),
        "fast_outro_hold_ms": int(fast_outro_hold_ms),
    }


def _battle_timeout_judgement(*, player_hp, player_hp_max, enemy_hp, enemy_hp_max):
    def _ratio(hp_value, hp_max_value):
        return max(0.0, min(1.0, float(int(hp_value or 0)) / max(1, int(hp_max_value or 1))))

    player_ratio = _ratio(player_hp, player_hp_max)
    enemy_ratio = _ratio(enemy_hp, enemy_hp_max)
    player_wins = player_ratio > enemy_ratio
    outcome = "win" if player_wins else "lose"
    display_outcome = "判定勝ち" if player_wins else "判定負け"
    return {
        "player_ratio": float(player_ratio),
        "enemy_ratio": float(enemy_ratio),
        "player_ratio_pct": round(player_ratio * 100.0, 1),
        "enemy_ratio_pct": round(enemy_ratio * 100.0, 1),
        "player_wins": bool(player_wins),
        "outcome": outcome,
        "display_outcome": display_outcome,
        "result_line": f"8ターン終了。残HP割合で{display_outcome}",
    }


def should_disable_turn_limit(area_key):
    return _area_layer(str(area_key or "").strip()) >= 4


def get_battle_turn_limit(area_key, is_boss=False):
    del is_boss
    if should_disable_turn_limit(area_key):
        return None
    return int(EXPLORE_MAX_TURNS)


def _battle_max_turns_for(*, area_key, is_boss=False):
    turn_limit = get_battle_turn_limit(area_key, is_boss=is_boss)
    return int(HARD_BATTLE_TURN_CAP if turn_limit is None else turn_limit)


def _hard_battle_turn_cap_judgement(*, area_key, is_boss=False):
    return {
        "player_ratio": None,
        "enemy_ratio": None,
        "player_ratio_pct": None,
        "enemy_ratio_pct": None,
        "player_wins": False,
        "outcome": "lose",
        "display_outcome": "敗北",
        "reason": "hard_turn_cap",
        "turn_limit_removed": True,
        "safety_turn_cap": int(HARD_BATTLE_TURN_CAP),
        "area_key": str(area_key or ""),
        "is_boss": bool(is_boss),
        "result_line": "試験継続不能。機体反応が限界に達しました。",
    }


def _boss_type_code(enemy_row):
    if not enemy_row:
        return None
    key = ((enemy_row.get("key") if isinstance(enemy_row, dict) else enemy_row["key"]) or "").strip().lower()
    return AREA_BOSS_TYPE_BY_KEY.get(key)


def _boss_type_meta(enemy_row):
    code = _boss_type_code(enemy_row)
    if not code:
        return None
    profile = AREA_BOSS_TYPE_PROFILES.get(code, {})
    return {
        "code": code,
        "label_ja": profile.get("label_ja", code),
        "recommend_build": profile.get("recommend_build", "自由"),
        "icon": profile.get("icon", ""),
    }


def _boss_recommendation_for_type(boss_type):
    return BOSS_TYPE_RECOMMENDED_BUILD.get((boss_type or "").upper())


def _apply_boss_type_modifiers(enemy_row):
    enemy = dict(enemy_row or {})
    meta = _boss_type_meta(enemy)
    if not meta:
        return enemy
    profile = AREA_BOSS_TYPE_PROFILES.get(meta["code"], {})
    mult = profile.get("mult", {})
    for stat in ("hp", "atk", "def", "acc"):
        base = int(enemy.get(stat) or 0)
        factor = float(mult.get(stat, 1.0))
        enemy[stat] = max(1, int(round(base * factor)))
    enemy["_boss_type"] = meta["code"]
    enemy["_boss_type_label"] = meta["label_ja"]
    enemy["_boss_type_recommend"] = meta["recommend_build"]
    enemy["_boss_type_icon"] = meta["icon"]
    return enemy


def _arch_key_for_hit(archetype):
    if isinstance(archetype, dict):
        return (archetype.get("key") or "none").lower()
    if isinstance(archetype, str):
        return archetype.lower()
    return "none"


def _hit_debug(att_acc, def_acc, attacker_archetype):
    att_key = _arch_key_for_hit(attacker_archetype)
    hit_bonus = 0.03 if att_key == "sniper" else 0.0
    hit_chance = _clamp(0.75 + (int(att_acc) - int(def_acc)) * 0.01 + hit_bonus, 0.60, 0.95)
    return {
        "hit_chance": float(hit_chance),
        "att_acc": int(att_acc),
        "def_acc": int(def_acc),
        "hit_bonus": float(hit_bonus),
    }


def _resolve_attack_logged(
    att_atk,
    att_acc,
    att_cri,
    def_def,
    def_acc,
    *,
    rng,
    attacker_archetype=None,
    defender_archetype=None,
    attacker_is_first_striker=False,
    crit_multiplier=1.5,
    force_hit=False,
    damage_noise_range=None,
):
    fallback = _hit_debug(att_acc, def_acc, attacker_archetype)
    result = resolve_attack(
        att_atk,
        att_acc,
        att_cri,
        def_def,
        def_acc,
        rng=rng,
        attacker_archetype=attacker_archetype,
        defender_archetype=defender_archetype,
        attacker_is_first_striker=attacker_is_first_striker,
        crit_multiplier=crit_multiplier,
        force_hit=force_hit,
        return_detail=True,
        damage_noise_range=damage_noise_range,
    )
    if isinstance(result, tuple) and len(result) >= 3 and isinstance(result[2], dict):
        damage, critical, detail = result[0], result[1], dict(result[2])
        detail.setdefault("hit_chance", fallback["hit_chance"])
        detail.setdefault("att_acc", fallback["att_acc"])
        detail.setdefault("def_acc", fallback["def_acc"])
        detail.setdefault("hit_bonus", fallback["hit_bonus"])
        detail.setdefault("hit_forced", bool(force_hit))
        detail.setdefault("miss", int(damage) <= 0)
        return int(damage), bool(critical), detail
    if isinstance(result, tuple) and len(result) >= 2:
        damage, critical = result[0], result[1]
    else:
        damage, critical = 0, False
    detail = {
        **fallback,
        "hit_forced": bool(force_hit),
        "miss": int(damage) <= 0,
    }
    return int(damage), bool(critical), detail


def _is_stable_element_build(parts):
    if not parts or len(parts) != 4:
        return False
    elems = [((p.get("element") if isinstance(p, dict) else None) or "").upper() for p in parts]
    if any(not e for e in elems):
        return False
    return len(set(elems)) == 1


def _build_type_from_parts(parts):
    return "STABLE" if _is_stable_element_build(parts) else "BURST"


def _stat_label(stat_key):
    key = str(stat_key or "").strip()
    lowered = key.lower()
    if lowered in STAT_UI_LABELS:
        return STAT_UI_LABELS[lowered]
    mapped = STAT_ABBR_TO_KEY.get(key.upper())
    if mapped:
        return STAT_UI_LABELS.get(mapped, key)
    return key


def _humanize_stat_text(text):
    out = str(text or "")
    for abbr, key in STAT_ABBR_TO_KEY.items():
        out = out.replace(abbr, STAT_UI_LABELS.get(key, abbr))
    return out


def _robot_style_battle_line(style_key):
    key = _normalize_style_key(style_key)
