def _set_bonus_catalog_rows():
    rows = []
    for element_key, element_label in ELEMENTS:
        bonus = SET_BONUS_TABLE.get(str(element_key or "").upper())
        if not bonus:
            continue
        stat_key, rate = bonus
        rows.append(
            {
                "element_key": str(element_key),
                "element_label": str(element_label),
                "stat_key": str(stat_key),
                "stat_label": _stat_label(stat_key),
                "rate": float(rate),
                "rate_text": f"+{int(round(float(rate) * 100))}%",
                "summary_text": f"{element_label}: {_stat_label(stat_key)} +{int(round(float(rate) * 100))}%",
            }
        )
    return rows


def _set_bonus_base_stats(parts):
    total = {key: 0 for key in PART_STAT_KEYS}
    for part in parts or ():
        if not part:
            continue
        computed = compute_part_stats(part)
        for key in PART_STAT_KEYS:
            total[key] += int(computed.get(key) or 0)
    return total


def _set_bonus_view_for_loadout(parts, set_bonus_key=None, disabled_reason=None):
    if disabled_reason:
        rows = _set_bonus_catalog_rows()
        return {
            "active": False,
            "status_label": "なし",
            "condition_text": str(disabled_reason),
            "element_key": None,
            "element_label": None,
            "stat_key": None,
            "stat_label": None,
            "rate_text": "",
            "delta_value": 0,
            "effect_text": "セットボーナスなし",
            "detail_text": "実験機：自由編成のためセットボーナスなし",
            "hint_text": "固定フレームで組むとセットボーナス対象になります。",
            "catalog_rows": rows,
        }
    active_key = str(set_bonus_key or "").strip().upper()
    rows = _set_bonus_catalog_rows()
    if active_key and active_key in SET_BONUS_TABLE:
        stat_key, rate = SET_BONUS_TABLE[active_key]
        base_stats = _set_bonus_base_stats(parts)
        before_value = int(base_stats.get(stat_key) or 0)
        boosted_value = int(math.ceil(before_value * (1.0 + float(rate))))
        if before_value > 0:
            boosted_value = max(before_value + 1, boosted_value)
        delta_value = max(0, int(boosted_value - before_value))
        return {
            "active": True,
            "status_label": "発動中",
            "condition_text": "同属性パーツ 4部位で発動",
            "element_key": active_key,
            "element_label": ELEMENT_LABEL_MAP.get(active_key, active_key),
            "stat_key": str(stat_key),
            "stat_label": _stat_label(stat_key),
            "rate_text": f"+{int(round(float(rate) * 100))}%",
            "delta_value": int(delta_value),
            "effect_text": f"{_stat_label(stat_key)} +{int(delta_value)}",
            "detail_text": f"{ELEMENT_LABEL_MAP.get(active_key, active_key)}統一で {_stat_label(stat_key)} が {before_value} → {boosted_value}",
            "hint_text": "4部位が同じ属性なら、対応能力が自動で伸びます。",
            "catalog_rows": rows,
        }
    return {
        "active": False,
        "status_label": "未発動",
        "condition_text": "同属性パーツ 4部位で発動",
        "element_key": None,
        "element_label": None,
        "stat_key": None,
        "stat_label": None,
        "rate_text": "",
        "delta_value": 0,
        "effect_text": "属性ごとに上がる能力が変わります",
        "detail_text": "無=耐久 / 炎=攻撃 / 水=素早さ / 雷=会心 / 風=命中 / 氷・鋼=防御 / 機械=命中 / 鉱石=会心",
        "hint_text": "今の構成は未発動です。",
        "catalog_rows": rows,
    }


def _series_meta_for_key(series_key):
    key = str(series_key or "").strip()
    if not key or key in LEGACY_GENERIC_SERIES_KEYS:
        return None
    row = SERIES_METADATA_BY_KEY.get(key)
    return dict(row) if row else None


def _series_badge_payload(series_key):
    meta = _series_meta_for_key(series_key)
    if not meta:
        return None
    return {
        "series_key": str(meta["series_key"]),
        "display_name": str(meta["display_name"]),
        "short_label": str(meta.get("short_label") or str(meta["display_name"]).replace("シリーズ", "")),
        "role_label": str(meta["role_label"]),
        "category": str(meta["category"]),
        "frame_type": str(meta.get("frame_type") or _infer_frame_type_from_series_key(meta["series_key"])),
        "max_rarity": str(meta.get("max_rarity") or "N").upper(),
        "can_evolve": bool(int(meta.get("can_evolve", 0))),
        "summary_text": f"{meta['display_name']} / 思想: {meta['role_label']}",
    }


def _series_rules_for_row(part_row, series_master_map=None):
    row = dict(part_row or {})
    frame_type = _frame_type_for_row(row)
    series_key = str(
        row.get("series_key")
        or row.get("instance_series")
        or row.get("series")
        or ""
    ).strip()
    base = {
        "series_key": series_key,
        "frame_type": frame_type,
        "max_rarity": "N" if frame_type == "insect" else "R",
        "can_evolve": 0 if frame_type == "insect" else 1,
        "display_name": row.get("series_label") or "",
        "short_label": "",
    }
    if not series_key or series_key in LEGACY_GENERIC_SERIES_KEYS:
        return base
    meta = (series_master_map or {}).get(series_key) or _series_meta_for_key(series_key) or {}
    merged = dict(base)
    if meta:
        merged.update(meta)
    merged["series_key"] = series_key
    merged["frame_type"] = _normalize_frame_type(merged.get("frame_type"), default=frame_type)
    merged["max_rarity"] = str(merged.get("max_rarity") or base["max_rarity"]).upper()
    merged["can_evolve"] = int(merged.get("can_evolve", base["can_evolve"]))
    display_name = str(merged.get("display_name") or row.get("series_label") or "").strip()
    merged["display_name"] = display_name
    merged["short_label"] = str(
        merged.get("short_label")
        or (display_name.replace("シリーズ", "") if display_name else "")
    ).strip()
    return merged


def _series_can_evolve_for_row(part_row, series_master_map=None):
    return bool(int(_series_rules_for_row(part_row, series_master_map=series_master_map).get("can_evolve") or 0))


def _series_is_n_only_for_row(part_row, series_master_map=None):
    rules = _series_rules_for_row(part_row, series_master_map=series_master_map)
    return str(rules.get("max_rarity") or "N").upper() == "N" and not bool(int(rules.get("can_evolve") or 0))


def _series_progress_layer_for_user(db, user_id):
    row = db.execute(
        "SELECT max_unlocked_layer FROM users WHERE id = ?",
        (int(user_id),),
    ).fetchone()
    layer = int(row["max_unlocked_layer"] or 1) if row else 1
    return max(1, min(5, layer))


def _load_series_master_map(db, active_only=False):
    where = "WHERE is_active = 1" if active_only else ""
    rows = db.execute(
        f"""
        SELECT
            series_key,
            display_name,
            category,
            frame_type,
            role_label,
            description,
            max_rarity,
            can_evolve,
            is_active,
            released_at
        FROM series_master
        {where}
        ORDER BY series_key ASC
        """
    ).fetchall()
    mapping = {}
    for row in rows:
        mapping[str(row["series_key"])] = dict(row)
    return mapping


def _load_series_bonus_defs(db, active_only=True):
    rows = db.execute(
        f"""
        SELECT ssb.series_key, ssb.pieces_required, ssb.stat_key, ssb.value, COALESCE(ssb.value_type, 'percent') AS value_type
        FROM series_set_bonus ssb
        JOIN series_master sm ON sm.series_key = ssb.series_key
        {"WHERE sm.is_active = 1" if active_only else ""}
        ORDER BY ssb.series_key ASC, ssb.pieces_required ASC, ssb.id ASC
        """
    ).fetchall()
    mapping = {}
    for row in rows:
        mapping.setdefault(str(row["series_key"]), []).append(
            {
                "series_key": str(row["series_key"]),
                "pieces_required": int(row["pieces_required"] or 0),
                "stat_key": str(row["stat_key"] or ""),
                "value": float(row["value"] or 0.0),
                "value_type": str(row["value_type"] or "percent"),
            }
        )
    return mapping


def _format_series_bonus_value(value, value_type="percent"):
    if str(value_type or "percent").strip().lower() == "flat":
        return f"{int(round(float(value or 0.0))):+d}"
    pct = int(round(float(value or 0.0) * 100))
    return f"{pct:+d}%"


def _series_bonus_view_for_loadout(db, parts, series_calc=None, progress_layer=1):
    calc = series_calc or {}
    counts = dict(calc.get("series_counts") or {})
    applied = list(calc.get("series_bonus") or [])
    meta_map = _load_series_master_map(db, active_only=False)
    line_items = []
    for series_key, count in sorted(counts.items(), key=lambda item: (-int(item[1]), item[0])):
        meta = meta_map.get(series_key) or _series_meta_for_key(series_key)
        if not meta:
            continue
        series_effects = [row for row in applied if str(row.get("series_key")) == series_key]
        effect_text = " / ".join(
            f"{_stat_label(row['stat_key'])} {_format_series_bonus_value(row['applied_value'], row.get('value_type'))}"
            for row in series_effects
        ) or "未発動"
        if count < 2:
            hint_text = "あと1部位で2部位効果"
        elif count < 4 and int(progress_layer or 1) < 4:
            hint_text = "第4層到達で4部位効果が解禁"
        elif count < 4:
            hint_text = "あと1部位で4部位効果"
        elif int(progress_layer or 1) < 5:
            hint_text = "第5層到達で4部位効果が最大化"
        else:
            hint_text = "4部位効果まで発動中"
        line_items.append(
            {
                "series_key": series_key,
                "display_name": str(meta["display_name"]),
                "role_label": str(meta["role_label"]),
                "count": int(count),
                "count_text": f"{int(count)}/4",
                "effect_text": effect_text,
                "hint_text": hint_text,
                "active": bool(series_effects),
            }
        )
    if line_items:
        top = line_items[0]
        return {
            "active": bool(applied),
            "status_label": "発動中" if applied else "準備中",
            "condition_text": "同シリーズ 2部位 / 4部位で発動",
            "effect_text": f"{top['display_name']} {top['count_text']} / {top['effect_text']}",
            "detail_text": top["hint_text"],
            "catalog_rows": line_items,
        }
    return {
        "active": False,
        "status_label": "未発動",
        "condition_text": "同シリーズ 2部位 / 4部位で発動",
        "effect_text": "同シリーズを集めると能力が伸びます",
        "detail_text": "第2層から2部位、第4層から4部位効果が使えます。",
        "catalog_rows": [],
    }


def _normalize_part_type_key(part_type):
    key = str(part_type or "").strip().lower()
    if key in PART_TYPE_TITLES_JA:
        return key
    if key == "rightarm":
        return "right_arm"
    if key == "leftarm":
        return "left_arm"
    return ""


def _guess_part_type_from_key(part_key):
    key = str(part_key or "").strip().lower()
    if key.startswith("right_arm_"):
        return "right_arm"
    if key.startswith("left_arm_"):
        return "left_arm"
    if key.startswith("head_"):
        return "head"
    if key.startswith("legs_"):
        return "legs"
    return ""


def generate_part_display_name_ja(part_key, rarity=None, element=None, part_type=None):
    key = str(part_key or "").strip()
    if not key:
        return ""
    tokens = [tok for tok in key.lower().split("_") if tok]
    part_type_norm = _normalize_part_type_key(part_type) or _guess_part_type_from_key(key)
    rarity_norm = str(rarity or "").strip().upper()
    element_norm = str(element or "").strip().lower()
    if not rarity_norm:
        for tok in tokens:
            tok_up = tok.upper()
            if tok_up in PART_RARITY_SUFFIX_JA:
                rarity_norm = tok_up
                break
    if not element_norm:
        for tok in tokens:
            if tok in PART_ELEMENT_TITLES_JA:
                element_norm = tok
                break
    if not part_type_norm or element_norm not in PART_ELEMENT_TITLES_JA:
        return key
    suffix = PART_RARITY_SUFFIX_JA.get(rarity_norm, "")
    return f"{PART_ELEMENT_TITLES_JA[element_norm]}{PART_TYPE_TITLES_JA[part_type_norm]}{suffix}"


def _part_display_name_ja(part_row_or_key, rarity=None, element=None, part_type=None):
    if isinstance(part_row_or_key, (sqlite3.Row, dict)):
        row = part_row_or_key
        key = str(row["key"]) if "key" in row.keys() and row["key"] else ""
        explicit = (
            str(row["display_name_ja"]).strip()
            if "display_name_ja" in row.keys() and row["display_name_ja"]
            else ""
        )
        if explicit:
            return explicit
        generated = generate_part_display_name_ja(
            key,
            rarity=(row["rarity"] if "rarity" in row.keys() else rarity),
            element=(row["element"] if "element" in row.keys() else element),
            part_type=(row["part_type"] if "part_type" in row.keys() else part_type),
        )
        if generated:
            return generated
        legacy = str(row["name"]).strip() if "name" in row.keys() and row["name"] else ""
        return legacy or key
    key = str(part_row_or_key or "").strip()
    generated = generate_part_display_name_ja(
        key,
        rarity=rarity,
        element=element,
        part_type=part_type,
    )
    return generated or key


