def _normalize_instance_id_values(raw_values, *, limit=None):
    normalized = []
    seen = set()
    max_items = max(1, int(limit)) if limit else None
    for raw in raw_values or ():
        for chunk in str(raw or "").split(","):
            token = chunk.strip()
            if not token.isdigit():
                continue
            value = int(token)
            if value <= 0 or value in seen:
                continue
            seen.add(value)
            normalized.append(value)
            if max_items and len(normalized) >= max_items:
                return normalized
    return normalized


def _part_total_value(stat_map):
    stats = stat_map or {}
    return sum(int(stats.get(key) or 0) for key in PART_STAT_KEYS)


def _delta_text(delta_value):
    delta = int(delta_value or 0)
    if delta > 0:
        return f"+{delta}"
    if delta < 0:
        return str(delta)
    return "±0"


def _delta_class(delta_value):
    delta = int(delta_value or 0)
    if delta > 0:
        return "up"
    if delta < 0:
        return "down"
    return "flat"


def _part_stat_rows(stats, compare_stats=None, *, focus_limit=2):
    stat_map = stats or {}
    compare_map = compare_stats or {}
    focus_keys = {
        row["key"] for row in _robot_focus_stat_rows(stat_map, limit=max(1, int(focus_limit or 2)))
    }
    rows = []
    for key in PART_STAT_KEYS:
        value = int(stat_map.get(key) or 0)
        after_value = None
        delta = None
        delta_text = None
        delta_class = ""
        if compare_stats is not None:
            after_value = int(compare_map.get(key) or 0)
            delta = int(after_value - value)
            delta_text = _delta_text(delta)
            if delta > 0:
                delta_class = "up"
            elif delta < 0:
                delta_class = "down"
            else:
                delta_class = "flat"
        rows.append(
            {
                "key": key,
                "label": _stat_label(key),
                "value": value,
                "after_value": after_value,
                "delta": delta,
                "delta_text": delta_text,
                "delta_class": delta_class,
                "is_focus": key in focus_keys,
            }
        )
    return rows


def _build_picker_stat_pair_rows(stats, compare_stats=None):
    stat_map = stats or {}
    compare_map = compare_stats or {}
    rows = []
    for left_key, right_key in (("hp", "atk"), ("def", "spd"), ("acc", "cri")):
        pair = {"left": {}, "right": {}}
        for side, key in (("left", left_key), ("right", right_key)):
            value = int(stat_map.get(key) or 0)
            delta = None
            delta_text = None
            delta_class = "flat"
            if compare_stats is not None:
                delta = int(value - int(compare_map.get(key) or 0))
                delta_text = _delta_text(delta)
                delta_class = _delta_class(delta)
            pair[side] = {
                "key": key,
                "label": _stat_label(key),
                "value": value,
                "delta": delta,
                "delta_text": delta_text,
                "delta_class": delta_class,
            }
        rows.append(pair)
    return rows


def _build_picker_summary_rows(stats, compare_stats=None, *, limit=2):
    stat_map = stats or {}
    if compare_stats is None:
        return [
            {
                "key": row["key"],
                "label": row["label"],
                "value": int(row["value"]),
                "delta": None,
                "delta_text": None,
                "delta_class": "flat",
                "display_text": f"{row['label']} {int(row['value'])}",
            }
            for row in _robot_focus_stat_rows(stat_map, limit=max(1, int(limit or 2)))
        ]

    compare_map = compare_stats or {}
    focus_keys = {
        row["key"] for row in _robot_focus_stat_rows(stat_map, limit=max(1, int(limit or 2)))
    }
    rows = []
    for index, key in enumerate(PART_STAT_KEYS):
        delta = int(stat_map.get(key) or 0) - int(compare_map.get(key) or 0)
        if delta == 0:
            continue
        rows.append(
            {
                "key": key,
                "label": _stat_label(key),
                "value": int(stat_map.get(key) or 0),
                "delta": delta,
                "delta_text": _delta_text(delta),
                "delta_class": _delta_class(delta),
                "display_text": f"{_stat_label(key)} {_delta_text(delta)}",
                "_sort_abs": abs(delta),
                "_sort_focus": 0 if key in focus_keys else 1,
                "_sort_index": index,
            }
        )
    rows.sort(key=lambda item: (-int(item["_sort_abs"]), int(item["_sort_focus"]), int(item["_sort_index"])))
    trimmed = rows[: max(1, int(limit or 2))]
    if trimmed:
        for row in trimmed:
            row.pop("_sort_abs", None)
            row.pop("_sort_focus", None)
            row.pop("_sort_index", None)
        return trimmed
    return [
        {
            "key": row["key"],
            "label": row["label"],
            "value": int(row["value"]),
            "delta": 0,
            "delta_text": "±0",
            "delta_class": "flat",
            "display_text": f"{row['label']} {int(row['value'])}",
        }
        for row in _robot_focus_stat_rows(stat_map, limit=max(1, int(limit or 2)))
    ]


def _build_picker_total_summary(stats, compare_stats=None):
    total_value = int(_part_total_value(stats))
    if compare_stats is None:
        return {
            "label": "総合",
            "value": total_value,
            "value_text": str(total_value),
            "value_class": "flat",
            "note_text": None,
        }
    delta = int(total_value - int(_part_total_value(compare_stats)))
    return {
        "label": "総合差分",
        "value": total_value,
        "value_text": _delta_text(delta),
        "value_class": _delta_class(delta),
        "note_text": f"候補総合 {total_value}",
    }


def _part_image_candidates(image_path):
    raw = str(image_path or "").strip().replace("\\", "/").lstrip("/")
    if not raw:
        return []
    aliased = PART_IMAGE_PATH_ALIASES.get(raw)
    rels = []
    if aliased and aliased != raw:
        rels.append(f"robot_assets/{aliased}")
    if raw.startswith("parts/dinosaur/"):
        filename = raw.rsplit("/", 1)[-1]
        if filename.startswith("head_"):
            rels.append(f"robot_assets/parts/head/{filename}")
        elif filename.startswith("right_arm_"):
            rels.append(f"robot_assets/parts/right_arm/{filename}")
        elif filename.startswith("left_arm_"):
            rels.append(f"robot_assets/parts/left_arm/{filename}")
        elif filename.startswith("legs_"):
            rels.append(f"robot_assets/parts/legs/{filename}")
    rels.append(f"robot_assets/{raw}")
    seen = set()
    out = []
    for rel in rels:
        if rel not in seen:
            seen.add(rel)
            out.append(rel)
    return out


def _part_card_payload(part_row, *, compare_row=None, can_discard=None):
    item = dict(part_row)
    status_key = str(item.get("status") or "inventory").strip().lower()
    stats = compute_part_stats(item)
    item["frame_type"] = _frame_type_for_row(item)
    item["frame_label"] = _frame_type_label(item["frame_type"])
    item["display_name"] = _part_display_name_ja(item)
    item["series_badge"] = _series_badge_payload(item.get("instance_series") or item.get("series"))
    item["series_n_only"] = bool(
        item.get("series_badge")
        and str(item["series_badge"].get("max_rarity") or "N").upper() == "N"
        and not bool(item["series_badge"].get("can_evolve"))
    )
    item["part_type_label"] = _part_type_ui_label(item.get("part_type"))
    item["rarity_label"] = str(item.get("rarity") or "N").upper()
    item["status_key"] = status_key
    item["is_equipped"] = status_key == "equipped"
    item["is_inventory"] = status_key == "inventory"
    item["is_overflow"] = False
    item["is_sold"] = status_key == "sold"
    item["locked"] = bool(int(item.get("locked") or 0))
    item["can_discard"] = (
        status_key == "inventory" and not item["locked"]
    ) if can_discard is None else bool(can_discard)
    if item["is_equipped"]:
        item["status_label"] = "装備中"
    elif item["is_sold"]:
        item["status_label"] = "売却済み"
    else:
        item["status_label"] = "所持中"
    if item["locked"]:
        item["material_hint"] = "保護中：売却や素材消費の対象になりません"
    elif item["is_inventory"]:
        item["material_hint"] = "強化素材に使える"
    elif item["is_sold"]:
        item["material_hint"] = "コインに変換済み"
    else:
        item["material_hint"] = "今は素材に使えない"
    item["image_url"] = url_for("static", filename=_part_image_rel(item), v=APP_VERSION)
    item["stats"] = stats
    item["total_value"] = int(_part_total_value(stats))
    item["focus_rows"] = _robot_focus_stat_rows(stats, limit=2)
    item["focus_line"] = " / ".join(row["label"] for row in item["focus_rows"])
    item["extreme_title"] = _extract_part_extreme_title(item)
    compare_stats = None
    if compare_row:
        compare_item = dict(compare_row)
        compare_stats = compute_part_stats(compare_item)
        item["compare_display_name"] = _part_display_name_ja(compare_item)
        item["compare_image_url"] = url_for("static", filename=_part_image_rel(compare_item), v=APP_VERSION)
        item["compare_stats"] = compare_stats
        item["compare_total_value"] = int(_part_total_value(compare_stats))
        item["compare_total_delta"] = int(item["compare_total_value"] - item["total_value"])
        item["compare_total_delta_text"] = _delta_text(item["compare_total_delta"])
    item["stat_rows"] = _part_stat_rows(stats, compare_stats)
    return item


def _part_instance_display_rows(db, instance_ids):
    normalized_ids = _normalize_instance_id_values(instance_ids, limit=32)
    if not normalized_ids:
        return []
    marks = ",".join("?" for _ in normalized_ids)
    return db.execute(
        f"""
        SELECT
            pi.id AS instance_id,
            pi.plus,
            pi.status,
            pi.w_hp, pi.w_atk, pi.w_def, pi.w_spd, pi.w_acc, pi.w_cri,
            pi.rarity AS instance_rarity,
            pi.element AS instance_element,
            pi.series AS instance_series,
            rp.part_type, rp.key, rp.series, rp.frame_type, rp.series_key, rp.series_label, rp.image_path, rp.offset_x, rp.offset_y,
            rp.rarity, rp.element, rp.display_name_ja
        FROM part_instances pi
        JOIN robot_parts rp ON rp.id = pi.part_id
        WHERE pi.id IN ({marks}) AND rp.is_active = 1
        """,
        normalized_ids,
    ).fetchall()


