def _world_effect_summary_lines(weekly_env):
    if not weekly_env:
        return []
    lines = []
    spawn_bonus = float(weekly_env.get("enemy_spawn_bonus") or 0.0)
    drop_bonus = float(weekly_env.get("drop_bonus") or 0.0)
    if spawn_bonus > 0:
        lines.append("NORMAL敵 出現率↑")
    if drop_bonus > 0:
        lines.append("ドロップ率↑")
    if not lines:
        lines.append("補正なし")
    return lines


def _element_to_faction(element):
    elem = (element or "").upper()
    if elem in {"THUNDER", "WIND"}:
        return "ventra"
    if elem in {"FIRE", "ICE"}:
        return "ignis"
    return "aurix"


def _build_battle_reward_front(*, reward_coin, reward_core, dropped_core_name, drop_items):
    drops = []
    other_drops = []
    part_rows = []
    if int(reward_core or 0) > 0:
        core_name = (dropped_core_name or "進化コア").strip() or "進化コア"
        drops.append(f"{core_name} ×{int(reward_core)}")
    drop_counter = Counter()
    part_row_map = {}
    for item in (drop_items or []):
        if item.get("kind") == "research_note":
            line = str(item.get("line") or "").strip()
            if line:
                other_drops.append(line)
            continue
        if item.get("kind") == "research_module":
            name = (item.get("module_name") or item.get("module_key") or "研究モジュール").strip()
            if item.get("source") == "pity":
                other_drops.append(f"研究ゲージ達成: {name}を獲得")
            else:
                other_drops.append(f"研究モジュール獲得: {name}")
            continue
        name = (item.get("part_display_name") or item.get("part_key") or "不明パーツ").strip()
        plus = int(item.get("plus") or 0)
        storage_suffix = ""
        if item.get("auto_sold"):
            storage_suffix = f"（自動売却 +{int(item.get('auto_sell_price') or 0)}コイン）"
        label_prefix = "恐竜発掘！ " if item.get("campaign_key") == DINOSAUR_DEBUT_CAMPAIGN["key"] else ""
        label = f"{label_prefix}{name} +{plus}{storage_suffix}"
        drop_counter[label] += 1
        row_key = (
            item.get("part_key") or name,
            plus,
            storage_suffix,
            label_prefix,
            item.get("image_url") or "",
            name,
        )
        if row_key not in part_row_map:
            part_row_map[row_key] = {
                "label": label,
                "image_url": item.get("image_url"),
                "count": 0,
                "part_instance_id": item.get("part_instance_id"),
                "storage_status": str(item.get("storage_status") or "").strip().lower(),
                "auto_sold": bool(item.get("auto_sold")),
                "locked": bool(int(item.get("locked") or 0)),
            }
        part_row_map[row_key]["count"] += 1
    for label, count in drop_counter.items():
        if count > 1:
            drops.append(f"{label} ×{count}")
        else:
            drops.append(label)
    for row in part_row_map.values():
        part_rows.append(row)
    drops.extend(other_drops)
    if not drops:
        drops.append("戦利品なし")
    return {
        "coin": int(reward_coin or 0),
        "drops": drops,
        "other_drops": other_drops,
        "part_rows": part_rows,
    }


def _part_inventory_status_payload(db, user_id, user_row=None):
    if user_row is None:
        user_row = db.execute(
            "SELECT id, part_inventory_limit FROM users WHERE id = ?",
            (int(user_id),),
        ).fetchone()
    limit = int(user_row["part_inventory_limit"] or 0) if user_row else 0
    count = _count_part_inventory(db, int(user_id))
    storage = _part_storage_snapshot(db, int(user_id))
    note = ""
    level = "normal"
    line = f"パーツ所持 {count} / {limit}" if limit > 0 else f"パーツ所持 {count}"
    if limit > 0 and count >= limit:
        level = "full"
        note = "所持枠がいっぱいです。整理すると、残したいパーツを選びやすくなります。"
        line = f"パーツ所持 {count} / {limit}　満杯です。"
    elif limit > 0 and count >= math.ceil(limit * 0.8):
        level = "warning"
        note = "そろそろ整理すると安心です。"
        line = f"パーツ所持 {count} / {limit}　そろそろ整理"
    elif limit > 0 and count >= max(1, limit - 2):
        note = "そろそろ整理すると、素材にしたいパーツを残しやすくなります。"
    return {
        "count": int(count),
        "limit": int(limit),
        "storage_count": int(storage.get("legacy_storage_count") or storage.get("storage_count") or 0),
        "note": note,
        "level": level,
        "line": line,
    }


def _should_show_market_after_battle(part_inventory_status, reward_front):
    inv = part_inventory_status or {}
    limit = int(inv.get("limit") or 0)
    count = int(inv.get("count") or 0)
    ratio = (count / float(limit)) if limit > 0 else 0.0
    has_part_reward = bool((reward_front or {}).get("part_rows") or [])
    return bool(has_part_reward or ratio >= 0.8)


def _battle_result_session_summary(summary):
    excluded = {
        "battle_cinematic",
        "battle_replay",
        "drop_items",
        "bonus_events",
        "stage_modifier",
        "world_bonus_notes",
    }
    compact = {k: v for k, v in (summary or {}).items() if k not in excluded}
    return json.loads(json.dumps(compact, ensure_ascii=False, default=str))


def _store_last_battle_result(db, user_id, *, summary, area_key, area_label):
    summary_payload = _battle_result_session_summary(summary)
    result_id = str(summary_payload.get("battle_id") or uuid.uuid4())
    now_ts = int(time.time())
    db.execute(
        """
        INSERT INTO battle_result_cache
        (id, user_id, area_key, area_label, summary_json, created_at)
        VALUES (?, ?, ?, ?, ?, ?)
        ON CONFLICT(id) DO UPDATE SET
            user_id = excluded.user_id,
            area_key = excluded.area_key,
            area_label = excluded.area_label,
            summary_json = excluded.summary_json,
            created_at = excluded.created_at
        """,
        (
            result_id,
            int(user_id),
            str(area_key or ""),
            str(area_label or ""),
            json.dumps(summary_payload, ensure_ascii=False, default=str),
            now_ts,
        ),
    )
    db.execute("DELETE FROM battle_result_cache WHERE created_at < ?", (now_ts - 86400 * 3,))
    session["last_battle_result_id"] = result_id
    session.pop("last_battle_result", None)
    return result_id


def _load_battle_result_cache(db, user_id, result_id):
    key = str(result_id or "").strip()
    if not key:
        return None
    row = db.execute(
        """
        SELECT id, area_key, area_label, summary_json
        FROM battle_result_cache
        WHERE id = ? AND user_id = ?
        LIMIT 1
        """,
        (key, int(user_id)),
    ).fetchone()
    if not row:
        return None
    try:
        summary = json.loads(row["summary_json"] or "{}")
    except Exception:
        summary = {}
    return {
        "id": row["id"],
        "area_key": row["area_key"],
        "area_label": row["area_label"],
        "summary": summary,
    }


def _refresh_battle_result_summary(db, user_id, user_row, summary):
    refreshed = dict(summary or {})
    reward_front = dict(refreshed.get("reward_front") or {})
    rows = []
    for row in reward_front.get("part_rows") or []:
        next_row = dict(row)
        part_instance_id = next_row.get("part_instance_id")
        if part_instance_id:
            part_row = db.execute(
                "SELECT locked, status FROM part_instances WHERE id = ? AND user_id = ? LIMIT 1",
                (int(part_instance_id), int(user_id)),
            ).fetchone()
            if part_row:
                next_row["locked"] = bool(int(part_row["locked"] or 0))
                next_row["storage_status"] = str(part_row["status"] or "").strip().lower()
        rows.append(next_row)
    reward_front["part_rows"] = rows
    refreshed["reward_front"] = reward_front
    part_inventory_status = _part_inventory_status_payload(db, user_id, user_row)
    refreshed["part_inventory_status"] = part_inventory_status
    refreshed["show_market_after_battle"] = bool(
        _market_can_access(db, user_row)
        and _should_show_market_after_battle(part_inventory_status, reward_front)
    )
    refreshed["next_explore_submission_id"] = _issue_explore_submission_id()

    remain, _ = _explore_remaining_seconds_for_user(db, user_row, user_id)
    is_admin = bool(int(user_row["is_admin"] or 0) == 1)
    remain = 0 if is_admin else int(remain or 0)
    refreshed["explore_ct_remain"] = int(remain)
    refreshed["explore_ct_ready_at"] = 0 if is_admin else int(time.time() + max(0, remain))
    refreshed["explore_ct_is_admin"] = bool(is_admin)
    if is_admin or remain <= 0:
        refreshed["explore_ct_button_label"] = "もう一度出撃"
        refreshed["explore_ct_status_label"] = "" if is_admin else "出撃可能"
    else:
        refreshed["explore_ct_button_label"] = f"もう一度出撃（あと{remain}秒）"
        refreshed["explore_ct_status_label"] = f"CT中: あと{remain}秒"
    return refreshed


def _extract_part_extreme_title(part_instance):
    if not part_instance:
        return None
    weights = {
        "atk": float(part_instance.get("w_atk") or 0.0),
        "spd": float(part_instance.get("w_spd") or 0.0),
        "def": float(part_instance.get("w_def") or 0.0),
        "acc": float(part_instance.get("w_acc") or 0.0),
        "cri": float(part_instance.get("w_cri") or 0.0),
        "hp": float(part_instance.get("w_hp") or 0.0),
    }
    top_key = max(weights, key=weights.get)
    top_val = weights[top_key]
    if top_key == "atk" and top_val >= 0.45:
        return "破壊型"
    if top_key == "spd" and top_val >= 0.40:
        return "疾風型"
    if top_key == "def" and top_val >= 0.40:
        return "鉄壁型"
    if top_key == "acc" and top_val >= 0.42:
        return "狙撃型"
    if top_key == "cri" and top_val >= 0.32:
        return "豪運型"
    return None


def _maybe_post_research_title(db, user_id, username, part_instance):
    title = _extract_part_extreme_title(part_instance)
    if not title:
        return
    day_key = datetime.now(JST).strftime("%Y-%m-%d")
    once_key = f"title_posted:{user_id}:{day_key}"
    seen = db.execute(
        "SELECT 1 FROM world_events_log WHERE event_type = 'daily_title_posted' AND payload_json LIKE ? LIMIT 1",
        (f'%"{once_key}"%',),
    ).fetchone()
    if seen:
        return
    message = f"『{title}』パーツが発見された！ ({username})"
    db.execute(
        "INSERT INTO chat_messages (user_id, username, message, created_at) VALUES (?, ?, ?, ?)",
        (user_id, "SYSTEM", message, now_str()),
    )
    _world_event_log(
        db,
        "daily_title_posted",
        {"once_key": once_key, "user_id": user_id, "title": title},
    )


def _world_choose_next_environment(db, week_key, influence_ratio=0.30):
    elements = [code for code, _ in ELEMENTS]
    prev_start = _world_week_bounds(week_key)[0] - timedelta(days=7)
    prev_key = _world_week_key(prev_start.timestamp())

    kills_raw = {e: _world_counter_get(db, prev_key, f"kills_{e}") for e in elements}
    builds_raw = {e: _world_counter_get(db, prev_key, f"builds_{e}") for e in elements}
    kills_sum = sum(kills_raw.values())
    builds_sum = sum(builds_raw.values())

    kills_norm = {e: (kills_raw[e] / kills_sum) if kills_sum > 0 else 0.0 for e in elements}
    builds_norm = {e: (builds_raw[e] / builds_sum) if builds_sum > 0 else 0.0 for e in elements}
    influence = {e: kills_norm[e] * 0.6 + builds_norm[e] * 0.4 for e in elements}

    random_scores = {e: random.random() for e in elements}
    random_total = sum(random_scores.values()) or 1.0
    random_norm = {e: random_scores[e] / random_total for e in elements}
    final_weights = {
        e: ((1.0 - influence_ratio) * random_norm[e]) + (influence_ratio * influence[e])
        for e in elements
    }
    chosen = random.choices(elements, weights=[final_weights[e] for e in elements], k=1)[0]
    mode = random.choice(["暴走", "活性", "安定", "静穏"])
    config = WORLD_MODES[mode]

    kills_top = sorted(kills_raw.items(), key=lambda x: x[1], reverse=True)[:2]
    builds_top = sorted(builds_raw.items(), key=lambda x: x[1], reverse=True)[:1]
    kills_top_txt = ", ".join(f"{k}:{v}" for k, v in kills_top if v > 0) or "データなし"
    builds_top_txt = ", ".join(f"{k}:{v}" for k, v in builds_top if v > 0) or "データなし"
    reason = (
        f"ランダム70% + 影響30% / 前週撃破上位={kills_top_txt} / "
        f"前週組立上位={builds_top_txt} / 世界状態={mode}"
    )
    return {
        "element": chosen,
        "mode": mode,
        "enemy_spawn_bonus": config["enemy_spawn_bonus"],
        "drop_bonus": config["drop_bonus"],
        "influence_ratio": influence_ratio,
        "reason": reason,
        "random_seed": random.randint(1, 2_147_483_647),
        "payload": {
            "week_key": week_key,
            "kills_raw": kills_raw,
            "builds_raw": builds_raw,
            "final_weights": final_weights,
            "chosen_element": chosen,
            "mode": mode,
        },
    }


def _ensure_world_week_environment(db):
    current_key = _world_week_key()
    row = db.execute(
        "SELECT * FROM world_weekly_environment WHERE week_key = ?",
        (current_key,),
    ).fetchone()
    if row:
        return row
    env = _world_choose_next_environment(db, current_key, influence_ratio=0.30)
    start, end = _world_week_bounds(current_key)
    cur = db.execute(
        """
        INSERT OR IGNORE INTO world_weekly_environment
        (week_key, element, mode, enemy_spawn_bonus, drop_bonus, started_at, ends_at, random_seed, influence_ratio, reason)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        """,
        (
            current_key,
            env["element"],
            env["mode"],
            env["enemy_spawn_bonus"],
            env["drop_bonus"],
            int(start.timestamp()),
            int(end.timestamp()),
            env["random_seed"],
            env["influence_ratio"],
            env["reason"],
        ),
    )
    if cur.rowcount > 0:
        research_result = _advance_world_research(db, current_key)
        rollover_payload = dict(env["payload"])
        rollover_payload["research"] = research_result
        _world_event_log(db, "week_rollover", rollover_payload)
        msg = (
            f"今週の戦況: {env['mode']}（属性: {env['element']}）。"
            f" 理由: {env['reason']}"
        )
        db.execute(
            "INSERT INTO chat_messages (user_id, username, message, created_at) VALUES (?, ?, ?, ?)",
            (0, "SYSTEM", msg[:200], now_str()),
        )
        db.commit()
    return db.execute(
        "SELECT * FROM world_weekly_environment WHERE week_key = ?",
        (current_key,),
    ).fetchone()


def _world_weekly_trends(db, week_key, limit=3):
    rows = db.execute(
        """
        SELECT metric_key, value
        FROM world_weekly_counters
        WHERE week_key = ? AND metric_key LIKE 'builds_%'
        ORDER BY value DESC, metric_key ASC
        LIMIT ?
        """,
        (week_key, limit),
    ).fetchall()
    trends = []
    for r in rows:
        metric_key = r["metric_key"]
        element = metric_key.replace("builds_", "")
        trends.append({"element": element, "value": int(r["value"])})
    return trends


def _world_research_progress_rows(db):
    _ensure_world_research_rows(db)
    rows = db.execute(
        """
        SELECT element, progress, unlocked_stage, updated_at
        FROM world_research_progress
        ORDER BY element ASC
        """
    ).fetchall()
    items = []
    for r in rows:
        stage = int(r["unlocked_stage"] or 0)
        next_part = _research_part_type_for_stage(stage + 1) if stage < len(RESEARCH_UNLOCK_ORDER) else None
        items.append(
            {
                "element": r["element"],
                "progress": int(r["progress"] or 0),
                "unlocked_stage": stage,
                "next_part_type": next_part,
                "updated_at": int(r["updated_at"] or 0),
            }
        )
    return items


def _home_research_summary(db, current_week_key):
    row = db.execute(
        """
        SELECT id, payload_json
        FROM world_events_log
        WHERE event_type = 'RESEARCH_ADVANCE'
          AND payload_json LIKE ?
        ORDER BY id DESC
        LIMIT 1
        """,
        (f'%"week_key": "{current_week_key}"%',),
    ).fetchone()
    winner_element = None
    if row and row["payload_json"]:
        try:
            payload = json.loads(row["payload_json"])
            winner_element = (payload.get("winner_element") or "").upper() or None
        except Exception:
            winner_element = None
    progress = 0
    unlocked_stage = 0
    if winner_element:
        p_row = db.execute(
            """
            SELECT progress, unlocked_stage
            FROM world_research_progress
            WHERE element = ?
            """,
            (winner_element,),
        ).fetchone()
        if p_row:
            progress = int(p_row["progress"] or 0)
            unlocked_stage = int(p_row["unlocked_stage"] or 0)
    next_part_type = _research_part_type_for_stage(unlocked_stage + 1) if unlocked_stage < len(RESEARCH_UNLOCK_ORDER) else None
    faction_key = _element_to_faction(winner_element) if winner_element else None
    icon_path = FACTION_EMBLEMS.get(faction_key) if faction_key else None
    return {
        "current_research_element": winner_element,
        "progress": progress,
        "unlocked_stage": unlocked_stage,
        "next_part_type": next_part_type,
        "icon_path": icon_path,
    }


def _home_research_unlock_banner(db, current_week_key):
    row = db.execute(
        """
        SELECT id, payload_json
        FROM world_events_log
        WHERE event_type = 'RESEARCH_UNLOCK'
        ORDER BY id DESC
        LIMIT 1
        """
    ).fetchone()
    if not row:
        return None
    try:
        payload = json.loads(row["payload_json"] or "{}")
    except Exception:
        return None
    if payload.get("week_key") != current_week_key:
        return None
    if int(session.get("home_seen_research_unlock_id") or 0) >= int(row["id"]):
        return None
    session["home_seen_research_unlock_id"] = int(row["id"])
    part_type = str(payload.get("part_type") or "").strip().upper()
    part_label = RESEARCH_PART_TYPE_LABELS_JA.get(part_type)
    if part_label:
        line_1 = f"{part_label}の設計が解放されました！"
        line_2 = f"これから出撃で{part_label}が見つかるかもしれません。"
    else:
        line_1 = "新しいパーツ設計が解放されました！"
        line_2 = "これから出撃で見つかるかもしれません。"
    return {
        "line_1": line_1,
        "line_2": line_2,
        "part_type": part_type,
        "part_label": part_label,
    }


