def _migrate_robot_builds(db):
    db.execute(
        """
        CREATE TABLE IF NOT EXISTS robot_builds_new (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER NOT NULL,
            base_key TEXT,
            head_key TEXT,
            r_arm_key TEXT,
            l_arm_key TEXT,
            legs_key TEXT,
            composed_image_path TEXT,
            head_offset_x INTEGER NOT NULL DEFAULT 0,
            head_offset_y INTEGER NOT NULL DEFAULT 0,
            r_arm_offset_x INTEGER NOT NULL DEFAULT 0,
            r_arm_offset_y INTEGER NOT NULL DEFAULT 0,
            l_arm_offset_x INTEGER NOT NULL DEFAULT 0,
            l_arm_offset_y INTEGER NOT NULL DEFAULT 0,
            legs_offset_x INTEGER NOT NULL DEFAULT 0,
            legs_offset_y INTEGER NOT NULL DEFAULT 0,
            created_at INTEGER NOT NULL,
            FOREIGN KEY (user_id) REFERENCES users(id)
        )
        """
    )
    rows = db.execute(
        "SELECT id, user_id, base_body_id, head_part_id, right_arm_part_id, left_arm_part_id, legs_part_id, created_at FROM robot_builds"
    ).fetchall()
    base_map = {
        row["id"]: row["name"]
        for row in db.execute("SELECT id, name FROM base_bodies").fetchall()
    }
    part_map = {
        row["id"]: row["name"]
        for row in db.execute("SELECT id, name FROM parts").fetchall()
    }

    def to_key(name):
        if not name:
            return None
        name = name.strip()
        if name.startswith("HEAD-"):
            return f"head_{name.split('-')[-1]}"
        if name.startswith("R-ARM-"):
            return f"r_arm_{name.split('-')[-1]}"
        if name.startswith("L-ARM-"):
            return f"l_arm_{name.split('-')[-1]}"
        if name.startswith("LEGS-"):
            return f"legs_{name.split('-')[-1]}"
        return None

    for r in rows:
        base_key = base_map.get(r["base_body_id"])
        head_key = to_key(part_map.get(r["head_part_id"]))
        r_arm_key = to_key(part_map.get(r["right_arm_part_id"]))
        l_arm_key = to_key(part_map.get(r["left_arm_part_id"]))
        legs_key = to_key(part_map.get(r["legs_part_id"]))
        db.execute(
            """
            INSERT INTO robot_builds_new (id, user_id, base_key, head_key, r_arm_key, l_arm_key, legs_key, composed_image_path, created_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                r["id"],
                r["user_id"],
                base_key,
                head_key,
                r_arm_key,
                l_arm_key,
                legs_key,
                None,
                r["created_at"],
            ),
        )
    db.execute("DROP TABLE robot_builds")
    db.execute("ALTER TABLE robot_builds_new RENAME TO robot_builds")


def get_db():
    if "db" not in g:
        g.db = sqlite3.connect(DB_PATH)
        g.db.row_factory = sqlite3.Row
        ensure_schema(g.db)
        ensure_tower_schema(g.db)
        _ensure_dirs()
        _ensure_default_images()
        _check_static_health()
        _seed_robot_parts(g.db)
        _seed_robot_assets_v2(g.db)
        if _repair_legacy_starter_part_rows(g.db) > 0:
            g.db.commit()
        _seed_milestones(g.db)
        _ensure_main_admin_account_ready(g.db)
        if not PART_OFFSET_CACHE:
            refresh_part_offset_cache(g.db)
    return g.db


def _add_initial_robots(db, user_id):
    rows = db.execute(
        "SELECT id, head, right_arm, left_arm, legs FROM robots_master ORDER BY RANDOM() LIMIT 3"
    ).fetchall()
    if not rows:
        return
    now = int(time.time())
    for r in rows:
        db.execute(
            "INSERT INTO user_robots (user_id, head, right_arm, left_arm, legs, obtained_at, master_id) VALUES (?, ?, ?, ?, ?, ?, ?)",
            (user_id, r["head"], r["right_arm"], r["left_arm"], r["legs"], now, r["id"]),
        )


def _starter_part_rows(db):
    out = {}
    for ptype in ("HEAD", "RIGHT_ARM", "LEFT_ARM", "LEGS"):
        row = db.execute(
            """
            SELECT *
            FROM robot_parts
            WHERE is_active = 1 AND part_type = ?
            ORDER BY
              CASE WHEN COALESCE(frame_type, 'normal') = 'normal' THEN 0 ELSE 1 END,
              CASE WHEN UPPER(COALESCE(rarity, 'N')) = 'N' THEN 0 ELSE 1 END,
              id ASC
            LIMIT 1
            """,
            (ptype,),
        ).fetchone()
        if not row:
            return None
        out[ptype] = row
    return out


def initialize_new_user(db, user_id, *, apply_admin_setup=True):
    user = db.execute(
        "SELECT id, username, is_admin, active_robot_id, max_unlocked_layer FROM users WHERE id = ?",
        (user_id,),
    ).fetchone()
    if not user:
        return {"ok": False, "created_robot": False, "created_inventory_set": False, "reason": "user_not_found"}

    db.execute(
        "UPDATE users SET max_unlocked_layer = CASE WHEN max_unlocked_layer IS NULL OR max_unlocked_layer < 1 THEN 1 ELSE max_unlocked_layer END WHERE id = ?",
        (user_id,),
    )

    starter_parts = _starter_part_rows(db)
    if not starter_parts:
        return {"ok": False, "created_robot": False, "created_inventory_set": False, "reason": "starter_parts_missing"}

    created_robot = False
    created_inventory_set = False
    active_robot_id = user["active_robot_id"]
    active_count = db.execute(
        "SELECT COUNT(*) AS c FROM robot_instances WHERE user_id = ? AND status != 'decomposed'",
        (user_id,),
    ).fetchone()["c"]

    if int(active_count or 0) == 0:
        robot_id = _create_robot_instance(
            db,
            user_id=user_id,
            robot_name="Starter Unit",
            head_key=starter_parts["HEAD"]["key"],
            r_arm_key=starter_parts["RIGHT_ARM"]["key"],
            l_arm_key=starter_parts["LEFT_ARM"]["key"],
            legs_key=starter_parts["LEGS"]["key"],
            status="active",
            combat_mode="normal",
        )
        equipped = {
            "head": _create_part_instance_from_master(db, user_id, starter_parts["HEAD"], plus=0),
            "r_arm": _create_part_instance_from_master(db, user_id, starter_parts["RIGHT_ARM"], plus=0),
            "l_arm": _create_part_instance_from_master(db, user_id, starter_parts["LEFT_ARM"], plus=0),
            "legs": _create_part_instance_from_master(db, user_id, starter_parts["LEGS"], plus=0),
        }
        _equip_part_instances_on_robot(db, robot_id, equipped)
        parts_row = db.execute("SELECT * FROM robot_instance_parts WHERE robot_instance_id = ?", (robot_id,)).fetchone()
        if parts_row:
            try:
                _compose_instance_image(db, {"id": robot_id}, parts_row)
            except Exception:
                # 初期化の本質は「行動可能な初期ロボ付与」。画像生成失敗ではロールバックしない。
                pass
        db.execute(
            "UPDATE users SET active_robot_id = ?, starter_robot_name_pending = 1 WHERE id = ?",
            (robot_id, user_id),
        )
        active_robot_id = robot_id
        created_robot = True
    elif not active_robot_id:
        first_active = db.execute(
            """
            SELECT id
            FROM robot_instances
            WHERE user_id = ? AND status = 'active'
            ORDER BY id ASC
            LIMIT 1
            """,
            (user_id,),
        ).fetchone()
        if first_active:
            db.execute("UPDATE users SET active_robot_id = ? WHERE id = ?", (int(first_active["id"]), user_id))
            active_robot_id = int(first_active["id"])

    for ptype in ("HEAD", "RIGHT_ARM", "LEFT_ARM", "LEGS"):
        part_key = starter_parts[ptype]["key"]
        inv_count = db.execute(
            """
            SELECT COUNT(*) AS c
            FROM part_instances pi
            JOIN robot_parts rp ON rp.id = pi.part_id
            WHERE pi.user_id = ? AND pi.status = 'inventory' AND rp.key = ?
            """,
            (user_id, part_key),
        ).fetchone()["c"]
        if int(inv_count or 0) <= 0:
            _create_part_instance_from_master(db, user_id, starter_parts[ptype], plus=0)
            created_inventory_set = True

    result = {
        "ok": True,
        "created_robot": bool(created_robot),
        "created_inventory_set": bool(created_inventory_set),
        "active_robot_id": (int(active_robot_id) if active_robot_id else None),
    }
    if apply_admin_setup and _is_main_admin_user_row(user):
        admin_state = _apply_main_admin_account_state(db, int(user_id))
        result["main_admin_bootstrap"] = {
            "granted_parts": int(admin_state.get("granted_parts") or 0),
            "equipped_fire_loadout": bool(admin_state.get("equipped_fire_loadout")),
            "changed": bool(admin_state.get("changed")),
        }
    return result


def _seed_robot_parts(db):
    bb_count = db.execute("SELECT COUNT(*) AS c FROM base_bodies").fetchone()["c"]
    if bb_count == 0:
        db.executemany(
            "INSERT INTO base_bodies (name, sprite_path) VALUES (?, ?)",
            [
                ("normal", "base_bodies/normal.png"),
                ("angel", "base_bodies/angel.png"),
                ("devil", "base_bodies/devil.png"),
            ],
        )
    part_count = db.execute("SELECT COUNT(*) AS c FROM parts").fetchone()["c"]
    if part_count == 0:
        items = []
        for i in range(1, 11):
            items.append((f"HEAD-{i}", "HEAD", f"parts/head/{i}.png", 2, 1, 1, 3))
            items.append((f"R-ARM-{i}", "RIGHT_ARM", f"parts/right_arm/{i}.png", 2, 1, 1, 2))
            items.append((f"L-ARM-{i}", "LEFT_ARM", f"parts/left_arm/{i}.png", 2, 1, 1, 2))
            items.append((f"LEGS-{i}", "LEGS", f"parts/legs/{i}.png", 1, 2, 2, 3))
        db.executemany(
            "INSERT INTO parts (name, type, sprite_path, attack, defense, speed, hp) VALUES (?, ?, ?, ?, ?, ?, ?)",
            items,
        )
        db.commit()


def _seed_robot_assets_v2(db):
    base_count = db.execute("SELECT COUNT(*) AS c FROM robot_bases").fetchone()["c"]
    if base_count == 0:
        db.executemany(
            "INSERT INTO robot_bases (key, image_path) VALUES (?, ?)",
            [
                ("normal", "base_bodies/normal.png"),
                ("angel", "base_bodies/angel.png"),
                ("devil", "base_bodies/devil.png"),
            ],
        )
    normal_count = db.execute(
        """
        SELECT COUNT(*) AS c
        FROM robot_parts
        WHERE COALESCE(frame_type, 'normal') = 'normal'
        """
    ).fetchone()["c"]
    if int(normal_count or 0) == 0:
        now = int(time.time())
        items = []
        for i in range(1, 11):
            items.append(("HEAD", f"head_{i}", f"parts/head/{i}.png", "N", "NORMAL", "S1", "normal", 0, 0, now))
            items.append(("RIGHT_ARM", f"r_arm_{i}", f"parts/right_arm/{i}.png", "N", "NORMAL", "S1", "normal", 0, 0, now))
            items.append(("LEFT_ARM", f"l_arm_{i}", f"parts/left_arm/{i}.png", "N", "NORMAL", "S1", "normal", 0, 0, now))
            items.append(("LEGS", f"legs_{i}", f"parts/legs/{i}.png", "N", "NORMAL", "S1", "normal", 0, 0, now))
        db.executemany(
            """
            INSERT INTO robot_parts (
                part_type, key, image_path, rarity, element, series, frame_type, offset_x, offset_y, created_at
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            ON CONFLICT(key) DO UPDATE SET
                part_type = excluded.part_type,
                image_path = excluded.image_path,
                rarity = excluded.rarity,
                element = excluded.element,
                series = excluded.series,
                frame_type = excluded.frame_type,
                offset_x = excluded.offset_x,
                offset_y = excluded.offset_y,
                is_active = 1
            """,
            items,
        )
        db.commit()
    _sync_series_catalog(db)
    insect_name_updates = _sync_insect_part_display_names(db)
    if _backfill_part_display_names(db) > 0:
        db.commit()
    elif insect_name_updates > 0:
        db.commit()


def _repair_legacy_starter_part_rows(db):
    updates = [
        ("head_1", "parts/head/head_n_normal.png", "HEAD"),
        ("r_arm_1", "parts/right_arm/right_arm_n_normal.png", "RIGHT_ARM"),
        ("l_arm_1", "parts/left_arm/left_arm_n_normal.png", "LEFT_ARM"),
        ("legs_1", "parts/legs/legs_n_normal.png", "LEGS"),
    ]
    changed = 0
    for key, image_path, part_type in updates:
        row = db.execute(
            """
            SELECT id, image_path, rarity, element, series, part_type
            FROM robot_parts
            WHERE key = ?
            LIMIT 1
            """,
            (key,),
        ).fetchone()
        if not row:
            continue
        next_values = (
            image_path,
            "N",
            "NORMAL",
            "n1",
            part_type,
            1,
        )
        current_values = (
            row["image_path"],
            (row["rarity"] or "").upper(),
            (row["element"] or "").upper(),
            row["series"] or "",
            row["part_type"],
            1,
        )
        if current_values == next_values:
            continue
        db.execute(
            """
            UPDATE robot_parts
            SET image_path = ?, rarity = ?, element = ?, series = ?, part_type = ?, is_active = 1
            WHERE key = ?
            """,
            (image_path, "N", "NORMAL", "n1", part_type, key),
        )
        changed += 1
    return changed


def _sync_series_catalog(db):
    now = int(time.time())
    for row in SERIES_DEFINITIONS:
        db.execute(
            """
            INSERT INTO series_master (
                series_key,
                display_name,
                category,
                frame_type,
                role_label,
                description,
                max_rarity,
                can_evolve,
                is_active,
                released_at
            )
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            ON CONFLICT(series_key) DO UPDATE SET
                display_name = excluded.display_name,
                category = excluded.category,
                frame_type = excluded.frame_type,
                role_label = excluded.role_label,
                description = excluded.description,
                max_rarity = excluded.max_rarity,
                can_evolve = excluded.can_evolve,
                is_active = CASE
                    WHEN series_master.is_active = 1 THEN 1
                    ELSE excluded.is_active
                END,
                released_at = CASE
                    WHEN series_master.released_at IS NOT NULL THEN series_master.released_at
                    ELSE excluded.released_at
                END
            """,
            (
                row["series_key"],
                row["display_name"],
                row["category"],
                row.get("frame_type") or "normal",
                row["role_label"],
                row["description"],
                str(row.get("max_rarity") or "N").upper(),
                int(row.get("can_evolve", 0)),
                int(row.get("default_active", 0)),
                now if int(row.get("default_active", 0)) else None,
            ),
        )
    for bonus in SERIES_BONUS_DEFINITIONS:
        db.execute(
            """
            INSERT INTO series_set_bonus (series_key, pieces_required, stat_key, value, value_type)
            VALUES (?, ?, ?, ?, ?)
            ON CONFLICT(series_key, pieces_required, stat_key) DO UPDATE SET
                value = excluded.value,
                value_type = excluded.value_type
            """,
            (
                bonus["series_key"],
                int(bonus["pieces_required"]),
                bonus["stat_key"],
                float(bonus["value"]),
                str(bonus.get("value_type") or "percent"),
            ),
        )
    for part in SERIES_PART_DEFINITIONS:
        db.execute(
            """
            INSERT INTO robot_parts (
                part_type,
                key,
                image_path,
                rarity,
                element,
                series,
                frame_type,
                series_key,
                series_label,
                display_name_ja,
                offset_x,
                offset_y,
                is_active,
                is_unlocked,
                is_admin_only,
                created_at
            )
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 0, 0, 1, 1, ?, ?)
            ON CONFLICT(key) DO UPDATE SET
                part_type = excluded.part_type,
                image_path = excluded.image_path,
                rarity = excluded.rarity,
                element = excluded.element,
                series = excluded.series,
                frame_type = excluded.frame_type,
                series_key = excluded.series_key,
                series_label = excluded.series_label,
                display_name_ja = excluded.display_name_ja,
                is_active = 1,
                is_admin_only = excluded.is_admin_only
            """,
            (
                part["part_type"],
                part["key"],
                part["image_path"],
                part["rarity"],
                part["element"],
                part["series"],
                part.get("frame_type") or "normal",
                part.get("series_key") or part.get("series"),
                part.get("series_label"),
                part["display_name_ja"],
                int(part.get("is_admin_only", 0)),
                now,
            ),
        )
    for part in INSECT_R_PART_DEFINITIONS:
        db.execute(
            """
            INSERT INTO robot_parts (
                part_type,
                key,
                image_path,
                rarity,
                element,
                series,
                frame_type,
                series_key,
                series_label,
                display_name_ja,
                offset_x,
                offset_y,
                is_active,
                is_unlocked,
                is_admin_only,
                created_at
            )
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 0, 0, 1, 1, 0, ?)
            ON CONFLICT(key) DO UPDATE SET
                part_type = excluded.part_type,
                image_path = excluded.image_path,
                rarity = excluded.rarity,
                element = excluded.element,
                series = excluded.series,
                frame_type = excluded.frame_type,
                series_key = excluded.series_key,
                series_label = excluded.series_label,
                display_name_ja = excluded.display_name_ja,
                is_active = 1,
                is_unlocked = 1,
                is_admin_only = 0
            """,
            (
                part["part_type"],
                part["key"],
                part["image_path"],
                part["rarity"],
                part["element"],
                part["series"],
                part.get("frame_type") or "insect",
                part.get("series_key") or part.get("series"),
                part.get("series_label"),
                part["display_name_ja"],
                now,
            ),
        )
        db.execute(
            """
            UPDATE robot_parts
            SET offset_x = COALESCE((SELECT src.offset_x FROM robot_parts src WHERE src.key = ? LIMIT 1), offset_x),
                offset_y = COALESCE((SELECT src.offset_y FROM robot_parts src WHERE src.key = ? LIMIT 1), offset_y)
            WHERE key = ?
            """,
            (part["source_key"], part["source_key"], part["key"]),
        )
    for part_key, series_key in PART_KEY_SERIES_ASSIGNMENTS.items():
        db.execute(
            """
            UPDATE robot_parts
            SET
                series = ?,
                frame_type = COALESCE((
                    SELECT sm.frame_type
                    FROM series_master sm
                    WHERE sm.series_key = ?
                    LIMIT 1
                ), frame_type, 'normal'),
                series_key = ?,
                series_label = (
                    SELECT display_name
                    FROM series_master
                    WHERE series_key = ?
                    LIMIT 1
                )
            WHERE key = ?
            """,
            (series_key, series_key, series_key, series_key, part_key),
        )
    db.execute(
        """
        UPDATE robot_parts
        SET frame_type = 'normal'
        WHERE frame_type IS NULL OR TRIM(frame_type) = ''
        """
    )
    db.execute("UPDATE robot_parts SET frame_type = 'dinosaur' WHERE COALESCE(series_key, series, '') LIKE 'dino_%'")
    db.execute(
        """
        UPDATE robot_parts
        SET
            series_key = COALESCE(NULLIF(TRIM(series_key), ''), NULLIF(TRIM(series), '')),
            series_label = COALESCE(
                NULLIF(TRIM(series_label), ''),
                (
                    SELECT sm.display_name
                    FROM series_master sm
                    WHERE sm.series_key = COALESCE(NULLIF(TRIM(robot_parts.series_key), ''), NULLIF(TRIM(robot_parts.series), ''))
                    LIMIT 1
                )
            )
        WHERE frame_type = 'insect'
        """
    )


def _sync_insect_part_display_names(db):
    changed = 0
    for part_key, display_name in INSECT_PART_DISPLAY_NAME_OVERRIDES.items():
        cur = db.execute(
            """
            UPDATE robot_parts
            SET display_name_ja = ?
            WHERE key = ?
              AND COALESCE(display_name_ja, '') != ?
            """,
            (display_name, part_key, display_name),
        )
        changed += int(cur.rowcount or 0)
    return changed


def release_series(db, series_key, *, emit_world_log=True):
    key = str(series_key or "").strip()
    if not key:
        return False
    meta = _series_meta_for_key(key)
    row = db.execute(
        "SELECT is_active, released_at FROM series_master WHERE series_key = ?",
        (key,),
    ).fetchone()
    if not row:
        return False
    already_active = int(row["is_active"] or 0) == 1
    released_at = int(time.time())
    db.execute(
        "UPDATE series_master SET is_active = 1, released_at = COALESCE(released_at, ?) WHERE series_key = ?",
        (released_at, key),
    )
    if emit_world_log and not already_active:
        _world_event_log(
            db,
            "series_released",
            {
                "message": f"{meta['display_name'] if meta else key} が解禁されました。",
                "series_key": key,
                "display_name": (meta.get("display_name") if meta else key),
                "category": (meta.get("category") if meta else ""),
            },
        )
    return not already_active


