def _count_part_inventory(db, user_id):
    return int(
        db.execute(
            "SELECT COUNT(*) AS c FROM part_instances WHERE user_id = ? AND status = 'inventory'",
            (user_id,),
        ).fetchone()["c"]
        or 0
    )


def _count_part_overflow(db, user_id):
    return int(
        db.execute(
            "SELECT COUNT(*) AS c FROM part_instances WHERE user_id = ? AND status = 'overflow'",
            (user_id,),
        ).fetchone()["c"]
        or 0
    )


def _count_part_legacy_storage(db, user_id):
    return int(
        db.execute(
            "SELECT COUNT(*) AS c FROM user_parts_inventory WHERE user_id = ?",
            (user_id,),
        ).fetchone()["c"]
        or 0
    )


def _part_storage_snapshot(db, user_id):
    inventory_count = _count_part_inventory(db, user_id)
    overflow_count = _count_part_overflow(db, user_id)
    legacy_count = _count_part_legacy_storage(db, user_id)
    return {
        "inventory_count": int(inventory_count),
        "overflow_count": int(overflow_count),
        "legacy_count": int(legacy_count),
        "storage_count": 0,
        "legacy_storage_count": int(overflow_count + legacy_count),
    }


def _inventory_space_remaining(db, user_id, user_row=None):
    if user_row is None:
        user_row = db.execute(
            "SELECT id, part_inventory_limit FROM users WHERE id = ?",
            (user_id,),
        ).fetchone()
    if not user_row:
        return 0
    limit = _part_inventory_limit_value(user_row["part_inventory_limit"] if "part_inventory_limit" in user_row.keys() else 60)
    used = _count_part_inventory(db, user_id)
    return max(0, limit - used)


def _next_part_instance_status(db, user_id, user_row=None):
    return "inventory"


def _return_part_instance_to_pool(db, user_id, part_instance_id, user_row=None):
    db.execute(
        "UPDATE part_instances SET status = 'inventory', updated_at = datetime('now') WHERE id = ? AND user_id = ?",
        (int(part_instance_id), int(user_id)),
    )
    return "inventory"


def _robot_decompose_return_part_count(rip_row, robot_row):
    if not rip_row:
        return 0
    slots = (
        ("head_part_instance_id", "head_key"),
        ("r_arm_part_instance_id", "r_arm_key"),
        ("l_arm_part_instance_id", "l_arm_key"),
        ("legs_part_instance_id", "legs_key"),
    )
    count = 0
    for instance_col, key_col in slots:
        if instance_col in rip_row.keys() and rip_row[instance_col]:
            count += 1
        elif key_col in robot_row.keys() and robot_row[key_col]:
            count += 1
    return count


def _effective_limits(db, user):
    ent = db.execute("SELECT * FROM qol_entitlements WHERE user_id = ?", (user["id"],)).fetchone()
    slot_bonus = ent["slot_bonus"] if ent else 0
    showcase_slots = ent["showcase_slots"] if ent else 1
    return {
        "robot_slots": user["robot_slot_limit"] + slot_bonus,
        "part_inventory": _part_inventory_limit_value(user["part_inventory_limit"] if "part_inventory_limit" in user.keys() else 60),
        "showcase_slots": showcase_slots,
    }


def _create_robot_instance(
    db,
    user_id,
    robot_name,
    head_key,
    r_arm_key,
    l_arm_key,
    legs_key,
    decor_asset_id=None,
    status="active",
    personality=None,
    combat_mode="normal",
    frame_type="normal",
    is_mixed_frame=False,
    build_frame_mode=None,
    offsets=None,
):
    now = int(time.time())
    if not personality:
        personality = pick_personality()
    cur = db.execute(
        """
        INSERT INTO robot_instances (
            user_id, name, status, personality, combat_mode, frame_type, is_mixed_frame, build_frame_mode,
            style_key, style_stats_json, style_rank_json, created_at, updated_at
        )
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, 'stable', '{}', ?, ?, ?)
        """,
        (
            user_id,
            robot_name,
            status,
            personality,
            _normalize_combat_mode(combat_mode),
            _normalize_frame_type(frame_type),
            1 if is_mixed_frame else 0,
            _normalize_build_frame_mode(build_frame_mode or frame_type),
            encode_style_rank_state(empty_style_rank_state()),
            now,
            now,
        ),
    )
    instance_id = cur.lastrowid
    offsets = offsets or {}
    db.execute(
        """
        INSERT INTO robot_instance_parts (
            robot_instance_id, head_key, r_arm_key, l_arm_key, legs_key,
            head_offset_x, head_offset_y,
            r_arm_offset_x, r_arm_offset_y,
            l_arm_offset_x, l_arm_offset_y,
            legs_offset_x, legs_offset_y,
            head_scale_percent, r_arm_scale_percent, l_arm_scale_percent, legs_scale_percent,
            decor_asset_id
        )
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        """,
        (
            instance_id,
            head_key,
            r_arm_key,
            l_arm_key,
            legs_key,
            int(offsets.get("head_offset_x", 0)),
            int(offsets.get("head_offset_y", 0)),
            int(offsets.get("r_arm_offset_x", 0)),
            int(offsets.get("r_arm_offset_y", 0)),
            int(offsets.get("l_arm_offset_x", 0)),
            int(offsets.get("l_arm_offset_y", 0)),
            int(offsets.get("legs_offset_x", 0)),
            int(offsets.get("legs_offset_y", 0)),
            _normalize_build_scale_percent(offsets.get("head_scale_percent", BUILD_PART_SCALE_DEFAULT)),
            _normalize_build_scale_percent(offsets.get("r_arm_scale_percent", BUILD_PART_SCALE_DEFAULT)),
            _normalize_build_scale_percent(offsets.get("l_arm_scale_percent", BUILD_PART_SCALE_DEFAULT)),
            _normalize_build_scale_percent(offsets.get("legs_scale_percent", BUILD_PART_SCALE_DEFAULT)),
            decor_asset_id,
        ),
    )
    return instance_id


def _add_part_drop(
    db,
    user_id,
    part_type=None,
    part_key=None,
    source="battle_drop",
    robot_instance_id=None,
    rarity=None,
    plus=0,
    as_instance=False,
    announce_username=None,
    area_key=None,
    campaign_key=None,
    campaign_label=None,
):
    rarity_code = (rarity or "").upper()
    if part_type is None or part_key is None:
        part = _pick_drop_part_master(db, rarity=rarity, area_key=area_key, user_id=user_id)
        if rarity_code == "R" and not part:
            return None
        if not part:
            part = db.execute(
                """
                SELECT rp.*
                FROM robot_parts rp
                LEFT JOIN series_master sm ON sm.series_key = rp.series
                WHERE rp.is_active = 1
                  AND (UPPER(COALESCE(rp.rarity, '')) != 'R' OR rp.is_unlocked = 1)
                  AND COALESCE(rp.is_admin_only, 0) = 0
                  AND NOT (
                        COALESCE(rp.frame_type, 'normal') = 'dinosaur'
                        OR COALESCE(rp.series_key, rp.series, '') LIKE 'dino_%'
                  )
                  AND (
                        COALESCE(TRIM(rp.series), '') = ''
                        OR rp.series IN ('S1', 'n1')
                        OR sm.series_key IS NULL
                        OR sm.is_active = 1
                  )
                ORDER BY RANDOM() LIMIT 1
                """
            ).fetchone()
        if not part:
            return None
        part_type = part["part_type"] if part_type is None else part_type
        part_key = part["key"] if part_key is None else part_key
    else:
        part = _get_part_by_key(db, part_key)

    create_as_instance = bool(as_instance or source == "battle_drop")
    if create_as_instance and part:
        inventory_full = _inventory_space_remaining(db, user_id) <= 0
        auto_sold = bool(AUTO_SELL_ENABLED and inventory_full)
        storage_status = "sold" if auto_sold else "inventory"
        pi_id = _create_part_instance_from_master(
            db,
            user_id,
            part,
            plus=int(plus),
            area_key=area_key,
            status=storage_status,
        )
        tendency = _area_growth_tendency(area_key)
        if announce_username:
            pi_row = db.execute("SELECT * FROM part_instances WHERE id = ?", (pi_id,)).fetchone()
            if pi_row:
                _maybe_post_research_title(db, user_id, announce_username, dict(pi_row))
        auto_sell_price = _auto_sell_value(
            {
                "rarity": part["rarity"] if "rarity" in part.keys() else "N",
                "master_rarity": part["rarity"] if "rarity" in part.keys() else "N",
                "plus": int(plus),
            }
        ) if auto_sold else 0
        if auto_sold:
            before = int(
                db.execute(
                    "SELECT COALESCE(coins, 0) AS coins FROM users WHERE id = ?",
                    (int(user_id),),
                ).fetchone()["coins"]
                or 0
            )
            db.execute(
                "UPDATE users SET coins = COALESCE(coins, 0) + ? WHERE id = ?",
                (int(auto_sell_price), int(user_id)),
            )
            request_ip = None
            try:
                request_ip = request.remote_addr
            except RuntimeError:
                request_ip = None
            audit_log(
                db,
                AUDIT_EVENT_TYPES["PART_AUTO_SELL"],
                user_id=int(user_id),
                request_id=getattr(g, "request_id", None),
                action_key="part_auto_sell",
                entity_type="part_instance",
                entity_id=int(pi_id),
                delta_coins=int(auto_sell_price),
                delta_count=1,
                payload={
                    "part_instance_id": int(pi_id),
                    "part_key": part["key"],
                    "rarity": str(part["rarity"] or "N").upper(),
                    "part_type": part["part_type"],
                    "sell_price": int(auto_sell_price),
                    "reason": "inventory_full",
                    "area_key": area_key,
                    "coin_before": int(before),
                    "coin_after": int(before + auto_sell_price),
                },
                ip=request_ip,
            )
        return {
            "part_type": part["part_type"],
            "part_key": part["key"],
            "rarity": part["rarity"],
            "plus": int(plus),
            "part_instance_id": pi_id,
            "source": source,
            "campaign_key": campaign_key,
            "campaign_label": campaign_label,
            "storage_status": storage_status,
            "auto_sold": auto_sold,
            "auto_sell_price": int(auto_sell_price),
            "growth_tendency_key": (tendency.get("key") if tendency else None),
            "growth_tendency_label": (tendency.get("label") if tendency else None),
        }
    db.execute(
        """
        INSERT INTO user_parts_inventory (user_id, part_type, part_key, obtained_at, source, robot_instance_id)
        VALUES (?, ?, ?, ?, ?, ?)
        """,
        (user_id, part_type, part_key, int(time.time()), source, robot_instance_id),
    )
    return {"part_type": part_type, "part_key": part_key, "source": source}


def _drop_audit_payload(area_key, battle_no, dropped_part):
    row = dropped_part or {}
    return {
        "area_key": area_key,
        "battle_no": battle_no,
        "drop_type": row.get("drop_type"),
        "source": row.get("source"),
        "campaign_key": row.get("campaign_key"),
        "campaign_label": row.get("campaign_label"),
        "part_type": row.get("part_type"),
        "part_key": row.get("part_key"),
        "rarity": row.get("rarity"),
        "plus": row.get("plus"),
        "storage_status": row.get("storage_status"),
        "auto_sold": bool(row.get("auto_sold")),
        "auto_sell_price": int(row.get("auto_sell_price") or 0),
        "growth_tendency_key": row.get("growth_tendency_key"),
        "growth_tendency_label": row.get("growth_tendency_label"),
    }


def _research_module_stat_line(module):
    if not module:
        return ""
    labels = {
        "hp_bonus": "耐久",
        "atk_bonus": "攻撃",
        "def_bonus": "防御",
        "spd_bonus": "素早さ",
        "acc_bonus": "命中",
        "cri_bonus": "会心",
    }
    parts = []
    for key, label in labels.items():
        raw_value = module.get(key) if isinstance(module, dict) else module[key]
        value = int(raw_value or 0)
        if value == 0:
            continue
        sign = "+" if value > 0 else ""
        parts.append(f"{label} {sign}{value}")
    return " / ".join(parts)


def _research_module_stat_chips(module):
    if not module:
        return []
    labels = {
        "hp_bonus": "耐久",
        "atk_bonus": "攻撃",
        "def_bonus": "防御",
        "spd_bonus": "素早さ",
        "acc_bonus": "命中",
        "cri_bonus": "会心",
    }
    chips = []
    for key, label in labels.items():
        try:
            raw_value = module.get(key) if isinstance(module, dict) else module[key]
        except (KeyError, IndexError):
            raw_value = 0
        value = int(raw_value or 0)
        if value == 0:
            continue
        sign = "+" if value > 0 else ""
        chips.append(
            {
                "label": label,
                "value": value,
                "text": f"{label} {sign}{value}",
                "tone": "positive" if value > 0 else "negative",
            }
        )
    return chips


def _research_module_family_label(family_key):
    labels = {
        "sniper": "精密",
        "heavy": "重装",
        "assault": "突撃",
        "stable": "安定",
        "berserk": "暴走",
        "analysis": "解析",
        "synthesized": "合成",
    }
    return labels.get(str(family_key or "").strip(), str(family_key or "").strip() or "研究")


def _synthesized_module_name(module):
    if not module:
        return "研究合成モジュール"
    try:
        generated_name = module.get("generated_name_ja") if isinstance(module, dict) else module["generated_name_ja"]
    except (KeyError, IndexError):
        generated_name = None
    if generated_name:
        return str(generated_name)
    try:
        master_name = module.get("name_ja") if isinstance(module, dict) else module["name_ja"]
    except (KeyError, IndexError):
        master_name = None
    if master_name:
        return str(master_name)
    try:
        family = module.get("synthesis_family") if isinstance(module, dict) else module["synthesis_family"]
    except (KeyError, IndexError):
        family = ""
    family = str(family or "").strip()
    if family.lower() == "none":
        family = ""
    if family in RESEARCH_MODULE_FAMILY_PAIR_NAMES:
        return RESEARCH_MODULE_FAMILY_PAIR_NAMES[family]
    parts = [part for part in family.split("_") if part]
    if len(parts) >= 2:
        return f"{_research_module_family_label(parts[0])}{_research_module_family_label(parts[1])}モジュール"
    if parts:
        return f"{_research_module_family_label(parts[0])}合成モジュール"
    return "研究合成モジュール"


def _research_module_view(row):
    if not row:
        return None
    module = dict(row)
    if module.get("module_key") == RESEARCH_MODULE_SYNTHESIS_KEY:
        module["name_ja"] = _synthesized_module_name(module)
        module["rarity"] = module.get("synthesis_grade") or module.get("rarity") or "refined"
        module["family"] = module.get("synthesis_family") or module.get("family") or "synthesized"
        module["result_label"] = RESEARCH_MODULE_SYNTHESIS_RESULT_LABELS.get(str(module.get("synthesis_result_type") or ""), "研究合成")
        module["synthesis_grade_label"] = {
            "prototype": "試作型",
            "refined": "改良型",
            "complete": "完成型",
            "anomaly": "異常型",
        }.get(str(module.get("synthesis_grade") or ""), str(module.get("synthesis_grade") or ""))
    else:
        module["result_label"] = ""
        module["synthesis_grade_label"] = ""
    module["stat_line"] = _research_module_stat_line(module)
    module["stat_chips"] = _research_module_stat_chips(module)
    module["effect_text"] = module["stat_line"] if module["stat_line"] else ("合成結果によって変化" if module.get("module_key") == RESEARCH_MODULE_SYNTHESIS_KEY else "なし")
    rarity_key = str(module.get("rarity") or "").strip()
    family_key = str(module.get("family") or "").strip()
    if family_key.lower() == "none":
        family_key = ""
    module["rarity_label"] = RESEARCH_MODULE_RARITY_LABELS.get(rarity_key, rarity_key or "研究")
    module["family_label"] = RESEARCH_MODULE_FAMILY_LABELS.get(family_key, _research_module_family_label(family_key) if family_key else "研究")
    module["tier_label"] = RESEARCH_MODULE_TIER_LABELS.get(int(module.get("tier") or 0), "")
    module["trade_policy_label"] = RESEARCH_MODULE_TRADE_POLICY_LABELS.get(str(module.get("trade_policy") or ""), "")
    if module.get("module_key") == RESEARCH_MODULE_SYNTHESIS_KEY:
        family_parts = [part for part in str(module.get("synthesis_family") or "").split("_") if part and part.lower() != "none"]
        if family_parts:
            module["family_label"] = " × ".join(RESEARCH_MODULE_FAMILY_LABELS.get(part, _research_module_family_label(part)) for part in family_parts)
        else:
            module["family_label"] = "合成"
        grade_label = module.get("synthesis_grade_label") or RESEARCH_MODULE_RARITY_LABELS.get(str(module.get("synthesis_grade") or ""), "")
        module["type_label"] = f"研究合成・{grade_label}" if grade_label else "研究合成"
        module["source_label"] = "研究合成"
    else:
        module["type_label"] = f"{module['rarity_label']}・{module['family_label']}系"
    module["source_label"] = _research_module_source_label(module)
    module["select_label"] = f"{module['name_ja']}｜{module['stat_line'] or module['effect_text']}"
    return module


def _research_module_source_label(module):
    if not module:
        return ""
    module_key = str(module.get("module_key") if isinstance(module, dict) else module["module_key"] or "")
    rarity = str(module.get("rarity") if isinstance(module, dict) else module["rarity"] or "")
    if module_key == RESEARCH_MODULE_SYNTHESIS_KEY:
        return "研究合成"
    if rarity == "complete":
        source_name = RESEARCH_MODULE_PROTOTYPE_NAME_BY_COMPLETE.get(module_key)
        if source_name:
            return f"{source_name} x3 合成"
        return "試作型 x3 合成"
    return RESEARCH_MODULE_SOURCE_LABELS.get(module_key, "通常戦ドロップ / 研究ゲージ保証")


def _active_research_module_for_user(db, user_id, user_row=None):
    user = user_row or db.execute("SELECT * FROM users WHERE id = ?", (int(user_id),)).fetchone()
    if not user or "active_research_module_instance_id" not in user.keys():
        return None
    module_instance_id = user["active_research_module_instance_id"]
    if not module_instance_id:
        return None
    row = db.execute(
        """
        SELECT urm.id AS instance_id, urm.user_id, urm.module_key, urm.status,
               rm.name_ja, rm.rarity, rm.family,
               COALESCE(urm.hp_bonus, rm.hp_bonus) AS hp_bonus,
               COALESCE(urm.atk_bonus, rm.atk_bonus) AS atk_bonus,
               COALESCE(urm.def_bonus, rm.def_bonus) AS def_bonus,
               COALESCE(urm.spd_bonus, rm.spd_bonus) AS spd_bonus,
               COALESCE(urm.acc_bonus, rm.acc_bonus) AS acc_bonus,
               COALESCE(urm.cri_bonus, rm.cri_bonus) AS cri_bonus,
               rm.description, rm.tier, rm.trade_policy, rm.source_type, rm.is_limited, rm.npc_sell_price,
               rm.is_active, urm.is_locked, urm.sold_at, urm.synthesis_grade, urm.synthesis_family,
               urm.synthesis_result_type, urm.origin_module_a_id, urm.origin_module_b_id,
               urm.generation, urm.synthesis_score, urm.generated_name_ja
        FROM user_research_modules urm
        JOIN research_modules rm ON rm.module_key = urm.module_key
        WHERE urm.id = ?
          AND urm.user_id = ?
          AND urm.status = 'inventory'
          AND rm.is_active = 1
        LIMIT 1
        """,
        (int(module_instance_id), int(user_id)),
    ).fetchone()
    return _research_module_view(row)


def _user_research_module_options(db, user_id):
    rows = db.execute(
        """
        SELECT urm.id AS instance_id, urm.user_id, urm.module_key, urm.status,
               rm.name_ja, rm.rarity, rm.family,
               COALESCE(urm.hp_bonus, rm.hp_bonus) AS hp_bonus,
               COALESCE(urm.atk_bonus, rm.atk_bonus) AS atk_bonus,
               COALESCE(urm.def_bonus, rm.def_bonus) AS def_bonus,
               COALESCE(urm.spd_bonus, rm.spd_bonus) AS spd_bonus,
               COALESCE(urm.acc_bonus, rm.acc_bonus) AS acc_bonus,
               COALESCE(urm.cri_bonus, rm.cri_bonus) AS cri_bonus,
               rm.description, rm.tier, rm.trade_policy, rm.source_type, rm.is_limited, rm.npc_sell_price,
               rm.is_active, urm.is_locked, urm.sold_at, urm.synthesis_grade, urm.synthesis_family,
               urm.synthesis_result_type, urm.origin_module_a_id, urm.origin_module_b_id,
               urm.generation, urm.synthesis_score, urm.generated_name_ja
        FROM user_research_modules urm
        JOIN research_modules rm ON rm.module_key = urm.module_key
        WHERE urm.user_id = ?
          AND urm.status = 'inventory'
          AND rm.is_active = 1
        ORDER BY rm.rarity ASC, rm.family ASC, urm.id ASC
        """,
        (int(user_id),),
    ).fetchall()
    return [_research_module_view(row) for row in rows]


def _apply_research_module_to_stats(stats, module):
    if not module:
        return dict(stats or {})
    result = dict(stats or {})
    bonus_keys = {
        "hp": "hp_bonus",
        "atk": "atk_bonus",
        "def": "def_bonus",
        "spd": "spd_bonus",
        "acc": "acc_bonus",
        "cri": "cri_bonus",
    }
    for stat_key, bonus_key in bonus_keys.items():
        result[stat_key] = max(1, int(result.get(stat_key) or 0) + int(module.get(bonus_key) or 0))
    return result


def _research_module_bonus_payload(module):
    payload = {}
    for key in ("hp_bonus", "atk_bonus", "def_bonus", "spd_bonus", "acc_bonus", "cri_bonus"):
        payload[key] = int((module or {}).get(key) or 0)
    return payload


def _research_module_strategy_metrics(turn_logs, *, result_win=False):
    logs = [dict(item) for item in (turn_logs or []) if isinstance(item, dict) and not item.get("separator_line")]
    player_damage_values = [max(0, int(item.get("player_damage") or 0)) for item in logs]
    metrics = {
        "turn_count": len(logs),
        "player_miss_count": sum(
            1
            for item in logs
            if str(item.get("player_action") or "").strip() not in {"", "行動不能", "追撃不要"}
            and int(item.get("player_damage") or 0) <= 0
        ),
        "player_crit_count": sum(1 for item in logs if bool(item.get("critical"))),
        "player_max_damage": max(player_damage_values) if player_damage_values else 0,
        "player_total_damage": sum(player_damage_values),
        "player_damage_taken": sum(max(0, int(item.get("enemy_damage") or 0)) for item in logs),
        "player_hp_remaining": int(logs[-1].get("player_after") or 0) if logs else 0,
        "result_win": bool(result_win),
    }
    return metrics


def _research_module_strategy_message(module, metrics):
    if not metrics.get("result_win"):
        return "作戦失敗。別の作戦や強化も試してみましょう。"
    if int(metrics.get("player_hp_remaining") or 0) <= 3:
        return "ギリギリの勝利。作戦が勝負を分けました。"
    if int(metrics.get("player_crit_count") or 0) > 0:
        return "会心が発生し、攻めの作戦が光りました。"
    if int(metrics.get("player_miss_count") or 0) == 0 and int((module or {}).get("acc_bonus") or 0) > 0:
        return "MISSなし。命中作戦が安定しました。"
    return "作戦成功！このモジュールを使って勝利しました。"


def _research_module_strategy_card(module, turn_logs, *, result_win=False):
    if not module:
        return None
    module_view = dict(module)
    bonuses = _research_module_bonus_payload(module_view)
    stat_chips = list(module_view.get("stat_chips") or [])
    if not stat_chips and module_view.get("module_key") == RESEARCH_MODULE_SYNTHESIS_KEY:
        stat_chips = [{"text": "効果: 合成結果によって変化", "tone": "neutral"}]
    metrics = _research_module_strategy_metrics(turn_logs, result_win=result_win)
    metric_lines = []
    if int(metrics["turn_count"]) > 0:
        metric_lines.append(f"ターン {int(metrics['turn_count'])}")
    metric_lines.append(f"会心 {int(metrics['player_crit_count'])}回")
    metric_lines.append(f"MISS {int(metrics['player_miss_count'])}回")
    if int(metrics["player_max_damage"]) > 0:
        metric_lines.append(f"最大ダメージ {int(metrics['player_max_damage'])}")
    return {
        "module_instance_id": int(module_view.get("instance_id") or 0),
        "module_key": str(module_view.get("module_key") or ""),
        "module_name": str(module_view.get("name_ja") or "研究モジュール").strip() or "研究モジュール",
        "type_label": str(module_view.get("type_label") or module_view.get("rarity_label") or "研究モジュール"),
        "family_label": str(module_view.get("family_label") or "研究"),
        "result_type": str(module_view.get("synthesis_result_type") or ""),
        "result_label": str(module_view.get("result_label") or ""),
        "stat_chips": stat_chips,
        "bonuses": bonuses,
        "message": _research_module_strategy_message(module_view, metrics),
        "metrics": metrics,
        "metric_lines": metric_lines,
    }


def _recommend_areas_for_module(module):
    bonuses = _research_module_bonus_payload(module)
    if bonuses["acc_bonus"] >= 6:
        return {
            "reason": "命中が高めなので、回避の高い敵が出るエリアで試しやすいです。",
            "areas": ["第2層Mist", "第4層Haze"],
        }
    if bonuses["hp_bonus"] >= 8 or bonuses["def_bonus"] >= 6:
        return {
            "reason": "耐久や防御が高めなので、長期戦になりやすいエリアで試しやすいです。",
            "areas": ["第4層Forge", "第5層Labyrinth"],
        }
    if bonuses["atk_bonus"] >= 8 or bonuses["cri_bonus"] >= 6:
        return {
            "reason": "攻撃や会心が高めなので、短期決戦のエリアで試しやすいです。",
            "areas": ["第2層Rush", "第4層Burst"],
        }
    if bonuses["spd_bonus"] >= 5:
        return {
            "reason": "素早さが高めなので、先手を取りたいエリアで試しやすいです。",
            "areas": ["第2層Rush", "第5層Pinnacle"],
        }
    return None


def _register_research_module_catalog(db, user_id, module_key, module_instance_id, *, source="admin", request_id=None, ip=None):
    now_ts = int(time.time())
    cur = db.execute(
        """
        INSERT OR IGNORE INTO user_research_module_catalog (
            user_id, module_key, first_obtained_at, first_instance_id
        )
        VALUES (?, ?, ?, ?)
        """,
        (int(user_id), str(module_key or "").strip(), now_ts, int(module_instance_id) if module_instance_id else None),
    )
    if int(cur.rowcount or 0) <= 0:
        return False
    audit_log(
        db,
        AUDIT_EVENT_TYPES["MODULE_CATALOG_REGISTER"],
        user_id=int(user_id),
        request_id=request_id,
        action_key="module_catalog_register",
        entity_type="research_module",
        entity_id=int(module_instance_id) if module_instance_id else None,
        delta_count=1,
        payload={
            "user_id": int(user_id),
            "module_key": str(module_key or "").strip(),
            "module_instance_id": int(module_instance_id) if module_instance_id else None,
            "source": str(source or "admin"),
        },
        ip=ip,
    )
    return True


def _grant_research_module_instance(db, user_id, module_key, *, source="admin", request_id=None, ip=None):
    module = db.execute(
        """
        SELECT *
        FROM research_modules
        WHERE module_key = ?
          AND is_active = 1
        LIMIT 1
        """,
        (str(module_key or "").strip(),),
    ).fetchone()
    if not module:
        return None
    now_ts = int(time.time())
    cur = db.execute(
        """
        INSERT INTO user_research_modules (user_id, module_key, status, created_at, updated_at)
        VALUES (?, ?, 'inventory', ?, ?)
        """,
        (int(user_id), module["module_key"], now_ts, now_ts),
    )
    instance_id = int(cur.lastrowid)
    _register_research_module_catalog(
        db,
        user_id,
        module["module_key"],
        instance_id,
        source=source,
        request_id=request_id,
        ip=ip,
    )
    payload = _research_module_view(module)
    payload["instance_id"] = instance_id
    return payload


def _roll_research_module_drop(db, user_id, area_key, *, rng=None):
    config = RESEARCH_MODULE_DROP_CONFIG.get(str(area_key or "").strip())
    if not config:
        return None
    rate, candidates = config
    roller = rng or random
    if roller.random() >= float(rate):
        return None
    module_key = roller.choice(tuple(candidates))
    return _grant_research_module_instance(db, user_id, module_key, source="drop")


def _advance_research_module_pity(db, user_id, area_key, *, rng=None, request_id=None, ip=None):
    gain = int(RESEARCH_MODULE_PITY_GAIN_BY_AREA.get(str(area_key or "").strip(), 0) or 0)
    if gain <= 0:
        return {"gain": 0, "before": None, "after": None, "grant": None}
    row = db.execute(
        "SELECT COALESCE(research_module_pity, 0) AS pity FROM users WHERE id = ?",
        (int(user_id),),
    ).fetchone()
    before = int(row["pity"] or 0) if row else 0
    after = before + gain
    grant = None
    roller = rng or random
    if after >= int(RESEARCH_MODULE_PITY_TARGET):
        module_key = roller.choice(tuple(RESEARCH_MODULE_PITY_CANDIDATES))
        grant = _grant_research_module_instance(db, user_id, module_key, source="pity", request_id=request_id, ip=ip)
        if grant:
            after -= int(RESEARCH_MODULE_PITY_TARGET)
    db.execute(
        "UPDATE users SET research_module_pity = ? WHERE id = ?",
        (max(0, int(after)), int(user_id)),
    )
    audit_log(
        db,
        AUDIT_EVENT_TYPES["MODULE_PITY_PROGRESS"],
        user_id=int(user_id),
        request_id=request_id,
        action_key="explore",
        entity_type="research_module_pity",
        delta_count=gain,
        payload={
            "user_id": int(user_id),
            "area_key": area_key,
            "gain": gain,
            "before": before,
            "after": max(0, int(after)),
            "target": int(RESEARCH_MODULE_PITY_TARGET),
        },
        ip=ip,
    )
    if grant:
        audit_log(
            db,
            AUDIT_EVENT_TYPES["MODULE_PITY_GRANT"],
            user_id=int(user_id),
            request_id=request_id,
            action_key="explore",
            entity_type="research_module",
            entity_id=grant.get("instance_id"),
            delta_count=1,
            payload={
                "user_id": int(user_id),
                "area_key": area_key,
                "module_key": grant.get("module_key"),
                "module_name": grant.get("name_ja"),
                "rarity": grant.get("rarity"),
                "family": grant.get("family"),
                "pity_before": before,
                "pity_after": max(0, int(after)),
                "target": int(RESEARCH_MODULE_PITY_TARGET),
            },
            ip=ip,
        )
    return {"gain": gain, "before": before, "after": max(0, int(after)), "grant": grant}


def _research_module_combine_candidates(db, user_id):
    user = db.execute("SELECT active_research_module_instance_id FROM users WHERE id = ?", (int(user_id),)).fetchone()
    active_id = int(user["active_research_module_instance_id"] or 0) if user and user["active_research_module_instance_id"] else 0
    rows = db.execute(
        """
        SELECT urm.module_key, rm.name_ja, rm.family, COUNT(*) AS count
        FROM user_research_modules urm
        JOIN research_modules rm ON rm.module_key = urm.module_key
        WHERE urm.user_id = ?
          AND urm.status = 'inventory'
          AND COALESCE(urm.is_locked, 0) = 0
          AND (? = 0 OR urm.id != ?)
          AND rm.rarity = 'prototype'
          AND rm.is_active = 1
        GROUP BY urm.module_key, rm.name_ja, rm.family
        HAVING COUNT(*) >= 3
        ORDER BY rm.family ASC, urm.module_key ASC
        """,
        (int(user_id), active_id, active_id),
    ).fetchall()
    candidates = []
    for row in rows:
        source_key = str(row["module_key"] or "")
        result_key = RESEARCH_MODULE_COMBINE_MAP.get(source_key)
        if not result_key:
            continue
        result = db.execute(
            "SELECT name_ja FROM research_modules WHERE module_key = ? AND rarity = 'complete' AND is_active = 1",
            (result_key,),
        ).fetchone()
        if not result:
            continue
        candidates.append(
            {
                "source_module_key": source_key,
                "source_name": row["name_ja"],
                "result_module_key": result_key,
                "result_name": result["name_ja"],
                "count": int(row["count"] or 0),
            }
        )
    return candidates


def _research_module_catalog_summary(db, user_id):
    total = int(
        db.execute("SELECT COUNT(*) AS c FROM research_modules WHERE is_active = 1").fetchone()["c"] or 0
    )
    registered = int(
        db.execute(
            """
            SELECT COUNT(*) AS c
            FROM user_research_module_catalog c
            JOIN research_modules rm ON rm.module_key = c.module_key
            WHERE c.user_id = ?
              AND rm.is_active = 1
            """,
            (int(user_id),),
        ).fetchone()["c"] or 0
    )
    percent = int((registered * 100) // total) if total > 0 else 0
    return {"registered": registered, "total": total, "percent": percent}


def _research_module_catalog_rows(db, user_id):
    rows = db.execute(
        """
        SELECT rm.*,
               c.first_obtained_at,
               c.first_instance_id,
               COUNT(CASE WHEN urm.status = 'inventory' THEN 1 END) AS owned_count
        FROM research_modules rm
        LEFT JOIN user_research_module_catalog c
          ON c.module_key = rm.module_key
         AND c.user_id = ?
        LEFT JOIN user_research_modules urm
          ON urm.module_key = rm.module_key
         AND urm.user_id = ?
         AND urm.status = 'inventory'
        WHERE rm.is_active = 1
        GROUP BY rm.module_key
        ORDER BY rm.tier ASC, rm.family ASC, rm.rarity DESC, rm.module_key ASC
        """,
        (int(user_id), int(user_id)),
    ).fetchall()
    result = []
    for row in rows:
        item = _research_module_view(row)
        item["owned_count"] = int(row["owned_count"] or 0)
        item["is_registered"] = row["first_obtained_at"] is not None
        item["first_obtained_at"] = row["first_obtained_at"]
        result.append(item)
    return result


def _research_module_instance_row(db, module_instance_id, user_id=None):
    where = ["urm.id = ?", "rm.is_active = 1"]
    params = [int(module_instance_id)]
    if user_id is not None:
        where.append("urm.user_id = ?")
        params.append(int(user_id))
    row = db.execute(
        f"""
        SELECT urm.id AS instance_id, urm.user_id, urm.module_key, urm.status,
               rm.name_ja, rm.rarity, rm.family,
               COALESCE(urm.hp_bonus, rm.hp_bonus) AS hp_bonus,
               COALESCE(urm.atk_bonus, rm.atk_bonus) AS atk_bonus,
               COALESCE(urm.def_bonus, rm.def_bonus) AS def_bonus,
               COALESCE(urm.spd_bonus, rm.spd_bonus) AS spd_bonus,
               COALESCE(urm.acc_bonus, rm.acc_bonus) AS acc_bonus,
               COALESCE(urm.cri_bonus, rm.cri_bonus) AS cri_bonus,
               rm.description, rm.tier, rm.trade_policy, rm.source_type, rm.is_limited, rm.npc_sell_price,
               rm.is_active, urm.is_locked, urm.sold_at, urm.synthesis_grade, urm.synthesis_family,
               urm.synthesis_result_type, urm.origin_module_a_id, urm.origin_module_b_id,
               COALESCE(urm.generation, 0) AS generation, COALESCE(urm.synthesis_score, 0) AS synthesis_score,
               urm.generated_name_ja
        FROM user_research_modules urm
        JOIN research_modules rm ON rm.module_key = urm.module_key
        WHERE {' AND '.join(where)}
        LIMIT 1
        """,
        params,
    ).fetchone()
    return _research_module_view(row)


def _research_module_bonus_dict(module):
    return {
        "hp_bonus": int((module or {}).get("hp_bonus") or 0),
        "atk_bonus": int((module or {}).get("atk_bonus") or 0),
        "def_bonus": int((module or {}).get("def_bonus") or 0),
        "spd_bonus": int((module or {}).get("spd_bonus") or 0),
        "acc_bonus": int((module or {}).get("acc_bonus") or 0),
        "cri_bonus": int((module or {}).get("cri_bonus") or 0),
    }


def _research_module_stats_total(stats):
    return sum(max(0, int((stats or {}).get(key) or 0)) for key in ("hp_bonus", "atk_bonus", "def_bonus", "spd_bonus", "acc_bonus", "cri_bonus"))


def _research_module_reroll_rule(module):
    rarity = str((module or {}).get("rarity") or "").strip()
    rule = RESEARCH_MODULE_REROLL_RULES.get(rarity)
    if rule:
        return {**rule, "rarity_key": rarity}
    return None


def _roll_research_module_reroll_bonuses(module, *, rng=None):
    rule = _research_module_reroll_rule(module)
    if not rule:
        raise ValueError("unsupported module rarity")
    roller = rng or random
    stat_keys = ("hp", "atk", "def", "spd", "acc", "cri")
    slots = min(len(stat_keys), max(1, int(rule["slots"])))
    before_total = _research_module_stats_total(_research_module_bonus_dict(module))
    if before_total > 0:
        target_min = max(1, int(round(before_total * 0.95)))
        target_max = max(target_min, int(round(before_total * 1.05)))
        target_total = int(roller.randint(target_min, target_max))
        slots = min(slots, target_total, len(stat_keys))
        picked = roller.sample(stat_keys, slots)
        bonuses = {f"{key}_bonus": 0 for key in stat_keys}
        if slots == 1:
            bonuses[f"{picked[0]}_bonus"] = target_total
            return bonuses
        cuts = sorted(roller.sample(range(1, target_total), slots - 1))
        values = []
        previous = 0
        for cut in cuts + [target_total]:
            values.append(cut - previous)
            previous = cut
        roller.shuffle(values)
        for stat_key, value in zip(picked, values):
            bonuses[f"{stat_key}_bonus"] = int(value)
        return bonuses
    picked = roller.sample(stat_keys, slots)
    bonuses = {f"{key}_bonus": 0 for key in stat_keys}
    for stat_key in picked:
        bonuses[f"{stat_key}_bonus"] = int(roller.randint(int(rule["min"]), int(rule["max"])))
    return bonuses


def _module_reroll_candidate_payload(before_stats, candidate_stats):
    before_total = _research_module_stats_total(before_stats)
    candidate_total = _research_module_stats_total(candidate_stats)
    ratio = (float(candidate_total) / float(before_total)) if before_total > 0 else 0.0
    return {
        "before_total": int(before_total),
        "candidate_total": int(candidate_total),
        "total_delta": int(candidate_total - before_total),
        "total_ratio": ratio,
    }


def _expire_module_reroll_candidates(db, *, user_id=None, module_id=None, now_ts=None, request_id=None, ip=None):
    now_value = int(now_ts or time.time())
    where = ["status = 'pending'", "expires_at <= ?"]
    params = [now_value]
    if user_id is not None:
        where.append("user_id = ?")
        params.append(int(user_id))
    if module_id is not None:
        where.append("module_id = ?")
        params.append(int(module_id))
    rows = db.execute(
        f"SELECT * FROM module_reroll_candidates WHERE {' AND '.join(where)}",
        tuple(params),
    ).fetchall()
    for row in rows:
        db.execute(
            "UPDATE module_reroll_candidates SET status = 'expired', decided_at = ? WHERE id = ? AND status = 'pending'",
            (now_value, int(row["id"])),
        )
        audit_log(
            db,
            AUDIT_EVENT_TYPES["MODULE_REROLL_EXPIRE"],
            user_id=int(row["user_id"]),
            request_id=request_id,
            action_key="module_reroll_expire",
            entity_type="module_reroll_candidate",
            entity_id=int(row["id"]),
            payload={
                "user_id": int(row["user_id"]),
                "module_id": int(row["module_id"]),
                "candidate_id": int(row["id"]),
                "status": "expired",
            },
            ip=ip,
        )
    return len(rows)


def _pending_module_reroll_candidate(db, user_id, module_id, *, now_ts=None):
    now_value = int(now_ts or time.time())
    _expire_module_reroll_candidates(db, user_id=user_id, module_id=module_id, now_ts=now_value)
    return db.execute(
        """
        SELECT *
        FROM module_reroll_candidates
        WHERE user_id = ?
          AND module_id = ?
          AND status = 'pending'
          AND expires_at > ?
        ORDER BY id DESC
        LIMIT 1
        """,
        (int(user_id), int(module_id), now_value),
    ).fetchone()


def _annotate_research_module_reroll_status(modules, user):
    if isinstance(user, dict):
        coins = int(user.get("coins") or 0)
    elif user and "coins" in user.keys():
        coins = int(user["coins"] or 0)
    else:
        coins = 0
    for module in modules:
        rule = _research_module_reroll_rule(module)
        cost = int(rule["cost"]) if rule else 0
        module["reroll_cost"] = cost
        module["can_reroll"] = bool(rule) and int(module.get("is_locked") or 0) == 0 and coins >= cost
        if not rule:
            module["reroll_status_label"] = "再調整対象外"
        elif int(module.get("is_locked") or 0) != 0:
            module["reroll_status_label"] = "保護中"
        elif coins < cost:
            module["reroll_status_label"] = f"コイン不足（{cost}）"
        else:
            module["reroll_status_label"] = f"配分再調整 {cost}コイン"
    return modules


def _module_reroll_token_key(module_instance_id):
    return f"module_reroll_token:{int(module_instance_id)}"


def _validate_research_module_reroll_target(db, user_id, module_instance_id):
    module = _research_module_instance_row(db, int(module_instance_id), int(user_id))
    if not module:
        return None, "再調整できないモジュールです"
    if str(module.get("status") or "") != "inventory" or module.get("sold_at"):
        return None, "所持中のモジュールだけ再調整できます"
    if int(module.get("is_locked") or 0) != 0:
        return None, "保護中のモジュールは再調整できません"
    rule = _research_module_reroll_rule(module)
    if not rule:
        return None, "このモジュールは再調整できません"
    return module, ""


def execute_research_module_reroll(db, user_id, module_instance_id, *, request_id=None, ip=None, rng=None):
    module, error = _validate_research_module_reroll_target(db, user_id, module_instance_id)
    if error:
        return {"ok": False, "reason": error}
    pending = _pending_module_reroll_candidate(db, user_id, module_instance_id)
    if pending:
        return {
            "ok": False,
            "reason": "未決定の配分再調整候補があります。先に採用するか、今のままにしてください。",
            "pending_candidate_id": int(pending["id"]),
        }
    user = db.execute("SELECT * FROM users WHERE id = ? LIMIT 1", (int(user_id),)).fetchone()
    coins_before = int(user["coins"] or 0) if user else 0
    rule = _research_module_reroll_rule(module)
    cost = int(rule["cost"])
    if coins_before < cost:
        return {"ok": False, "reason": f"コインが足りません。必要: {cost} / 所持: {coins_before}"}
    before_stats = _research_module_bonus_dict(module)
    candidate_stats = _roll_research_module_reroll_bonuses(module, rng=rng)
    coins_after = coins_before - cost
    now_ts = int(time.time())
    db.execute("UPDATE users SET coins = ? WHERE id = ?", (coins_after, int(user_id)))
    cur = db.execute(
        """
        INSERT INTO module_reroll_candidates (
            user_id, module_id, before_stats_json, candidate_stats_json,
            cost_coins, status, created_at, expires_at, request_id
        )
        VALUES (?, ?, ?, ?, ?, 'pending', ?, ?, ?)
        """,
        (
            int(user_id),
            int(module_instance_id),
            json.dumps(before_stats, ensure_ascii=False, sort_keys=True),
            json.dumps(candidate_stats, ensure_ascii=False, sort_keys=True),
            cost,
            now_ts,
            now_ts + 86400,
            request_id,
        ),
    )
    candidate_id = int(cur.lastrowid)
    totals = _module_reroll_candidate_payload(before_stats, candidate_stats)
    payload = {
        "user_id": int(user_id),
        "module_id": int(module_instance_id),
        "module_instance_id": int(module_instance_id),
        "module_key": module["module_key"],
        "module_name": module["name_ja"],
        "rarity": module["rarity"],
        "cost": cost,
        "candidate_id": candidate_id,
        "status": "pending",
        "before_stats": before_stats,
        "candidate_stats": candidate_stats,
        "after_stats": candidate_stats,
        **totals,
        "coins_before": coins_before,
        "coins_after": coins_after,
    }
    audit_log(
        db,
        AUDIT_EVENT_TYPES["MODULE_REROLL_CANDIDATE_CREATE"],
        user_id=int(user_id),
        request_id=request_id,
        action_key="module_reroll_candidate_create",
        entity_type="module_reroll_candidate",
        entity_id=candidate_id,
        delta_coins=-cost,
        payload=payload,
        ip=ip,
    )
    audit_log(
        db,
        AUDIT_EVENT_TYPES["COIN_DELTA"],
        user_id=int(user_id),
        request_id=request_id,
        action_key="module_reroll",
        entity_type="module_reroll_candidate",
        entity_id=candidate_id,
        delta_coins=-cost,
        payload={**payload, "source": "module_reroll", "spend": cost},
        ip=ip,
    )
    db.commit()
    return {
        "ok": True,
        "module": module,
        "candidate_id": candidate_id,
        "before_stats": before_stats,
        "candidate_stats": candidate_stats,
        "after_stats": candidate_stats,
        **totals,
        "cost": cost,
        "coins_before": coins_before,
        "coins_after": coins_after,
        "expires_at": now_ts + 86400,
    }


def _module_reroll_candidate_row(db, candidate_id, user_id=None):
    where = ["id = ?"]
    params = [int(candidate_id)]
    if user_id is not None:
        where.append("user_id = ?")
        params.append(int(user_id))
    return db.execute(
        f"SELECT * FROM module_reroll_candidates WHERE {' AND '.join(where)} LIMIT 1",
        tuple(params),
    ).fetchone()


def module_reroll_candidate_view(db, candidate_id, user_id=None):
    row = _module_reroll_candidate_row(db, candidate_id, user_id)
    if not row:
        return None
    module = _research_module_instance_row(db, int(row["module_id"]), int(row["user_id"]))
    before_stats = json.loads(row["before_stats_json"] or "{}")
    candidate_stats = json.loads(row["candidate_stats_json"] or "{}")
    totals = _module_reroll_candidate_payload(before_stats, candidate_stats)
    return {
        "id": int(row["id"]),
        "user_id": int(row["user_id"]),
        "module_id": int(row["module_id"]),
        "module": module,
        "before_stats": before_stats,
        "candidate_stats": candidate_stats,
        "before_chips": _research_module_stat_chips(before_stats),
        "candidate_chips": _research_module_stat_chips(candidate_stats),
        "cost_coins": int(row["cost_coins"] or 0),
        "status": row["status"],
        "created_at": int(row["created_at"] or 0),
        "expires_at": int(row["expires_at"] or 0),
        "is_expired": int(row["expires_at"] or 0) <= int(time.time()),
        **totals,
    }


def accept_module_reroll_candidate(db, user_id, candidate_id, *, request_id=None, ip=None):
    row = _module_reroll_candidate_row(db, candidate_id, user_id)
    if not row:
        return {"ok": False, "reason": "配分再調整候補が見つかりません。"}
    now_ts = int(time.time())
    if row["status"] != "pending":
        return {"ok": False, "reason": "この候補は処理済みです。"}
    if int(row["expires_at"] or 0) <= now_ts:
        _expire_module_reroll_candidates(db, user_id=user_id, module_id=int(row["module_id"]), now_ts=now_ts, request_id=request_id, ip=ip)
        db.commit()
        return {"ok": False, "reason": "この候補は期限切れです。"}
    module, error = _validate_research_module_reroll_target(db, user_id, int(row["module_id"]))
    if error:
        return {"ok": False, "reason": error}
    before_stats = json.loads(row["before_stats_json"] or "{}")
    candidate_stats = json.loads(row["candidate_stats_json"] or "{}")
    current_stats = _research_module_bonus_dict(module)
    cur = db.execute(
        """
        UPDATE user_research_modules
        SET hp_bonus = ?, atk_bonus = ?, def_bonus = ?, spd_bonus = ?, acc_bonus = ?, cri_bonus = ?, updated_at = ?
        WHERE id = ?
          AND user_id = ?
          AND status = 'inventory'
          AND COALESCE(is_locked, 0) = 0
        """,
        (
            int(candidate_stats.get("hp_bonus") or 0),
            int(candidate_stats.get("atk_bonus") or 0),
            int(candidate_stats.get("def_bonus") or 0),
            int(candidate_stats.get("spd_bonus") or 0),
            int(candidate_stats.get("acc_bonus") or 0),
            int(candidate_stats.get("cri_bonus") or 0),
            now_ts,
            int(row["module_id"]),
            int(user_id),
        ),
    )
    if int(cur.rowcount or 0) != 1:
        db.rollback()
        return {"ok": False, "reason": "候補を採用できませんでした。"}
    db.execute("UPDATE module_reroll_candidates SET status = 'accepted', decided_at = ? WHERE id = ? AND status = 'pending'", (now_ts, int(candidate_id)))
    payload = {
        "user_id": int(user_id),
        "module_id": int(row["module_id"]),
        "candidate_id": int(candidate_id),
        "status": "accepted",
        "before_stats": before_stats,
        "current_stats_before_accept": current_stats,
        "candidate_stats": candidate_stats,
        **_module_reroll_candidate_payload(before_stats, candidate_stats),
    }
    audit_log(db, AUDIT_EVENT_TYPES["MODULE_REROLL_ACCEPT"], user_id=int(user_id), request_id=request_id, action_key="module_reroll_accept", entity_type="module_reroll_candidate", entity_id=int(candidate_id), payload=payload, ip=ip)
    db.commit()
    return {"ok": True, "module_id": int(row["module_id"])}


def reject_module_reroll_candidate(db, user_id, candidate_id, *, request_id=None, ip=None):
    row = _module_reroll_candidate_row(db, candidate_id, user_id)
    if not row:
        return {"ok": False, "reason": "配分再調整候補が見つかりません。"}
    if row["status"] != "pending":
        return {"ok": False, "reason": "この候補は処理済みです。"}
    now_ts = int(time.time())
    status = "expired" if int(row["expires_at"] or 0) <= now_ts else "rejected"
    db.execute("UPDATE module_reroll_candidates SET status = ?, decided_at = ? WHERE id = ? AND status = 'pending'", (status, now_ts, int(candidate_id)))
    payload = {
        "user_id": int(user_id),
        "module_id": int(row["module_id"]),
        "candidate_id": int(candidate_id),
        "status": status,
        "before_stats": json.loads(row["before_stats_json"] or "{}"),
        "candidate_stats": json.loads(row["candidate_stats_json"] or "{}"),
    }
    event_type = AUDIT_EVENT_TYPES["MODULE_REROLL_EXPIRE" if status == "expired" else "MODULE_REROLL_REJECT"]
    audit_log(db, event_type, user_id=int(user_id), request_id=request_id, action_key=f"module_reroll_{status}", entity_type="module_reroll_candidate", entity_id=int(candidate_id), payload=payload, ip=ip)
    db.commit()
    return {"ok": True, "module_id": int(row["module_id"]), "status": status}


def _module_reroll_audit_rows(db, *, limit=100):
    rows = db.execute(
        """
        SELECT wel.*, u.username, u.display_name
        FROM world_events_log wel
        LEFT JOIN users u ON u.id = wel.user_id
        WHERE wel.event_type = ?
        ORDER BY wel.id DESC
        LIMIT ?
        """,
        (AUDIT_EVENT_TYPES["MODULE_REROLL"], max(1, min(300, int(limit or 100)))),
    ).fetchall()
    restored_source_ids = {
        int(row["source_event_id"])
        for row in db.execute(
            """
            SELECT json_extract(payload_json, '$.source_event_id') AS source_event_id
            FROM world_events_log
            WHERE event_type = ?
              AND json_extract(payload_json, '$.source_event_id') IS NOT NULL
            """,
            (AUDIT_EVENT_TYPES["MODULE_REROLL_RESTORE"],),
        ).fetchall()
        if row["source_event_id"] is not None
    }
    out = []
    for row in rows:
        payload = json.loads(row["payload_json"] or "{}")
        before_stats = payload.get("before_stats") or {}
        after_stats = payload.get("after_stats") or payload.get("candidate_stats") or {}
        before_total = _research_module_stats_total(before_stats)
        after_total = _research_module_stats_total(after_stats)
        ratio = (float(after_total) / float(before_total)) if before_total > 0 else 0.0
        out.append(
            {
                "id": int(row["id"]),
                "created_at": row["created_at"],
                "user_id": int(row["user_id"] or payload.get("user_id") or 0),
                "username": row["display_name"] or row["username"] or "-",
                "module_id": int(payload.get("module_id") or payload.get("module_instance_id") or 0),
                "rarity": payload.get("rarity") or "",
                "before_stats": before_stats,
                "after_stats": after_stats,
                "before_total": before_total,
                "after_total": after_total,
                "total_delta": after_total - before_total,
                "is_large_drop": bool(before_total > 0 and ratio < 0.5),
                "cost": int(payload.get("cost") or 0),
                "coins_before": int(payload.get("coins_before") or 0),
                "coins_after": int(payload.get("coins_after") or 0),
                "request_id": row["request_id"] or payload.get("request_id") or "",
                "restored": int(row["id"]) in restored_source_ids,
            }
        )
    return out


def restore_module_reroll_from_audit(db, *, admin_user_id, event_id, reason="", request_id=None, ip=None):
    if not _is_admin_user(admin_user_id):
        return {"ok": False, "reason": "管理者権限が必要です。"}
    event = db.execute(
        "SELECT * FROM world_events_log WHERE id = ? AND event_type = ? LIMIT 1",
        (int(event_id), AUDIT_EVENT_TYPES["MODULE_REROLL"]),
    ).fetchone()
    if not event:
        return {"ok": False, "reason": "再調整履歴が見つかりません。"}
    already = db.execute(
        """
        SELECT id
        FROM world_events_log
        WHERE event_type = ?
          AND CAST(json_extract(payload_json, '$.source_event_id') AS INTEGER) = ?
        LIMIT 1
        """,
        (AUDIT_EVENT_TYPES["MODULE_REROLL_RESTORE"], int(event_id)),
    ).fetchone()
    if already:
        return {"ok": False, "reason": "この履歴は復旧済みです。"}
    payload = json.loads(event["payload_json"] or "{}")
    target_user_id = int(payload.get("user_id") or event["user_id"] or 0)
    module_id = int(payload.get("module_id") or payload.get("module_instance_id") or 0)
    before_stats = payload.get("before_stats") or {}
    if target_user_id <= 0 or module_id <= 0 or not before_stats:
        return {"ok": False, "reason": "復旧に必要な情報が不足しています。"}
    module = _research_module_instance_row(db, module_id, target_user_id)
    if not module:
        return {"ok": False, "reason": "対象モジュールが見つかりません。"}
    current_stats = _research_module_bonus_dict(module)
    now_ts = int(time.time())
    cur = db.execute(
        """
        UPDATE user_research_modules
        SET hp_bonus = ?, atk_bonus = ?, def_bonus = ?, spd_bonus = ?, acc_bonus = ?, cri_bonus = ?, updated_at = ?
        WHERE id = ? AND user_id = ?
        """,
        (
            int(before_stats.get("hp_bonus") or 0),
            int(before_stats.get("atk_bonus") or 0),
            int(before_stats.get("def_bonus") or 0),
            int(before_stats.get("spd_bonus") or 0),
            int(before_stats.get("acc_bonus") or 0),
            int(before_stats.get("cri_bonus") or 0),
            now_ts,
            module_id,
            target_user_id,
        ),
    )
    if int(cur.rowcount or 0) != 1:
        db.rollback()
        return {"ok": False, "reason": "復旧に失敗しました。"}
    restored_at = now_str()
    audit_log(
        db,
        AUDIT_EVENT_TYPES["MODULE_REROLL_RESTORE"],
        user_id=int(admin_user_id),
        request_id=request_id,
        action_key="module_reroll_restore",
        entity_type="research_module",
        entity_id=module_id,
        payload={
            "admin_user_id": int(admin_user_id),
            "target_user_id": target_user_id,
            "module_id": module_id,
            "source_event_id": int(event_id),
            "restored_stats": before_stats,
            "current_stats_before_restore": current_stats,
            "restored_at": restored_at,
            "reason": reason or "モジュール再調整v1の仕様説明不足による今回限りの復旧",
        },
        ip=ip,
    )
    db.commit()
    return {"ok": True, "module_id": module_id, "target_user_id": target_user_id}


def _factory_facility_def(facility_key):
    key = str(facility_key or "").strip()
    return next((item for item in FACTORY_FACILITY_DEFS if item["facility_key"] == key), None)


def _factory_rate_for_level(level):
    return int(FACTORY_POINT_RATE_BY_LEVEL.get(max(1, min(int(level or 1), FACTORY_MAX_LEVEL)), 0) or 0)


def _factory_upgrade_cost_for_level(level):
    return int(FACTORY_UPGRADE_COST_BY_LEVEL.get(int(level or 0), 0) or 0)


def _factory_prize_type_label(prize_type):
    return {
        "title": "称号",
        "decor": "DECOR",
        "factory_skin": "工場スキン",
    }.get(str(prize_type or ""), str(prize_type or "景品"))


def _factory_pending_points(row, now_ts=None, storage_cap_hours=None):
    if not row:
        return 0
    current_ts = int(now_ts or time.time())
    last_ts = int(row["last_claimed_at"] or current_ts)
    elapsed = max(0, current_ts - last_ts)
    cap_hours = int(storage_cap_hours if storage_cap_hours is not None else FACTORY_STORAGE_CAP_HOURS)
    capped = min(elapsed, max(1, cap_hours) * 3600)
    rate = _factory_rate_for_level(int(row["level"] or 1))
    return int((capped * rate) // 3600)


def ensure_user_factory_facilities(db, user_id, *, request_id=None, ip=None):
    uid = int(user_id)
    now_ts = int(time.time())
    created = []
    for facility in FACTORY_FACILITY_DEFS:
        cur = db.execute(
            """
            INSERT OR IGNORE INTO user_factory_facilities
            (user_id, facility_key, level, last_claimed_at, created_at, updated_at)
            VALUES (?, ?, 1, ?, ?, ?)
            """,
            (uid, facility["facility_key"], now_ts, now_ts, now_ts),
        )
        if int(cur.rowcount or 0) > 0:
            created.append(facility["facility_key"])
    if created:
        audit_log(
            db,
            AUDIT_EVENT_TYPES["FACTORY_ENSURE_DEFAULTS"],
            user_id=uid,
            request_id=request_id,
            action_key="factory_ensure_defaults",
            entity_type="factory",
            delta_count=len(created),
            payload={"user_id": uid, "created_facilities": created},
            ip=ip,
        )
    return {"created_count": len(created), "created_facilities": created}


def ensure_factory_prizes(db, *, user_id=None, request_id=None, ip=None):
    now_ts = int(time.time())
    existing_keys = {
        row["prize_key"]
        for row in db.execute("SELECT prize_key FROM factory_prizes").fetchall()
    }
    created = []
    for prize in FACTORY_PRIZE_DEFS:
        db.execute(
            """
            INSERT INTO factory_prizes (
                prize_key, name_ja, description, prize_type, cost_points,
                grant_key, is_active, sort_order, created_at, updated_at
            )
            VALUES (?, ?, ?, ?, ?, ?, 1, ?, ?, ?)
            ON CONFLICT(prize_key) DO UPDATE SET
                name_ja = excluded.name_ja,
                description = excluded.description,
                prize_type = excluded.prize_type,
                cost_points = excluded.cost_points,
                grant_key = excluded.grant_key,
                sort_order = excluded.sort_order,
                updated_at = excluded.updated_at
            """,
            (
                prize["prize_key"],
                prize["name_ja"],
                prize["description"],
                prize["prize_type"],
                int(prize["cost_points"]),
                prize["grant_key"],
                int(prize["sort_order"]),
                now_ts,
                now_ts,
            ),
        )
        if prize["prize_key"] not in existing_keys:
            created.append(prize["prize_key"])
    if created:
        audit_log(
            db,
            AUDIT_EVENT_TYPES["FACTORY_PRIZE_ENSURE_DEFAULTS"],
            user_id=int(user_id) if user_id else None,
            request_id=request_id,
            action_key="factory_prize_ensure_defaults",
            entity_type="factory_prize",
            delta_count=len(created),
            payload={"created_prizes": created},
            ip=ip,
        )
    return {"created_count": len(created), "created_prizes": created}


def get_factory_prize_view(db, user_id, *, ensure=True):
    uid = int(user_id)
    if ensure:
        ensure_factory_prizes(db, user_id=uid)
    user = db.execute("SELECT factory_points FROM users WHERE id = ? LIMIT 1", (uid,)).fetchone()
    factory_points = int(user["factory_points"] or 0) if user else 0
    rows = db.execute(
        """
        SELECT fp.*,
               CASE WHEN ufpc.id IS NULL THEN 0 ELSE 1 END AS is_claimed
        FROM factory_prizes fp
        LEFT JOIN user_factory_prize_claims ufpc
          ON ufpc.prize_key = fp.prize_key
         AND ufpc.user_id = ?
        WHERE fp.is_active = 1
        ORDER BY fp.sort_order ASC, fp.id ASC
        """,
        (uid,),
    ).fetchall()
    prizes = []
    for row in rows:
        cost = int(row["cost_points"] or 0)
        claimed = bool(int(row["is_claimed"] or 0))
        can_claim = (not claimed) and factory_points >= cost
        if claimed:
            status_label = "交換済み"
        elif can_claim:
            status_label = "交換可能"
        else:
            status_label = "ポイント不足"
        prizes.append(
            {
                "id": int(row["id"]),
                "prize_key": row["prize_key"],
                "name_ja": row["name_ja"],
                "description": row["description"] or "",
                "prize_type": row["prize_type"],
                "prize_type_label": _factory_prize_type_label(row["prize_type"]),
                "cost_points": cost,
                "grant_key": row["grant_key"],
                "is_claimed": claimed,
                "can_claim": can_claim,
                "status_label": status_label,
            }
        )
    return {"factory_points": factory_points, "prizes": prizes}


def claim_factory_prize(db, user_id, prize_key, *, request_id=None, ip=None):
    uid = int(user_id)
    key = str(prize_key or "").strip()
    if not key:
        return {"ok": False, "reason": "景品の指定が不正です。"}
    ensure_factory_prizes(db, user_id=uid, request_id=request_id, ip=ip)
    prize = db.execute(
        "SELECT * FROM factory_prizes WHERE prize_key = ? AND is_active = 1 LIMIT 1",
        (key,),
    ).fetchone()
    if not prize:
        return {"ok": False, "reason": "交換できる景品が見つかりません。"}
    existing = db.execute(
        "SELECT id FROM user_factory_prize_claims WHERE user_id = ? AND prize_key = ? LIMIT 1",
        (uid, key),
    ).fetchone()
    if existing:
        return {"ok": False, "reason": "この景品は交換済みです。", "duplicate_reason": "already_claimed"}
    user = db.execute("SELECT factory_points FROM users WHERE id = ? LIMIT 1", (uid,)).fetchone()
    before_points = int(user["factory_points"] or 0) if user else 0
    cost = int(prize["cost_points"] or 0)
    if before_points < cost:
        return {"ok": False, "reason": f"工場ポイントが足りません。必要: {cost} / 所持: {before_points}"}
    now_ts = int(time.time())
    after_points = before_points - cost
    cur = db.execute(
        """
        INSERT OR IGNORE INTO user_factory_prize_claims (user_id, prize_key, claimed_at)
        VALUES (?, ?, ?)
        """,
        (uid, key, now_ts),
    )
    if int(cur.rowcount or 0) != 1:
        db.rollback()
        return {"ok": False, "reason": "この景品は交換済みです。", "duplicate_reason": "already_claimed"}
    db.execute("UPDATE users SET factory_points = ? WHERE id = ?", (after_points, uid))
    audit_log(
        db,
        AUDIT_EVENT_TYPES["FACTORY_PRIZE_CLAIM"],
        user_id=uid,
        request_id=request_id,
        action_key="factory_prize_claim",
        entity_type="factory_prize",
        entity_id=int(prize["id"]),
        delta_count=-cost,
        payload={
            "user_id": uid,
            "prize_key": key,
            "prize_type": prize["prize_type"],
            "cost_points": cost,
            "factory_points_before": before_points,
            "factory_points_after": after_points,
            "grant_key": prize["grant_key"],
        },
        ip=ip,
    )
    db.commit()
    return {
        "ok": True,
        "prize_key": key,
        "name_ja": prize["name_ja"],
        "cost_points": cost,
        "factory_points_after": after_points,
    }


def _factory_cosmetic_default_key(cosmetic_type):
    ctype = str(cosmetic_type or "").strip()
    item = next((row for row in FACTORY_COSMETIC_DEFS if row["cosmetic_type"] == ctype and int(row["is_default"]) == 1), None)
    return item["cosmetic_key"] if item else None


def _factory_cosmetic_column(cosmetic_type):
    return FACTORY_COSMETIC_EQUIP_COLUMNS.get(str(cosmetic_type or "").strip())


def ensure_factory_cosmetics(db, user_id=None, *, request_id=None, ip=None):
    now_ts = int(time.time())
    existing_keys = {
        row["cosmetic_key"]
        for row in db.execute("SELECT cosmetic_key FROM factory_cosmetics").fetchall()
    }
    created = []
    for item in FACTORY_COSMETIC_DEFS:
        db.execute(
            """
            INSERT INTO factory_cosmetics (
                cosmetic_key, cosmetic_type, name_ja, description, image_path,
                is_default, is_active, sort_order, created_at, updated_at
            )
            VALUES (?, ?, ?, ?, ?, ?, 1, ?, ?, ?)
            ON CONFLICT(cosmetic_key) DO UPDATE SET
                cosmetic_type = excluded.cosmetic_type,
                name_ja = excluded.name_ja,
                description = excluded.description,
                image_path = excluded.image_path,
                is_default = excluded.is_default,
                sort_order = excluded.sort_order,
                updated_at = excluded.updated_at
            """,
            (
                item["cosmetic_key"],
                item["cosmetic_type"],
                item["name_ja"],
                item["description"],
                item["image_path"],
                int(item["is_default"]),
                int(item["sort_order"]),
                now_ts,
                now_ts,
            ),
        )
        if item["cosmetic_key"] not in existing_keys:
            created.append(item["cosmetic_key"])
    unlocked = []
    uid = int(user_id or 0)
    if uid > 0:
        for item in FACTORY_COSMETIC_DEFS:
            if int(item["is_default"]) != 1:
                continue
            cur = db.execute(
                """
                INSERT OR IGNORE INTO user_factory_cosmetics (user_id, cosmetic_key, unlocked_at)
                VALUES (?, ?, ?)
                """,
                (uid, item["cosmetic_key"], now_ts),
            )
            if int(cur.rowcount or 0) > 0:
                unlocked.append(item["cosmetic_key"])
            column_name = _factory_cosmetic_column(item["cosmetic_type"])
            if column_name:
                db.execute(
                    f"""
                    UPDATE users
                    SET {column_name} = COALESCE(NULLIF({column_name}, ''), ?)
                    WHERE id = ?
                    """,
                    (item["cosmetic_key"], uid),
                )
    if created or unlocked:
        audit_log(
            db,
            AUDIT_EVENT_TYPES["FACTORY_COSMETIC_ENSURE_DEFAULTS"],
            user_id=uid if uid > 0 else None,
            request_id=request_id,
            action_key="factory_cosmetic_ensure_defaults",
            entity_type="factory_cosmetic",
            delta_count=len(created) + len(unlocked),
            payload={"created_cosmetics": created, "unlocked_defaults": unlocked},
            ip=ip,
        )
    if unlocked and uid > 0:
        audit_log(
            db,
            AUDIT_EVENT_TYPES["FACTORY_COSMETIC_UNLOCK"],
            user_id=uid,
            request_id=request_id,
            action_key="factory_cosmetic_unlock_default",
            entity_type="factory_cosmetic",
            delta_count=len(unlocked),
            payload={"user_id": uid, "unlocked_cosmetics": unlocked, "source": "default"},
            ip=ip,
        )
    return {"created_count": len(created), "unlocked_count": len(unlocked)}


def get_factory_cosmetic_loadout(db, user_id, *, ensure=True):
    uid = int(user_id)
    if ensure:
        ensure_factory_cosmetics(db, uid)
    user = db.execute(
        """
        SELECT equipped_factory_background, equipped_factory_floor,
               equipped_factory_facility, equipped_factory_decoration
        FROM users
        WHERE id = ?
        LIMIT 1
        """,
        (uid,),
    ).fetchone()
    equipped_keys = {}
    for ctype, column_name in FACTORY_COSMETIC_EQUIP_COLUMNS.items():
        key = str((user[column_name] if user and column_name in user.keys() else "") or "").strip()
        equipped_keys[ctype] = key or _factory_cosmetic_default_key(ctype)
    if not any(equipped_keys.values()):
        return {"equipped_keys": equipped_keys, "equipped": {}}
    rows = db.execute(
        f"""
        SELECT *
        FROM factory_cosmetics
        WHERE cosmetic_key IN ({",".join(["?"] * len(equipped_keys))})
        """,
        tuple(equipped_keys.values()),
    ).fetchall()
    by_key = {row["cosmetic_key"]: dict(row) for row in rows}
    equipped = {}
    for ctype, key in equipped_keys.items():
        row = by_key.get(key)
        if row:
            equipped[ctype] = {
                "cosmetic_key": row["cosmetic_key"],
                "cosmetic_type": row["cosmetic_type"],
                "type_label": FACTORY_COSMETIC_TYPE_LABELS.get(ctype, ctype),
                "name_ja": row["name_ja"],
                "description": row["description"] or "",
                "image_path": row["image_path"] or "",
            }
    return {"equipped_keys": equipped_keys, "equipped": equipped}


def get_factory_customize_view(db, user_id, *, ensure=True):
    uid = int(user_id)
    if ensure:
        ensure_factory_cosmetics(db, uid)
    loadout = get_factory_cosmetic_loadout(db, uid, ensure=False)
    rows = db.execute(
        """
        SELECT fc.*,
               CASE WHEN ufc.id IS NULL THEN 0 ELSE 1 END AS is_owned
        FROM factory_cosmetics fc
        LEFT JOIN user_factory_cosmetics ufc
          ON ufc.cosmetic_key = fc.cosmetic_key
         AND ufc.user_id = ?
        WHERE fc.is_active = 1
        ORDER BY fc.cosmetic_type ASC, fc.sort_order ASC, fc.id ASC
        """,
        (uid,),
    ).fetchall()
    categories = []
    for ctype, type_label in FACTORY_COSMETIC_TYPE_LABELS.items():
        equipped_key = loadout["equipped_keys"].get(ctype)
        items = []
        for row in rows:
            if row["cosmetic_type"] != ctype:
                continue
            items.append(
                {
                    "cosmetic_key": row["cosmetic_key"],
                    "cosmetic_type": row["cosmetic_type"],
                    "name_ja": row["name_ja"],
                    "description": row["description"] or "",
                    "image_path": row["image_path"] or "",
                    "is_owned": bool(int(row["is_owned"] or 0)),
                    "is_equipped": str(row["cosmetic_key"]) == str(equipped_key),
                }
            )
        categories.append({"cosmetic_type": ctype, "type_label": type_label, "items": items})
    return {"categories": categories, "loadout": loadout}


def equip_factory_cosmetic(db, user_id, cosmetic_key, *, request_id=None, ip=None):
    uid = int(user_id)
    key = str(cosmetic_key or "").strip()
    if not key:
        return {"ok": False, "reason": "カスタマイズ項目の指定が不正です。"}
    ensure_factory_cosmetics(db, uid, request_id=request_id, ip=ip)
    row = db.execute(
        """
        SELECT fc.*
        FROM factory_cosmetics fc
        JOIN user_factory_cosmetics ufc
          ON ufc.cosmetic_key = fc.cosmetic_key
         AND ufc.user_id = ?
        WHERE fc.cosmetic_key = ?
          AND fc.is_active = 1
        LIMIT 1
        """,
        (uid, key),
    ).fetchone()
    if not row:
        return {"ok": False, "reason": "未所持、または利用できないカスタマイズ項目です。"}
    ctype = str(row["cosmetic_type"] or "").strip()
    column_name = _factory_cosmetic_column(ctype)
    if not column_name:
        return {"ok": False, "reason": "カスタマイズ種別が不正です。"}
    before = get_factory_cosmetic_loadout(db, uid, ensure=False)["equipped_keys"].get(ctype)
    db.execute(f"UPDATE users SET {column_name} = ? WHERE id = ?", (key, uid))
    audit_log(
        db,
        AUDIT_EVENT_TYPES["FACTORY_COSMETIC_EQUIP"],
        user_id=uid,
        request_id=request_id,
        action_key="factory_cosmetic_equip",
        entity_type="factory_cosmetic",
        entity_id=int(row["id"]),
        payload={
            "user_id": uid,
            "cosmetic_key": key,
            "cosmetic_type": ctype,
            "before_key": before,
            "after_key": key,
        },
        ip=ip,
    )
    db.commit()
    return {"ok": True, "cosmetic_key": key, "cosmetic_type": ctype, "name_ja": row["name_ja"]}


def _companion_def(companion_key):
    key = str(companion_key or "").strip()
    return next((item for item in COMPANION_DEFS if item["companion_key"] == key), None)


def _companion_upgrade_cost(level):
    return int(COMPANION_UPGRADE_COST_BY_LEVEL.get(int(level or 0), 0) or 0)


def _companion_collector_bonus_percent(level):
    return max(1, min(int(level or 1), COMPANION_MAX_LEVEL))


def _companion_maintenance_bonus_hours(level):
    return int(COMPANION_MAINTENANCE_CAP_BONUS_HOURS.get(max(1, min(int(level or 1), COMPANION_MAX_LEVEL)), 0) or 0)


def _companion_effect_label(effect_type, level):
    lvl = max(1, min(int(level or 1), COMPANION_MAX_LEVEL))
    if effect_type == "factory_claim_bonus":
        return f"工場回収 +{_companion_collector_bonus_percent(lvl)}%"
    if effect_type == "factory_cap_bonus":
        return f"工場蓄積上限 +{_companion_maintenance_bonus_hours(lvl)}時間"
    if effect_type == "scout_log":
        return "出撃後の個人ログに偵察メモが出ることがあります"
    return "戦闘ステータスには影響しません"


def _companion_dispatch_time_label(seconds):
    remain = max(0, int(seconds or 0))
    minutes = (remain + 59) // 60
    if minutes >= 60:
        hours = minutes // 60
        rest = minutes % 60
        return f"あと{hours}時間{rest}分" if rest else f"あと{hours}時間"
    return f"あと{minutes}分"


def _companion_source_is_available(db, row):
    if not row:
        return False
    source_type = str(row["source_type"] or "default").strip()
    if source_type in ("default", "lab_pet"):
        return True
    if source_type == "lab_submission":
        source_id = int(row["source_id"] or 0)
        if source_id <= 0:
            return False
        approved = db.execute(
            "SELECT id FROM lab_robot_submissions WHERE id = ? AND status = 'approved' LIMIT 1",
            (source_id,),
        ).fetchone()
        return bool(approved)
    return False


def ensure_companions(db, user_id=None, *, request_id=None, ip=None):
    now_ts = int(time.time())
    existing_keys = {
        row["companion_key"]
        for row in db.execute("SELECT companion_key FROM companion_robot_masters").fetchall()
    }
    created = []
    for item in COMPANION_DEFS:
        db.execute(
            """
            INSERT INTO companion_robot_masters (
                companion_key, name_ja, description, effect_type, base_effect_value,
                source_type, source_id, image_path, is_active, sort_order, created_at, updated_at
            )
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, 1, ?, ?, ?)
            ON CONFLICT(companion_key) DO UPDATE SET
                name_ja = excluded.name_ja,
                description = excluded.description,
                effect_type = excluded.effect_type,
                base_effect_value = excluded.base_effect_value,
                source_type = excluded.source_type,
                source_id = excluded.source_id,
                image_path = excluded.image_path,
                sort_order = excluded.sort_order,
                updated_at = excluded.updated_at
            """,
            (
                item["companion_key"],
                item["name_ja"],
                item["description"],
                item["effect_type"],
                int(item["base_effect_value"]),
                item["source_type"],
                item["source_id"],
                item["image_path"],
                int(item["sort_order"]),
                now_ts,
                now_ts,
            ),
        )
        if item["companion_key"] not in existing_keys:
            created.append(item["companion_key"])

    unlocked = []
    uid = int(user_id or 0)
    if uid > 0:
        for item in COMPANION_DEFS:
            cur = db.execute(
                """
                INSERT OR IGNORE INTO user_companion_robots (user_id, companion_key, level, unlocked_at, updated_at)
                VALUES (?, ?, 1, ?, ?)
                """,
                (uid, item["companion_key"], now_ts, now_ts),
            )
            if int(cur.rowcount or 0) > 0:
                unlocked.append(item["companion_key"])
        default_key = "collector_petbot"
        if default_key:
            db.execute(
                """
                UPDATE users
                SET active_companion_key = COALESCE(NULLIF(active_companion_key, ''), ?)
                WHERE id = ?
                """,
                (default_key, uid),
            )

    if created or unlocked:
        audit_log(
            db,
            AUDIT_EVENT_TYPES["COMPANION_ENSURE_DEFAULTS"],
            user_id=uid if uid > 0 else None,
            request_id=request_id,
            action_key="companion_ensure_defaults",
            entity_type="companion_robot",
            delta_count=len(created) + len(unlocked),
            payload={"created_companions": created, "unlocked_defaults": unlocked},
            ip=ip,
        )
    if unlocked and uid > 0:
        audit_log(
            db,
            AUDIT_EVENT_TYPES["COMPANION_UNLOCK"],
            user_id=uid,
            request_id=request_id,
            action_key="companion_unlock_default",
            entity_type="companion_robot",
            delta_count=len(unlocked),
            payload={"user_id": uid, "unlocked_companions": unlocked, "source": "default"},
            ip=ip,
        )
    return {"created_count": len(created), "unlocked_count": len(unlocked)}


def get_active_companion(db, user_id, *, ensure=True):
    uid = int(user_id)
    if ensure:
        ensure_companions(db, uid)
    row = db.execute(
        """
        SELECT dm.*, ud.level
        FROM users u
        JOIN user_companion_robots ud
          ON ud.user_id = u.id
         AND ud.companion_key = u.active_companion_key
        JOIN companion_robot_masters dm
          ON dm.companion_key = ud.companion_key
        WHERE u.id = ?
          AND dm.is_active = 1
        LIMIT 1
        """,
        (uid,),
    ).fetchone()
    if not row or not _companion_source_is_available(db, row):
        return None
    level = max(1, min(int(row["level"] or 1), COMPANION_MAX_LEVEL))
    return {
        "companion_key": row["companion_key"],
        "name_ja": row["name_ja"],
        "description": row["description"] or "",
        "effect_type": row["effect_type"],
        "source_type": row["source_type"] or "default",
        "source_id": int(row["source_id"] or 0) if row["source_id"] else None,
        "image_path": row["image_path"] or "",
        "level": level,
        "effect_label": _companion_effect_label(row["effect_type"], level),
    }


def get_companion_view(db, user_id, *, ensure=True):
    uid = int(user_id)
    if ensure:
        ensure_companions(db, uid)
    user = db.execute("SELECT factory_points, active_companion_key FROM users WHERE id = ? LIMIT 1", (uid,)).fetchone()
    factory_points = int(user["factory_points"] or 0) if user else 0
    active_key = str((user["active_companion_key"] if user else "") or "")
    rows = db.execute(
        """
        SELECT dm.*,
               ud.level, ud.experience, ud.dispatch_count, ud.factory_points_collected,
               CASE WHEN ud.id IS NULL THEN 0 ELSE 1 END AS is_owned
        FROM companion_robot_masters dm
        LEFT JOIN user_companion_robots ud
          ON ud.companion_key = dm.companion_key
         AND ud.user_id = ?
        WHERE dm.is_active = 1
        ORDER BY dm.sort_order ASC, dm.id ASC
        """,
        (uid,),
    ).fetchall()
    companions = []
    for row in rows:
        if not _companion_source_is_available(db, row):
            continue
        level = max(1, min(int(row["level"] or 1), COMPANION_MAX_LEVEL))
        next_level = level + 1 if level < COMPANION_MAX_LEVEL else None
        upgrade_cost = _companion_upgrade_cost(level)
        is_owned = bool(int(row["is_owned"] or 0))
        companions.append(
            {
                "companion_key": row["companion_key"],
                "name_ja": row["name_ja"],
                "description": row["description"] or "",
                "effect_type": row["effect_type"],
                "source_type": row["source_type"] or "default",
                "source_id": int(row["source_id"] or 0) if row["source_id"] else None,
                "image_path": row["image_path"] or "",
                "level": level,
                "experience": int(row["experience"] or 0) if "experience" in row.keys() else 0,
                "dispatch_count": int(row["dispatch_count"] or 0) if "dispatch_count" in row.keys() else 0,
                "factory_points_collected": int(row["factory_points_collected"] or 0) if "factory_points_collected" in row.keys() else 0,
                "is_owned": is_owned,
                "is_selected": str(row["companion_key"]) == active_key,
                "effect_label": _companion_effect_label(row["effect_type"], level),
                "next_effect_label": _companion_effect_label(row["effect_type"], next_level) if next_level else "",
                "upgrade_cost": upgrade_cost,
                "can_upgrade": bool(is_owned and next_level and factory_points >= upgrade_cost),
                "is_max_level": level >= COMPANION_MAX_LEVEL,
            }
        )
    active = next((item for item in companions if item["is_selected"]), None)
    totals = db.execute(
        """
        SELECT
            COALESCE(SUM(dispatch_count), 0) AS dispatch_count,
            COALESCE(SUM(factory_points_collected), 0) AS factory_points_collected
        FROM user_companion_robots
        WHERE user_id = ?
        """,
        (uid,),
    ).fetchone()
    best = db.execute(
        """
        SELECT MAX(COALESCE(base_reward_factory_points, reward_factory_points, 0) + COALESCE(event_bonus_points, 0)) AS best_points
        FROM user_companion_dispatches
        WHERE user_id = ? AND status = 'claimed'
        """,
        (uid,),
    ).fetchone()
    dispatch_total = int(totals["dispatch_count"] or 0) if totals else 0
    album = {
        "dispatch_count": dispatch_total,
        "return_rate": "100%" if dispatch_total > 0 else "0%",
        "factory_points_collected": int(totals["factory_points_collected"] or 0) if totals else 0,
        "best_points": int(best["best_points"] or 0) if best else 0,
    }
    return {"factory_points": factory_points, "active_companion": active, "companions": companions, "album": album}


def equip_companion(db, user_id, companion_key, *, request_id=None, ip=None):
    uid = int(user_id)
    key = str(companion_key or "").strip()
    if not key:
        return {"ok": False, "reason": "相棒ロボの指定が不正です。"}
    ensure_companions(db, uid, request_id=request_id, ip=ip)
    row = db.execute(
        """
        SELECT dm.*
        FROM companion_robot_masters dm
        JOIN user_companion_robots ud
          ON ud.companion_key = dm.companion_key
         AND ud.user_id = ?
        WHERE dm.companion_key = ?
          AND dm.is_active = 1
        LIMIT 1
        """,
        (uid, key),
    ).fetchone()
    if not row or not _companion_source_is_available(db, row):
        return {"ok": False, "reason": "未所持、または利用できない相棒ロボです。"}
    current_dispatch = get_active_companion_dispatch(db, uid, refresh=True)
    if current_dispatch:
        return {"ok": False, "reason": "相棒ロボが派遣中、または帰還待ちです。報酬を受け取ってから変更してください。"}
    before = db.execute("SELECT active_companion_key FROM users WHERE id = ?", (uid,)).fetchone()
    before_key = str((before["active_companion_key"] if before else "") or "")
    db.execute("UPDATE users SET active_companion_key = ? WHERE id = ?", (key, uid))
    audit_log(
        db,
        AUDIT_EVENT_TYPES["COMPANION_EQUIP"],
        user_id=uid,
        request_id=request_id,
        action_key="companion_equip",
        entity_type="companion_robot",
        entity_id=int(row["id"]),
        payload={
            "user_id": uid,
            "companion_key": key,
            "source_type": row["source_type"] or "default",
            "source_id": int(row["source_id"] or 0) if row["source_id"] else None,
            "effect_type": row["effect_type"],
            "active_companion_key": key,
            "before_key": before_key,
            "after_key": key,
        },
        ip=ip,
    )
    db.commit()
    return {"ok": True, "companion_key": key, "name_ja": row["name_ja"]}


def upgrade_companion(db, user_id, companion_key, *, request_id=None, ip=None):
    uid = int(user_id)
    key = str(companion_key or "").strip()
    if not key:
        return {"ok": False, "reason": "相棒ロボの指定が不正です。"}
    ensure_companions(db, uid, request_id=request_id, ip=ip)
    row = db.execute(
        """
        SELECT dm.*, ud.id AS user_companion_id, ud.level
        FROM companion_robot_masters dm
        JOIN user_companion_robots ud
          ON ud.companion_key = dm.companion_key
         AND ud.user_id = ?
        WHERE dm.companion_key = ?
          AND dm.is_active = 1
        LIMIT 1
        """,
        (uid, key),
    ).fetchone()
    if not row or not _companion_source_is_available(db, row):
        return {"ok": False, "reason": "未所持、または利用できない相棒ロボです。"}
    current_dispatch = _companion_dispatch_active_for_key(db, uid, key)
    if current_dispatch:
        return {"ok": False, "reason": "この相棒ロボは派遣中、または帰還待ちです。報酬を受け取ってから強化してください。"}
    level_before = max(1, min(int(row["level"] or 1), COMPANION_MAX_LEVEL))
    if level_before >= COMPANION_MAX_LEVEL:
        return {"ok": False, "reason": "この相棒ロボは最大Lvです。"}
    cost = _companion_upgrade_cost(level_before)
    user = db.execute("SELECT factory_points FROM users WHERE id = ? LIMIT 1", (uid,)).fetchone()
    points_before = int(user["factory_points"] or 0) if user else 0
    if points_before < cost:
        return {"ok": False, "reason": f"工場ポイントが足りません。必要: {cost} / 所持: {points_before}"}
    now_ts = int(time.time())
    level_after = level_before + 1
    points_after = points_before - cost
    cur = db.execute(
        """
        UPDATE user_companion_robots
        SET level = ?, updated_at = ?
        WHERE id = ? AND user_id = ? AND level = ?
        """,
        (level_after, now_ts, int(row["user_companion_id"]), uid, level_before),
    )
    if int(cur.rowcount or 0) != 1:
        db.rollback()
        return {"ok": False, "reason": "強化に失敗しました。もう一度確認してください。"}
    db.execute("UPDATE users SET factory_points = ? WHERE id = ?", (points_after, uid))
    payload = {
        "user_id": uid,
        "companion_key": key,
        "source_type": row["source_type"] or "default",
        "source_id": int(row["source_id"] or 0) if row["source_id"] else None,
        "effect_type": row["effect_type"],
        "active_companion_key": key,
        "level_before": level_before,
        "level_after": level_after,
        "cost_points": cost,
        "factory_points_before": points_before,
        "factory_points_after": points_after,
    }
    audit_log(
        db,
        AUDIT_EVENT_TYPES["COMPANION_UPGRADE"],
        user_id=uid,
        request_id=request_id,
        action_key="companion_upgrade",
        entity_type="companion_robot",
        entity_id=int(row["id"]),
        delta_count=-cost,
        payload=payload,
        ip=ip,
    )
    audit_log(
        db,
        AUDIT_EVENT_TYPES["FACTORY_POINTS_DELTA"],
        user_id=uid,
        request_id=request_id,
        action_key="companion_upgrade",
        entity_type="companion_robot",
        entity_id=int(row["id"]),
        delta_count=-cost,
        payload={**payload, "source": "companion_upgrade"},
        ip=ip,
    )
    db.commit()
    return {"ok": True, "companion_key": key, "name_ja": row["name_ja"], "level_after": level_after, "factory_points_after": points_after}


def ensure_companion_dispatch_masters(db, *, user_id=None, request_id=None, ip=None):
    now_ts = int(time.time())
    existing_keys = {
        row["dispatch_key"]
        for row in db.execute("SELECT dispatch_key FROM companion_dispatch_masters").fetchall()
    }
    created = []
    for item in COMPANION_DISPATCH_DEFS:
        db.execute(
            """
            INSERT INTO companion_dispatch_masters (
                dispatch_key, name_ja, description, duration_minutes,
                min_factory_points, max_factory_points, is_active,
                sort_order, created_at, updated_at
            )
            VALUES (?, ?, ?, ?, ?, ?, 1, ?, ?, ?)
            ON CONFLICT(dispatch_key) DO UPDATE SET
                name_ja = excluded.name_ja,
                description = excluded.description,
                duration_minutes = excluded.duration_minutes,
                min_factory_points = excluded.min_factory_points,
                max_factory_points = excluded.max_factory_points,
                sort_order = excluded.sort_order,
                updated_at = excluded.updated_at
            """,
            (
                item["dispatch_key"],
                item["name_ja"],
                item["description"],
                int(item["duration_minutes"]),
                int(item["min_factory_points"]),
                int(item["max_factory_points"]),
                int(item["sort_order"]),
                now_ts,
                now_ts,
            ),
        )
        if item["dispatch_key"] not in existing_keys:
            created.append(item["dispatch_key"])
    if created:
        audit_log(
            db,
            AUDIT_EVENT_TYPES["COMPANION_DISPATCH_ENSURE_DEFAULTS"],
            user_id=int(user_id) if user_id else None,
            request_id=request_id,
            action_key="companion_dispatch_ensure_defaults",
            entity_type="companion_dispatch",
            delta_count=len(created),
            payload={"created_dispatches": created},
            ip=ip,
        )
    return {"created_count": len(created), "created_dispatches": created}


