def _companion_album_active_photo_rows(db):
    return db.execute(
        """
        SELECT *
        FROM companion_album_photos
        WHERE is_active = 1
        ORDER BY sort_order ASC, id ASC
        """
    ).fetchall()


def _select_companion_album_photo_for_dispatch(db, user_id, dispatch_id):
    rows = _companion_album_active_photo_rows(db)
    if not rows:
        return {"photo_key": "", "duplicate": False, "compensation_points": 0}
    owned = {
        row["photo_key"]
        for row in db.execute(
            "SELECT photo_key FROM user_companion_album_photos WHERE user_id = ?",
            (int(user_id),),
        ).fetchall()
    }
    candidates = [row for row in rows if row["photo_key"] not in owned]
    if candidates:
        index = int(dispatch_id or 0) % len(candidates)
        return {
            "photo_key": candidates[index]["photo_key"],
            "duplicate": False,
            "compensation_points": 0,
        }
    index = int(dispatch_id or 0) % len(rows)
    return {
        "photo_key": rows[index]["photo_key"],
        "duplicate": True,
        "compensation_points": int(COMPANION_ALBUM_PHOTO_DUPLICATE_COMPENSATION_POINTS),
    }


def _companion_album_photo_map(db):
    return {row["photo_key"]: dict(row) for row in _companion_album_active_photo_rows(db)}


def companion_album_summary(db, user_id, *, ensure=True):
    uid = int(user_id)
    if ensure:
        ensure_companion_album_photos(db, user_id=uid)
    totals = db.execute(
        """
        SELECT
            COALESCE(COUNT(*), 0) AS dispatch_count,
            COALESCE(SUM(base_reward_factory_points + event_bonus_points), 0) AS factory_points_collected,
            COALESCE(MAX(base_reward_factory_points + event_bonus_points), 0) AS best_points,
            COALESCE(SUM(CASE WHEN event_type = 'great_success' THEN 1 ELSE 0 END), 0) AS great_success_count,
            COALESCE(SUM(CASE WHEN event_type = 'scrap_found' THEN 1 ELSE 0 END), 0) AS scrap_found_count,
            COALESCE(SUM(CASE WHEN event_type = 'rare_photo' THEN 1 ELSE 0 END), 0) AS rare_photo_count
        FROM user_companion_dispatches
        WHERE user_id = ? AND status = 'claimed'
        """,
        (uid,),
    ).fetchone()
    photo_total = int(db.execute("SELECT COUNT(*) AS c FROM companion_album_photos WHERE is_active = 1").fetchone()["c"] or 0)
    photo_owned = int(
        db.execute(
            """
            SELECT COUNT(*) AS c
            FROM user_companion_album_photos ucap
            JOIN companion_album_photos cap ON cap.photo_key = ucap.photo_key AND cap.is_active = 1
            WHERE ucap.user_id = ?
            """,
            (uid,),
        ).fetchone()["c"]
        or 0
    )
    return {
        "dispatch_count": int(totals["dispatch_count"] or 0),
        "factory_points_collected": int(totals["factory_points_collected"] or 0),
        "best_points": int(totals["best_points"] or 0),
        "great_success_count": int(totals["great_success_count"] or 0),
        "scrap_found_count": int(totals["scrap_found_count"] or 0),
        "rare_photo_count": int(totals["rare_photo_count"] or 0),
        "photo_owned": photo_owned,
        "photo_total": photo_total,
    }


def get_companion_album_view(db, user_id, *, ensure=True):
    uid = int(user_id)
    if ensure:
        ensure_companions(db, uid)
        ensure_companion_album_photos(db, user_id=uid)
    rows = _companion_album_active_photo_rows(db)
    owned_rows = {
        row["photo_key"]: row
        for row in db.execute(
            "SELECT * FROM user_companion_album_photos WHERE user_id = ?",
            (uid,),
        ).fetchall()
    }
    photos = []
    for row in rows:
        owned = owned_rows.get(row["photo_key"])
        photos.append(
            {
                "photo_key": row["photo_key"],
                "name_ja": row["name_ja"] if owned else "？？？",
                "description": row["description"] if owned else "未発見",
                "image_path": row["image_path"] or "",
                "is_owned": bool(owned),
                "unlocked_at": int(owned["unlocked_at"] or 0) if owned else None,
                "source_dispatch_id": int(owned["source_dispatch_id"] or 0) if owned and owned["source_dispatch_id"] else None,
            }
        )
    return {"summary": companion_album_summary(db, uid, ensure=False), "photos": photos}


def _companion_dispatch_event_view(event_type, base_points):
    key = str(event_type or "none").strip() or "none"
    event = COMPANION_DISPATCH_EVENT_DEFS.get(key) or COMPANION_DISPATCH_EVENT_DEFS["none"]
    bonus = int((int(base_points or 0) * int(event["bonus_percent"] or 0)) // 100)
    return {
        "event_type": event["event_type"],
        "event_label": event["label"],
        "event_message": event["message"],
        "event_bonus_points": bonus,
    }


def _roll_companion_dispatch_event(dispatch_id, user_id, dispatch_key, base_points, *, event_type_override=None):
    if event_type_override:
        return _companion_dispatch_event_view(event_type_override, base_points)
    seed = int(dispatch_id or 0) * 37 + int(user_id or 0) * 17 + sum(ord(ch) for ch in str(dispatch_key or ""))
    roll = seed % 100 + 1
    if roll <= 5:
        return _companion_dispatch_event_view("great_success", base_points)
    if roll <= 15:
        return _companion_dispatch_event_view("scrap_found", base_points)
    if roll <= 18:
        return _companion_dispatch_event_view("rare_photo", base_points)
    return _companion_dispatch_event_view("none", base_points)


def _companion_dispatch_journal_for_key(journal_key):
    key = str(journal_key or "").strip()
    if key:
        for item_key, text in COMPANION_DISPATCH_JOURNALS:
            if item_key == key:
                return {"journal_key": item_key, "journal_text": text}
    item_key, text = random.choice(COMPANION_DISPATCH_JOURNALS)
    return {"journal_key": item_key, "journal_text": text}


def _refresh_companion_dispatches(db, user_id=None, *, now_ts=None):
    current_ts = int(now_ts or time.time())
    if user_id:
        db.execute(
            """
            UPDATE user_companion_dispatches
            SET status = 'completed', updated_at = ?
            WHERE user_id = ?
              AND status = 'active'
              AND completes_at <= ?
            """,
            (current_ts, int(user_id), current_ts),
        )
    else:
        db.execute(
            """
            UPDATE user_companion_dispatches
            SET status = 'completed', updated_at = ?
            WHERE status = 'active'
              AND completes_at <= ?
            """,
            (current_ts, current_ts),
        )


def get_active_companion_dispatch(db, user_id, *, refresh=True, now_ts=None):
    uid = int(user_id)
    current_ts = int(now_ts or time.time())
    if refresh:
        _refresh_companion_dispatches(db, uid, now_ts=current_ts)
    row = db.execute(
        """
        SELECT ucd.*, cdm.name_ja AS dispatch_name_ja, cdm.description AS dispatch_description,
               cdm.duration_minutes, cdm.min_factory_points, cdm.max_factory_points,
               crm.name_ja AS companion_name_ja
        FROM user_companion_dispatches ucd
        JOIN companion_dispatch_masters cdm ON cdm.dispatch_key = ucd.dispatch_key
        JOIN companion_robot_masters crm ON crm.companion_key = ucd.companion_key
        WHERE ucd.user_id = ?
          AND ucd.status IN ('active', 'completed')
        ORDER BY ucd.id DESC
        LIMIT 1
        """,
        (uid,),
    ).fetchone()
    if not row:
        return None
    completes_at = int(row["completes_at"] or 0)
    status = str(row["status"] or "active")
    remaining_seconds = max(0, completes_at - current_ts)
    return {
        "id": int(row["id"]),
        "dispatch_id": int(row["id"]),
        "user_id": uid,
        "companion_key": row["companion_key"],
        "companion_name_ja": row["companion_name_ja"],
        "dispatch_key": row["dispatch_key"],
        "dispatch_name_ja": row["dispatch_name_ja"],
        "dispatch_description": row["dispatch_description"] or "",
        "status": status,
        "is_active": status == "active",
        "is_completed": status == "completed",
        "reward_factory_points": int(row["reward_factory_points"] or 0),
        "base_reward_factory_points": int(row["base_reward_factory_points"] or 0) if "base_reward_factory_points" in row.keys() else int(row["reward_factory_points"] or 0),
        "event_type": row["event_type"] if "event_type" in row.keys() and row["event_type"] else "none",
        "event_label": row["event_label"] if "event_label" in row.keys() and row["event_label"] else "通常帰還",
        "event_message": row["event_message"] if "event_message" in row.keys() and row["event_message"] else "",
        "event_bonus_points": int(row["event_bonus_points"] or 0) if "event_bonus_points" in row.keys() else 0,
        "event_photo_key": row["event_photo_key"] if "event_photo_key" in row.keys() and row["event_photo_key"] else "",
        "journal_key": row["journal_key"] if "journal_key" in row.keys() and row["journal_key"] else "",
        "journal_text": row["journal_text"] if "journal_text" in row.keys() and row["journal_text"] else "",
        "started_at": int(row["started_at"] or 0),
        "completes_at": completes_at,
        "claimed_at": int(row["claimed_at"] or 0) if row["claimed_at"] else None,
        "remaining_seconds": remaining_seconds,
        "remaining_label": _companion_dispatch_time_label(remaining_seconds),
    }


def _companion_dispatch_options(db):
    rows = db.execute(
        """
        SELECT *
        FROM companion_dispatch_masters
        WHERE is_active = 1
        ORDER BY sort_order ASC, id ASC
        """
    ).fetchall()
    return [
        {
            "dispatch_key": row["dispatch_key"],
            "name_ja": row["name_ja"],
            "description": row["description"] or "",
            "duration_minutes": int(row["duration_minutes"] or 0),
            "duration_label": f"{int(row['duration_minutes'] or 0) // 60}時間" if int(row["duration_minutes"] or 0) >= 60 else f"{int(row['duration_minutes'] or 0)}分",
            "min_factory_points": int(row["min_factory_points"] or 0),
            "max_factory_points": int(row["max_factory_points"] or 0),
        }
        for row in rows
    ]


def get_companion_dispatch_view(db, user_id, *, ensure=True, now_ts=None):
    uid = int(user_id)
    if ensure:
        ensure_companions(db, uid)
        ensure_companion_dispatch_masters(db, user_id=uid)
    current = get_active_companion_dispatch(db, uid, refresh=True, now_ts=now_ts)
    active_companion = get_active_companion(db, uid, ensure=False)
    user = db.execute("SELECT factory_points FROM users WHERE id = ? LIMIT 1", (uid,)).fetchone()
    return {
        "factory_points": int(user["factory_points"] or 0) if user else 0,
        "active_companion": active_companion,
        "current_dispatch": current,
        "dispatches": _companion_dispatch_options(db),
        "can_start": bool(active_companion and not current),
    }


def companion_dispatch_summary(db, user_id, *, ensure=True, now_ts=None):
    uid = int(user_id)
    if ensure:
        ensure_companion_dispatch_masters(db, user_id=uid)
    current = get_active_companion_dispatch(db, uid, refresh=True, now_ts=now_ts)
    if not current:
        return {"current_dispatch": None, "status_label": "派遣なし", "is_active": False, "is_completed": False}
    if current["is_completed"]:
        return {**current, "current_dispatch": current, "status_label": "相棒ロボ帰還済み"}
    return {**current, "current_dispatch": current, "status_label": f"相棒ロボ派遣中 {current['remaining_label']}"}


def _companion_dispatch_active_for_key(db, user_id, companion_key):
    key = str(companion_key or "").strip()
    if not key:
        return None
    current = get_active_companion_dispatch(db, int(user_id), refresh=True)
    if current and current["companion_key"] == key:
        return current
    return None


def start_companion_dispatch(
    db,
    user_id,
    dispatch_key,
    *,
    request_id=None,
    ip=None,
    event_type_override=None,
    journal_key_override=None,
):
    uid = int(user_id)
    key = str(dispatch_key or "").strip()
    ensure_companion_dispatch_masters(db, user_id=uid, request_id=request_id, ip=ip)
    ensure_companion_album_photos(db, user_id=uid, request_id=request_id, ip=ip)
    current = get_active_companion_dispatch(db, uid, refresh=True)
    if current:
        return {"ok": False, "reason": "相棒ロボは派遣中です。帰還後に受け取ってください。"}
    active = get_active_companion(db, uid, ensure=False)
    if not active:
        return {"ok": False, "reason": "派遣できる相棒ロボがいません。"}
    owned = db.execute(
        """
        SELECT ud.id
        FROM user_companion_robots ud
        JOIN companion_robot_masters crm ON crm.companion_key = ud.companion_key
        WHERE ud.user_id = ?
          AND ud.companion_key = ?
          AND crm.is_active = 1
        LIMIT 1
        """,
        (uid, active["companion_key"]),
    ).fetchone()
    if not owned:
        return {"ok": False, "reason": "未所持、または利用できない相棒ロボです。"}
    course = db.execute(
        "SELECT * FROM companion_dispatch_masters WHERE dispatch_key = ? AND is_active = 1 LIMIT 1",
        (key,),
    ).fetchone()
    if not course:
        return {"ok": False, "reason": "派遣コースが見つかりません。"}
    now_ts = int(time.time())
    reward = random.randint(int(course["min_factory_points"] or 0), int(course["max_factory_points"] or 0))
    completes_at = now_ts + int(course["duration_minutes"] or 0) * 60
    cur = db.execute(
        """
        INSERT INTO user_companion_dispatches (
            user_id, companion_key, dispatch_key, status, reward_factory_points,
            base_reward_factory_points, started_at, completes_at, created_at, updated_at
        )
        VALUES (?, ?, ?, 'active', ?, ?, ?, ?, ?, ?)
        """,
        (uid, active["companion_key"], key, reward, reward, now_ts, completes_at, now_ts, now_ts),
    )
    dispatch_id = int(cur.lastrowid)
    event = _roll_companion_dispatch_event(
        dispatch_id,
        uid,
        key,
        reward,
        event_type_override=event_type_override,
    )
    photo_result = {"photo_key": "", "duplicate": False, "compensation_points": 0}
    if event["event_type"] == "rare_photo":
        photo_result = _select_companion_album_photo_for_dispatch(db, uid, dispatch_id)
        event["event_bonus_points"] = int(event["event_bonus_points"]) + int(photo_result["compensation_points"])
    journal = _companion_dispatch_journal_for_key(journal_key_override)
    db.execute(
        """
        UPDATE user_companion_dispatches
        SET event_type = ?, event_label = ?, event_message = ?, event_bonus_points = ?,
            event_photo_key = ?, journal_key = ?, journal_text = ?, updated_at = ?
        WHERE id = ?
        """,
        (
            event["event_type"],
            event["event_label"],
            event["event_message"],
            int(event["event_bonus_points"]),
            photo_result["photo_key"],
            journal["journal_key"],
            journal["journal_text"],
            now_ts,
            dispatch_id,
        ),
    )
    audit_log(
        db,
        AUDIT_EVENT_TYPES["COMPANION_DISPATCH_START"],
        user_id=uid,
        request_id=request_id,
        action_key="companion_dispatch_start",
        entity_type="companion_dispatch",
        entity_id=dispatch_id,
        payload={
            "user_id": uid,
            "companion_key": active["companion_key"],
            "dispatch_key": key,
            "dispatch_id": dispatch_id,
            "reward_factory_points": reward,
            "base_reward_factory_points": reward,
            "event_type": event["event_type"],
            "event_bonus_points": int(event["event_bonus_points"]),
            "event_photo_key": photo_result["photo_key"],
            "event_photo_duplicate": bool(photo_result["duplicate"]),
            "journal_key": journal["journal_key"],
            "started_at": now_ts,
            "completes_at": completes_at,
        },
        ip=ip,
    )
    db.commit()
    return {"ok": True, "dispatch_id": dispatch_id, "dispatch_key": key, "name_ja": course["name_ja"], "completes_at": completes_at}


def claim_companion_dispatch(db, user_id, *, request_id=None, ip=None):
    uid = int(user_id)
    ensure_companion_dispatch_masters(db, user_id=uid, request_id=request_id, ip=ip)
    ensure_companion_album_photos(db, user_id=uid, request_id=request_id, ip=ip)
    current = get_active_companion_dispatch(db, uid, refresh=True)
    if not current:
        return {"ok": False, "reason": "受け取れる派遣はありません。"}
    if current["status"] == "active":
        return {"ok": False, "reason": "相棒ロボはまだ派遣中です。"}
    if current["status"] != "completed":
        return {"ok": False, "reason": "受け取り済み、または無効な派遣です。"}
    user = db.execute("SELECT factory_points FROM users WHERE id = ? LIMIT 1", (uid,)).fetchone()
    before_points = int(user["factory_points"] or 0) if user else 0
    base_reward = int(current["base_reward_factory_points"] or current["reward_factory_points"] or 0)
    bonus_points = int(current["event_bonus_points"] or 0)
    reward = base_reward + bonus_points
    after_points = before_points + reward
    now_ts = int(time.time())
    unlocked_photo = None
    photo_duplicate = False
    photo_compensation_points = 0
    cur = db.execute(
        """
        UPDATE user_companion_dispatches
        SET status = 'claimed', claimed_at = ?, updated_at = ?
        WHERE id = ?
          AND user_id = ?
          AND status = 'completed'
        """,
        (now_ts, now_ts, int(current["id"]), uid),
    )
    if int(cur.rowcount or 0) != 1:
        db.rollback()
        return {"ok": False, "reason": "この派遣報酬は受け取り済みです。"}
    db.execute("UPDATE users SET factory_points = ? WHERE id = ?", (after_points, uid))
    db.execute(
        """
        UPDATE user_companion_robots
        SET experience = COALESCE(experience, 0) + 1,
            dispatch_count = COALESCE(dispatch_count, 0) + 1,
            factory_points_collected = COALESCE(factory_points_collected, 0) + ?,
            updated_at = ?
        WHERE user_id = ? AND companion_key = ?
        """,
        (reward, now_ts, uid, current["companion_key"]),
    )
    if current["event_type"] == "rare_photo" and current.get("event_photo_key"):
        photo_map = _companion_album_photo_map(db)
        photo = photo_map.get(current["event_photo_key"])
        if photo:
            photo_cur = db.execute(
                """
                INSERT OR IGNORE INTO user_companion_album_photos
                (user_id, photo_key, unlocked_at, source_dispatch_id)
                VALUES (?, ?, ?, ?)
                """,
                (uid, current["event_photo_key"], now_ts, int(current["id"])),
            )
            photo_duplicate = int(photo_cur.rowcount or 0) != 1
            photo_compensation_points = bonus_points if photo_duplicate else 0
            if not photo_duplicate:
                unlocked_photo = {
                    "photo_key": photo["photo_key"],
                    "name_ja": photo["name_ja"],
                    "description": photo["description"] or "",
                }
            audit_log(
                db,
                AUDIT_EVENT_TYPES["COMPANION_ALBUM_PHOTO_UNLOCK"],
                user_id=uid,
                request_id=request_id,
                action_key="companion_album_photo_unlock",
                entity_type="companion_album_photo",
                entity_id=int(photo["id"]),
                delta_count=0 if photo_duplicate else 1,
                payload={
                    "user_id": uid,
                    "photo_key": current["event_photo_key"],
                    "dispatch_id": int(current["id"]),
                    "event_type": current["event_type"],
                    "duplicate": bool(photo_duplicate),
                    "compensation_points": int(photo_compensation_points),
                },
                ip=ip,
            )
    payload = {
        "user_id": uid,
        "companion_key": current["companion_key"],
        "dispatch_key": current["dispatch_key"],
        "dispatch_id": int(current["id"]),
        "reward_factory_points": reward,
        "base_reward_factory_points": base_reward,
        "event_type": current["event_type"],
        "event_label": current["event_label"],
        "event_bonus_points": bonus_points,
        "event_photo_key": current.get("event_photo_key") or "",
        "unlocked_photo": unlocked_photo,
        "photo_duplicate": bool(photo_duplicate),
        "photo_compensation_points": int(photo_compensation_points),
        "journal_key": current["journal_key"],
        "journal_text": current["journal_text"],
        "started_at": int(current["started_at"] or 0),
        "completes_at": int(current["completes_at"] or 0),
        "claimed_at": now_ts,
        "factory_points_before": before_points,
        "factory_points_after": after_points,
    }
    audit_log(
        db,
        AUDIT_EVENT_TYPES["COMPANION_DISPATCH_CLAIM"],
        user_id=uid,
        request_id=request_id,
        action_key="companion_dispatch_claim",
        entity_type="companion_dispatch",
        entity_id=int(current["id"]),
        delta_count=reward,
        payload=payload,
        ip=ip,
    )
    audit_log(
        db,
        AUDIT_EVENT_TYPES["COMPANION_DISPATCH_EVENT"],
        user_id=uid,
        request_id=request_id,
        action_key="companion_dispatch_event",
        entity_type="companion_dispatch",
        entity_id=int(current["id"]),
        delta_count=bonus_points,
        payload={
            "user_id": uid,
            "dispatch_key": current["dispatch_key"],
        "event_type": current["event_type"],
        "bonus_points": bonus_points,
        "journal_key": current["journal_key"],
        "event_photo_key": current.get("event_photo_key") or "",
    },
        ip=ip,
    )
    audit_log(
        db,
        AUDIT_EVENT_TYPES["FACTORY_POINTS_DELTA"],
        user_id=uid,
        request_id=request_id,
        action_key="companion_dispatch_claim",
        entity_type="companion_dispatch",
        entity_id=int(current["id"]),
        delta_count=reward,
        payload={**payload, "source": "companion_dispatch_claim"},
        ip=ip,
    )
    db.commit()
    return {
        "ok": True,
        "reward_factory_points": reward,
        "base_reward_factory_points": base_reward,
        "event_type": current["event_type"],
        "event_label": current["event_label"],
        "event_message": current["event_message"],
        "event_bonus_points": bonus_points,
        "event_photo_key": current.get("event_photo_key") or "",
        "unlocked_photo": unlocked_photo,
        "photo_duplicate": bool(photo_duplicate),
        "photo_compensation_points": int(photo_compensation_points),
        "journal_key": current["journal_key"],
        "journal_text": current["journal_text"],
        "factory_points_after": after_points,
    }


def _factory_storage_cap_hours_for_user(db, user_id):
    active = get_active_companion(db, user_id, ensure=False)
    if active and active["effect_type"] == "factory_cap_bonus":
        return int(FACTORY_STORAGE_CAP_HOURS) + _companion_maintenance_bonus_hours(active["level"])
    return int(FACTORY_STORAGE_CAP_HOURS)


def _factory_collector_bonus_percent_for_user(db, user_id):
    active = get_active_companion(db, user_id, ensure=False)
    if active and active["effect_type"] == "factory_claim_bonus":
        return _companion_collector_bonus_percent(active["level"])
    return 0


def ensure_factory_research_projects(db, *, user_id=None, request_id=None, ip=None):
    now_ts = int(time.time())
    existing_keys = {
        row["research_key"]
        for row in db.execute("SELECT research_key FROM world_research_projects").fetchall()
    }
    created = []
    for item in FACTORY_RESEARCH_DEFS:
        db.execute(
            """
            INSERT INTO world_research_projects (
                research_key, name_ja, description, required_points, current_points,
                reward_key, reward_label, is_completed, sort_order, created_at, updated_at
            )
            VALUES (?, ?, ?, ?, 0, ?, ?, 0, ?, ?, ?)
            ON CONFLICT(research_key) DO UPDATE SET
                name_ja = excluded.name_ja,
                description = excluded.description,
                required_points = excluded.required_points,
                reward_key = excluded.reward_key,
                reward_label = excluded.reward_label,
                sort_order = excluded.sort_order,
                updated_at = excluded.updated_at
            """,
            (
                item["research_key"],
                item["name_ja"],
                item["description"],
                int(item["required_points"]),
                item["reward_key"],
                item["reward_label"],
                int(item["sort_order"]),
                now_ts,
                now_ts,
            ),
        )
        if item["research_key"] not in existing_keys:
            created.append(item["research_key"])
    if created:
        audit_log(
            db,
            AUDIT_EVENT_TYPES["FACTORY_RESEARCH_ENSURE_DEFAULTS"],
            user_id=int(user_id) if user_id else None,
            request_id=request_id,
            action_key="factory_research_ensure_defaults",
            entity_type="world_research_project",
            delta_count=len(created),
            payload={"created_research_projects": created},
            ip=ip,
        )
    return {"created_count": len(created), "created_research_projects": created}


def _factory_research_project_view(row):
    required = max(1, int(row["required_points"] or 1))
    current = max(0, int(row["current_points"] or 0))
    percent = min(100, int((current * 100) // required))
    filled = min(10, max(0, int(round(percent / 10))))
    return {
        "id": int(row["id"]),
        "research_key": row["research_key"],
        "name_ja": row["name_ja"],
        "description": row["description"] or "",
        "required_points": required,
        "current_points": current,
        "remaining_points": max(0, required - current),
        "progress_percent": percent,
        "progress_bar": "█" * filled + "░" * (10 - filled),
        "reward_key": row["reward_key"],
        "reward_label": row["reward_label"] or "見た目報酬",
        "is_completed": bool(int(row["is_completed"] or 0)),
        "completed_at": int(row["completed_at"] or 0) if row["completed_at"] else None,
    }


def _factory_research_project_rows(db):
    return db.execute(
        """
        SELECT *
        FROM world_research_projects
        ORDER BY is_completed ASC, sort_order ASC, id ASC
        """
    ).fetchall()


def factory_research_summary(db, *, ensure=True):
    if ensure:
        ensure_factory_research_projects(db)
    rows = _factory_research_project_rows(db)
    projects = [_factory_research_project_view(row) for row in rows]
    active = next((item for item in projects if not item["is_completed"]), projects[0] if projects else None)
    if not active:
        return {"active_project": None, "progress_percent": 0, "label": "世界研究", "desc": "研究テーマ準備中"}
    return {
        "active_project": active,
        "progress_percent": active["progress_percent"],
        "label": active["name_ja"],
        "desc": f"{active['progress_percent']}% / あと {100 - active['progress_percent']}%",
    }


def factory_research_rankings(db, *, week_key=None, limit=3):
    wk = str(week_key or _world_week_key())
    weekly = db.execute(
        """
        SELECT u.id, u.username, u.display_name, SUM(urc.points) AS points
        FROM user_research_contributions urc
        JOIN users u ON u.id = urc.user_id
        WHERE urc.week_key = ?
        GROUP BY u.id
        ORDER BY points DESC, u.id ASC
        LIMIT ?
        """,
        (wk, int(limit)),
    ).fetchall()
    total = db.execute(
        """
        SELECT u.id, u.username, u.display_name, SUM(urc.points) AS points
        FROM user_research_contributions urc
        JOIN users u ON u.id = urc.user_id
        GROUP BY u.id
        ORDER BY points DESC, u.id ASC
        LIMIT ?
        """,
        (int(limit),),
    ).fetchall()

    def _rows(rows):
        decorated = _decorate_user_rows(db, rows, user_key="id")
        return [
            {
                "rank": index,
                "user_id": int(row["id"]),
                "username": row["username"],
                "display_label": row.get("display_username") or row.get("display_name") or row.get("username") or f"User#{int(row['id'])}",
                "points": int(row["points"] or 0),
            }
            for index, row in enumerate(decorated, start=1)
        ]

    return {"week_key": wk, "weekly": _rows(weekly), "total": _rows(total)}


def get_factory_research_view(db, user_id, *, ensure=True):
    uid = int(user_id)
    if ensure:
        ensure_factory_research_projects(db, user_id=uid)
    user = db.execute("SELECT factory_points FROM users WHERE id = ? LIMIT 1", (uid,)).fetchone()
    projects = [_factory_research_project_view(row) for row in _factory_research_project_rows(db)]
    return {
        "factory_points": int(user["factory_points"] or 0) if user else 0,
        "projects": projects,
        "rankings": factory_research_rankings(db, limit=3),
        "donation_presets": (100, 500, 1000),
    }


def donate_factory_research_points(db, user_id, research_key, amount, *, request_id=None, ip=None):
    uid = int(user_id)
    key = str(research_key or "").strip()
    try:
        donate_points = int(amount)
    except (TypeError, ValueError):
        donate_points = 0
    if donate_points <= 0:
        return {"ok": False, "reason": "寄付ポイントは1以上で指定してください。"}
    ensure_factory_research_projects(db, user_id=uid, request_id=request_id, ip=ip)
    project = db.execute(
        "SELECT * FROM world_research_projects WHERE research_key = ? LIMIT 1",
        (key,),
    ).fetchone()
    if not project:
        return {"ok": False, "reason": "研究テーマが見つかりません。"}
    if int(project["is_completed"] or 0) == 1:
        return {"ok": False, "reason": "この研究は完了済みです。"}
    user = db.execute("SELECT factory_points FROM users WHERE id = ? LIMIT 1", (uid,)).fetchone()
    points_before = int(user["factory_points"] or 0) if user else 0
    if points_before < donate_points:
        return {"ok": False, "reason": f"工場ポイントが足りません。必要: {donate_points} / 所持: {points_before}"}
    now_ts = int(time.time())
    week_key = _world_week_key()
    current_before = int(project["current_points"] or 0)
    current_after = current_before + donate_points
    points_after = points_before - donate_points
    db.execute("UPDATE users SET factory_points = ? WHERE id = ?", (points_after, uid))
    db.execute(
        """
        UPDATE world_research_projects
        SET current_points = ?, updated_at = ?
        WHERE id = ? AND is_completed = 0
        """,
        (current_after, now_ts, int(project["id"])),
    )
    db.execute(
        """
        INSERT INTO user_research_contributions
        (user_id, research_key, points, week_key, created_at, request_id)
        VALUES (?, ?, ?, ?, ?, ?)
        """,
        (uid, key, donate_points, week_key, now_ts, request_id),
    )
    audit_log(
        db,
        AUDIT_EVENT_TYPES["FACTORY_RESEARCH_DONATE"],
        user_id=uid,
        request_id=request_id,
        action_key="factory_research_donate",
        entity_type="world_research_project",
        entity_id=int(project["id"]),
        delta_count=donate_points,
        payload={
            "user_id": uid,
            "research_key": key,
            "amount": donate_points,
            "factory_points_before": points_before,
            "factory_points_after": points_after,
            "current_points_before": current_before,
            "current_points_after": current_after,
            "required_points": int(project["required_points"] or 0),
            "week_key": week_key,
        },
        ip=ip,
    )
    completed = False
    if current_after >= int(project["required_points"] or 0):
        cur = db.execute(
            """
            UPDATE world_research_projects
            SET is_completed = 1, completed_at = ?, updated_at = ?
            WHERE id = ? AND is_completed = 0
            """,
            (now_ts, now_ts, int(project["id"])),
        )
        completed = int(cur.rowcount or 0) == 1
        if completed:
            audit_log(
                db,
                AUDIT_EVENT_TYPES["FACTORY_RESEARCH_COMPLETE"],
                user_id=None,
                request_id=request_id,
                action_key="factory_research_complete",
                entity_type="world_research_project",
                entity_id=int(project["id"]),
                delta_count=current_after,
                payload={
                    "research_key": key,
                    "name_ja": project["name_ja"],
                    "reward_key": project["reward_key"],
                    "reward_label": project["reward_label"],
                    "required_points": int(project["required_points"] or 0),
                    "current_points": current_after,
                    "completed_by_user_id": uid,
                    "week_key": week_key,
                },
                ip=ip,
            )
    db.commit()
    return {
        "ok": True,
        "research_key": key,
        "amount": donate_points,
        "factory_points_after": points_after,
        "current_points_after": current_after,
        "completed": completed,
    }


def get_user_factory_view(db, user_id, *, now_ts=None, ensure=True):
    uid = int(user_id)
    if ensure:
        ensure_user_factory_facilities(db, uid)
        ensure_companions(db, uid)
    current_ts = int(now_ts or time.time())
    storage_cap_hours = _factory_storage_cap_hours_for_user(db, uid)
    collector_bonus_percent = _factory_collector_bonus_percent_for_user(db, uid)
    rows = db.execute(
        """
        SELECT *
        FROM user_factory_facilities
        WHERE user_id = ?
        ORDER BY CASE facility_key
            WHEN 'scrap_collector' THEN 1
            WHEN 'energy_reactor' THEN 2
            WHEN 'research_terminal' THEN 3
            ELSE 9
        END, id ASC
        """,
        (uid,),
    ).fetchall()
    facilities = []
    for row in rows:
        facility_def = _factory_facility_def(row["facility_key"]) or {}
        level = max(1, min(int(row["level"] or 1), FACTORY_MAX_LEVEL))
        base_pending = _factory_pending_points(row, current_ts, storage_cap_hours=storage_cap_hours)
        bonus_points = int((base_pending * collector_bonus_percent) // 100)
        pending = base_pending + bonus_points
        next_level = level + 1 if level < FACTORY_MAX_LEVEL else None
        upgrade_cost = _factory_upgrade_cost_for_level(level)
        facilities.append(
            {
                "id": int(row["id"]),
                "facility_key": row["facility_key"],
                "facility_name": facility_def.get("facility_name", row["facility_key"]),
                "description": facility_def.get("description", ""),
                "level": level,
                "rate_per_hour": _factory_rate_for_level(level),
                "base_pending_points": base_pending,
                "bonus_points": bonus_points,
                "pending_points": pending,
                "can_claim": pending > 0,
                "next_level": next_level,
                "next_rate_per_hour": _factory_rate_for_level(next_level) if next_level else None,
                "upgrade_cost": upgrade_cost,
                "can_upgrade": bool(next_level and upgrade_cost > 0),
                "last_claimed_at": int(row["last_claimed_at"] or 0),
            }
        )
    user = db.execute("SELECT factory_points, coins FROM users WHERE id = ? LIMIT 1", (uid,)).fetchone()
    total_pending = sum(int(item["pending_points"] or 0) for item in facilities)
    return {
        "factory_points": int(user["factory_points"] or 0) if user and "factory_points" in user.keys() else 0,
        "coins": int(user["coins"] or 0) if user else 0,
        "facilities": facilities,
        "total_pending_points": int(total_pending),
        "has_claimable": total_pending > 0,
        "storage_cap_hours": storage_cap_hours,
        "collector_bonus_percent": collector_bonus_percent,
    }


def _base_visit_user(db, user_id):
    try:
        uid = int(user_id)
    except (TypeError, ValueError):
        return None
    if uid <= 0:
        return None
    user = db.execute("SELECT * FROM users WHERE id = ? LIMIT 1", (uid,)).fetchone()
    if not user:
        return None
    if "is_banned" in user.keys() and int(user["is_banned"] or 0) == 1:
        return None
    return user


def _base_like_state(db, base_user_id, viewer_user_id=None):
    base_uid = int(base_user_id)
    count = int(
        db.execute(
            "SELECT COUNT(*) AS c FROM user_base_likes WHERE base_user_id = ?",
            (base_uid,),
        ).fetchone()["c"]
        or 0
    )
    liked_by_me = False
    if viewer_user_id:
        liked_by_me = bool(
            db.execute(
                """
                SELECT 1
                FROM user_base_likes
                WHERE base_user_id = ? AND liked_by_user_id = ?
                LIMIT 1
                """,
                (base_uid, int(viewer_user_id)),
            ).fetchone()
        )
    return {"like_count": count, "liked_by_me": liked_by_me}


def _base_robot_view(db, user_id):
    robot = _get_active_robot(db, user_id) or _select_main_robot(db, user_id)
    if not robot:
        return {
            "exists": False,
            "name": "未設定",
            "image_url": url_for("static", filename="assets/placeholder_player.png"),
        }
    image_url = robot["image_url"] if "image_url" in robot.keys() and robot["image_url"] else None
    if not image_url:
        image_url = _composed_image_url(robot["composed_image_path"], robot["updated_at"]) if robot["composed_image_path"] else None
    return {
        "exists": True,
        "id": int(robot["id"]),
        "name": robot["name"] or f"Robot#{int(robot['id'])}",
        "image_url": image_url or url_for("static", filename="assets/placeholder_player.png"),
    }


def get_base_visit_view(db, base_user_id, *, viewer_user_id=None, ensure=True):
    base_user = _base_visit_user(db, base_user_id)
    if not base_user:
        return {"exists": False, "base_user_id": int(base_user_id or 0)}
    uid = int(base_user["id"])
    viewer_uid = int(viewer_user_id) if viewer_user_id else None
    display_name = _display_username_for_user_row(db, base_user)
    cosmetics = get_factory_cosmetic_loadout(db, uid, ensure=ensure)
    companion = get_active_companion(db, uid, ensure=ensure)
    dispatch = companion_dispatch_summary(db, uid, ensure=ensure)
    factory = get_user_factory_view(db, uid, ensure=ensure)
    album_summary = companion_album_summary(db, uid, ensure=ensure)
    showcase_rows = _showcase_rows(db, uid)
    like_state = _base_like_state(db, uid, viewer_uid)
    factory_summary = [
        {
            "facility_key": row["facility_key"],
            "facility_name": row["facility_name"],
            "level": int(row["level"]),
            "rate_per_hour": int(row["rate_per_hour"]),
        }
        for row in factory.get("facilities", [])
    ]
    return {
        "exists": True,
        "base_user_id": uid,
        "username": base_user["username"],
        "display_name": display_name,
        "robot": _base_robot_view(db, uid),
        "cosmetics": cosmetics,
        "companion": companion,
        "dispatch": dispatch,
        "album": {
            "photo_owned": int(album_summary.get("photo_owned") or 0),
            "photo_total": int(album_summary.get("photo_total") or 0),
            "dispatch_count": int(album_summary.get("dispatch_count") or 0),
            "factory_points_collected": int(album_summary.get("factory_points_collected") or 0),
        },
        "factory": {
            "factory_points": int(factory.get("factory_points") or 0),
            "facilities": factory_summary,
        },
        "showcase_rows": [row for row in showcase_rows if row.get("robot_instance_id")][:3],
        "like_count": int(like_state["like_count"]),
        "liked_by_me": bool(like_state["liked_by_me"]),
        "is_self": bool(viewer_uid and viewer_uid == uid),
        "can_like": bool(viewer_uid and viewer_uid != uid and not like_state["liked_by_me"]),
    }


def _base_ranking_week_start_ts(now_ts=None):
    week_key = _world_week_key(now_ts)
    week_start, _ = _world_week_bounds(week_key)
    return int(week_start.timestamp()), week_key


def _base_ranking_rows(db, *, since_ts=None, limit=10):
    params = []
    where = "WHERE COALESCE(u.is_banned, 0) = 0"
    if since_ts is not None:
        where += " AND ubl.created_at >= ?"
        params.append(int(since_ts))
    params.append(int(limit))
    rows = db.execute(
        f"""
        SELECT u.*, COUNT(ubl.id) AS like_count
        FROM user_base_likes ubl
        JOIN users u ON u.id = ubl.base_user_id
        {where}
        GROUP BY u.id
        ORDER BY like_count DESC, u.id ASC
        LIMIT ?
        """,
        tuple(params),
    ).fetchall()
    ranking_rows = []
    for row in rows:
        uid = int(row["id"])
        companion = get_active_companion(db, uid, ensure=False)
        album = companion_album_summary(db, uid, ensure=False)
        robot = _base_robot_view(db, uid)
        ranking_rows.append(
            {
                "user_id": uid,
                "username": row["username"],
                "display_name": _display_username_for_user_row(db, row),
                "robot": robot,
                "robot_image_url": robot.get("image_url") or url_for("static", filename="assets/placeholder_player.png"),
                "companion_name": companion.get("name_ja") if companion else "相棒未設定",
                "like_count": int(row["like_count"] or 0),
                "photo_owned": int(album.get("photo_owned") or 0),
                "photo_total": int(album.get("photo_total") or 0),
            }
        )
    return ranking_rows


def get_base_ranking_view(db, *, viewer_user_id=None, limit=10, request_id=None, ip=None):
    viewer_uid = int(viewer_user_id) if viewer_user_id else None
    ensure_companion_album_photos(db, user_id=viewer_uid)
    week_start_ts, week_key = _base_ranking_week_start_ts()
    weekly_rows = _base_ranking_rows(db, since_ts=week_start_ts, limit=limit)
    total_rows = _base_ranking_rows(db, limit=limit)
    for ranking_type, rows in (("weekly", weekly_rows), ("total", total_rows)):
        audit_log(
            db,
            AUDIT_EVENT_TYPES["BASE_RANKING_VIEW"],
            user_id=viewer_uid,
            request_id=request_id,
            action_key="base_ranking_view",
            entity_type="base_ranking",
            entity_id=None,
            payload={
                "viewer_user_id": viewer_uid,
                "ranking_type": ranking_type,
                "result_count": len(rows),
            },
            ip=ip,
        )
    return {
        "viewer_user_id": viewer_uid,
        "week_key": week_key,
        "sections": [
            {
                "key": "weekly",
                "title": "今週の話題基地",
                "description": "今週いいねされた基地のランキングです。",
                "rows": weekly_rows,
            },
            {
                "key": "total",
                "title": "累計人気基地",
                "description": "これまでの基地いいね累計ランキングです。",
                "rows": total_rows,
            },
        ],
    }


def like_base(db, base_user_id, liked_by_user_id, *, request_id=None, ip=None):
    base_user = _base_visit_user(db, base_user_id)
    if not base_user:
        return {"ok": False, "reason": "基地が見つかりません。"}
    viewer = _base_visit_user(db, liked_by_user_id)
    if not viewer:
        return {"ok": False, "reason": "ログインユーザーを確認できません。"}
    base_uid = int(base_user["id"])
    viewer_uid = int(viewer["id"])
    if base_uid == viewer_uid:
        return {"ok": False, "reason": "自分の基地にはいいねできません。"}
    now_ts = int(time.time())
    cur = db.execute(
        """
        INSERT OR IGNORE INTO user_base_likes (base_user_id, liked_by_user_id, created_at)
        VALUES (?, ?, ?)
        """,
        (base_uid, viewer_uid, now_ts),
    )
    if int(cur.rowcount or 0) != 1:
        db.rollback()
        return {"ok": False, "reason": "この基地はいいね済みです。"}
    like_count_after = _base_like_state(db, base_uid, viewer_uid)["like_count"]
    audit_log(
        db,
        AUDIT_EVENT_TYPES["BASE_LIKE"],
        user_id=viewer_uid,
        request_id=request_id,
        action_key="base_like",
        entity_type="user_base",
        entity_id=base_uid,
        delta_count=1,
        payload={
            "viewer_user_id": viewer_uid,
            "base_user_id": base_uid,
            "liked_by_user_id": viewer_uid,
            "like_count_after": int(like_count_after),
        },
        ip=ip,
    )
    db.commit()
    return {"ok": True, "like_count_after": int(like_count_after)}


def claim_factory_facility_points(db, user_id, facility_key, *, request_id=None, ip=None):
    uid = int(user_id)
    key = str(facility_key or "").strip()
    if not _factory_facility_def(key):
        return {"ok": False, "reason": "工場施設の指定が不正です。"}
    ensure_user_factory_facilities(db, uid, request_id=request_id, ip=ip)
    ensure_companions(db, uid, request_id=request_id, ip=ip)
    now_ts = int(time.time())
    row = db.execute(
        "SELECT * FROM user_factory_facilities WHERE user_id = ? AND facility_key = ? LIMIT 1",
        (uid, key),
    ).fetchone()
    if not row:
        return {"ok": False, "reason": "工場施設が見つかりません。"}
    storage_cap_hours = _factory_storage_cap_hours_for_user(db, uid)
    collector_bonus_percent = _factory_collector_bonus_percent_for_user(db, uid)
    base_gained = _factory_pending_points(row, now_ts, storage_cap_hours=storage_cap_hours)
    bonus_gained = int((base_gained * collector_bonus_percent) // 100)
    gained = base_gained + bonus_gained
    if base_gained <= 0:
        return {"ok": False, "reason": "まだ回収できる工場ポイントがありません。"}
    user = db.execute("SELECT factory_points FROM users WHERE id = ? LIMIT 1", (uid,)).fetchone()
    before_points = int(user["factory_points"] or 0) if user else 0
    after_points = before_points + gained
    db.execute(
        "UPDATE user_factory_facilities SET last_claimed_at = ?, updated_at = ? WHERE id = ? AND user_id = ?",
        (now_ts, now_ts, int(row["id"]), uid),
    )
    db.execute("UPDATE users SET factory_points = ? WHERE id = ?", (after_points, uid))
    audit_log(
        db,
        AUDIT_EVENT_TYPES["FACTORY_CLAIM"],
        user_id=uid,
        request_id=request_id,
        action_key="factory_claim",
        entity_type="factory_facility",
        entity_id=int(row["id"]),
        delta_count=gained,
        payload={
            "user_id": uid,
            "facility_key": key,
            "level_before": int(row["level"] or 1),
            "level_after": int(row["level"] or 1),
            "points_gained": gained,
            "base_points_gained": base_gained,
            "bonus_points_gained": bonus_gained,
            "collector_bonus_percent": collector_bonus_percent,
            "storage_cap_hours": storage_cap_hours,
            "factory_points_before": before_points,
            "factory_points_after": after_points,
        },
        ip=ip,
    )
    db.commit()
    return {"ok": True, "points_gained": gained, "factory_points_after": after_points, "bonus_points_gained": bonus_gained}


def upgrade_factory_facility(db, user_id, facility_key, *, request_id=None, ip=None):
    uid = int(user_id)
    key = str(facility_key or "").strip()
    if not _factory_facility_def(key):
        return {"ok": False, "reason": "工場施設の指定が不正です。"}
    ensure_user_factory_facilities(db, uid, request_id=request_id, ip=ip)
    row = db.execute(
        "SELECT * FROM user_factory_facilities WHERE user_id = ? AND facility_key = ? LIMIT 1",
        (uid, key),
    ).fetchone()
    if not row:
        return {"ok": False, "reason": "工場施設が見つかりません。"}
    level_before = int(row["level"] or 1)
    if level_before >= FACTORY_MAX_LEVEL:
        return {"ok": False, "reason": "この施設は最大Lvです。"}
    cost = _factory_upgrade_cost_for_level(level_before)
    user = db.execute("SELECT coins FROM users WHERE id = ? LIMIT 1", (uid,)).fetchone()
    coins_before = int(user["coins"] or 0) if user else 0
    if coins_before < cost:
        return {"ok": False, "reason": f"コインが足りません。必要: {cost} / 所持: {coins_before}"}
    now_ts = int(time.time())
    level_after = level_before + 1
    coins_after = coins_before - cost
    cur = db.execute(
        """
        UPDATE user_factory_facilities
        SET level = ?, updated_at = ?
        WHERE id = ? AND user_id = ? AND level = ?
        """,
        (level_after, now_ts, int(row["id"]), uid, level_before),
    )
    if int(cur.rowcount or 0) != 1:
        db.rollback()
        return {"ok": False, "reason": "強化に失敗しました。もう一度確認してください。"}
    db.execute("UPDATE users SET coins = ? WHERE id = ?", (coins_after, uid))
    payload = {
        "user_id": uid,
        "facility_key": key,
        "level_before": level_before,
        "level_after": level_after,
        "cost": cost,
        "coins_before": coins_before,
        "coins_after": coins_after,
    }
    audit_log(
        db,
        AUDIT_EVENT_TYPES["FACTORY_UPGRADE"],
        user_id=uid,
        request_id=request_id,
        action_key="factory_upgrade",
        entity_type="factory_facility",
        entity_id=int(row["id"]),
        delta_coins=-cost,
        payload=payload,
        ip=ip,
    )
    audit_log(
        db,
        AUDIT_EVENT_TYPES["COIN_DELTA"],
        user_id=uid,
        request_id=request_id,
        action_key="factory_upgrade",
        entity_type="factory_facility",
        entity_id=int(row["id"]),
        delta_coins=-cost,
        payload={**payload, "source": "factory_upgrade", "spend": cost},
        ip=ip,
    )
    db.commit()
    return {"ok": True, "level_after": level_after, "coins_after": coins_after, "cost": cost}


def _research_module_synthesis_materials(db, user_id):
    user = db.execute("SELECT active_research_module_instance_id FROM users WHERE id = ?", (int(user_id),)).fetchone()
    active_id = int(user["active_research_module_instance_id"] or 0) if user and user["active_research_module_instance_id"] else 0
    rows = _user_research_module_options(db, user_id)
    materials = []
    for item in rows:
        reason = ""
        if int(item.get("is_locked") or 0) != 0:
            reason = "保護中のため素材不可"
        elif active_id and int(item["instance_id"]) == active_id:
            reason = "使用中のため素材不可"
        item["is_synthesis_material"] = not reason
        item["synthesis_block_reason"] = reason
        materials.append(item)
    return materials


def _annotate_research_module_material_status(modules, active_module=None):
    active_id = int(active_module.get("instance_id") or 0) if active_module else 0
    for module in modules:
        is_active = active_id and int(module.get("instance_id") or 0) == active_id
        module["is_active_module"] = bool(is_active)
        if is_active:
            module["material_status_label"] = "使用中のため素材不可"
            module["is_synthesis_material"] = False
        elif int(module.get("is_locked") or 0) != 0:
            module["material_status_label"] = "保護中のため素材不可"
            module["is_synthesis_material"] = False
        else:
            module["material_status_label"] = "素材OK"
            module["is_synthesis_material"] = True
    return modules


def _research_module_synthesis_cost(module_a, module_b):
    return RESEARCH_MODULE_SYNTHESIS_COST_COINS


def _validate_research_module_synthesis_materials(db, user_id, module_a_id, module_b_id):
    if int(module_a_id or 0) <= 0 or int(module_b_id or 0) <= 0:
        return None, None, "素材は2個選んでください"
    if int(module_a_id or 0) == int(module_b_id or 0):
        return None, None, "同じモジュールを2つ選ぶことはできません"
    user = db.execute("SELECT active_research_module_instance_id FROM users WHERE id = ?", (int(user_id),)).fetchone()
    active_id = int(user["active_research_module_instance_id"] or 0) if user and user["active_research_module_instance_id"] else 0
    modules = []
    for module_id in (module_a_id, module_b_id):
        module = _research_module_instance_row(db, int(module_id), None)
        if not module:
            return None, None, "素材に使えない研究モジュールです"
        if int(module.get("user_id") or 0) != int(user_id):
            return None, None, "所有者が違います"
        if module.get("sold_at"):
            return None, None, "すでに売却済みです"
        if str(module.get("status") or "") != "inventory":
            return None, None, "すでに消費済みです"
        if int(module.get("is_locked") or 0) != 0:
            return None, None, "ロック中のため素材にできません"
        if active_id and int(module["instance_id"]) == active_id:
            return None, None, "現在使用中のため素材にできません"
        modules.append(module)
    return modules[0], modules[1], ""


def _research_module_synthesis_family(module_a, module_b):
    families = sorted(
        [
            str(module_a.get("family") or "synthesized").strip(),
            str(module_b.get("family") or "synthesized").strip(),
        ]
    )
    return "_".join(families)


def _research_module_synthesis_score(bonuses):
    positives = sum(max(0, int(value or 0)) for value in bonuses.values())
    negatives = sum(abs(min(0, int(value or 0))) for value in bonuses.values())
    return int(positives - negatives // 2)


def _roll_research_module_synthesis(module_a, module_b, *, rng=None):
    return synthesize_research_module(module_a, module_b, rng=rng)


def _ensure_user_item_row(db, user_id, item_key):
    db.execute(
        """
        INSERT INTO user_items (user_id, item_key, qty)
        VALUES (?, ?, 0)
        ON CONFLICT(user_id, item_key) DO NOTHING
        """,
        (user_id, item_key),
    )


def _get_user_item_qty(db, user_id, item_key):
    _ensure_user_item_row(db, user_id, item_key)
    row = db.execute(
        "SELECT qty FROM user_items WHERE user_id = ? AND item_key = ?",
        (user_id, item_key),
    ).fetchone()
    return row["qty"] if row else 0


def _ensure_player_core_row(db, user_id, core_key):
    db.execute(
        """
        INSERT OR IGNORE INTO user_core_inventory (user_id, core_asset_id, quantity, updated_at)
        SELECT ?, ca.id, 0, datetime('now')
        FROM core_assets ca
        WHERE ca.core_key = ? AND ca.is_active = 1
        """,
        (int(user_id), str(core_key)),
    )


def _get_player_core_qty(db, user_id, core_key):
    _ensure_player_core_row(db, user_id, core_key)
    row = db.execute(
        """
        SELECT uci.quantity
        FROM user_core_inventory uci
        JOIN core_assets ca ON ca.id = uci.core_asset_id
        WHERE uci.user_id = ? AND ca.core_key = ?
        """,
        (int(user_id), str(core_key)),
    ).fetchone()
    return int(row["quantity"] or 0) if row else 0


def _grant_player_core(db, user_id, core_key, qty=1):
    grant_qty = max(0, int(qty or 0))
    if grant_qty <= 0:
        return 0
    _ensure_player_core_row(db, user_id, core_key)
    db.execute(
        """
        UPDATE user_core_inventory
        SET quantity = quantity + ?, updated_at = datetime('now')
        WHERE user_id = ?
          AND core_asset_id = (SELECT id FROM core_assets WHERE core_key = ? LIMIT 1)
        """,
        (grant_qty, int(user_id), str(core_key)),
    )
    return grant_qty


def _consume_player_core(db, user_id, core_key, qty=1):
    consume_qty = max(0, int(qty or 0))
    if consume_qty <= 0:
        return False
    current_qty = _get_player_core_qty(db, user_id, core_key)
    if current_qty < consume_qty:
        return False
    db.execute(
        """
        UPDATE user_core_inventory
        SET quantity = quantity - ?, updated_at = datetime('now')
        WHERE user_id = ?
          AND core_asset_id = (SELECT id FROM core_assets WHERE core_key = ? LIMIT 1)
        """,
        (consume_qty, int(user_id), str(core_key)),
    )
    return True


def _get_player_evolution_core_progress(db, user_id):
    row = db.execute(
        "SELECT evolution_core_progress FROM users WHERE id = ?",
        (int(user_id),),
    ).fetchone()
    if not row:
        return 0
    return max(0, int(row["evolution_core_progress"] or 0))


def _evolution_core_progress_status(progress, *, core_qty=0):
    current = max(0, int(progress or 0))
    target = max(1, int(EVOLUTION_CORE_PROGRESS_TARGET))
    if current >= target:
        current = current % target
    remain = max(0, int(target - current))
    if int(core_qty or 0) > 0:
        home_label = f"進化コア {int(core_qty)}個 / 次 {current}/{target}"
    else:
        home_label = f"あと{remain}勝で進化コア"
    return {
        "current": int(current),
        "target": int(target),
        "remaining_wins": int(remain),
        "progress_label": f"進化コア進捗 {int(current)}/{int(target)}",
        "remaining_label": f"あと{int(remain)}勝で進化コア",
        "home_label": home_label,
    }


def _advance_evolution_core_progress(
    db,
    user_id,
    battle_wins,
    *,
    request_id=None,
    action_key="explore",
    area_key=None,
    ip=None,
):
    wins = max(0, int(battle_wins or 0))
    target = max(1, int(EVOLUTION_CORE_PROGRESS_TARGET))
    progress_added = wins * int(EVOLUTION_CORE_PROGRESS_PER_WIN)
    before = _get_player_evolution_core_progress(db, user_id)
    if progress_added <= 0:
        return {
            "wins": wins,
            "progress_added": 0,
            "progress_before": before,
            "progress_after": before,
            "granted_core_qty": 0,
            "target": target,
        }

    total_after_add = int(before + progress_added)
    granted_core_qty = int(total_after_add // target)
    progress_after = int(total_after_add % target)
    db.execute(
        "UPDATE users SET evolution_core_progress = ? WHERE id = ?",
        (progress_after, int(user_id)),
    )
    audit_log(
        db,
        AUDIT_EVENT_TYPES["CORE_PROGRESS"],
        user_id=user_id,
        request_id=request_id,
        action_key=action_key,
        entity_type="core",
        entity_id=None,
        delta_count=int(progress_added),
        payload={
            "core_key": EVOLUTION_CORE_KEY,
            "battle_wins": int(wins),
            "progress_before": int(before),
            "progress_after": int(progress_after),
            "progress_added": int(progress_added),
            "target": int(target),
            "area_key": area_key,
            "granted_core_qty": int(granted_core_qty),
        },
        ip=ip,
    )
    if granted_core_qty > 0:
        granted_core_qty = int(_grant_player_core(db, user_id, EVOLUTION_CORE_KEY, qty=granted_core_qty))
        audit_log(
            db,
            AUDIT_EVENT_TYPES["CORE_GUARANTEE"],
            user_id=user_id,
            request_id=request_id,
            action_key=action_key,
            entity_type="core",
            entity_id=None,
            delta_count=int(granted_core_qty),
            payload={
                "core_key": EVOLUTION_CORE_KEY,
                "quantity": int(granted_core_qty),
                "battle_wins": int(wins),
                "progress_before": int(before),
                "progress_after_add": int(total_after_add),
                "progress_after_reset": int(progress_after),
                "target": int(target),
                "area_key": area_key,
            },
            ip=ip,
        )
        audit_log(
            db,
            AUDIT_EVENT_TYPES["CORE_DROP"],
            user_id=user_id,
            request_id=request_id,
            action_key=action_key,
            entity_type="core",
            entity_id=None,
            delta_count=int(granted_core_qty),
            payload={
                "core_key": EVOLUTION_CORE_KEY,
                "core_name": "進化コア",
                "quantity": int(granted_core_qty),
                "area_key": area_key,
                "source": "progress_guarantee",
                "battle_wins": int(wins),
                "target": int(target),
            },
            ip=ip,
        )
        audit_log(
            db,
            AUDIT_EVENT_TYPES["INVENTORY_DELTA"],
            user_id=user_id,
            request_id=request_id,
            action_key=action_key,
            entity_type="core",
            entity_id=None,
            delta_count=int(granted_core_qty),
            payload={
                "reason": "core_progress_guarantee",
                "core_key": EVOLUTION_CORE_KEY,
                "quantity": int(granted_core_qty),
                "area_key": area_key,
                "battle_wins": int(wins),
            },
            ip=ip,
        )
    return {
        "wins": int(wins),
        "progress_added": int(progress_added),
        "progress_before": int(before),
        "progress_after": int(progress_after),
        "granted_core_qty": int(granted_core_qty),
        "target": int(target),
    }


def _next_rarity_for_evolution(rarity_code):
    rarity = str(rarity_code or "").upper().strip()
    return EVOLUTION_PATH.get(rarity)


def _candidate_evolved_part_keys(base_part_key):
    key = str(base_part_key or "").strip().lower()
    if not key:
        return []
    candidates = []
    insect_r_by_source = {
        str(part.get("source_key") or "").strip().lower(): str(part.get("key") or "").strip().lower()
        for part in INSECT_R_PART_DEFINITIONS
    }
    if key in insect_r_by_source:
        candidates.append(insect_r_by_source[key])
    if "_n_" in key:
        candidates.append(key.replace("_n_", "_r_", 1))
    if key.endswith("_n"):
        candidates.append(f"{key[:-2]}_r")
    normal_fallback = {
        "head_normal": "head_r_normal",
        "right_arm_normal": "right_arm_r_normal",
        "left_arm_normal": "left_arm_r_normal",
        "legs_normal": "legs_r_normal",
        "head_n_normal": "head_r_normal",
        "right_arm_n_normal": "right_arm_r_normal",
        "left_arm_n_normal": "left_arm_r_normal",
        "legs_n_normal": "legs_r_normal",
    }
    if key in normal_fallback:
        candidates.append(normal_fallback[key])
    unique = []
    seen = set()
    for candidate in candidates:
        if candidate and candidate not in seen:
            seen.add(candidate)
            unique.append(candidate)
    return unique


def resolve_evolved_part_key(base_part_key):
    db = get_db()
    for candidate in _candidate_evolved_part_keys(base_part_key):
        row = db.execute(
            """
            SELECT id
            FROM robot_parts
            WHERE key = ? AND is_active = 1 AND UPPER(COALESCE(rarity, '')) = 'R'
            LIMIT 1
            """,
            (candidate,),
        ).fetchone()
        if row:
            return candidate
    return None


def _norm_part_type(part_type):
    if part_type == "R_ARM":
        return "RIGHT_ARM"
    if part_type == "L_ARM":
        return "LEFT_ARM"
    return part_type


def _create_part_instance_from_master(db, user_id, part_row, plus=0, area_key=None, status="inventory"):
    ptype = _norm_part_type(part_row["part_type"])
    rarity = (part_row["rarity"] or "N").upper()
    part_key = str(part_row["key"] or "")
    if rarity == "N" and part_key in DINO_PART_STAT_BY_KEY:
        fixed_stats = DINO_PART_STAT_BY_KEY[part_key]
        weights = {f"w_{stat_key}": float(fixed_stats.get(stat_key, 0) or 0) / 12.0 for stat_key in STATS}
    else:
        bias = dict(_area_weight_bias(area_key) or {})
        series_bias = _series_weight_bias_for_part_row(part_row) or {}
        for stat_key, delta in series_bias.items():
            bias[stat_key] = float(bias.get(stat_key, 0.0)) + float(delta or 0.0)
        weights = generate_noisy_weights(ptype, bias=bias)
    element = (part_row["element"] or "NORMAL").upper()
    series = part_row["series"] or "S1"
    status_key = str(status or "inventory").strip().lower()
    if status_key not in {"inventory", "equipped", "overflow", "sold"}:
        status_key = "inventory"
    cur = db.execute(
        """
        INSERT INTO part_instances
        (part_id, user_id, part_type, rarity, element, series, plus, w_hp, w_atk, w_def, w_spd, w_acc, w_cri, status, created_at, updated_at)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime('now'))
        """,
        (
            part_row["id"],
            user_id,
            ptype,
            rarity,
            element,
            series,
            plus,
            weights["w_hp"],
            weights["w_atk"],
            weights["w_def"],
            weights["w_spd"],
            weights["w_acc"],
            weights["w_cri"],
            status_key,
            int(time.time()),
        ),
    )
    return cur.lastrowid


def _market_day_key():
    return datetime.now(JST).strftime("%Y-%m-%d")


def _market_next_update_label():
    tomorrow = (datetime.now(JST) + timedelta(days=1)).strftime("%Y-%m-%d")
    return f"{tomorrow} 00:00頃"


def _market_refresh_cost(refresh_count_today):
    count = max(0, int(refresh_count_today or 0))
    if count < len(MARKET_REFRESH_COSTS):
        return int(MARKET_REFRESH_COSTS[count])
    return int(MARKET_REFRESH_COSTS[-1])


def _part_inventory_limit_value(raw_limit):
    if raw_limit is None:
        return 60
    try:
        limit = int(raw_limit)
    except Exception:
        return 60
    if limit < 0:
        return 60
    return limit


def _part_inventory_expand_price(current_limit):
    limit = _part_inventory_limit_value(current_limit)
    if limit >= int(PART_INVENTORY_EXPANSION_MAX_LIMIT):
        return None
    return PART_INVENTORY_EXPANSION_PRICES.get(limit)


def _part_inventory_expansion_state(user_row):
    raw_limit = 60
    if user_row and "part_inventory_limit" in user_row.keys():
        raw_limit = user_row["part_inventory_limit"]
    current_limit = _part_inventory_limit_value(raw_limit)
    price = _part_inventory_expand_price(current_limit)
    next_limit = min(
        int(PART_INVENTORY_EXPANSION_MAX_LIMIT),
        current_limit + int(PART_INVENTORY_EXPANSION_UNIT),
    )
    can_expand = price is not None and current_limit < int(PART_INVENTORY_EXPANSION_MAX_LIMIT)
    coins = int(user_row["coins"] or 0) if user_row and "coins" in user_row.keys() else 0
    return {
        "current_limit": int(current_limit),
        "next_limit": int(next_limit),
        "max_limit": int(PART_INVENTORY_EXPANSION_MAX_LIMIT),
        "price": int(price or 0),
        "can_expand": bool(can_expand),
        "has_enough_coins": bool(can_expand and coins >= int(price or 0)),
        "is_max": bool(current_limit >= int(PART_INVENTORY_EXPANSION_MAX_LIMIT)),
    }


def _market_part_type_aliases(part_type):
    norm = _norm_part_type(str(part_type or "").strip().upper())
    aliases = [norm]
    if norm == "RIGHT_ARM":
        aliases.append("R_ARM")
    elif norm == "LEFT_ARM":
        aliases.append("L_ARM")
    return tuple(dict.fromkeys(alias for alias in aliases if alias))


def _market_pick_weighted(items, rng):
    total = sum(int(weight) for _key, weight in items)
    if total <= 0:
        return items[0][0]
    roll = rng.randint(1, total)
    current = 0
    for key, weight in items:
        current += int(weight)
        if roll <= current:
            return key
    return items[-1][0]


def _market_excludes_part_row(part_row):
    row = dict(part_row or {})
    rarity = str(row.get("rarity") or "N").strip().upper()
    if rarity != "R":
        return False
    frame_type = _frame_type_for_row(row)
    series_key = str(row.get("series_key") or row.get("series") or "").strip()
    # 虫Rは当面、廃品市場ではなく進化合成だけで入手させる。
    return frame_type == "insect" or _is_insect_series_key(series_key)


def _market_pick_part_row(db, *, slot_key, rng):
    if slot_key in MARKET_FIXED_SLOT_PART_TYPES:
        rarity_roll = "N"
        part_type = MARKET_FIXED_SLOT_PART_TYPES[slot_key]
    else:
        rarity_roll = _market_pick_weighted(MARKET_FREE_RARITY_ROLL, rng)
        part_type = rng.choice(tuple(MARKET_FIXED_SLOT_PART_TYPES.values()))
    rarity = "R" if rarity_roll == "R" else "N"
    aliases = _market_part_type_aliases(part_type)
    marks = ",".join("?" for _ in aliases)
    rows = db.execute(
        f"""
        SELECT *
        FROM robot_parts
        WHERE is_active = 1
          AND COALESCE(is_unlocked, 1) = 1
          AND UPPER(COALESCE(rarity, 'N')) = ?
          AND NOT (
            UPPER(COALESCE(rarity, 'N')) = 'R'
            AND (
              COALESCE(frame_type, 'normal') = 'insect'
              OR COALESCE(series_key, series, '') LIKE 'insect_%'
            )
          )
          AND UPPER(COALESCE(part_type, '')) IN ({marks})
        ORDER BY key ASC
        """,
        (rarity, *aliases),
    ).fetchall()
    if not rows and rarity == "R":
        rows = db.execute(
            f"""
            SELECT *
            FROM robot_parts
            WHERE is_active = 1
              AND COALESCE(is_unlocked, 1) = 1
              AND UPPER(COALESCE(rarity, 'N')) = 'N'
              AND UPPER(COALESCE(part_type, '')) IN ({marks})
            ORDER BY key ASC
            """,
            aliases,
        ).fetchall()
    if not rows:
        return None, rarity_roll
    return rows[rng.randrange(len(rows))], rarity_roll


def _market_listing_price(rarity_roll, rng):
    key = "N+1" if rarity_roll == "N+1" else ("R" if rarity_roll == "R" else "N")
    lo, hi = MARKET_PRICE_RANGES[key]
    return int(rng.randint(int(lo), int(hi)))


def _market_part_helper_line(item):
    rarity = str(item.get("rarity") or "N").strip().upper()
    part_type = _norm_part_type(item.get("part_type"))
    if rarity == "R":
        return "進化素材を背負った夢枠。必要な時だけ狙いたい一品"
    if int(item.get("plus") or 0) > 0:
        return "少し強化済み。今日の編成を一段だけ押し上げます"
    return {
        "HEAD": "耐久と命中を整えたい機体向け",
        "RIGHT_ARM": "攻撃を補いたい時に扱いやすい標準装備",
        "LEFT_ARM": "命中と会心を伸ばしたい機体向け",
        "LEGS": "素早さを少し補いたい時に",
    }.get(part_type, "足りない部位を補うための標準パーツ")


def _market_listing_preview_weights(item):
    part_type = _norm_part_type(str(item.get("part_type") or "").strip().upper())
    template = WEIGHT_TEMPLATES.get(part_type)
    if not template:
        return None
    bias = _series_weight_bias_for_part_row(item) or {}
    base = dict(template)
    min_floor = 0.01
    for key, value in bias.items():
        stat_key = str(key or "").strip().lower()
        if stat_key in STATS:
            base[stat_key] = max(min_floor, float(base.get(stat_key, min_floor)) + float(value or 0.0))
    try:
        seed = int(item.get("seed") or item.get("id") or 0)
    except Exception:
        seed = 0
    rng = random.Random(seed)
    raw = {}
    for key in STATS:
        raw[key] = max(min_floor, float(base.get(key, min_floor)) + rng.uniform(-0.08, 0.08))
    total = sum(raw.values())
    if total <= 0:
        return None
    return {f"w_{key}": raw[key] / total for key in STATS}


def _market_listing_stat_preview(item):
    try:
        weights = _market_listing_preview_weights(item)
        if not weights:
            return None
        payload = {
            "part_type": _norm_part_type(item.get("part_type")),
            "key": item.get("key") or item.get("part_key"),
            "series": item.get("series"),
            "rarity": str(item.get("rarity") or item.get("master_rarity") or "N").upper(),
            "element": str(item.get("element") or "NORMAL").upper(),
            "plus": int(item.get("plus") or 0),
            **weights,
        }
        stats = compute_part_stats(payload)
        focus_rows = _robot_focus_stat_rows(stats, limit=2)
        return {
            "part_type_label": _part_type_ui_label(item.get("part_type")),
            "rarity_label": str(payload["rarity"] or "N").upper(),
            "plus_label": f"+{int(payload['plus'])}",
            "total_value": int(_part_total_value(stats)),
            "focus_rows": focus_rows,
            "focus_line": " / ".join(f"{row['label']} {int(row['value'])}" for row in focus_rows),
            "stat_rows": _part_stat_rows(stats),
        }
    except Exception:
        app.logger.exception("market.listing_stat_preview_failed listing_id=%s", item.get("id"))
        return None


def _market_generate_listings_for_user(db, user_id, day_key, *, replace=False):
    now_ts = int(time.time())
    if replace:
        db.execute(
            "DELETE FROM market_daily_listings WHERE user_id = ? AND day_key = ?",
            (int(user_id), str(day_key)),
        )
    existing = {
        row["slot_key"]
        for row in db.execute(
            "SELECT slot_key FROM market_daily_listings WHERE user_id = ? AND day_key = ?",
            (int(user_id), str(day_key)),
        ).fetchall()
    }
    created = 0
    for slot_key in MARKET_SLOT_KEYS:
        if slot_key in existing:
            continue
        seed = int((time.time_ns() + random.randint(0, 999999)) % 2147483647)
        rng = random.Random(seed)
        part_row, rarity_roll = _market_pick_part_row(db, slot_key=slot_key, rng=rng)
        if not part_row:
            continue
        rarity = "R" if rarity_roll == "R" else "N"
        plus = 1 if rarity_roll == "N+1" else 0
        price = _market_listing_price(rarity_roll, rng)
        db.execute(
            """
            INSERT INTO market_daily_listings
            (user_id, day_key, slot_key, part_key, part_type, rarity, plus, price, seed, is_sold, created_at, updated_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, 0, ?, ?)
            ON CONFLICT(user_id, day_key, slot_key) DO UPDATE SET
                part_key = excluded.part_key,
                part_type = excluded.part_type,
                rarity = excluded.rarity,
                plus = excluded.plus,
                price = excluded.price,
                seed = excluded.seed,
                is_sold = 0,
                sold_to_user_id = NULL,
                sold_at = NULL,
                updated_at = excluded.updated_at
            """,
            (
                int(user_id),
                str(day_key),
                slot_key,
                part_row["key"],
                _norm_part_type(part_row["part_type"]),
                rarity,
                int(plus),
                int(price),
                int(seed),
                now_ts,
                now_ts,
            ),
        )
        created += 1
    if created > 0:
        try:
            audit_log(
                db,
                AUDIT_EVENT_TYPES["MARKET_DAILY_GENERATE"],
                user_id=int(user_id),
                request_id=getattr(g, "request_id", None) if has_request_context() else None,
                action_key="market_daily_generate",
                entity_type="market_daily_listings",
                delta_count=int(created),
                payload={"day_key": str(day_key), "replace": bool(replace), "created": int(created)},
                ip=request.remote_addr if has_request_context() else None,
            )
        except Exception:
            pass
    return created


def _market_user_state(db, user_id):
    row = db.execute(
        """
        SELECT
            id,
            username,
            is_admin,
            COALESCE(coins, 0) AS coins,
            COALESCE(part_inventory_limit, 60) AS part_inventory_limit,
            COALESCE(market_refresh_count_today, 0) AS market_refresh_count_today,
            market_free_refresh_used_at,
            market_refresh_day_key
        FROM users
        WHERE id = ?
        LIMIT 1
        """,
        (int(user_id),),
    ).fetchone()
    return dict(row) if row else None


def _market_reset_daily_state_if_needed(db, user_id, day_key):
    state = _market_user_state(db, user_id)
    if not state:
        return None
    if str(state.get("market_refresh_day_key") or "") != str(day_key):
        db.execute(
            """
            UPDATE users
            SET market_refresh_count_today = 0,
                market_free_refresh_used_at = NULL,
                market_refresh_day_key = ?
            WHERE id = ?
            """,
            (str(day_key), int(user_id)),
        )
        state["market_refresh_count_today"] = 0
        state["market_free_refresh_used_at"] = None
        state["market_refresh_day_key"] = str(day_key)
    return state


def _market_ensure_daily_listings(db, user_id):
    day_key = _market_day_key()
    _market_reset_daily_state_if_needed(db, user_id, day_key)
    count = int(
        db.execute(
            "SELECT COUNT(*) AS c FROM market_daily_listings WHERE user_id = ? AND day_key = ?",
            (int(user_id), day_key),
        ).fetchone()["c"]
        or 0
    )
    if count < len(MARKET_SLOT_KEYS):
        _market_generate_listings_for_user(db, user_id, day_key)
    return day_key


def _market_listing_rows(db, user_id, day_key):
    rows = db.execute(
        """
        SELECT
            ml.*,
            rp.id AS part_id,
            rp.key AS key,
            rp.image_path,
            rp.display_name_ja,
            rp.element,
            rp.series,
            COALESCE(rp.rarity, ml.rarity) AS master_rarity
        FROM market_daily_listings ml
        JOIN robot_parts rp ON rp.key = ml.part_key
        WHERE ml.user_id = ? AND ml.day_key = ?
        ORDER BY
            CASE ml.slot_key
              WHEN 'head' THEN 1
              WHEN 'right_arm' THEN 2
              WHEN 'left_arm' THEN 3
              WHEN 'legs' THEN 4
              WHEN 'free_1' THEN 5
              WHEN 'free_2' THEN 6
              ELSE 99
            END,
            ml.id ASC
        """,
        (int(user_id), str(day_key)),
    ).fetchall()
    items = []
    featured_id = None
    ranked = sorted(
        rows,
        key=lambda row: (
            0 if str(row["rarity"] or "").upper() == "R" else 1,
            0 if int(row["plus"] or 0) > 0 else 1,
            -int(row["price"] or 0),
            int(row["id"] or 0),
        ),
    )
    if ranked:
        featured_id = int(ranked[0]["id"])
    for row in rows:
        item = dict(row)
        item["slot_label"] = MARKET_PART_TYPE_LABELS.get(item["slot_key"], item["slot_key"])
        item["display_name"] = _part_display_name_ja(
            {
                "key": item["key"],
                "display_name_ja": item.get("display_name_ja"),
                "rarity": item.get("rarity"),
                "element": item.get("element"),
                "part_type": item.get("part_type"),
            }
        )
        item["image_url"] = url_for("static", filename=_part_image_rel(item), v=APP_VERSION)
        item["rarity_label"] = str(item.get("rarity") or "N").upper()
        item["plus_label"] = f"+{int(item.get('plus') or 0)}" if int(item.get("plus") or 0) > 0 else ""
        item["is_sold"] = bool(int(item.get("is_sold") or 0))
        item["stock_remaining"] = 0 if item["is_sold"] else 1
        item["helper_line"] = _market_part_helper_line(item)
        item["stat_preview"] = _market_listing_stat_preview(item)
        item["is_featured"] = featured_id is not None and int(item.get("id") or 0) == int(featured_id)
        items.append(item)
    return items


def _auto_sell_value(part_row):
    rarity = str(part_row["rarity"] or part_row["master_rarity"] or "N").strip().upper()
    return int(AUTO_SELL_PRICE_BY_RARITY.get(rarity, AUTO_SELL_PRICE_BY_RARITY["N"]))


def _market_sell_value(part_row):
    rarity = str(part_row["rarity"] or part_row["master_rarity"] or "N").strip().upper()
    base = MARKET_SELL_BASE_BY_RARITY.get(rarity, MARKET_SELL_BASE_BY_RARITY["N"])
    plus_bonus = max(0, int(part_row["plus"] or 0)) * MARKET_SELL_PLUS_BONUS if rarity == "N" else 0
    return int(base + plus_bonus)


def _market_sellable_part_rows(db, user_id, limit=80):
    rows = db.execute(
        """
        SELECT
            pi.*,
            rp.key,
            rp.image_path,
            rp.display_name_ja,
            COALESCE(rp.rarity, pi.rarity) AS master_rarity,
            COALESCE(rp.element, pi.element) AS master_element
        FROM part_instances pi
        JOIN robot_parts rp ON rp.id = pi.part_id
        WHERE pi.user_id = ? AND pi.status = 'inventory' AND COALESCE(pi.locked, 0) = 0
        ORDER BY
            CASE UPPER(COALESCE(pi.rarity, rp.rarity, 'N')) WHEN 'R' THEN 2 ELSE 1 END ASC,
            pi.plus ASC,
            pi.id ASC
        LIMIT ?
        """,
        (int(user_id), max(1, int(limit or 80))),
    ).fetchall()
    items = []
    for row in rows:
        item = _part_card_payload(row, can_discard=False)
        item["sell_value"] = _market_sell_value(row)
        items.append(item)
    return items


def _market_locked_inventory_part_count(db, user_id):
    row = db.execute(
        """
        SELECT COUNT(*) AS c
        FROM part_instances
        WHERE user_id = ?
          AND status = 'inventory'
          AND COALESCE(locked, 0) = 1
        """,
        (int(user_id),),
    ).fetchone()
    return int(row["c"] or 0) if row else 0


def cleanup_overflow_parts_to_coins(db, *, user_id=None, execute=False, request_id=None):
    params = []
    where = "pi.status = 'overflow'"
    if user_id is not None:
        where += " AND pi.user_id = ?"
        params.append(int(user_id))
    rows = db.execute(
        f"""
        SELECT
            pi.*,
            rp.key,
            rp.display_name_ja,
            rp.rarity AS master_rarity,
            rp.element AS master_element,
            rp.image_path
        FROM part_instances pi
        JOIN robot_parts rp ON rp.id = pi.part_id
        WHERE {where}
        ORDER BY pi.user_id ASC, pi.id ASC
        """,
        params,
    ).fetchall()
    by_user = {}
    for row in rows:
        uid = int(row["user_id"])
        by_user.setdefault(uid, {"sold_count": 0, "total_coins": 0, "part_instance_ids": []})
        value = int(_auto_sell_value(row))
        by_user[uid]["sold_count"] += 1
        by_user[uid]["total_coins"] += value
        by_user[uid]["part_instance_ids"].append(int(row["id"]))

    summary = {
        "execute": bool(execute),
        "user_count": len(by_user),
        "sold_count": sum(int(item["sold_count"]) for item in by_user.values()),
        "total_coins": sum(int(item["total_coins"]) for item in by_user.values()),
        "users": by_user,
    }
    if not execute or not rows:
        return summary

    for uid, payload in by_user.items():
        ids = payload["part_instance_ids"]
        if not ids:
            continue
        marks = ",".join("?" for _ in ids)
        before = int(db.execute("SELECT COALESCE(coins, 0) AS coins FROM users WHERE id = ?", (uid,)).fetchone()["coins"] or 0)
        db.execute(
            "UPDATE users SET coins = COALESCE(coins, 0) + ? WHERE id = ?",
            (int(payload["total_coins"]), uid),
        )
        db.execute(
            f"UPDATE part_instances SET status = 'sold', updated_at = datetime('now') WHERE user_id = ? AND status = 'overflow' AND id IN ({marks})",
            (uid, *ids),
        )
        audit_log(
            db,
            AUDIT_EVENT_TYPES["PART_OVERFLOW_CLEANUP_SELL"],
            user_id=uid,
            request_id=request_id,
            action_key="overflow_cleanup_sell",
            entity_type="part_instance",
            delta_coins=int(payload["total_coins"]),
            delta_count=int(payload["sold_count"]),
            payload={
                "sold_count": int(payload["sold_count"]),
                "total_coins": int(payload["total_coins"]),
                "part_instance_ids": ids[:500],
                "truncated_ids": max(0, len(ids) - 500),
                "reason": "market_release_cleanup",
                "coin_before": before,
                "coin_after": before + int(payload["total_coins"]),
            },
        )
    return summary


def _market_can_access(db, user_row):
    return _release_open_for_viewer(db, MARKET_FEATURE_KEY, user_row=user_row)


def can_access_market(user):
    if not user:
        return False
    return _market_can_access(get_db(), user)


def _market_require_access(db, user_row):
    if not _market_can_access(db, user_row):
        abort(404)


def _take_or_materialize_part_instance(db, user_id, part_key):
    # Prefer existing individual parts first.
    row = db.execute(
        """
        SELECT pi.id
        FROM part_instances pi
        JOIN robot_parts rp ON rp.id = pi.part_id
        WHERE pi.user_id = ? AND pi.status = 'inventory' AND rp.key = ?
        ORDER BY pi.plus DESC, pi.id ASC
        LIMIT 1
        """,
        (user_id, part_key),
    ).fetchone()
    if row:
        return row["id"]

    # Lazy migration from old inventory row.
    inv = db.execute(
        """
        SELECT id FROM user_parts_inventory
        WHERE user_id = ? AND part_key = ?
        ORDER BY obtained_at ASC, id ASC
        LIMIT 1
        """,
        (user_id, part_key),
    ).fetchone()
    if not inv:
        return None
    part = _get_part_by_key(db, part_key)
    if not part:
        return None
    if _inventory_space_remaining(db, user_id) <= 0:
        return None
    pi_id = _create_part_instance_from_master(db, user_id, part, plus=0, status="inventory")
    db.execute("DELETE FROM user_parts_inventory WHERE id = ?", (inv["id"],))
    return pi_id


def _equip_part_instances_on_robot(db, robot_instance_id, part_instance_ids):
    db.execute(
        """
        UPDATE robot_instance_parts
        SET head_part_instance_id = ?,
            r_arm_part_instance_id = ?,
            l_arm_part_instance_id = ?,
            legs_part_instance_id = ?
        WHERE robot_instance_id = ?
        """,
        (
            part_instance_ids["head"],
            part_instance_ids["r_arm"],
            part_instance_ids["l_arm"],
            part_instance_ids["legs"],
            robot_instance_id,
        ),
    )
    for pi_id in part_instance_ids.values():
        db.execute("UPDATE part_instances SET status = 'equipped' WHERE id = ?", (pi_id,))


def _clone_part_instance_for_user(db, source_part_instance_id, user_id, *, status="inventory"):
    source = db.execute(
        """
        SELECT *
        FROM part_instances
        WHERE id = ? AND user_id = ?
        """,
        (int(source_part_instance_id), int(user_id)),
    ).fetchone()
    if not source:
        return None
    status_key = str(status or "inventory").strip().lower()
    if status_key not in {"inventory", "equipped", "overflow", "sold"}:
        status_key = "inventory"
    cur = db.execute(
        """
        INSERT INTO part_instances
        (part_id, user_id, part_type, rarity, element, series, plus,
         w_hp, w_atk, w_def, w_spd, w_acc, w_cri, status, created_at, updated_at)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime('now'))
        """,
        (
            source["part_id"],
            int(user_id),
            _norm_part_type(source["part_type"]),
            source["rarity"],
            source["element"],
            source["series"],
            int(source["plus"] or 0),
            source["w_hp"],
            source["w_atk"],
            source["w_def"],
            source["w_spd"],
            source["w_acc"],
            source["w_cri"],
            status_key,
            int(time.time()),
        ),
    )
    return int(cur.lastrowid)


def _ensure_robot_instance_part_instances(db, robot_instance_id):
    row = db.execute(
        """
        SELECT *
        FROM robot_instance_parts
        WHERE robot_instance_id = ?
        """,
        (robot_instance_id,),
    ).fetchone()
    if not row:
        return None
    mapping = {
        "head": row["head_part_instance_id"] if "head_part_instance_id" in row.keys() else None,
        "r_arm": row["r_arm_part_instance_id"] if "r_arm_part_instance_id" in row.keys() else None,
        "l_arm": row["l_arm_part_instance_id"] if "l_arm_part_instance_id" in row.keys() else None,
        "legs": row["legs_part_instance_id"] if "legs_part_instance_id" in row.keys() else None,
    }
    user_id = db.execute(
        "SELECT user_id FROM robot_instances WHERE id = ?",
        (robot_instance_id,),
    ).fetchone()["user_id"]
    changed = False
    key_map = {
        "head": row["head_key"],
        "r_arm": row["r_arm_key"],
        "l_arm": row["l_arm_key"],
        "legs": row["legs_key"],
    }
    for slot, key in key_map.items():
        if mapping[slot]:
            continue
        part = _get_part_by_key(db, key)
        if not part:
            continue
        mapping[slot] = _create_part_instance_from_master(db, user_id, part, plus=0)
        db.execute("UPDATE part_instances SET status = 'equipped' WHERE id = ?", (mapping[slot],))
        changed = True
    if changed:
        db.execute(
            """
            UPDATE robot_instance_parts
            SET head_part_instance_id = ?,
                r_arm_part_instance_id = ?,
                l_arm_part_instance_id = ?,
                legs_part_instance_id = ?
            WHERE robot_instance_id = ?
            """,
            (mapping["head"], mapping["r_arm"], mapping["l_arm"], mapping["legs"], robot_instance_id),
        )
    return mapping


def _compute_robot_stats_for_instance(db, robot_instance_id):
    mapping = _ensure_robot_instance_part_instances(db, robot_instance_id)
    if not mapping or not all(mapping.values()):
        return None
    owner_row = db.execute(
        "SELECT user_id, COALESCE(is_mixed_frame, 0) AS is_mixed_frame FROM robot_instances WHERE id = ?",
        (int(robot_instance_id),),
    ).fetchone()
    series_progress_layer = _series_progress_layer_for_user(db, owner_row["user_id"]) if owner_row else 1
    series_bonus_defs = (
        _load_series_bonus_defs(db, active_only=True)
        if owner_row and _series_system_enabled_for_user(db, user_id=owner_row["user_id"])
        else {}
    )
    rows = db.execute(
        f"""
        SELECT pi.*, rp.part_type, rp.key
        FROM part_instances pi
        JOIN robot_parts rp ON rp.id = pi.part_id
        WHERE pi.id IN ({",".join(["?"] * 4)})
        """,
        [mapping["head"], mapping["r_arm"], mapping["l_arm"], mapping["legs"]],
    ).fetchall()
    if len(rows) != 4:
        return None
    by_type = {_norm_part_type(r["part_type"]): dict(r) for r in rows}
    if not all(t in by_type for t in ("HEAD", "RIGHT_ARM", "LEFT_ARM", "LEGS")):
        return None
    ordered = [by_type["HEAD"], by_type["RIGHT_ARM"], by_type["LEFT_ARM"], by_type["LEGS"]]
    calc = compute_robot_stats(
        ordered,
        series_bonus_defs=series_bonus_defs,
        series_progress_layer=series_progress_layer,
        disable_set_bonus=bool(int(owner_row["is_mixed_frame"] or 0)) if owner_row else False,
    )
    archetype = compute_archetype(ordered)
    computed_style = _robot_style_from_final_stats(calc["stats"])
    row = db.execute(
        "SELECT style_key FROM robot_instances WHERE id = ?",
        (int(robot_instance_id),),
    ).fetchone()
    stored_style_key = _normalize_style_key(row["style_key"] if row and "style_key" in row.keys() else None)
    if stored_style_key != computed_style["style_key"]:
        db.execute(
            "UPDATE robot_instances SET style_key = ? WHERE id = ?",
            (computed_style["style_key"], int(robot_instance_id)),
        )
    return {
        "stats": calc["stats"],
        "power": calc["power"],
        "set_bonus": calc["set_bonus"],
        "series_bonus": calc.get("series_bonus") or [],
        "series_counts": calc.get("series_counts") or {},
        "set_bonus_enabled": bool(calc.get("set_bonus_enabled", True)),
        "is_mixed_frame": bool(int(owner_row["is_mixed_frame"] or 0)) if owner_row else False,
        "series_progress_layer": int(series_progress_layer),
        "parts": ordered,
        "archetype": archetype,
        "robot_style": computed_style,
    }


def _robot_weekly_fit(db, robot_instance_id, weekly_element):
    if not weekly_element:
        return False
    row = db.execute(
        "SELECT head_key, r_arm_key, l_arm_key, legs_key FROM robot_instance_parts WHERE robot_instance_id = ?",
        (robot_instance_id,),
    ).fetchone()
    if not row:
        return False
    element = _build_element_from_keys(db, row["head_key"], row["r_arm_key"], row["l_arm_key"], row["legs_key"])
    return element == weekly_element


def _preview_part_payload_for_key(db, user_id, part_key):
    """Return an estimate payload for build preview without mutating inventory."""
    row = db.execute(
        """
        SELECT pi.*, rp.part_type, rp.key, rp.rarity AS master_rarity, rp.element AS master_element
        FROM part_instances pi
        JOIN robot_parts rp ON rp.id = pi.part_id
        WHERE pi.user_id = ? AND pi.status = 'inventory' AND rp.key = ?
        ORDER BY pi.plus DESC, pi.id ASC
        LIMIT 1
        """,
        (user_id, part_key),
    ).fetchone()
    if row:
        return dict(row)

    part = _get_part_by_key(db, part_key)
    if not part:
        return None
    weights = generate_noisy_weights(_norm_part_type(part["part_type"]), noise=0.0)
    return {
        "part_type": part["part_type"],
        "key": part["key"],
        "series": part["series"],
        "rarity": (part["rarity"] or "N").upper(),
        "element": (part["element"] or "NORMAL").upper(),
        "plus": 0,
        **weights,
    }


def _build_stat_comparison_rows(current_stats, candidate_stats):
    cur = dict(current_stats or {})
    cand = dict(candidate_stats or {})
    rows = []
    for key in ("hp", "atk", "def", "spd", "acc", "cri", "power"):
        label = _stat_label(key)
        current_val = float(cur.get(key) or 0.0)
        candidate_val = float(cand.get(key) or 0.0)
        delta = candidate_val - current_val
        if key != "power":
            current_show = int(round(current_val))
            candidate_show = int(round(candidate_val))
            delta_show = int(round(delta))
        else:
            current_show = round(current_val, 1)
            candidate_show = round(candidate_val, 1)
            delta_show = round(delta, 1)
        rows.append(
            {
                "key": key,
                "label": label,
                "current": current_show,
                "candidate": candidate_show,
                "delta": delta_show,
                "delta_text": (f"+{delta_show}" if delta_show > 0 else str(delta_show)),
            }
        )
    return rows


def _normalize_maintenance_slot(slot):
    value = str(slot or "").strip().upper()
    return value if value in ROBOT_MAINTENANCE_SLOT_DEF_BY_KEY else "HEAD"


