def _decorate_user_rows(db, rows, user_key="user_id"):
    cache = {}
    decorated = []
    for row in rows:
        item = dict(row)
        user_id = item.get(user_key)
        if user_id:
            visuals = _user_visuals(db, user_id, cache)
            item["avatar_path"] = visuals["avatar"]
            item["avatar_url"] = visuals.get("avatar_url")
            item["avatar_kind"] = visuals.get("avatar_kind", "seed")
            item["avatar_is_generated"] = bool(visuals.get("avatar_is_generated"))
            item["badge_path"] = visuals["badge"]
            item["display_username"] = visuals.get("display_username") or str(item.get("username") or "").strip()
            item["trophy_keys"] = list(visuals.get("trophy_keys") or [])
            item["trophy_badges"] = list(visuals.get("trophy_badges") or [])
            item["presence_state"] = visuals["presence_state"]
            item["presence_label"] = visuals["presence_label"]
            item["presence_title"] = visuals["presence_title"]
        else:
            presence = _user_presence_snapshot(0)
            item["avatar_path"] = DEFAULT_AVATAR_REL
            item["avatar_url"] = None
            item["avatar_kind"] = "seed"
            item["avatar_is_generated"] = True
            item["badge_path"] = DEFAULT_BADGE_REL
            item["display_username"] = str(item.get("username") or "SYSTEM").strip() or "SYSTEM"
            item["trophy_keys"] = []
            item["trophy_badges"] = []
            item["presence_state"] = presence["state"]
            item["presence_label"] = presence["label"]
            item["presence_title"] = presence["title"]
        decorated.append(item)
    return decorated


def _get_part_by_key(db, key):
    return db.execute("SELECT * FROM robot_parts WHERE key = ?", (key,)).fetchone()


def _today_progress(db, user_id):
    start_ts, end_ts = _jst_day_bounds()
    explore_count = db.execute(
        """
        SELECT COUNT(*) AS c
        FROM world_events_log
        WHERE user_id = ?
          AND event_type = ?
          AND created_at >= ? AND created_at < ?
        """,
        (user_id, AUDIT_EVENT_TYPES["EXPLORE_END"], start_ts, end_ts),
    ).fetchone()["c"]
    win_count = db.execute(
        """
        SELECT COALESCE(SUM(CASE WHEN CAST(json_extract(payload_json, '$.result.win') AS INTEGER) = 1 THEN 1 ELSE 0 END), 0) AS c
        FROM world_events_log
        WHERE user_id = ?
          AND event_type = ?
          AND created_at >= ? AND created_at < ?
        """,
        (user_id, AUDIT_EVENT_TYPES["EXPLORE_END"], start_ts, end_ts),
    ).fetchone()["c"]
    coins = db.execute(
        """
        SELECT COALESCE(SUM(COALESCE(delta_coins, CAST(json_extract(payload_json, '$.reward_coin') AS INTEGER), 0)), 0) AS c
        FROM world_events_log
        WHERE user_id = ?
          AND event_type = ?
          AND (
                action_key = 'explore'
                OR CAST(json_extract(payload_json, '$.area_key') AS TEXT) IS NOT NULL
              )
          AND created_at >= ? AND created_at < ?
        """,
        (user_id, AUDIT_EVENT_TYPES["COIN_DELTA"], start_ts, end_ts),
    ).fetchone()["c"]
    part_drop_count = db.execute(
        """
        SELECT COUNT(*) AS c
        FROM world_events_log
        WHERE user_id = ?
          AND event_type = ?
          AND created_at >= ? AND created_at < ?
        """,
        (user_id, AUDIT_EVENT_TYPES["DROP"], start_ts, end_ts),
    ).fetchone()["c"]
    boss_defeat_count = db.execute(
        """
        SELECT COUNT(*) AS c
        FROM world_events_log
        WHERE user_id = ?
          AND event_type = ?
          AND created_at >= ? AND created_at < ?
        """,
        (user_id, AUDIT_EVENT_TYPES["BOSS_DEFEAT"], start_ts, end_ts),
    ).fetchone()["c"]
    evolve_count = db.execute(
        """
        SELECT COUNT(*) AS c
        FROM world_events_log
        WHERE user_id = ?
          AND event_type = ?
          AND created_at >= ? AND created_at < ?
        """,
        (user_id, AUDIT_EVENT_TYPES["PART_EVOLVE"], start_ts, end_ts),
    ).fetchone()["c"]
    fuse_count = db.execute(
        """
        SELECT COUNT(*) AS c
        FROM world_events_log
        WHERE user_id = ?
          AND event_type = ?
          AND created_at >= ? AND created_at < ?
        """,
        (user_id, AUDIT_EVENT_TYPES["FUSE"], start_ts, end_ts),
    ).fetchone()["c"]
    power_gain = db.execute(
        """
        SELECT COALESCE(SUM(COALESCE(
            CAST(json_extract(payload_json, '$.power_delta_estimate') AS INTEGER),
            CAST(json_extract(payload_json, '$.power_delta') AS INTEGER),
            0
        )), 0) AS c
        FROM world_events_log
        WHERE user_id = ?
          AND event_type IN (?, ?, ?)
          AND created_at >= ? AND created_at < ?
        """,
        (
            user_id,
            AUDIT_EVENT_TYPES["FUSE"],
            AUDIT_EVENT_TYPES["PART_EVOLVE"],
            AUDIT_EVENT_TYPES["ROBOT_MAINTENANCE"],
            start_ts,
            end_ts,
        ),
    ).fetchone()["c"]
    progress = {
        "explore_count": int(explore_count or 0),
        "win_count": int(win_count or 0),
        "coin_total": int(coins or 0),
        "part_drop_count": int(part_drop_count or 0),
        "power_gain": int(power_gain or 0),
        "boss_defeat_count": int(boss_defeat_count or 0),
        "evolve_count": int(evolve_count or 0),
        "fuse_count": int(fuse_count or 0),
    }
    progress["is_empty"] = not any(
        int(progress.get(key) or 0)
        for key in ("explore_count", "win_count", "coin_total", "part_drop_count", "power_gain", "boss_defeat_count", "evolve_count", "fuse_count")
    )
    progress["power_gain_text"] = f"{progress['power_gain']:+d}"
    return progress


def _home_boss_pity_status(db, user_id):
    rows = db.execute(
        """
        SELECT area_key, no_boss_streak
        FROM user_boss_progress
        WHERE user_id = ?
        """,
        (user_id,),
    ).fetchall()
    by_area = {row["area_key"]: int(row["no_boss_streak"] or 0) for row in rows}
    out = []
    for area_key in AREA_BOSS_KEYS:
        if area_key in SPECIAL_EXPLORE_AREA_KEYS:
            continue
        pity = int(AREA_BOSS_PITY_MISSES.get(area_key, 15))
        streak = int(by_area.get(area_key, 0))
        out.append(
            {
                "area_key": area_key,
                "area_label": _boss_area_label(area_key),
                "streak": streak,
                "pity": pity,
                "remain": max(0, pity - streak),
            }
        )
    return out


def _home_boss_alert_status(db, user_id, now_ts=None):
    ts = int(time.time()) if now_ts is None else int(now_ts)
    out = []
    for area_key in AREA_BOSS_ALERT_AREAS:
        alert = _get_active_boss_alert(db, user_id, area_key, now_ts=ts)
        if not alert:
            continue
        layer_no = _area_layer(area_key)
        remain_sec = max(0, int(alert["expires_at"]) - ts)
        enemy_meta = _boss_type_meta(alert.get("enemy"))
        rec = _boss_recommendation_for_type(enemy_meta["code"] if enemy_meta else None)
        out.append(
            {
                "area_key": area_key,
                "area_label": _boss_area_label(area_key),
                "layer_no": int(layer_no),
                "layer_label": _layer_label(layer_no),
                "enemy_name": alert["enemy"]["name_ja"] if alert.get("enemy") else "エリアボス",
                "attempts_left": int(alert["attempts_left"]),
                "attempts_max": int(AREA_BOSS_ALERT_ATTEMPTS),
                "expires_at": int(alert["expires_at"]),
                "remain_minutes": int(math.ceil(remain_sec / 60.0)),
                "boss_type": (enemy_meta["code"] if enemy_meta else None),
                "boss_type_label": (enemy_meta["label_ja"] if enemy_meta else None),
                "boss_type_recommend": (enemy_meta["recommend_build"] if enemy_meta else None),
                "boss_type_icon": (enemy_meta["icon"] if enemy_meta else ""),
                "recommended_build": (rec["build"] if rec else None),
                "recommended_text": (rec["text"] if rec else None),
            }
        )
    return out


def _boss_alert_recommendation_context(boss_alert_status):
    if not boss_alert_status:
        return {
            "boss_alert_active": False,
            "boss_type": None,
            "recommended_build": None,
            "recommended_text": None,
        }
    first = boss_alert_status[0]
    return {
        "boss_alert_active": True,
        "boss_type": first.get("boss_type"),
        "recommended_build": first.get("recommended_build"),
        "recommended_text": first.get("recommended_text"),
    }


def _boss_goal_hint(db, user_id, *, boss_alert_status=None, max_unlocked_layer=1):
    if boss_alert_status:
        return ""
    if not _has_fixed_boss_defeat_in_area(db, int(user_id), "layer_1"):
        return "目標：第1層ボスを撃破する。第1層を出撃していると低確率でボス警報が出ます。"
    if int(max_unlocked_layer or 1) >= 2:
        return "第N層は前の層のボス撃破で解放されます。"
    return "出撃中にボス警報が発生することがあります。ボス撃破で次の層が解放されます。"


def _boss_unlock_guide_lines(db, user_row, *, compact=False):
    max_layer = _visible_user_max_unlocked_layer(user_row, db=db)
    release_cap = _release_layer_cap_for_viewer(db, user_row=user_row) if db and user_row else MAX_UNLOCKABLE_LAYER
    user_id = int(user_row["id"]) if user_row and "id" in user_row.keys() and user_row["id"] is not None else 0
    lines = []
    if user_id > 0 and not _has_fixed_boss_defeat_in_area(db, user_id, "layer_1"):
        lines.append("第1層ボス：第1層を出撃していると低確率で警報")
    else:
        lines.append(f"現在：第{max_layer}層まで解放済み")
    next_layer = max_layer + 1
    if next_layer <= min(MAX_UNLOCKABLE_LAYER, release_cap):
        lines.append(f"第{next_layer}層：第{next_layer - 1}層ボス撃破で解放")
    elif (
        release_cap >= 4
        and max_layer >= 4
        and user_id > 0
        and not _is_special_area_unlocked(db, user_id, LAYER4_FINAL_AREA_KEY)
    ):
        lines.append("第4層最終試験：3ボス撃破で解放")
    elif (
        release_cap >= 5
        and max_layer >= 5
        and user_id > 0
        and not _is_special_area_unlocked(db, user_id, LAYER5_FINAL_AREA_KEY)
    ):
        lines.append("第5層最終試験：2ボス撃破で解放")
    lines.append("ボス撃破で次の層や特別報酬につながります")
    return lines[:2] if compact else lines


def _has_any_active_boss_alert(db, user_id, now_ts=None):
    return len(_home_boss_alert_status(db, user_id, now_ts=now_ts)) > 0


def _home_fuse_ready(db, user_id):
    return get_strengthen_candidate_count(db, user_id) > 0


def get_max_part_plus_for_user(rarity: str, max_unlocked_layer: int) -> int:
    rarity_key = str(rarity or "N").strip().upper()
    try:
        layer = int(max_unlocked_layer or 1)
    except Exception:
        layer = 1
    if rarity_key == "R" and layer >= R_PART_PLUS_CAP_UNLOCK_LAYER:
        return R_PART_PLUS_CAP_AFTER_LAYER4
    return 5


def _get_user_max_unlocked_layer(db, user_id):
    row = db.execute("SELECT max_unlocked_layer FROM users WHERE id = ?", (int(user_id),)).fetchone()
    if not row:
        return 1
    try:
        return int(row["max_unlocked_layer"] or 1)
    except Exception:
        return 1


def _part_plus_cap_for_row(row, max_unlocked_layer):
    getter = row.get if hasattr(row, "get") else lambda key, default=None: row[key] if key in row.keys() else default
    return get_max_part_plus_for_user(getter("rarity", "N"), max_unlocked_layer)


def get_strengthen_candidate_count(db, user_id):
    max_unlocked_layer = _get_user_max_unlocked_layer(db, user_id)
    rows = db.execute(
        """
        SELECT
            rp.key,
            UPPER(COALESCE(pi.rarity, rp.rarity, 'N')) AS rarity,
            COUNT(*) AS qty_total,
            SUM(CASE WHEN pi.status = 'inventory' AND COALESCE(pi.locked, 0) = 0 THEN 1 ELSE 0 END) AS qty_inventory
        FROM part_instances pi
        JOIN robot_parts rp ON rp.id = pi.part_id
        WHERE pi.user_id = ?
          AND pi.status IN ('inventory', 'equipped')
        GROUP BY rp.key, UPPER(COALESCE(pi.rarity, rp.rarity, 'N'))
        HAVING COUNT(*) >= 3
           AND SUM(CASE WHEN pi.status = 'inventory' AND COALESCE(pi.locked, 0) = 0 THEN 1 ELSE 0 END) >= 2
        """,
        (int(user_id),),
    ).fetchall()
    count = 0
    for row in rows:
        cap = get_max_part_plus_for_user(row["rarity"], max_unlocked_layer)
        under_cap = db.execute(
            """
            SELECT 1
            FROM part_instances pi
            JOIN robot_parts rp ON rp.id = pi.part_id
            WHERE pi.user_id = ?
              AND pi.status IN ('inventory', 'equipped')
              AND rp.key = ?
              AND UPPER(COALESCE(pi.rarity, rp.rarity, 'N')) = ?
              AND COALESCE(pi.plus, 0) < ?
            LIMIT 1
            """,
            (int(user_id), row["key"], row["rarity"], int(cap)),
        ).fetchone()
        if under_cap:
            count += 1
    return count


def _home_build_ready(db, user_id):
    rows = db.execute(
        """
        SELECT rp.part_type
        FROM part_instances pi
        JOIN robot_parts rp ON rp.id = pi.part_id
        WHERE pi.user_id = ? AND pi.status = 'inventory' AND rp.is_active = 1
        GROUP BY rp.part_type
        """,
        (int(user_id),),
    ).fetchall()
    owned_types = {str(r["part_type"] or "").upper() for r in rows}
    return {"HEAD", "RIGHT_ARM", "LEFT_ARM", "LEGS"}.issubset(owned_types)


def _home_recent_unlocked_layer(db, user_id, now_ts=None):
    ts = int(time.time()) if now_ts is None else int(now_ts)
    since = ts - max(60, int(HOME_UNLOCK_RECENT_SECONDS))
    row = db.execute(
        """
        SELECT CAST(json_extract(payload_json, '$.unlocked_layer') AS INTEGER) AS unlocked_layer
        FROM world_events_log
        WHERE user_id = ?
          AND event_type = ?
          AND created_at >= ?
          AND CAST(json_extract(payload_json, '$.unlocked_layer') AS INTEGER) IS NOT NULL
        ORDER BY id DESC
        LIMIT 1
        """,
        (user_id, AUDIT_EVENT_TYPES["BOSS_DEFEAT"], since),
    ).fetchone()
    if not row:
        return None
    v = int(row["unlocked_layer"] or 0)
    return v if 1 <= v <= MAX_UNLOCKABLE_LAYER else None


def _has_fixed_boss_defeat_in_area(db, user_id, area_key):
    row = db.execute(
        """
        SELECT 1
        FROM world_events_log
        WHERE user_id = ?
          AND event_type = ?
          AND COALESCE(json_extract(payload_json, '$.area_key'), '') = ?
          AND COALESCE(json_extract(payload_json, '$.boss_kind'), 'fixed') = 'fixed'
        ORDER BY id DESC
        LIMIT 1
        """,
        (int(user_id), AUDIT_EVENT_TYPES["BOSS_DEFEAT"], str(area_key or "")),
    ).fetchone()
    return bool(row)


def _evolution_feature_unlocked(db, user=None, *, user_id=None, is_admin=None, max_unlocked_layer=None):
    if user is not None:
        if user_id is None:
            user_id = int(user["id"])
        if is_admin is None:
            is_admin = bool(int(user["is_admin"] or 0)) if "is_admin" in user.keys() else False
        if max_unlocked_layer is None:
            max_unlocked_layer = int(user["max_unlocked_layer"] or 1) if "max_unlocked_layer" in user.keys() else 1
    if user_id is None:
        return False
    if bool(is_admin):
        return True
    if int(max_unlocked_layer or 0) >= 3:
        return True
    return _has_fixed_boss_defeat_in_area(db, user_id, "layer_2")


def _normalize_faction_key(faction):
    v = str(faction or "").strip().lower()
    return v if v in FACTION_KEYS else None


def _new_invite_code():
    return uuid.uuid4().hex[:8].upper()


def _ensure_user_invite_code(db, user_id):
    uid = int(user_id)
    row = db.execute("SELECT invite_code FROM users WHERE id = ?", (uid,)).fetchone()
    if not row:
        return None
    current = (row["invite_code"] or "").strip() if "invite_code" in row.keys() else ""
    if current:
        return current
    for _ in range(12):
        code = _new_invite_code()
        try:
            db.execute("UPDATE users SET invite_code = ? WHERE id = ? AND (invite_code IS NULL OR invite_code = '')", (code, uid))
            return code
        except sqlite3.IntegrityError:
            continue
    return None


def _public_game_root_url():
    if PUBLIC_GAME_URL:
        return PUBLIC_GAME_URL.rstrip("/")
    if has_request_context():
        return request.url_root.rstrip("/")
    return "https://example.com"


def _absolute_public_url(path_or_url):
    text = str(path_or_url or "").strip()
    if not text:
        return _public_game_root_url()
    if text.startswith("http://") or text.startswith("https://"):
        return text
    if not text.startswith("/"):
        text = "/" + text
    return _public_game_root_url().rstrip("/") + text


def _google_oauth_client_id():
    return (os.getenv("GOOGLE_OAUTH_CLIENT_ID") or "").strip()


def _google_oauth_client_secret():
    return (os.getenv("GOOGLE_OAUTH_CLIENT_SECRET") or "").strip()


def _google_oauth_enabled():
    return bool(_google_oauth_client_id() and _google_oauth_client_secret())


def _google_oauth_redirect_uri():
    explicit = (os.getenv("GOOGLE_OAUTH_REDIRECT_URI") or "").strip()
    if explicit:
        return explicit
    if has_request_context():
        return f"{_public_game_root_url()}{url_for('google_oauth_callback')}"
    return ""


def _google_oauth_discovery_doc(force=False):
    now = time.time()
    cached = _google_oauth_discovery_cache.get("data")
    loaded_at = float(_google_oauth_discovery_cache.get("loaded_at") or 0.0)
    if cached and not force and (now - loaded_at) < 3600:
        return cached
    req = Request(
        GOOGLE_OAUTH_DISCOVERY_URL,
        headers={
            "Accept": "application/json",
            "User-Agent": f"robolabo/{APP_VERSION}",
        },
        method="GET",
    )
    with urlopen(req, timeout=8.0) as resp:
        payload = json.loads(resp.read().decode("utf-8"))
    if not isinstance(payload, dict):
        raise ValueError("google_oauth_discovery_invalid")
    _google_oauth_discovery_cache["loaded_at"] = now
    _google_oauth_discovery_cache["data"] = payload
    return payload


def _google_oauth_authorize_url(*, state, nonce):
    discovery = _google_oauth_discovery_doc()
    auth_endpoint = (
        str(discovery.get("authorization_endpoint") or "").strip()
        or "https://accounts.google.com/o/oauth2/v2/auth"
    )
    query = urlencode(
        {
            "client_id": _google_oauth_client_id(),
            "redirect_uri": _google_oauth_redirect_uri(),
            "response_type": "code",
            "scope": GOOGLE_OAUTH_SCOPE,
            "state": state,
            "nonce": nonce,
            "access_type": "online",
            "include_granted_scopes": "true",
            "prompt": "select_account",
        }
    )
    return f"{auth_endpoint}?{query}"


def _google_oauth_exchange_code(code):
    discovery = _google_oauth_discovery_doc()
    token_endpoint = (
        str(discovery.get("token_endpoint") or "").strip()
        or "https://oauth2.googleapis.com/token"
    )
    payload = urlencode(
        {
            "code": code,
            "client_id": _google_oauth_client_id(),
            "client_secret": _google_oauth_client_secret(),
            "redirect_uri": _google_oauth_redirect_uri(),
            "grant_type": "authorization_code",
        }
    ).encode("utf-8")
    req = Request(
        token_endpoint,
        data=payload,
        headers={
            "Accept": "application/json",
            "Content-Type": "application/x-www-form-urlencoded",
            "User-Agent": f"robolabo/{APP_VERSION}",
        },
        method="POST",
    )
    with urlopen(req, timeout=8.0) as resp:
        token_payload = json.loads(resp.read().decode("utf-8"))
    return token_payload if isinstance(token_payload, dict) else {}


def _google_oauth_fetch_userinfo(access_token):
    discovery = _google_oauth_discovery_doc()
    userinfo_endpoint = (
        str(discovery.get("userinfo_endpoint") or "").strip()
        or "https://openidconnect.googleapis.com/v1/userinfo"
    )
    req = Request(
        userinfo_endpoint,
        headers={
            "Accept": "application/json",
            "Authorization": f"Bearer {access_token}",
            "User-Agent": f"robolabo/{APP_VERSION}",
        },
        method="GET",
    )
    with urlopen(req, timeout=8.0) as resp:
        profile = json.loads(resp.read().decode("utf-8"))
    return profile if isinstance(profile, dict) else {}


def _oauth_safe_next_path(next_path):
    text = str(next_path or "").strip()
    if text.startswith("/") and not text.startswith("//"):
        return text
    return ""


def _social_username_seed(*values):
    for value in values:
        text = str(value or "").strip()
        if not text:
            continue
        seed = re.sub(r"[^0-9A-Za-z_-]+", "", text)
        seed = seed.strip("_-")
        if seed:
            return seed[:24]
    return "pilot"


def _build_unique_social_username(db, *seed_values):
    base = _social_username_seed(*seed_values)
    if _is_main_admin_username(base):
        base = "pilot"
    candidate = base
    suffix = 1
    while _find_user_for_login(db, candidate):
        trimmed = base[: max(8, 24 - len(str(suffix)) - 1)]
        candidate = f"{trimmed}_{suffix}"
        suffix += 1
    return candidate


def _build_unique_anonymous_google_username(db):
    rng = random.SystemRandom()
    for _attempt in range(100):
        candidate = f"robo_{rng.randint(1000, 9999)}"
        if not _find_user_for_login(db, candidate):
            return candidate
    return _build_unique_social_username(db, f"robo_{uuid.uuid4().hex[:8]}", "google")


def _google_default_display_name():
    return f"研究員{random.SystemRandom().randint(1000, 9999)}"


def _find_user_identity(db, provider, provider_user_id):
    provider_value = str(provider or "").strip().lower()
    sub_value = str(provider_user_id or "").strip()
    if not provider_value or not sub_value:
        return None
    return db.execute(
        """
        SELECT *
        FROM user_auth_identities
        WHERE provider = ? AND provider_user_id = ?
        LIMIT 1
        """,
        (provider_value, sub_value),
    ).fetchone()


def _upsert_user_identity(db, *, user_id, provider, provider_user_id, email=None, display_name=None, avatar_url=None):
    now_ts = int(time.time())
    existing = _find_user_identity(db, provider, provider_user_id)
    if existing:
        db.execute(
            """
            UPDATE user_auth_identities
            SET user_id = ?, email = ?, display_name = ?, avatar_url = ?, updated_at = ?
            WHERE id = ?
            """,
            (
                int(user_id),
                (str(email or "").strip() or None),
                (str(display_name or "").strip() or None),
                (str(avatar_url or "").strip() or None),
                now_ts,
                int(existing["id"]),
            ),
        )
        return int(existing["id"])
    cur = db.execute(
        """
        INSERT INTO user_auth_identities (
            user_id,
            provider,
            provider_user_id,
            email,
            display_name,
            avatar_url,
            created_at,
            updated_at
        )
        VALUES (?, ?, ?, ?, ?, ?, ?, ?)
        """,
        (
            int(user_id),
            str(provider or "").strip().lower(),
            str(provider_user_id or "").strip(),
            (str(email or "").strip() or None),
            (str(display_name or "").strip() or None),
            (str(avatar_url or "").strip() or None),
            now_ts,
            now_ts,
        ),
    )
    return int(cur.lastrowid)


