def _load_stripe_api():
    global stripe, _stripe_api_module, _stripe_api_import_error
    if stripe is not None:
        return stripe
    if _stripe_api_module is not None:
        return _stripe_api_module
    if _stripe_api_import_error is not None:
        raise RuntimeError("Stripe SDK の読み込みに失敗しました。") from _stripe_api_import_error
    try:
        _stripe_api_module = import_module("stripe")
        return _stripe_api_module
    except ModuleNotFoundError as exc:
        _stripe_api_import_error = exc
        raise RuntimeError("Stripe SDK が未インストールです。") from exc
    except Exception as exc:
        _stripe_api_import_error = exc
        raise RuntimeError("Stripe SDK の初期化に失敗しました。") from exc


def _configure_stripe_api():
    stripe_api = _load_stripe_api()
    if not STRIPE_SECRET_KEY:
        raise RuntimeError("STRIPE_SECRET_KEY が未設定です。")
    stripe_api.api_key = STRIPE_SECRET_KEY
    return stripe_api


def _stripe_value(obj, key, default=None):
    if obj is None:
        return default
    if isinstance(obj, dict):
        return obj.get(key, default)
    return getattr(obj, key, default)


def _get_decor_asset_by_key(db, decor_key):
    key = str(decor_key or "").strip()
    if not key:
        return None
    return db.execute("SELECT * FROM robot_decor_assets WHERE key = ?", (key,)).fetchone()


def _user_has_decor_key(db, user_id, decor_key):
    decor = _get_decor_asset_by_key(db, decor_key)
    if not decor:
        return False
    row = db.execute(
        """
        SELECT 1
        FROM user_decor_inventory
        WHERE user_id = ? AND decor_asset_id = ?
        LIMIT 1
        """,
        (int(user_id), int(decor["id"])),
    ).fetchone()
    return bool(row)


def _user_has_any_decor_key(db, user_id, decor_keys):
    for decor_key in decor_keys or ():
        key = str(decor_key or "").strip()
        if key and _user_has_decor_key(db, user_id, key):
            return True
    return False


def _trophy_definition(trophy_key):
    key = str(trophy_key or "").strip()
    return USER_TROPHY_DEFS.get(key)


def _sorted_trophy_keys(keys):
    unique_keys = []
    seen = set()
    for trophy_key in keys or ():
        key = str(trophy_key or "").strip()
        if not key or key in seen or key not in USER_TROPHY_DEFS:
            continue
        seen.add(key)
        unique_keys.append(key)
    unique_keys.sort(
        key=lambda key: (
            int(USER_TROPHY_DEFS.get(key, {}).get("sort_order", 9999)),
            str(USER_TROPHY_DEFS.get(key, {}).get("label") or key),
            key,
        )
    )
    return unique_keys


def _trophy_badges_for_keys(keys):
    badges = []
    for trophy_key in _sorted_trophy_keys(keys):
        definition = _trophy_definition(trophy_key) or {}
        label = str(definition.get("label") or trophy_key)
        description = str(definition.get("description") or "").strip()
        badges.append(
            {
                "key": trophy_key,
                "label": label,
                "short_label": str(definition.get("short_label") or label).strip() or label,
                "description": description,
                "title": (f"{label} | {description}" if description else label),
            }
        )
    return badges


def _render_user_trophy_badges_markup(item, *, compact=True, max_items=1):
    badges = list((item or {}).get("trophy_badges") or [])
    if not badges:
        return Markup("")
    limit = max(0, int(max_items or 0))
    shown = badges if limit <= 0 else badges[:limit]
    compact_class = " is-compact" if compact else ""
    parts = [f'<span class="user-trophy-list{compact_class}">']
    for badge in shown:
        badge_key = escape(str(badge.get("key") or "unknown"))
        title = escape(str(badge.get("title") or badge.get("label") or badge_key))
        label = str(badge.get("short_label") if compact else badge.get("label") or badge_key).strip() or str(badge_key)
        parts.append(
            f'<span class="user-trophy-badge trophy-{badge_key}" title="{title}">{escape(label)}</span>'
        )
    if limit > 0 and len(badges) > limit:
        more_count = len(badges) - limit
        parts.append(
            f'<span class="user-trophy-badge is-more" title="ほか {more_count} 件">+{more_count}</span>'
        )
    parts.append("</span>")
    return Markup("".join(parts))


def _render_user_name_badged_markup(item, text=None, *, outer_class="user-signal-name", compact=True, max_items=1):
    item = item or {}
    label = (
        text
        or item.get("display_username")
        or item.get("username")
        or item.get("user_label")
        or "SYSTEM"
    )
    class_name = str(outer_class or "user-signal-name").strip() or "user-signal-name"
    classes = f"{class_name} user-name-with-badges"
    if compact:
        classes = f"{classes} is-compact"
    badges_markup = _render_user_trophy_badges_markup(item, compact=compact, max_items=max_items)
    return Markup(
        f'<span class="{escape(classes)}">'
        f'<span class="user-name-text">{escape(str(label))}</span>'
        f"{badges_markup}"
        f"</span>"
    )


def _get_user_trophy_keys(db, user_id):
    if not user_id:
        return []
    rows = db.execute(
        """
        SELECT trophy_key
        FROM user_trophies
        WHERE user_id = ?
        ORDER BY granted_at ASC, trophy_key ASC
        """,
        (int(user_id),),
    ).fetchall()
    return _sorted_trophy_keys(row["trophy_key"] for row in rows)


def _user_has_trophy_key(db, user_id, trophy_key):
    key = str(trophy_key or "").strip()
    if not user_id or not key:
        return False
    row = db.execute(
        """
        SELECT 1
        FROM user_trophies
        WHERE user_id = ? AND trophy_key = ?
        LIMIT 1
        """,
        (int(user_id), key),
    ).fetchone()
    return bool(row)


def _grant_user_trophy(db, user_id, trophy_key):
    key = str(trophy_key or "").strip()
    if not key or not _trophy_definition(key):
        return {"ok": False, "granted": False, "duplicate_reason": "missing_trophy_definition", "trophy_key": key}
    inserted = db.execute(
        """
        INSERT OR IGNORE INTO user_trophies (user_id, trophy_key, granted_at)
        VALUES (?, ?, ?)
        """,
        (int(user_id), key, _now_ts()),
    ).rowcount > 0
    return {
        "ok": True,
        "granted": bool(inserted),
        "duplicate_reason": (None if inserted else "already_owned_trophy"),
        "trophy_key": key,
        "trophy_badge": (_trophy_badges_for_keys([key])[0] if _trophy_definition(key) else None),
    }


