def _lab_small_boost_day_key(now_ts=None):
    now = _now_ts() if now_ts is None else int(now_ts)
    return _jst_day_key_from_ts(now)


def _lab_small_boost_source_key(raw_source):
    source = str(raw_source or "").strip().lower()
    return source if source in LAB_SMALL_BOOST_SOURCE_LABELS else ""


def _lab_small_boost_grant_already_logged(db, *, user_id, source, day_key):
    start_ts, end_ts = _jst_day_key_to_bounds(day_key)
    rows = db.execute(
        """
        SELECT payload_json
        FROM world_events_log
        WHERE user_id = ?
          AND event_type IN (?, ?)
          AND created_at >= ?
          AND created_at < ?
        """,
        (
            int(user_id),
            AUDIT_EVENT_TYPES["RESEARCH_BOOST_GRANT"],
            AUDIT_EVENT_TYPES["LAB_SMALL_BOOST_GRANT"],
            int(start_ts),
            int(end_ts),
        ),
    ).fetchall()
    for row in rows:
        try:
            payload = json.loads(row["payload_json"] or "{}")
        except Exception:
            payload = {}
        if (payload.get("source") == source or payload.get("reason") == source) and payload.get("day_key") == day_key:
            return True
    return False


def _lab_small_boost_source_received_today(db, *, user_id, source, now_ts=None):
    source_key = _lab_small_boost_source_key(source)
    if not source_key:
        return False
    day_key = _lab_small_boost_day_key(now_ts)
    return _lab_small_boost_grant_already_logged(
        db,
        user_id=int(user_id),
        source=source_key,
        day_key=day_key,
    )


def _grant_lab_small_boost_if_available(db, user_id, source, *, user_row=None, now_ts=None):
    source_key = _lab_small_boost_source_key(source)
    if not source_key:
        return {"handled": False, "granted": False, "message": ""}
    if not _lab_small_boost_feature_open(db, user_row=user_row, user_id=int(user_id)):
        return {"handled": False, "granted": False, "message": ""}
    now = _now_ts() if now_ts is None else int(now_ts)
    day_key = _lab_small_boost_day_key(now)
    if _lab_small_boost_grant_already_logged(db, user_id=int(user_id), source=source_key, day_key=day_key):
        return {"handled": False, "granted": False, "already_received": True, "message": ""}
    if user_row is None or "research_boost_charges" not in user_row.keys():
        user_row = db.execute(
            """
            SELECT id, is_admin, research_boost_charges, lab_small_boost_count, lab_small_boost_until
            FROM users
            WHERE id = ?
            """,
            (int(user_id),),
        ).fetchone()
    if not user_row:
        return {"handled": False, "granted": False, "message": ""}
    before_count = _lab_small_boost_count(user_row)
    grant_amount = 1 if before_count < int(RESEARCH_BOOST_MAX_CHARGES) else 0
    after_count = min(int(RESEARCH_BOOST_MAX_CHARGES), before_count + grant_amount)
    if _research_boost_charges(user_row) != after_count:
        db.execute(
            "UPDATE users SET research_boost_charges = ? WHERE id = ?",
            (int(after_count), int(user_id)),
        )
    message = (
        f"研究ブーストを1回分獲得しました（{after_count}/{RESEARCH_BOOST_MAX_CHARGES}）"
        if grant_amount > 0
        else f"研究ブーストは上限です（{RESEARCH_BOOST_MAX_CHARGES}/{RESEARCH_BOOST_MAX_CHARGES}）"
    )
    audit_log(
        db,
        AUDIT_EVENT_TYPES["RESEARCH_BOOST_GRANT"],
        user_id=int(user_id),
        request_id=(getattr(g, "request_id", None) if has_request_context() else None),
        action_key="research_boost_grant",
        entity_type="user",
        entity_id=int(user_id),
        delta_count=int(grant_amount),
        payload={
            "reason": source_key,
            "source": source_key,
            "source_label": LAB_SMALL_BOOST_SOURCE_LABELS[source_key],
            "day_key": day_key,
            "amount": 1,
            "granted": int(grant_amount),
            "before": int(before_count),
            "after": int(after_count),
            "capped": bool(grant_amount <= 0),
            "count_before": int(before_count),
            "count_after": int(after_count),
            "cap": int(RESEARCH_BOOST_MAX_CHARGES),
        },
        ip=(request.remote_addr if has_request_context() else None),
    )
    return {
        "handled": True,
        "granted": bool(grant_amount > 0),
        "grant_amount": int(grant_amount),
        "already_received": False,
        "capped": bool(grant_amount <= 0),
        "source": source_key,
        "reason": source_key,
        "before": int(before_count),
        "after": int(after_count),
        "before_count": int(before_count),
        "count": int(after_count),
        "message": message,
    }


def _flash_lab_small_boost_result(result):
    message = str((result or {}).get("message") or "").strip()
    if message:
        flash(message, "notice")


def _lab_small_boost_ct_seconds_for_user(user_row, now_ts=None):
    return int(_explore_ct_seconds_for_user(user_row, now_ts=now_ts))


def _lab_small_boost_status_for_user(user_row, *, now_ts=None, paid_boost_active=False, ct_seconds=None):
    now = _now_ts() if now_ts is None else int(now_ts)
    count = _lab_small_boost_count(user_row)
    paid_active = bool(paid_boost_active)
    auto_use_enabled = _research_boost_auto_use_enabled(user_row)
    if count <= 0:
        status_line = "ログイン・実験室・Xシェアで補充できます"
    elif auto_use_enabled:
        status_line = f"次の{count}回はCTなしで出撃できます"
    else:
        status_line = "OFF中です。ONにすると出撃時に使います"
    return {
        "count": int(count),
        "cap": int(RESEARCH_BOOST_MAX_CHARGES),
        "active": False,
        "until": 0,
        "remain_seconds": 0,
        "remain_label": "",
        "ct_seconds": int(ct_seconds or _explore_ct_seconds_for_user(user_row, now_ts=now)),
        "paid_boost_active": paid_active,
        "paid_boost_message": "",
        "can_use": False,
        "auto_use": bool(auto_use_enabled),
        "toggle_label": ("OFFにする" if auto_use_enabled else "ONにする"),
        "toggle_status": ("自動使用: ON" if auto_use_enabled else "自動使用: OFF"),
        "status_line": status_line,
        "helper_line": "1回の出撃で1つ消費します",
    }


def _research_boost_submission_already_consumed(submission_id):
    sid = str(submission_id or "").strip()
    if not sid:
        return False
    mapping = session.get("research_boost_consumed_submissions") if has_request_context() else None
    return bool(isinstance(mapping, dict) and mapping.get(sid))


def _mark_research_boost_submission_consumed(submission_id):
    if not has_request_context():
        return
    sid = str(submission_id or "").strip()
    if not sid:
        return
    mapping = session.get("research_boost_consumed_submissions")
    if not isinstance(mapping, dict):
        mapping = {}
    mapping[sid] = 1
    if len(mapping) > 32:
        mapping = {k: v for k, v in list(mapping.items())[-32:]}
    session["research_boost_consumed_submissions"] = mapping


def _consume_research_boost_if_available(db, user_id, *, user_row=None, area_key="", submission_id="", now_ts=None):
    if (
        user_row is None
        or "research_boost_charges" not in user_row.keys()
        or "research_boost_auto_use_enabled" not in user_row.keys()
    ):
        user_row = db.execute(
            "SELECT id, is_admin, research_boost_charges, research_boost_auto_use_enabled FROM users WHERE id = ?",
            (int(user_id),),
        ).fetchone()
    if not user_row:
        return {"used": False, "before": 0, "after": 0}
    before_count = _research_boost_charges(user_row)
    if int(user_row["is_admin"] or 0) == 1:
        return {"used": False, "before": int(before_count), "after": int(before_count), "admin": True}
    if not _lab_small_boost_feature_open(db, user_row=user_row, user_id=int(user_id)):
        return {"used": False, "before": int(before_count), "after": int(before_count), "feature_closed": True}
    if _research_boost_submission_already_consumed(submission_id):
        return {
            "used": True,
            "already_consumed": True,
            "before": int(before_count),
            "after": int(before_count),
            "skip_cooldown": True,
        }
    if not _research_boost_auto_use_enabled(user_row):
        return {"used": False, "before": int(before_count), "after": int(before_count), "auto_use": False}
    if before_count <= 0:
        return {"used": False, "before": 0, "after": 0}
    cur = db.execute(
        """
        UPDATE users
        SET research_boost_charges = research_boost_charges - 1
        WHERE id = ?
          AND research_boost_charges > 0
        """,
        (int(user_id),),
    )
    if cur.rowcount <= 0:
        fresh = db.execute(
            "SELECT research_boost_charges FROM users WHERE id = ?",
            (int(user_id),),
        ).fetchone()
        after_count = _research_boost_charges(fresh)
        return {"used": False, "before": int(after_count), "after": int(after_count)}
    fresh = db.execute(
        "SELECT research_boost_charges FROM users WHERE id = ?",
        (int(user_id),),
    ).fetchone()
    after_count = _research_boost_charges(fresh)
    audit_log(
        db,
        AUDIT_EVENT_TYPES["RESEARCH_BOOST_CONSUME"],
        user_id=int(user_id),
        request_id=(getattr(g, "request_id", None) if has_request_context() else None),
        action_key="research_boost_consume",
        entity_type="user",
        entity_id=int(user_id),
        delta_count=-1,
        payload={
            "user_id": int(user_id),
            "before": int(before_count),
            "after": int(after_count),
            "used_for": "explore",
            "area_key": str(area_key or ""),
            "submission_id": str(submission_id or ""),
        },
        ip=(request.remote_addr if has_request_context() else None),
    )
    _mark_research_boost_submission_consumed(submission_id)
    return {"used": True, "before": int(before_count), "after": int(after_count), "skip_cooldown": True}


def _grant_explore_boost_reward(db, user_id, product):
    boost_days = max(1, int((product or {}).get("boost_days") or EXPLORE_BOOST_DURATION_DAYS))
    user_row = db.execute(
        "SELECT id, explore_boost_until FROM users WHERE id = ?",
        (int(user_id),),
    ).fetchone()
    if not user_row:
        return {
            "ok": False,
            "granted": False,
            "duplicate_reason": "missing_user",
            "boost_days": boost_days,
            "starts_at": None,
            "ends_at": None,
        }
    starts_at = _now_ts()
    existing_until = _explore_boost_until_ts(user_row)
    effective_start = max(starts_at, existing_until)
    ends_at = effective_start + (boost_days * 86400)
    db.execute("UPDATE users SET explore_boost_until = ? WHERE id = ?", (ends_at, int(user_id)))
    return {
        "ok": True,
        "granted": True,
        "duplicate_reason": None,
        "boost_days": boost_days,
        "starts_at": effective_start,
        "ends_at": ends_at,
    }


def _grant_payment_reward(db, user_id, product):
    grant_type = str((product or {}).get("grant_type") or "").strip().lower()
    if grant_type == "decor":
        return _grant_support_reward(db, user_id, product)
    if grant_type == "explore_boost":
        return _grant_explore_boost_reward(db, user_id, product)
    return {"ok": False, "granted": False, "duplicate_reason": "unsupported_grant_type"}


def _payment_grant_audit_event_types(product):
    grant_type = str((product or {}).get("grant_type") or "").strip().lower()
    if grant_type == "explore_boost":
        return {
            "success": AUDIT_EVENT_TYPES["EXPLORE_BOOST_GRANT_SUCCESS"],
            "skip": AUDIT_EVENT_TYPES["EXPLORE_BOOST_GRANT_SKIP_DUPLICATE"],
            "failed": AUDIT_EVENT_TYPES["EXPLORE_BOOST_GRANT_FAILED"],
        }
    return {
        "success": AUDIT_EVENT_TYPES["PAYMENT_GRANT_SUCCESS"],
        "skip": AUDIT_EVENT_TYPES["PAYMENT_GRANT_SKIP_DUPLICATE"],
        "failed": AUDIT_EVENT_TYPES["PAYMENT_GRANT_FAILED"],
    }


def _payment_status_label(status):
    status_key = str(status or "").strip().lower()
    return {
        PAYMENT_STATUS_CREATED: "支払い待ち",
        PAYMENT_STATUS_COMPLETED: "支払い完了",
        PAYMENT_STATUS_GRANTED: "付与完了",
        PAYMENT_STATUS_FAILED: "失敗",
        PAYMENT_STATUS_EXPIRED: "期限切れ",
    }.get(status_key, status_key or "-")


def _payment_order_for_session(db, stripe_checkout_session_id):
    session_id = str(stripe_checkout_session_id or "").strip()
    if not session_id:
        return None
    return db.execute(
        "SELECT * FROM payment_orders WHERE stripe_checkout_session_id = ?",
        (session_id,),
    ).fetchone()


def _latest_payment_order_for_user_product(db, user_id, product_key):
    keys = _payment_product_keys(product_key)
    if not keys:
        return None
    placeholders = ",".join(["?"] * len(keys))
    return db.execute(
        f"""
        SELECT *
        FROM payment_orders
        WHERE user_id = ? AND product_key IN ({placeholders})
        ORDER BY id DESC
        LIMIT 1
        """,
        [int(user_id), *keys],
    ).fetchone()


def _payment_return_endpoint_for_product(product_key):
    product = _payment_product(product_key)
    return str((product or {}).get("return_endpoint") or "support")


def _payment_status_labels_map():
    return {
        PAYMENT_STATUS_CREATED: _payment_status_label(PAYMENT_STATUS_CREATED),
        PAYMENT_STATUS_COMPLETED: _payment_status_label(PAYMENT_STATUS_COMPLETED),
        PAYMENT_STATUS_GRANTED: _payment_status_label(PAYMENT_STATUS_GRANTED),
        PAYMENT_STATUS_FAILED: _payment_status_label(PAYMENT_STATUS_FAILED),
        PAYMENT_STATUS_EXPIRED: _payment_status_label(PAYMENT_STATUS_EXPIRED),
    }


def _create_checkout_session_for_product(db, *, user_id, product):
    stripe_api = _configure_stripe_api()
    success_query = (
        f"product_key={quote(str(product['product_key']), safe='')}"
        "&session_id={CHECKOUT_SESSION_ID}"
    )
    cancel_query = urlencode({"product_key": product["product_key"]})
    metadata = {
        "user_id": str(int(user_id)),
        "product_key": product["product_key"],
        "grant_type": product["grant_type"],
    }
    if product.get("boost_days"):
        metadata["boost_days"] = str(int(product["boost_days"]))
    checkout_session = stripe_api.checkout.Session.create(
        mode="payment",
        line_items=[{"price": product["price_id"], "quantity": 1}],
        success_url=f"{_public_game_root_url()}{url_for('payment_success')}?{success_query}",
        cancel_url=f"{_public_game_root_url()}{url_for('payment_cancel')}?{cancel_query}",
        client_reference_id=str(int(user_id)),
        metadata=metadata,
    )
    now_ts = _now_ts()
    session_id = str(_stripe_value(checkout_session, "id", "") or "").strip()
    payment_intent_id = str(_stripe_value(checkout_session, "payment_intent", "") or "").strip() or None
    amount_jpy = _stripe_value(checkout_session, "amount_total", None)
    try:
        amount_jpy = int(amount_jpy) if amount_jpy is not None else None
    except (TypeError, ValueError):
        amount_jpy = None
    currency = str(_stripe_value(checkout_session, "currency", "") or "").lower() or "jpy"
    db.execute(
        """
        INSERT INTO payment_orders (
            user_id,
            product_key,
            stripe_checkout_session_id,
            stripe_payment_intent_id,
            amount_jpy,
            currency,
            status,
            grant_type,
            boost_days,
            created_at,
            updated_at
        )
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        """,
        (
            int(user_id),
            product["product_key"],
            session_id,
            payment_intent_id,
            amount_jpy,
            currency,
            PAYMENT_STATUS_CREATED,
            product["grant_type"],
            int(product.get("boost_days") or 0),
            now_ts,
            now_ts,
        ),
    )
    order_id = int(db.execute("SELECT last_insert_rowid() AS id").fetchone()["id"])
    audit_log(
        db,
        AUDIT_EVENT_TYPES["PAYMENT_CHECKOUT_CREATE"],
        user_id=int(user_id),
        request_id=getattr(g, "request_id", None),
        action_key=product["product_key"],
        entity_type="payment_order",
        entity_id=order_id,
        payload={
            "product_key": product["product_key"],
            "stripe_checkout_session_id": session_id,
            "stripe_payment_intent_id": payment_intent_id,
            "stripe_event_id": None,
            "amount_jpy": amount_jpy,
            "currency": currency,
            "status": PAYMENT_STATUS_CREATED,
            "grant_type": product["grant_type"],
            "boost_days": int(product.get("boost_days") or 0),
        },
        ip=request.remote_addr,
    )
    checkout_url = str(_stripe_value(checkout_session, "url", "") or "").strip()
    return {
        "session_id": session_id,
        "checkout_url": checkout_url,
    }


def _update_payment_order(db, order_id, **fields):
    if not fields:
        return
    fields["updated_at"] = _now_ts()
    columns = list(fields.keys())
    assignments = ", ".join(f"{col} = ?" for col in columns)
    params = [fields[col] for col in columns]
    params.append(int(order_id))
    db.execute(f"UPDATE payment_orders SET {assignments} WHERE id = ?", params)


def _referral_counts_for_referrer(db, user_id):
    uid = int(user_id)
    rows = db.execute(
        """
        SELECT status, COUNT(*) AS c
        FROM user_referrals
        WHERE referrer_user_id = ?
        GROUP BY status
        """,
        (uid,),
    ).fetchall()
    pending = 0
    qualified = 0
    for row in rows:
        status = (row["status"] or "").strip().lower()
        count = int(row["c"] or 0)
        if status == "qualified":
            qualified += count
        elif status == "pending":
            pending += count
    return {"pending": pending, "qualified": qualified}


def _attach_referral_if_valid(db, *, referred_user_id, referral_code, request_ip=None):
    code = (referral_code or "").strip().upper()
    referred_id = int(referred_user_id)
    result = "invalid_code"
    payload = {
        "referrer_user_id": None,
        "referred_user_id": referred_id,
        "referral_code": code,
        "result": result,
    }
    if not code:
        return {"ok": False, "result": "no_ref"}
    referrer = db.execute("SELECT id FROM users WHERE invite_code = ? LIMIT 1", (code,)).fetchone()
    if not referrer:
        audit_log(
            db,
            AUDIT_EVENT_TYPES["REFERRAL_ATTACH"],
            user_id=referred_id,
            request_id=(getattr(g, "request_id", None) if g else None),
            action_key="register",
            entity_type="user",
            entity_id=referred_id,
            payload=payload,
            ip=request_ip,
        )
        return {"ok": False, "result": result}
    referrer_id = int(referrer["id"])
    if referrer_id == referred_id:
        result = "ignored_self"
    else:
        db.execute(
            """
            INSERT INTO user_referrals
            (referrer_user_id, referred_user_id, referral_code, status, created_at)
            VALUES (?, ?, ?, 'pending', ?)
            ON CONFLICT(referrer_user_id, referred_user_id) DO NOTHING
            """,
            (referrer_id, referred_id, code, int(time.time())),
        )
        result = "attached"
    payload.update({"referrer_user_id": referrer_id, "result": result})
    audit_log(
        db,
        AUDIT_EVENT_TYPES["REFERRAL_ATTACH"],
        user_id=referred_id,
        request_id=(getattr(g, "request_id", None) if g else None),
        action_key="register",
        entity_type="user",
        entity_id=referred_id,
        payload=payload,
        ip=request_ip,
    )
    return {"ok": result == "attached", "result": result, "referrer_user_id": referrer_id}


def evaluate_referral_qualification(db, user_id, request_ip=None):
    uid = int(user_id)
    pending = db.execute(
        """
        SELECT id, referrer_user_id
        FROM user_referrals
        WHERE referred_user_id = ? AND status = 'pending'
        ORDER BY id ASC
        """,
        (uid,),
    ).fetchall()
    if not pending:
        return {"updated": 0, "qualified": False}
    user_row = db.execute("SELECT created_at FROM users WHERE id = ?", (uid,)).fetchone()
    if not user_row:
        return {"updated": 0, "qualified": False}
    has_robot = bool(
        db.execute(
            "SELECT 1 FROM robot_instances WHERE user_id = ? AND status != 'decomposed' LIMIT 1",
            (uid,),
        ).fetchone()
    )
    explore_count = int(
        db.execute(
            "SELECT COUNT(*) AS c FROM world_events_log WHERE user_id = ? AND event_type = ?",
            (uid, AUDIT_EVENT_TYPES["EXPLORE_END"]),
        ).fetchone()["c"]
        or 0
    )
    second_day_login = int(time.time()) >= (int(user_row["created_at"] or 0) + 86400)
    if not (has_robot and explore_count >= 10 and second_day_login):
        return {"updated": 0, "qualified": False}
    now_ts = int(time.time())
    updated = 0
    for row in pending:
        db.execute(
            "UPDATE user_referrals SET status = 'qualified', qualified_at = ? WHERE id = ? AND status = 'pending'",
            (now_ts, int(row["id"])),
        )
        updated += 1
        audit_log(
            db,
            AUDIT_EVENT_TYPES["REFERRAL_QUALIFIED"],
            user_id=uid,
            request_id=(getattr(g, "request_id", None) if g else None),
            action_key="referral_qualify",
            entity_type="user_referral",
            entity_id=int(row["id"]),
            payload={
                "referrer_user_id": int(row["referrer_user_id"] or 0),
                "referred_user_id": uid,
                "conditions": {
                    "built_robot": has_robot,
                    "explore_count": explore_count,
                    "second_day_login": second_day_login,
                },
            },
            ip=request_ip,
        )
    return {"updated": updated, "qualified": updated > 0}


def build_share_text(event_type, payload):
    if event_type == "share.boss.defeat":
        boss_name = payload.get("enemy_name") or "未知のボス"
        area_name = payload.get("area_label") or payload.get("area_key") or "不明エリア"
        actor_name = payload.get("robot_name") or payload.get("username") or "パイロット"
        return f"ボス撃破！{actor_name} が {area_name} で {boss_name} を討伐。{payload.get('game_url') or _public_game_root_url()}"
    return payload.get("game_url") or _public_game_root_url()


def _faction_unlock_counts(db, user_id):
    explore_row = db.execute(
        """
        SELECT COUNT(*) AS c
        FROM world_events_log
        WHERE user_id = ?
          AND event_type = ?
          AND (
              COALESCE(json_extract(payload_json, '$.area_key'), '') = ''
              OR json_extract(payload_json, '$.area_key') = 'layer_1'
          )
        """,
        (int(user_id), AUDIT_EVENT_TYPES["EXPLORE_END"]),
    ).fetchone()
    strengthen_row = db.execute(
        """
        SELECT COUNT(*) AS c
        FROM world_events_log
        WHERE user_id = ?
          AND event_type = ?
          AND LOWER(COALESCE(CAST(json_extract(payload_json, '$.success') AS TEXT), 'true')) NOT IN ('0', 'false', 'no')
        """,
        (int(user_id), AUDIT_EVENT_TYPES["FUSE"]),
    ).fetchone()
    out = {
        "layer1_explore": int((explore_row["c"] if explore_row else 0) or 0),
        "strengthen": int((strengthen_row["c"] if strengthen_row else 0) or 0),
        "layer1_boss_defeated": bool(_has_fixed_boss_defeat_in_area(db, int(user_id), "layer_1")),
    }
    return out


def _faction_unlock_ready(counts):
    if counts.get("layer1_boss_defeated"):
        return True
    return (
        int(counts.get("layer1_explore", 0)) >= int(FACTION_UNLOCK_REQUIREMENTS["layer1_explore"]["required"])
        and int(counts.get("strengthen", 0)) >= int(FACTION_UNLOCK_REQUIREMENTS["strengthen"]["required"])
    )


def _faction_unlock_progress_line(counts):
    return (
        f"陣営参加まで: 出撃 {min(int(counts.get('layer1_explore', 0)), FACTION_UNLOCK_REQUIREMENTS['layer1_explore']['required'])}/{FACTION_UNLOCK_REQUIREMENTS['layer1_explore']['required']} / "
        f"パーツ強化 {min(int(counts.get('strengthen', 0)), FACTION_UNLOCK_REQUIREMENTS['strengthen']['required'])}/{FACTION_UNLOCK_REQUIREMENTS['strengthen']['required']} / "
        f"第1層ボス撃破 {'達成' if counts.get('layer1_boss_defeated') else '未達成'}"
    )


def _faction_unlock_progress_rows(counts):
    return (
        {
            "label": "出撃",
            "value": f"{min(int(counts.get('layer1_explore', 0)), FACTION_UNLOCK_REQUIREMENTS['layer1_explore']['required'])} / {FACTION_UNLOCK_REQUIREMENTS['layer1_explore']['required']}",
        },
        {
            "label": "パーツ強化",
            "value": f"{min(int(counts.get('strengthen', 0)), FACTION_UNLOCK_REQUIREMENTS['strengthen']['required'])} / {FACTION_UNLOCK_REQUIREMENTS['strengthen']['required']}",
        },
        {
            "label": "第1層ボス撃破",
            "value": "達成" if counts.get("layer1_boss_defeated") else "未達成",
        },
    )


def _faction_member_counts(db):
    rows = db.execute(
        """
        SELECT faction, COUNT(*) AS c
        FROM users
        WHERE faction IN ('ignis', 'ventra', 'aurix')
        GROUP BY faction
        """
    ).fetchall()
    counts = {k: 0 for k in FACTION_KEYS}
    for row in rows:
        fk = _normalize_faction_key(row["faction"])
        if fk:
            counts[fk] = int(row["c"] or 0)
    return counts


def get_faction_counts(db):
    return _faction_member_counts(db)


def _faction_minority_keys(counts):
    values = {key: int((counts or {}).get(key, 0) or 0) for key in FACTION_KEYS}
    if not values or len(set(values.values())) <= 1:
        return set()
    minimum = min(values.values())
    return {key for key, value in values.items() if value == minimum}


def _faction_changed_at_ts(value):
    text = str(value or "").strip()
    if not text:
        return 0
    try:
        return int(text)
    except (TypeError, ValueError):
        pass
    try:
        return int(time.mktime(time.strptime(text[:19], "%Y-%m-%d %H:%M:%S")))
    except (OverflowError, TypeError, ValueError):
        return 0


def _faction_change_status(user_row, now_ts=None):
    current = _normalize_faction_key(user_row["faction"] if user_row and "faction" in user_row.keys() else None)
    if not current:
        return {
            "can_change": True,
            "current_faction": None,
            "next_change_at": 0,
            "next_change_at_text": "",
            "remaining_seconds": 0,
        }
    changed_at = user_row["faction_changed_at"] if "faction_changed_at" in user_row.keys() else None
    changed_ts = _faction_changed_at_ts(changed_at)
    if changed_ts <= 0:
        return {
            "can_change": True,
            "current_faction": current,
            "next_change_at": 0,
            "next_change_at_text": "",
            "remaining_seconds": 0,
        }
    now_value = int(_now_ts() if now_ts is None else now_ts)
    next_ts = int(changed_ts + FACTION_CHANGE_COOLDOWN_DAYS * 86400)
    remaining = max(0, next_ts - now_value)
    return {
        "can_change": remaining <= 0,
        "current_faction": current,
        "next_change_at": next_ts,
        "next_change_at_text": _format_jst_ts(next_ts),
        "remaining_seconds": remaining,
    }


def _faction_recommended_key(counts):
    ranked = sorted([(int(counts.get(k, 0)), k) for k in FACTION_KEYS], key=lambda x: (x[0], x[1]))
    return ranked[0][1] if ranked else None


def get_current_week_range(week_key=None):
    return _world_week_bounds(str(week_key or _world_week_key()))


def get_current_week_key():
    return _world_week_key()


def _faction_activity_score(*, explore_count=0, boss_defeat_count=0, evolve_count=0):
    return int(explore_count or 0) + int(boss_defeat_count or 0) * 20 + int(evolve_count or 0) * 10


FACTION_WEEKLY_BONUS_REQUIRED_SCORE = 10
FACTION_WEEKLY_BONUS_COINS = 50


def _faction_weekly_participation_badge(faction_key, week_key):
    key = _normalize_faction_key(faction_key)
    wk = str(week_key or _world_week_key())
    safe_week = wk.replace("-", "_")
    return {
        "badge_key": f"weekly_{key}_{safe_week}",
        "badge_label": f"今週の{FACTION_LABELS.get(key, key)}研究員",
    }


def get_user_weekly_faction_activity(db, user_id, week_key=None):
    wk = str(week_key or _world_week_key())
    start_dt, end_dt = get_current_week_range(wk)
    start_ts = int(start_dt.timestamp())
    end_ts = int(end_dt.timestamp())
    user = db.execute("SELECT id, faction FROM users WHERE id = ?", (int(user_id),)).fetchone()
    faction_key = _normalize_faction_key(user["faction"] if user and "faction" in user.keys() else None)
    base = {
        "week_key": wk,
        "faction_key": faction_key,
        "explore_count": 0,
        "boss_defeat_count": 0,
        "evolve_count": 0,
        "activity_score": 0,
    }
    if not user:
        return base
    row = db.execute(
        """
        SELECT
            SUM(CASE WHEN event_type = ? THEN 1 ELSE 0 END) AS explore_count,
            SUM(CASE WHEN event_type = ? THEN 1 ELSE 0 END) AS boss_defeat_count,
            SUM(
                CASE
                    WHEN event_type = ?
                     AND LOWER(COALESCE(CAST(json_extract(payload_json, '$.success') AS TEXT), 'true')) NOT IN ('0', 'false', 'no')
                    THEN 1
                    ELSE 0
                END
            ) AS evolve_count
        FROM world_events_log
        WHERE user_id = ?
          AND created_at >= ?
          AND created_at < ?
          AND event_type IN (?, ?, ?)
        """,
        (
            AUDIT_EVENT_TYPES["EXPLORE_END"],
            AUDIT_EVENT_TYPES["BOSS_DEFEAT"],
            AUDIT_EVENT_TYPES["PART_EVOLVE"],
            int(user_id),
            start_ts,
            end_ts,
            AUDIT_EVENT_TYPES["EXPLORE_END"],
            AUDIT_EVENT_TYPES["BOSS_DEFEAT"],
            AUDIT_EVENT_TYPES["PART_EVOLVE"],
        ),
    ).fetchone()
    explore_count = int((row or {})["explore_count"] or 0)
    boss_defeat_count = int((row or {})["boss_defeat_count"] or 0)
    evolve_count = int((row or {})["evolve_count"] or 0)
    base.update(
        {
            "explore_count": explore_count,
            "boss_defeat_count": boss_defeat_count,
            "evolve_count": evolve_count,
            "activity_score": _faction_activity_score(
                explore_count=explore_count,
                boss_defeat_count=boss_defeat_count,
                evolve_count=evolve_count,
            ),
        }
    )
    return base


def can_claim_faction_weekly_bonus(db, user_id, week_key=None):
    activity = get_user_weekly_faction_activity(db, user_id, week_key)
    faction_key = _normalize_faction_key(activity.get("faction_key"))
    wk = activity["week_key"]
    badge = _faction_weekly_participation_badge(faction_key, wk) if faction_key else {"badge_key": None, "badge_label": None}
    result = {
        "can_claim": False,
        "reason": None,
        "week_key": wk,
        "faction_key": faction_key,
        "activity_score": int(activity.get("activity_score") or 0),
        "coin_reward": FACTION_WEEKLY_BONUS_COINS,
        "badge_key": badge["badge_key"],
        "badge_label": badge["badge_label"],
        "required_score": FACTION_WEEKLY_BONUS_REQUIRED_SCORE,
    }
    if not faction_key:
        result["reason"] = "no_faction"
        return result
    if int(activity.get("activity_score") or 0) < FACTION_WEEKLY_BONUS_REQUIRED_SCORE:
        result["reason"] = "insufficient_activity"
        return result
    exists = db.execute(
        "SELECT 1 FROM faction_weekly_claims WHERE user_id = ? AND week_key = ? LIMIT 1",
        (int(user_id), wk),
    ).fetchone()
    if exists:
        result["reason"] = "already_claimed"
        return result
    result["can_claim"] = True
    return result


def grant_faction_weekly_bonus(db, user_id, week_key=None, *, request_id=None, ip=None):
    claim = can_claim_faction_weekly_bonus(db, user_id, week_key)
    if not claim.get("can_claim"):
        return {**claim, "claimed": False}
    now_text = now_str()
    user_id_int = int(user_id)
    coins_before = int(
        db.execute("SELECT COALESCE(coins, 0) AS coins FROM users WHERE id = ?", (user_id_int,)).fetchone()["coins"]
        or 0
    )
    db.execute("UPDATE users SET coins = COALESCE(coins, 0) + ? WHERE id = ?", (int(claim["coin_reward"]), user_id_int))
    db.execute(
        """
        INSERT INTO faction_weekly_claims
        (user_id, week_key, faction_key, activity_score, coin_reward, badge_key, claimed_at, created_at)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?)
        """,
        (
            user_id_int,
            claim["week_key"],
            claim["faction_key"],
            int(claim["activity_score"]),
            int(claim["coin_reward"]),
            claim["badge_key"],
            now_text,
            now_text,
        ),
    )
    db.execute(
        """
        INSERT OR IGNORE INTO user_faction_badges
        (user_id, faction_key, badge_key, badge_label, badge_kind, week_key, source_type, granted_at, created_at)
        VALUES (?, ?, ?, ?, 'weekly_participation', ?, 'participation', ?, ?)
        """,
        (
            user_id_int,
            claim["faction_key"],
            claim["badge_key"],
            claim["badge_label"],
            claim["week_key"],
            now_text,
            now_text,
        ),
    )
    payload = {
        "user_id": user_id_int,
        "week_key": claim["week_key"],
        "faction_key": claim["faction_key"],
        "activity_score": int(claim["activity_score"]),
        "coin_reward": int(claim["coin_reward"]),
        "badge_key": claim["badge_key"],
        "coins_before": coins_before,
        "coins_after": coins_before + int(claim["coin_reward"]),
    }
    audit_log(
        db,
        AUDIT_EVENT_TYPES["FACTION_WEEKLY_BONUS_CLAIM"],
        user_id=user_id_int,
        request_id=request_id,
        action_key="faction_weekly_bonus_claim",
        entity_type="user",
        entity_id=user_id_int,
        delta_coins=int(claim["coin_reward"]),
        delta_count=1,
        payload=payload,
        ip=ip,
    )
    return {**claim, "claimed": True, "coins_before": coins_before, "coins_after": coins_before + int(claim["coin_reward"])}


def get_weekly_faction_activity(db, week_key=None):
    wk = str(week_key or _world_week_key())
    start_dt, end_dt = get_current_week_range(wk)
    start_ts = int(start_dt.timestamp())
    end_ts = int(end_dt.timestamp())
    member_counts = _faction_member_counts(db)
    minority_keys = _faction_minority_keys(member_counts)
    rows = db.execute(
        """
        SELECT
            LOWER(TRIM(u.faction)) AS faction,
            SUM(CASE WHEN e.event_type = ? THEN 1 ELSE 0 END) AS explore_count,
            SUM(CASE WHEN e.event_type = ? THEN 1 ELSE 0 END) AS boss_defeat_count,
            SUM(
                CASE
                    WHEN e.event_type = ?
                     AND LOWER(COALESCE(CAST(json_extract(e.payload_json, '$.success') AS TEXT), 'true')) NOT IN ('0', 'false', 'no')
                    THEN 1
                    ELSE 0
                END
            ) AS evolve_count
        FROM world_events_log e
        JOIN users u ON u.id = e.user_id
        WHERE e.user_id IS NOT NULL
          AND e.created_at >= ?
          AND e.created_at < ?
          AND e.event_type IN (?, ?, ?)
          AND LOWER(TRIM(COALESCE(u.faction, ''))) IN ('ignis', 'ventra', 'aurix')
          AND COALESCE(u.is_admin, 0) = 0
        GROUP BY LOWER(TRIM(u.faction))
        """,
        (
            AUDIT_EVENT_TYPES["EXPLORE_END"],
            AUDIT_EVENT_TYPES["BOSS_DEFEAT"],
            AUDIT_EVENT_TYPES["PART_EVOLVE"],
            start_ts,
            end_ts,
            AUDIT_EVENT_TYPES["EXPLORE_END"],
            AUDIT_EVENT_TYPES["BOSS_DEFEAT"],
            AUDIT_EVENT_TYPES["PART_EVOLVE"],
        ),
    ).fetchall()
    by_key = {}
    for row in rows:
        key = _normalize_faction_key(row["faction"])
        if not key:
            continue
        explore_count = int(row["explore_count"] or 0)
        boss_defeat_count = int(row["boss_defeat_count"] or 0)
        evolve_count = int(row["evolve_count"] or 0)
        by_key[key] = {
            "explore_count": explore_count,
            "boss_defeat_count": boss_defeat_count,
            "evolve_count": evolve_count,
            "activity_score": _faction_activity_score(
                explore_count=explore_count,
                boss_defeat_count=boss_defeat_count,
                evolve_count=evolve_count,
            ),
        }
    out = []
    for key in FACTION_KEYS:
        base = by_key.get(key, {})
        out.append(
            {
                "faction_key": key,
                "faction_name": FACTION_LABELS.get(key, key),
                "member_count": int(member_counts.get(key, 0) or 0),
                "explore_count": int(base.get("explore_count", 0) or 0),
                "boss_defeat_count": int(base.get("boss_defeat_count", 0) or 0),
                "evolve_count": int(base.get("evolve_count", 0) or 0),
                "activity_score": int(base.get("activity_score", 0) or 0),
                "is_minority": key in minority_keys,
            }
        )
    return out


FACTION_WEEKLY_REPORT_LABELS = {
    "research_leader": "今週の研究優勢陣営",
    "chasing": "追跡中",
    "minority_elite": "少数精鋭で研究中",
    "steady": "研究継続中",
}


def _faction_weekly_report_label(rank, is_minority):
    try:
        rank_int = int(rank or 0)
    except (TypeError, ValueError):
        rank_int = 0
    if rank_int == 1:
        return "research_leader"
    if bool(is_minority):
        return "minority_elite"
    if rank_int == 2:
        return "chasing"
    return "steady"


def _faction_weekly_report_view_row(row):
    label_key = str(row["report_label"] or "").strip() or _faction_weekly_report_label(row["rank"], row["is_minority"])
    faction_key = _normalize_faction_key(row["faction_key"]) or str(row["faction_key"] or "")
    return {
        "week_key": row["week_key"],
        "faction_key": faction_key,
        "faction_name": FACTION_LABELS.get(faction_key, faction_key),
        "member_count": int(row["member_count"] or 0),
        "explore_count": int(row["explore_count"] or 0),
        "boss_defeat_count": int(row["boss_defeat_count"] or 0),
        "evolve_count": int(row["evolve_count"] or 0),
        "activity_score": int(row["activity_score"] or 0),
        "rank": int(row["rank"] or 0),
        "report_label": label_key,
        "report_label_text": FACTION_WEEKLY_REPORT_LABELS.get(label_key, "研究継続中"),
        "is_minority": bool(int(row["is_minority"] or 0)),
        "is_finalized": bool(int(row["is_finalized"] or 0)),
        "finalized_at": row["finalized_at"],
    }


def calculate_faction_weekly_report(db, week_key=None, finalize=False):
    wk = str(week_key or _world_week_key())
    _world_week_bounds(wk)
    now_text = now_str()
    activity_rows = get_weekly_faction_activity(db, wk)
    ordered = sorted(
        activity_rows,
        key=lambda row: (
            -int(row.get("activity_score", 0) or 0),
            int(row.get("member_count", 0) or 0),
            str(row.get("faction_key") or ""),
        ),
    )
    previous_score = None
    previous_rank = 0
    for idx, row in enumerate(ordered, start=1):
        score = int(row.get("activity_score", 0) or 0)
        if previous_score is None or score != previous_score:
            previous_rank = idx
            previous_score = score
        row["rank"] = previous_rank
        row["report_label"] = _faction_weekly_report_label(previous_rank, row.get("is_minority"))

    finalized_at = now_text if finalize else None
    updated_count = 0
    for row in ordered:
        db.execute(
            """
            INSERT INTO faction_weekly_reports
            (week_key, faction_key, member_count, explore_count, boss_defeat_count, evolve_count,
             activity_score, rank, report_label, is_minority, is_finalized, finalized_at, created_at, updated_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            ON CONFLICT(week_key, faction_key) DO UPDATE SET
                member_count = excluded.member_count,
                explore_count = excluded.explore_count,
                boss_defeat_count = excluded.boss_defeat_count,
                evolve_count = excluded.evolve_count,
                activity_score = excluded.activity_score,
                rank = excluded.rank,
                report_label = excluded.report_label,
                is_minority = excluded.is_minority,
                is_finalized = CASE WHEN excluded.is_finalized = 1 THEN 1 ELSE faction_weekly_reports.is_finalized END,
                finalized_at = CASE WHEN excluded.is_finalized = 1 THEN excluded.finalized_at ELSE faction_weekly_reports.finalized_at END,
                updated_at = excluded.updated_at
            """,
            (
                wk,
                row["faction_key"],
                int(row.get("member_count", 0) or 0),
                int(row.get("explore_count", 0) or 0),
                int(row.get("boss_defeat_count", 0) or 0),
                int(row.get("evolve_count", 0) or 0),
                int(row.get("activity_score", 0) or 0),
                int(row.get("rank", 0) or 0),
                row.get("report_label") or "steady",
                1 if row.get("is_minority") else 0,
                1 if finalize else 0,
                finalized_at,
                now_text,
                now_text,
            ),
        )
        updated_count += 1
    emitted_world_event = False
    if finalize:
        emitted_world_event = _emit_faction_weekly_report_world_event(db, wk)
    return {"week_key": wk, "updated_count": updated_count, "finalized": bool(finalize), "emitted_world_event": emitted_world_event}


def get_faction_weekly_report(db, week_key=None):
    wk = str(week_key or _world_week_key())
    rows = db.execute(
        """
        SELECT *
        FROM faction_weekly_reports
        WHERE week_key = ?
        ORDER BY COALESCE(rank, 99) ASC, activity_score DESC, member_count ASC, faction_key ASC
        """,
        (wk,),
    ).fetchall()
    return [_faction_weekly_report_view_row(row) for row in rows]


def get_my_faction_weekly_position(db, user, week_key=None):
    if not user:
        return None
    faction_key = _normalize_faction_key(user["faction"] if "faction" in user.keys() else None)
    if not faction_key:
        return None
    for row in get_faction_weekly_report(db, week_key):
        if row["faction_key"] == faction_key:
            return row
    return None


def _emit_faction_weekly_report_world_event(db, week_key):
    exists = db.execute(
        """
        SELECT 1
        FROM world_events_log
        WHERE event_type = ?
          AND json_extract(payload_json, '$.week_key') = ?
        LIMIT 1
        """,
        (FACTION_WEEKLY_REPORT_EVENT_TYPE, week_key),
    ).fetchone()
    if exists:
        return False
    rows = get_faction_weekly_report(db, week_key)
    if not rows:
        return False
    top = rows[0]
    payload = {
        "week_key": week_key,
        "top_faction": top["faction_key"],
        "top_faction_name": top["faction_name"],
        "activity_score": int(top["activity_score"]),
        "explore_count": int(top["explore_count"]),
        "boss_defeat_count": int(top["boss_defeat_count"]),
        "evolve_count": int(top["evolve_count"]),
    }
    _world_event_log(db, FACTION_WEEKLY_REPORT_EVENT_TYPE, payload)
    return True


