def _faction_weekly_event_def(event_key):
    return FACTION_WEEKLY_EVENTS.get(str(event_key or "").strip())


def _faction_weekly_event_view_row(row):
    if not row:
        return None
    event_key = str(row["event_key"] or "").strip()
    event_def = _faction_weekly_event_def(event_key) or {}
    return {
        "id": int(row["id"]),
        "week_key": row["week_key"],
        "event_key": event_key,
        "event_name": row["event_name"] or event_def.get("name", event_key),
        "description": row["description"] or event_def.get("description", ""),
        "effect_summary": row["effect_summary"] or event_def.get("effect_summary", ""),
        "action_hint": event_def.get("action_hint", ""),
        "status": row["status"],
        "starts_at": row["starts_at"],
        "ends_at": row["ends_at"],
        "finalized_at": row["finalized_at"],
    }


def get_current_faction_weekly_event(db, week_key=None):
    wk = str(week_key or _world_week_key())
    row = db.execute(
        """
        SELECT *
        FROM faction_weekly_events
        WHERE week_key = ? AND status IN ('active', 'finalized')
        ORDER BY CASE status WHEN 'active' THEN 1 WHEN 'finalized' THEN 2 ELSE 9 END, id DESC
        LIMIT 1
        """,
        (wk,),
    ).fetchone()
    return _faction_weekly_event_view_row(row)


def get_faction_weekly_event_row(db, week_key=None):
    wk = str(week_key or _world_week_key())
    row = db.execute(
        "SELECT * FROM faction_weekly_events WHERE week_key = ? LIMIT 1",
        (wk,),
    ).fetchone()
    return _faction_weekly_event_view_row(row)


def _insert_faction_weekly_event_log(db, week_key, event_key, action, admin_user_id=None, payload=None):
    db.execute(
        """
        INSERT INTO faction_weekly_event_logs
        (week_key, event_key, action, admin_user_id, payload_json, created_at)
        VALUES (?, ?, ?, ?, ?, ?)
        """,
        (
            str(week_key),
            str(event_key),
            str(action),
            int(admin_user_id) if admin_user_id else None,
            json.dumps(payload or {}, ensure_ascii=False),
            now_str(),
        ),
    )


def set_faction_weekly_event(db, week_key, event_key, status="draft", admin_user_id=None):
    wk = str(week_key or _world_week_key())
    _world_week_bounds(wk)
    event_def = _faction_weekly_event_def(event_key)
    if not event_def:
        raise ValueError("invalid event_key")
    status_value = str(status or "draft").strip()
    if status_value not in {"draft", "active", "finalized", "cancelled"}:
        status_value = "draft"
    now_text = now_str()
    db.execute(
        """
        INSERT INTO faction_weekly_events
        (week_key, event_key, event_name, description, effect_summary, status, created_by, created_at, updated_at)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
        ON CONFLICT(week_key) DO UPDATE SET
            event_key = excluded.event_key,
            event_name = excluded.event_name,
            description = excluded.description,
            effect_summary = excluded.effect_summary,
            status = excluded.status,
            updated_at = excluded.updated_at
        """,
        (
            wk,
            str(event_key),
            event_def["name"],
            event_def["description"],
            event_def["effect_summary"],
            status_value,
            int(admin_user_id) if admin_user_id else None,
            now_text,
            now_text,
        ),
    )
    _insert_faction_weekly_event_log(db, wk, event_key, "set", admin_user_id, {"status": status_value})
    return get_faction_weekly_event_row(db, wk)


def _emit_faction_weekly_event_log_once(db, week_key, event_type, event_row):
    existing = db.execute(
        """
        SELECT 1 FROM world_events_log
        WHERE event_type = ?
          AND json_extract(payload_json, '$.week_key') = ?
        LIMIT 1
        """,
        (event_type, str(week_key)),
    ).fetchone()
    if existing:
        return False
    _world_event_log(
        db,
        event_type,
        {
            "week_key": str(week_key),
            "event_key": event_row["event_key"],
            "event_name": event_row["event_name"],
            "description": event_row["description"],
            "effect_summary": event_row["effect_summary"],
        },
    )
    return True


def activate_faction_weekly_event(db, week_key, admin_user_id=None):
    wk = str(week_key or _world_week_key())
    event = get_faction_weekly_event_row(db, wk)
    if not event:
        raise ValueError("weekly event is not set")
    now_text = now_str()
    db.execute(
        "UPDATE faction_weekly_events SET status = 'active', starts_at = COALESCE(starts_at, ?), updated_at = ? WHERE week_key = ?",
        (now_text, now_text, wk),
    )
    event = get_faction_weekly_event_row(db, wk)
    _insert_faction_weekly_event_log(db, wk, event["event_key"], "activate", admin_user_id)
    emitted = _emit_faction_weekly_event_log_once(db, wk, FACTION_WEEKLY_EVENT_STARTED_EVENT_TYPE, event)
    return {**event, "emitted_world_event": emitted}


def finalize_faction_weekly_event(db, week_key, admin_user_id=None):
    wk = str(week_key or _world_week_key())
    event = get_faction_weekly_event_row(db, wk)
    if not event:
        raise ValueError("weekly event is not set")
    now_text = now_str()
    db.execute(
        """
        UPDATE faction_weekly_events
        SET status = 'finalized', ends_at = COALESCE(ends_at, ?), finalized_at = COALESCE(finalized_at, ?), updated_at = ?
        WHERE week_key = ?
        """,
        (now_text, now_text, now_text, wk),
    )
    event = get_faction_weekly_event_row(db, wk)
    _insert_faction_weekly_event_log(db, wk, event["event_key"], "finalize", admin_user_id)
    emitted = _emit_faction_weekly_event_log_once(db, wk, FACTION_WEEKLY_EVENT_FINALIZED_EVENT_TYPE, event)
    return {**event, "emitted_world_event": emitted}


def cancel_faction_weekly_event(db, week_key, admin_user_id=None):
    wk = str(week_key or _world_week_key())
    event = get_faction_weekly_event_row(db, wk)
    if not event:
        raise ValueError("weekly event is not set")
    now_text = now_str()
    db.execute("UPDATE faction_weekly_events SET status = 'cancelled', ends_at = COALESCE(ends_at, ?), updated_at = ? WHERE week_key = ?", (now_text, now_text, wk))
    _insert_faction_weekly_event_log(db, wk, event["event_key"], "cancel", admin_user_id)
    return get_faction_weekly_event_row(db, wk)


def get_faction_event_material_bonus(db, source_event_type, base_amount, week_key=None):
    amount = max(0, int(base_amount or 0))
    event = get_current_faction_weekly_event(db, week_key)
    if not event:
        return amount
    source_type = str(source_event_type or "")
    if event["event_key"] == "facility_focus":
        if source_type == AUDIT_EVENT_TYPES["EXPLORE_END"]:
            return amount + 1
        if source_type == AUDIT_EVENT_TYPES["BOSS_DEFEAT"]:
            return amount + 5
        if source_type == AUDIT_EVENT_TYPES["PART_EVOLVE"]:
            return amount + 5
    if event["event_key"] == "guardian_focus" and source_type == "faction_guardian_attack":
        return max(1, int(math.ceil(amount * 1.2)))
    if amount > 0:
        return max(1, amount)
    return amount


def apply_faction_event_territory_score_bonus(db, score_parts, week_key=None):
    event = get_current_faction_weekly_event(db, week_key)
    parts = dict(score_parts or {})
    if not event:
        return parts
    def _add_ten_percent(value):
        return (int(value or 0) * 11 + 9) // 10

    if event["event_key"] == "territory_focus":
        parts["activity_score"] = _add_ten_percent(parts.get("activity_score", 0))
        parts["facility_score"] = _add_ten_percent(parts.get("facility_score", 0))
    elif event["event_key"] == "guardian_focus":
        parts["guardian_score"] = _add_ten_percent(parts.get("guardian_score", 0))
    elif event["event_key"] == "representative_focus":
        parts["representative_score"] = _add_ten_percent(parts.get("representative_score", 0))
    elif event["event_key"] == "guardian_author_focus":
        parts["guardian_duel_score"] = _add_ten_percent(parts.get("guardian_duel_score", 0))
    return parts


def _faction_shop_item_type_label(item_type):
    return FACTION_SHOP_ITEM_TYPES.get(str(item_type or "").strip(), str(item_type or ""))


def _faction_shop_item_view_row(row, *, purchased=False, can_purchase=None, equipped_slot=None):
    if not row:
        return None
    faction_key = _normalize_faction_key(row["faction_key"]) if row["faction_key"] else None
    item_type = str(row["item_type"] or "").strip()
    conditions = []
    if faction_key:
        conditions.append(f"{FACTION_LABELS.get(faction_key, faction_key)}所属")
    if int(row["required_facility_level"] or 0) > 0:
        conditions.append(f"施設Lv.{int(row['required_facility_level'])}以上")
    if row["required_title_key"]:
        title_def = FACTION_TITLES.get(str(row["required_title_key"]))
        conditions.append(f"称号: {title_def['label'] if title_def else row['required_title_key']}")
    if row["required_event_key"]:
        event_def = _faction_weekly_event_def(row["required_event_key"])
        conditions.append(f"イベント: {event_def['name'] if event_def else row['required_event_key']}")
    if int(row["required_territory_count"] or 0) > 0:
        conditions.append(f"研究影響エリア {int(row['required_territory_count'])}以上")
    if int(row["required_guardian_author"] or 0) == 1:
        conditions.append("守護機作者")
    return {
        "id": int(row["id"]),
        "item_key": row["item_key"],
        "item_name": row["item_name"],
        "description": row["description"] or "",
        "item_type": item_type,
        "item_type_label": _faction_shop_item_type_label(item_type),
        "faction_key": faction_key,
        "faction_name": FACTION_LABELS.get(faction_key, "全陣営") if faction_key else "全陣営",
        "price_coins": max(0, int(row["price_coins"] or 0)),
        "required_facility_level": int(row["required_facility_level"] or 0),
        "required_title_key": row["required_title_key"] or "",
        "required_event_key": row["required_event_key"] or "",
        "required_territory_count": int(row["required_territory_count"] or 0),
        "required_guardian_author": bool(int(row["required_guardian_author"] or 0)),
        "grant_title_key": row["grant_title_key"] or "",
        "badge_label": row["badge_label"] or "",
        "image_path": row["image_path"] or "",
        "sort_order": int(row["sort_order"] or 0),
        "is_active": bool(int(row["is_active"] or 0)),
        "is_limited": bool(int(row["is_limited"] or 0)),
        "starts_at": row["starts_at"] or "",
        "ends_at": row["ends_at"] or "",
        "conditions": conditions,
        "condition_text": " / ".join(conditions) if conditions else "条件なし",
        "purchased": bool(purchased),
        "can_purchase": can_purchase,
        "equippable_slot": FACTION_SHOP_EQUIP_SLOTS.get(item_type),
        "equipped_slot": equipped_slot,
    }


def ensure_default_faction_shop_items(db):
    now_text = now_str()
    created_count = 0
    for seed in DEFAULT_FACTION_SHOP_ITEMS:
        item_type = str(seed.get("item_type") or "").strip()
        if item_type not in FACTION_SHOP_ITEM_TYPES:
            continue
        faction_key = _normalize_faction_key(seed.get("faction_key")) if seed.get("faction_key") else None
        cur = db.execute(
            """
            INSERT OR IGNORE INTO faction_shop_items
            (item_key, item_name, description, item_type, faction_key, price_coins,
             required_facility_level, required_title_key, required_event_key, required_territory_count,
             required_guardian_author, grant_title_key, badge_label, image_path, sort_order,
             is_active, is_limited, starts_at, ends_at, created_at, updated_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 1, 0, NULL, NULL, ?, ?)
            """,
            (
                seed["item_key"],
                seed["item_name"],
                seed.get("description") or "",
                item_type,
                faction_key,
                max(0, int(seed.get("price_coins") or 0)),
                max(0, int(seed.get("required_facility_level") or 0)),
                seed.get("required_title_key") or None,
                seed.get("required_event_key") or None,
                max(0, int(seed.get("required_territory_count") or 0)),
                1 if seed.get("required_guardian_author") else 0,
                seed.get("grant_title_key") or None,
                seed.get("badge_label") or "",
                seed.get("image_path") or "",
                int(seed.get("sort_order") or 0),
                now_text,
                now_text,
            ),
        )
        created_count += int(cur.rowcount or 0)
    return {"created_count": created_count}


def get_faction_shop_items(db, *, include_inactive=False):
    where = "" if include_inactive else "WHERE is_active = 1"
    rows = db.execute(
        f"""
        SELECT *
        FROM faction_shop_items
        {where}
        ORDER BY sort_order ASC, id ASC
        """
    ).fetchall()
    return [_faction_shop_item_view_row(row) for row in rows]


def _get_faction_shop_item_row(db, item_id):
    return db.execute("SELECT * FROM faction_shop_items WHERE id = ? LIMIT 1", (int(item_id),)).fetchone()


def get_user_faction_shop_purchases(db, user_id):
    rows = db.execute(
        """
        SELECT p.*, i.item_name, i.description, i.item_type, i.badge_label, i.image_path
        FROM user_faction_shop_purchases p
        JOIN faction_shop_items i ON i.id = p.item_id
        WHERE p.user_id = ?
        ORDER BY p.purchased_at DESC, p.id DESC
        """,
        (int(user_id),),
    ).fetchall()
    equipped = get_user_equipped_faction_shop_items(db, user_id)
    result = []
    for row in rows:
        slot = equipped.get(str(row["item_key"]))
        result.append(
            {
                "id": int(row["id"]),
                "item_id": int(row["item_id"]),
                "item_key": row["item_key"],
                "item_name": row["item_name"],
                "description": row["description"] or "",
                "item_type": row["item_type"],
                "item_type_label": _faction_shop_item_type_label(row["item_type"]),
                "faction_key": _normalize_faction_key(row["faction_key"]) if row["faction_key"] else None,
                "price_paid_coins": int(row["price_paid_coins"] or 0),
                "purchased_at": row["purchased_at"],
                "badge_label": row["badge_label"] or "",
                "image_path": row["image_path"] or "",
                "equippable_slot": FACTION_SHOP_EQUIP_SLOTS.get(str(row["item_type"] or "")),
                "equipped_slot": slot,
            }
        )
    return result


def get_user_equipped_faction_shop_items(db, user_id):
    rows = db.execute(
        """
        SELECT e.*, i.item_name, i.item_type, i.badge_label, i.image_path
        FROM user_equipped_faction_shop_items e
        JOIN faction_shop_items i ON i.id = e.item_id
        WHERE e.user_id = ?
        """,
        (int(user_id),),
    ).fetchall()
    by_item_key = {}
    for row in rows:
        item = {
            "slot_key": row["slot_key"],
            "item_id": int(row["item_id"]),
            "item_key": row["item_key"],
            "item_name": row["item_name"],
            "item_type": row["item_type"],
            "badge_label": row["badge_label"] or row["item_name"],
            "image_path": row["image_path"] or "",
        }
        by_item_key[str(row["item_key"])] = item
        by_item_key[str(row["slot_key"])] = item
    return by_item_key


def _faction_shop_current_seconds():
    return int(time.time())


def _faction_shop_parse_time(value):
    text = str(value or "").strip()
    if not text:
        return None
    for fmt in ("%Y-%m-%d %H:%M:%S", "%Y-%m-%d"):
        try:
            return int(datetime.strptime(text, fmt).timestamp())
        except ValueError:
            continue
    return None


def _user_has_faction_title(db, user_id, title_key):
    return bool(
        db.execute(
            "SELECT 1 FROM user_faction_titles WHERE user_id = ? AND title_key = ? LIMIT 1",
            (int(user_id), str(title_key)),
        ).fetchone()
    )


def _user_is_guardian_author(db, user_id):
    if _user_has_faction_title(db, user_id, "guardian_author"):
        return True
    return bool(
        db.execute(
            "SELECT 1 FROM faction_guardians WHERE author_user_id = ? LIMIT 1",
            (int(user_id),),
        ).fetchone()
    )


def can_purchase_faction_shop_item(db, user_id, item_id):
    user = db.execute("SELECT * FROM users WHERE id = ? LIMIT 1", (int(user_id),)).fetchone()
    if not user:
        return {"ok": False, "reason": "ユーザーが見つかりません。"}
    item = _get_faction_shop_item_row(db, item_id)
    if not item or int(item["is_active"] or 0) != 1:
        return {"ok": False, "reason": "この商品は現在交換できません。"}
    now_ts = _faction_shop_current_seconds()
    if int(item["is_limited"] or 0) == 1:
        starts_at = _faction_shop_parse_time(item["starts_at"])
        ends_at = _faction_shop_parse_time(item["ends_at"])
        if starts_at and now_ts < starts_at:
            return {"ok": False, "reason": "この商品の交換期間はまだ始まっていません。"}
        if ends_at and now_ts > ends_at:
            return {"ok": False, "reason": "この商品の交換期間は終了しました。"}
    if db.execute("SELECT 1 FROM user_faction_shop_purchases WHERE user_id = ? AND item_key = ? LIMIT 1", (int(user_id), item["item_key"])).fetchone():
        return {"ok": False, "reason": "すでに購入済みです。"}
    price = max(0, int(item["price_coins"] or 0))
    if int(user["coins"] or 0) < price:
        return {"ok": False, "reason": "コインが不足しています。"}
    user_faction = _normalize_faction_key(user["faction"] if "faction" in user.keys() else None)
    item_faction = _normalize_faction_key(item["faction_key"]) if item["faction_key"] else None
    if not user_faction:
        return {"ok": False, "reason": "研究方針を選ぶと陣営ショップを利用できます。"}
    if item_faction and user_faction != item_faction:
        return {"ok": False, "reason": f"この商品は{FACTION_LABELS.get(item_faction, item_faction)}所属研究員向けです。"}
    required_level = int(item["required_facility_level"] or 0)
    if required_level > 0:
        ensure_faction_facilities(db)
        facility = db.execute("SELECT level FROM faction_facilities WHERE faction_key = ? LIMIT 1", (item_faction or user_faction,)).fetchone()
        if not facility or int(facility["level"] or 0) < required_level:
            return {"ok": False, "reason": "施設レベルが足りません。"}
    if item["required_title_key"] and not _user_has_faction_title(db, user_id, item["required_title_key"]):
        return {"ok": False, "reason": "必要な称号をまだ獲得していません。"}
    if item["required_event_key"]:
        if not db.execute(
            """
            SELECT 1 FROM faction_weekly_events
            WHERE event_key = ? AND status IN ('active', 'finalized')
            LIMIT 1
            """,
            (item["required_event_key"],),
        ).fetchone():
            return {"ok": False, "reason": "必要な陣営イベントの記録がまだありません。"}
    required_territory = int(item["required_territory_count"] or 0)
    if required_territory > 0:
        summary = get_faction_territory_summary(db, user_faction, _world_week_key())
        if int((summary or {}).get("controlled_count") or 0) < required_territory:
            return {"ok": False, "reason": "研究影響エリア数が足りません。"}
    if int(item["required_guardian_author"] or 0) == 1 and not _user_is_guardian_author(db, user_id):
        return {"ok": False, "reason": "守護機作者向けの商品です。"}
    return {"ok": True, "reason": "交換できます。", "item": _faction_shop_item_view_row(item), "user_coins": int(user["coins"] or 0)}


def purchase_faction_shop_item(db, user_id, item_id):
    check = can_purchase_faction_shop_item(db, user_id, item_id)
    if not check["ok"]:
        return {"ok": False, "reason": check["reason"]}
    item = _get_faction_shop_item_row(db, item_id)
    price = max(0, int(item["price_coins"] or 0))
    now_text = now_str()
    try:
        cur = db.execute(
            "UPDATE users SET coins = COALESCE(coins, 0) - ? WHERE id = ? AND COALESCE(coins, 0) >= ?",
            (price, int(user_id), price),
        )
        if int(cur.rowcount or 0) != 1:
            db.rollback()
            return {"ok": False, "reason": "コインが不足しています。"}
        db.execute(
            """
            INSERT INTO user_faction_shop_purchases
            (user_id, item_id, item_key, faction_key, price_paid_coins, purchased_at, created_at)
            VALUES (?, ?, ?, ?, ?, ?, ?)
            """,
            (
                int(user_id),
                int(item["id"]),
                item["item_key"],
                _normalize_faction_key(item["faction_key"]) if item["faction_key"] else None,
                price,
                now_text,
                now_text,
            ),
        )
    except sqlite3.IntegrityError:
        db.rollback()
        return {"ok": False, "reason": "すでに購入済みです。"}
    title_result = None
    if str(item["item_type"] or "") == "title_ticket" and item["grant_title_key"]:
        title_result = grant_user_faction_title(
            db,
            int(user_id),
            _normalize_faction_key(item["faction_key"]) or db.execute("SELECT faction FROM users WHERE id = ?", (int(user_id),)).fetchone()["faction"],
            str(item["grant_title_key"]),
            week_key="shop",
            source_type="shop",
            source_id=int(item["id"]),
            equip_if_first=True,
        )
    row = db.execute(
        "SELECT * FROM user_faction_shop_purchases WHERE user_id = ? AND item_key = ? LIMIT 1",
        (int(user_id), item["item_key"]),
    ).fetchone()
    after = db.execute("SELECT coins FROM users WHERE id = ? LIMIT 1", (int(user_id),)).fetchone()
    return {
        "ok": True,
        "reason": "交換しました。",
        "purchase_id": int(row["id"]) if row else None,
        "item": _faction_shop_item_view_row(item, purchased=True),
        "price_paid_coins": price,
        "coins_after": int(after["coins"] or 0) if after else 0,
        "title_result": title_result,
    }


def equip_faction_shop_item(db, user_id, purchase_id, slot_key):
    purchase = db.execute(
        """
        SELECT p.*, i.item_type
        FROM user_faction_shop_purchases p
        JOIN faction_shop_items i ON i.id = p.item_id
        WHERE p.id = ? AND p.user_id = ?
        LIMIT 1
        """,
        (int(purchase_id), int(user_id)),
    ).fetchone()
    if not purchase:
        return {"ok": False, "reason": "購入済みアイテムが見つかりません。"}
    expected_slot = FACTION_SHOP_EQUIP_SLOTS.get(str(purchase["item_type"] or ""))
    chosen_slot = str(slot_key or "").strip()
    if not expected_slot or chosen_slot != expected_slot:
        return {"ok": False, "reason": "このアイテムはその枠に装備できません。"}
    now_text = now_str()
    db.execute(
        """
        INSERT INTO user_equipped_faction_shop_items
        (user_id, slot_key, item_id, item_key, equipped_at, updated_at)
        VALUES (?, ?, ?, ?, ?, ?)
        ON CONFLICT(user_id, slot_key) DO UPDATE SET
            item_id = excluded.item_id,
            item_key = excluded.item_key,
            equipped_at = excluded.equipped_at,
            updated_at = excluded.updated_at
        """,
        (int(user_id), chosen_slot, int(purchase["item_id"]), purchase["item_key"], now_text, now_text),
    )
    return {"ok": True, "reason": "装備しました。", "item_key": purchase["item_key"], "slot_key": chosen_slot, "item_id": int(purchase["item_id"])}


def _insert_faction_weekly_quest_log(db, week_key, faction_key, quest_id, action, payload=None):
    db.execute(
        """
        INSERT INTO faction_weekly_quest_logs
        (week_key, faction_key, quest_id, action, payload_json, created_at)
        VALUES (?, ?, ?, ?, ?, ?)
        """,
        (
            str(week_key),
            _normalize_faction_key(faction_key) if faction_key else None,
            int(quest_id) if quest_id else None,
            str(action),
            json.dumps(payload or {}, ensure_ascii=False),
            now_str(),
        ),
    )


def _faction_weekly_quest_view_row(db, row, *, user_id=None):
    if not row:
        return None
    current = max(0, int(row["current_value"] or 0))
    target = max(1, int(row["target_value"] or 1))
    participant = None
    if user_id:
        participant = db.execute(
            "SELECT * FROM faction_weekly_quest_participants WHERE quest_id = ? AND user_id = ? LIMIT 1",
            (int(row["id"]), int(user_id)),
        ).fetchone()
    participant_count = db.execute(
        "SELECT COUNT(*) AS c FROM faction_weekly_quest_participants WHERE quest_id = ? AND contribution_value > 0",
        (int(row["id"]),),
    ).fetchone()["c"]
    return {
        "id": int(row["id"]),
        "week_key": row["week_key"],
        "faction_key": _normalize_faction_key(row["faction_key"]),
        "faction_name": FACTION_LABELS.get(_normalize_faction_key(row["faction_key"]), row["faction_key"]),
        "quest_key": row["quest_key"],
        "quest_name": row["quest_name"],
        "description": row["description"] or "",
        "quest_type": row["quest_type"],
        "target_value": target,
        "current_value": current,
        "progress_percent": min(100, int(math.floor(current * 100 / target))),
        "reward_coins": int(row["reward_coins"] or 0),
        "reward_facility_material": int(row["reward_facility_material"] or 0),
        "reward_title_key": row["reward_title_key"] or "",
        "status": row["status"],
        "completed_at": row["completed_at"],
        "finalized_at": row["finalized_at"],
        "participant_count": int(participant_count or 0),
        "my_contribution": int(participant["contribution_value"] or 0) if participant else 0,
        "reward_claimed": bool(int(participant["reward_claimed"] or 0)) if participant else False,
        "can_claim": bool(participant and int(participant["contribution_value"] or 0) > 0 and int(participant["reward_claimed"] or 0) == 0 and row["status"] in ("completed", "finalized")),
    }


def get_faction_weekly_quests(db, week_key=None, faction_key=None, *, user_id=None):
    wk = str(week_key or _world_week_key())
    key = _normalize_faction_key(faction_key)
    if key:
        rows = db.execute(
            """
            SELECT * FROM faction_weekly_quests
            WHERE week_key = ? AND faction_key = ?
            ORDER BY id ASC
            """,
            (wk, key),
        ).fetchall()
    else:
        rows = db.execute(
            """
            SELECT * FROM faction_weekly_quests
            WHERE week_key = ?
            ORDER BY faction_key ASC, id ASC
            """,
            (wk,),
        ).fetchall()
    return [_faction_weekly_quest_view_row(db, row, user_id=user_id) for row in rows]


def generate_faction_weekly_quests(db, week_key=None, overwrite=False):
    wk = str(week_key or _world_week_key())
    _world_week_bounds(wk)
    current_event = get_current_faction_weekly_event(db, wk)
    event_key = (current_event or {}).get("event_key") or "default"
    quest_keys = FACTION_WEEKLY_QUEST_EVENT_KEYS.get(event_key, FACTION_WEEKLY_QUEST_EVENT_KEYS["default"])
    now_text = now_str()
    created_count = 0
    skipped_count = 0
    if overwrite:
        db.execute("DELETE FROM faction_weekly_quest_participants WHERE quest_id IN (SELECT id FROM faction_weekly_quests WHERE week_key = ?)", (wk,))
        db.execute("DELETE FROM faction_weekly_quests WHERE week_key = ?", (wk,))
    for faction_key in FACTION_KEYS:
        for quest_key in quest_keys:
            quest_def = FACTION_WEEKLY_QUEST_DEFINITIONS[quest_key]
            cur = db.execute(
                """
                INSERT OR IGNORE INTO faction_weekly_quests
                (week_key, faction_key, quest_key, quest_name, description, quest_type, target_value,
                 current_value, reward_coins, reward_facility_material, reward_title_key, status,
                 created_at, updated_at)
                VALUES (?, ?, ?, ?, ?, ?, ?, 0, ?, ?, ?, 'active', ?, ?)
                """,
                (
                    wk,
                    faction_key,
                    quest_key,
                    quest_def["quest_name"],
                    quest_def["description"],
                    quest_def["quest_type"],
                    int(quest_def["base_target"]),
                    int(quest_def["reward_coins"]),
                    int(quest_def["reward_facility_material"]),
                    quest_def.get("reward_title_key"),
                    now_text,
                    now_text,
                ),
            )
            if int(cur.rowcount or 0) == 1:
                created_count += 1
                row = db.execute("SELECT id FROM faction_weekly_quests WHERE week_key = ? AND faction_key = ? AND quest_key = ?", (wk, faction_key, quest_key)).fetchone()
                _insert_faction_weekly_quest_log(db, wk, faction_key, int(row["id"]), "generate", {"event_key": event_key, "quest_key": quest_key})
            else:
                skipped_count += 1
    return {"week_key": wk, "event_key": event_key, "created_count": created_count, "skipped_count": skipped_count}


def _emit_faction_weekly_quest_completed_once(db, quest_row):
    existing = db.execute(
        """
        SELECT 1 FROM world_events_log
        WHERE event_type = ?
          AND json_extract(payload_json, '$.quest_id') = ?
        LIMIT 1
        """,
        (FACTION_WEEKLY_QUEST_COMPLETED_EVENT_TYPE, int(quest_row["id"])),
    ).fetchone()
    if existing:
        return False
    faction_key = _normalize_faction_key(quest_row["faction_key"])
    _world_event_log(
        db,
        FACTION_WEEKLY_QUEST_COMPLETED_EVENT_TYPE,
        {
            "week_key": quest_row["week_key"],
            "faction_key": faction_key,
            "faction_name": FACTION_LABELS.get(faction_key, faction_key),
            "quest_id": int(quest_row["id"]),
            "quest_key": quest_row["quest_key"],
            "quest_name": quest_row["quest_name"],
            "current_value": int(quest_row["current_value"] or 0),
            "target_value": int(quest_row["target_value"] or 0),
        },
    )
    return True


def add_faction_quest_progress(db, user_id, faction_key, quest_type, amount, source_event_type=None, source_event_id=None, week_key=None):
    uid = int(user_id or 0)
    key = _normalize_faction_key(faction_key)
    qtype = str(quest_type or "").strip()
    value = max(0, int(amount or 0))
    wk = str(week_key or _world_week_key())
    if uid <= 0 or not key or not qtype or value <= 0:
        return {"updated_count": 0, "completed_count": 0}
    rows = db.execute(
        """
        SELECT * FROM faction_weekly_quests
        WHERE week_key = ? AND faction_key = ? AND quest_type = ? AND status IN ('active', 'completed')
        ORDER BY id ASC
        """,
        (wk, key, qtype),
    ).fetchall()
    updated = 0
    completed = 0
    for row in rows:
        before_status = row["status"]
        new_value = int(row["current_value"] or 0) + value
        new_status = "completed" if new_value >= int(row["target_value"] or 0) else before_status
        completed_at = now_str() if before_status != "completed" and new_status == "completed" else row["completed_at"]
        db.execute(
            """
            UPDATE faction_weekly_quests
            SET current_value = ?, status = ?, completed_at = ?, updated_at = ?
            WHERE id = ?
            """,
            (new_value, new_status, completed_at, now_str(), int(row["id"])),
        )
        db.execute(
            """
            INSERT INTO faction_weekly_quest_participants
            (week_key, faction_key, quest_id, user_id, contribution_value, reward_claimed, created_at, updated_at)
            VALUES (?, ?, ?, ?, ?, 0, ?, ?)
            ON CONFLICT(quest_id, user_id) DO UPDATE SET
                contribution_value = contribution_value + excluded.contribution_value,
                updated_at = excluded.updated_at
            """,
            (wk, key, int(row["id"]), uid, value, now_str(), now_str()),
        )
        _insert_faction_weekly_quest_log(db, wk, key, int(row["id"]), "progress", {"user_id": uid, "quest_type": qtype, "amount": value, "source_event_type": source_event_type, "source_event_id": source_event_id})
        updated += 1
        if before_status != "completed" and new_status == "completed":
            completed += 1
            quest = db.execute("SELECT * FROM faction_weekly_quests WHERE id = ?", (int(row["id"]),)).fetchone()
            _insert_faction_weekly_quest_log(db, wk, key, int(row["id"]), "complete", {"current_value": new_value})
            _emit_faction_weekly_quest_completed_once(db, quest)
    return {"updated_count": updated, "completed_count": completed}


def sync_faction_territory_quest_progress(db, week_key, totals_by_faction):
    wk = str(week_key or _world_week_key())
    updated = 0
    completed = 0
    for faction_key, total_score in (totals_by_faction or {}).items():
        key = _normalize_faction_key(faction_key)
        if not key:
            continue
        value = max(0, int(total_score or 0))
        rows = db.execute(
            """
            SELECT * FROM faction_weekly_quests
            WHERE week_key = ? AND faction_key = ? AND quest_type = 'territory_score' AND status IN ('active', 'completed')
            ORDER BY id ASC
            """,
            (wk, key),
        ).fetchall()
        for row in rows:
            before_status = row["status"]
            new_status = "completed" if value >= int(row["target_value"] or 0) else before_status
            completed_at = now_str() if before_status != "completed" and new_status == "completed" else row["completed_at"]
            db.execute(
                """
                UPDATE faction_weekly_quests
                SET current_value = ?, status = ?, completed_at = ?, updated_at = ?
                WHERE id = ?
                """,
                (value, new_status, completed_at, now_str(), int(row["id"])),
            )
            _insert_faction_weekly_quest_log(
                db,
                wk,
                key,
                int(row["id"]),
                "progress",
                {"quest_type": "territory_score", "amount": value, "source_event_type": "faction_territory_score_sync"},
            )
            updated += 1
            if before_status != "completed" and new_status == "completed":
                completed += 1
                quest = db.execute("SELECT * FROM faction_weekly_quests WHERE id = ?", (int(row["id"]),)).fetchone()
                _insert_faction_weekly_quest_log(db, wk, key, int(row["id"]), "complete", {"current_value": value})
                _emit_faction_weekly_quest_completed_once(db, quest)
    return {"updated_count": updated, "completed_count": completed}


def claim_faction_weekly_quest_reward(db, user_id, quest_id):
    uid = int(user_id or 0)
    quest = db.execute("SELECT * FROM faction_weekly_quests WHERE id = ? LIMIT 1", (int(quest_id),)).fetchone()
    if not quest or quest["status"] not in ("completed", "finalized"):
        return {"ok": False, "reason": "このクエスト報酬はまだ受け取れません。"}
    user = db.execute("SELECT id, faction FROM users WHERE id = ? LIMIT 1", (uid,)).fetchone()
    user_faction = _normalize_faction_key(user["faction"] if user else None)
    if user_faction != _normalize_faction_key(quest["faction_key"]):
        return {"ok": False, "reason": "所属陣営のクエスト報酬だけ受け取れます。"}
    participant = db.execute("SELECT * FROM faction_weekly_quest_participants WHERE quest_id = ? AND user_id = ? LIMIT 1", (int(quest_id), uid)).fetchone()
    if not participant or int(participant["contribution_value"] or 0) <= 0:
        return {"ok": False, "reason": "このクエストに貢献した研究員だけ報酬を受け取れます。"}
    if int(participant["reward_claimed"] or 0) == 1:
        return {"ok": False, "reason": "この報酬は受け取り済みです。"}
    reward_coins = max(0, int(quest["reward_coins"] or 0))
    reward_material = max(0, int(quest["reward_facility_material"] or 0))
    now_text = now_str()
    if reward_coins:
        db.execute("UPDATE users SET coins = COALESCE(coins, 0) + ? WHERE id = ?", (reward_coins, uid))
    material_result = None
    if reward_material:
        material_result = grant_faction_facility_material(db, user_faction, uid, "faction_weekly_quest_reward", int(quest_id), reward_material, week_key=quest["week_key"])
    if quest["reward_title_key"]:
        grant_user_faction_title(db, uid, user_faction, quest["reward_title_key"], week_key=quest["week_key"], source_type="quest", source_id=int(quest_id), equip_if_first=True)
    db.execute(
        "UPDATE faction_weekly_quest_participants SET reward_claimed = 1, reward_claimed_at = ?, updated_at = ? WHERE id = ?",
        (now_text, now_text, int(participant["id"])),
    )
    _insert_faction_weekly_quest_log(db, quest["week_key"], user_faction, int(quest_id), "reward_claim", {"user_id": uid, "reward_coins": reward_coins, "reward_facility_material": reward_material})
    after = db.execute("SELECT coins FROM users WHERE id = ? LIMIT 1", (uid,)).fetchone()
    return {"ok": True, "reward_coins": reward_coins, "reward_facility_material": reward_material, "coins_after": int(after["coins"] or 0), "material_result": material_result}


def finalize_faction_weekly_quests(db, week_key=None):
    wk = str(week_key or _world_week_key())
    now_text = now_str()
    db.execute("UPDATE faction_weekly_quests SET status = 'finalized', finalized_at = COALESCE(finalized_at, ?), updated_at = ? WHERE week_key = ? AND status = 'completed'", (now_text, now_text, wk))
    counts = {}
    for faction_key in FACTION_KEYS:
        counts[faction_key] = int(db.execute("SELECT COUNT(*) AS c FROM faction_weekly_quests WHERE week_key = ? AND faction_key = ? AND status IN ('completed', 'finalized')", (wk, faction_key)).fetchone()["c"] or 0)
    existing = db.execute(
        "SELECT 1 FROM world_events_log WHERE event_type = ? AND json_extract(payload_json, '$.week_key') = ? LIMIT 1",
        (FACTION_WEEKLY_QUEST_RESULT_EVENT_TYPE, wk),
    ).fetchone()
    emitted = False
    if not existing:
        _world_event_log(db, FACTION_WEEKLY_QUEST_RESULT_EVENT_TYPE, {"week_key": wk, "completed_counts": counts})
        emitted = True
    _insert_faction_weekly_quest_log(db, wk, None, None, "finalize", {"completed_counts": counts, "emitted_world_event": emitted})
    return {"week_key": wk, "completed_counts": counts, "emitted_world_event": emitted}


def cancel_faction_weekly_quest(db, quest_id):
    quest = db.execute("SELECT * FROM faction_weekly_quests WHERE id = ? LIMIT 1", (int(quest_id),)).fetchone()
    if not quest:
        raise ValueError("quest not found")
    db.execute("UPDATE faction_weekly_quests SET status = 'cancelled', updated_at = ? WHERE id = ?", (now_str(), int(quest_id)))
    _insert_faction_weekly_quest_log(db, quest["week_key"], quest["faction_key"], int(quest_id), "cancel")
    return _faction_weekly_quest_view_row(db, db.execute("SELECT * FROM faction_weekly_quests WHERE id = ?", (int(quest_id),)).fetchone())


