def _home_next_action_card(
    db,
    user,
    boss_alert_status,
    max_unlocked_layer,
    new_layer_badge,
    unlocked_layer_recent,
    faction_status=None,
    total_explores=0,
):
    robot_count = int(
        db.execute(
            "SELECT COUNT(*) AS c FROM robot_instances WHERE user_id = ? AND status != 'decomposed'",
            (user["id"],),
        ).fetchone()["c"]
        or 0
    )
    has_any_robot = robot_count > 0
    if not has_any_robot:
        return {
            "title": "Next Action",
            "desc": "まずは機体を1体完成させよう",
            "cta_label": "組み立てる",
            "cta_url": url_for("build"),
            "is_post": False,
            "area_key": None,
            "boss_enter": False,
        }
    if _get_active_robot(db, user["id"]) is None:
        return {
            "title": "Next Action",
            "desc": "出撃機体が未設定です",
            "cta_label": "組み立てる",
            "cta_url": url_for("build"),
            "is_post": False,
            "area_key": None,
            "boss_enter": False,
        }
    if boss_alert_status:
        alert = boss_alert_status[0]
        remain = "●" * max(1, int(alert.get("attempts_left") or 0))
        return {
            "title": "Next Action",
            "desc": "ボス警報が発令中",
            "cta_label": f"ボスに挑戦（残り{remain}）",
            "cta_url": url_for("explore"),
            "is_post": True,
            "area_key": alert["area_key"],
            "boss_enter": True,
        }
    tutorial_layer1_card = _tutorial_layer1_home_next_action_card(db, user)
    if tutorial_layer1_card:
        return tutorial_layer1_card
    unlocked_layer = int(new_layer_badge or 0) or int(unlocked_layer_recent or 0)
    if unlocked_layer:
        return {
            "title": "Next Action",
            "desc": "新しい層が開いた",
            "cta_label": f"NEW 第{unlocked_layer}層へ行く",
            "cta_url": url_for("map_view"),
            "is_post": False,
            "area_key": None,
            "boss_enter": False,
        }
    current_layer = max(1, min(MAX_UNLOCKABLE_LAYER, int(max_unlocked_layer or 1)))
    area_key = HOME_PRIMARY_AREA_BY_LAYER.get(current_layer, "layer_1")
    if current_layer == 1:
        if int(total_explores or 0) <= 0:
            return {
                "title": "Next Action",
                "desc": "最初の出撃へ。まずは第1層で1勝しよう",
                "cta_label": "第1層へ出撃",
                "cta_url": url_for("explore"),
                "is_post": True,
                "area_key": "layer_1",
                "boss_enter": False,
            }
        if _home_fuse_ready(db, int(user["id"])):
            return {
                "title": "Next Action",
            "desc": "同じパーツが3個そろいました。ベースを残して素材2個で強化できます。",
                "cta_label": "強化する",
                "cta_url": url_for("parts_strengthen", mode="select"),
                "is_post": False,
                "area_key": None,
                "boss_enter": False,
            }
        if _home_build_ready(db, int(user["id"])):
            return {
                "title": "Next Action",
                "desc": "今のロボを残したまま、新しいロボを組み立てられます。",
                "cta_label": "組み立てる",
                "cta_url": url_for("build"),
                "is_post": False,
                "area_key": None,
                "boss_enter": False,
            }
        if robot_count >= 2:
            return {
                "title": "Next Action",
                "desc": "作ったロボを見てみよう",
                "cta_label": "ロボ一覧を見る",
                "cta_url": url_for("robots"),
                "is_post": False,
                "area_key": None,
                "boss_enter": False,
            }
        return {
            "title": "Next Action",
            "desc": "まずは出撃してパーツを集めましょう。同じパーツが3個そろうと強化できます。",
            "cta_label": "出撃",
            "cta_url": url_for("explore"),
            "is_post": True,
            "area_key": area_key,
            "boss_enter": False,
        }
    if (
        current_layer >= 4
        and _is_special_area_unlocked(db, int(user["id"]), LAYER4_FINAL_AREA_KEY)
        and not _has_fixed_boss_defeat_in_area(db, int(user["id"]), LAYER4_FINAL_AREA_KEY)
    ):
        return {
            "title": "Next Action",
            "desc": "第4層最終試験が解放中",
            "cta_label": "アーク=ゼロに挑む",
            "cta_url": url_for("explore"),
            "is_post": True,
            "area_key": LAYER4_FINAL_AREA_KEY,
            "boss_enter": False,
        }
    if (
        current_layer >= 5
        and _is_special_area_unlocked(db, int(user["id"]), LAYER5_FINAL_AREA_KEY)
        and not _has_fixed_boss_defeat_in_area(db, int(user["id"]), LAYER5_FINAL_AREA_KEY)
    ):
        return {
            "title": "Next Action",
            "desc": "第5層最終試験が解放中",
            "cta_label": "オメガフレームに挑む",
            "cta_url": url_for("explore"),
            "is_post": True,
            "area_key": LAYER5_FINAL_AREA_KEY,
            "boss_enter": False,
        }
    if current_layer < MAX_UNLOCKABLE_LAYER:
        return {
            "title": "Next Action",
            "desc": f"{_layer_label(current_layer)}の代表エリアへ",
            "cta_label": f"第{current_layer}層ボスを狙う",
            "cta_url": url_for("explore"),
            "is_post": True,
            "area_key": area_key,
            "boss_enter": False,
        }
    if _home_fuse_ready(db, int(user["id"])):
        return {
            "title": "Next Action",
            "desc": "同じパーツ3個で +1",
            "cta_label": "強化する",
            "cta_url": url_for("parts_strengthen", mode="select"),
            "is_post": False,
            "area_key": None,
            "boss_enter": False,
        }
    return {
        "title": "Next Action",
        "desc": f"{_layer_label(current_layer)}を周回",
        "cta_label": "出撃",
        "cta_url": url_for("explore"),
        "is_post": True,
        "area_key": area_key,
        "boss_enter": False,
    }


def _recent_drop_items(db, user_id, limit=5):
    start_ts, _ = _jst_day_bounds()
    rows = db.execute(
        """
        SELECT id, created_at, payload_json
        FROM world_events_log
        WHERE user_id = ?
          AND event_type = 'audit.drop'
          AND created_at >= ?
        ORDER BY id DESC
        LIMIT ?
        """,
        (user_id, start_ts, int(limit)),
    ).fetchall()
    if not rows:
        rows = db.execute(
            """
            SELECT id, created_at, payload_json
            FROM world_events_log
            WHERE user_id = ?
              AND event_type = 'audit.drop'
              AND created_at >= ?
            ORDER BY id DESC
            LIMIT ?
            """,
            (user_id, int(time.time()) - 86400, int(limit)),
        ).fetchall()

    items = []
    for r in rows:
        try:
            payload = json.loads(r["payload_json"] or "{}")
        except json.JSONDecodeError:
            payload = {}
        part_key = payload.get("part_key")
        part_type = payload.get("part_type")
        rarity = payload.get("rarity")
        plus = int(payload.get("plus") or 0)
        part_row = _get_part_by_key(db, part_key) if part_key else None
        display_name = _part_display_name_ja(part_row) if part_row else (part_key or "-")
        items.append(
            {
                "part_type": part_type,
                "part_key": part_key,
                "part_display_name": display_name,
                "rarity": rarity,
                "plus": plus,
                "element": ((part_row["element"] if part_row else None) or "-"),
                "image_url": url_for("static", filename=_part_image_rel(part_row)),
                "link": url_for("parts", tab="instances"),
            }
        )
    return items


