def _format_jst_ts(ts):
    if not ts:
        return "-"
    return datetime.fromtimestamp(int(ts), JST).strftime("%Y-%m-%d %H:%M")


def _parse_jst_day_filter(raw_value, *, end=False):
    text = str(raw_value or "").strip()
    if not text:
        return None
    try:
        base = datetime.strptime(text, "%Y-%m-%d").replace(tzinfo=JST)
    except ValueError:
        return None
    if end:
        base = base + timedelta(days=1)
    return int(base.timestamp())


def _feed_user_label(db, user_id):
    if user_id is None:
        return "SYSTEM"
    row = db.execute("SELECT id, username, is_admin FROM users WHERE id = ?", (int(user_id),)).fetchone()
    if row and row["username"]:
        return _display_username_for_user_row(db, row)
    return f"User#{int(user_id)}"


def _supporter_crown_mark_for_user(db, user_id):
    uid = int(user_id or 0)
    if uid <= 0:
        return ""
    trophy_keys = set(_get_user_trophy_keys(db, uid))
    if _user_has_decor_key(db, uid, SUPPORT_PACK_LAB_DECOR_KEY):
        trophy_keys.add(SUPPORTER_LAB_TROPHY_KEY)
    if _user_has_any_decor_key(db, uid, (SUPPORT_PACK_DECOR_KEY, LEGACY_SUPPORT_PACK_DECOR_KEY)):
        trophy_keys.add(SUPPORTER_FOUNDER_TROPHY_KEY)
    if SUPPORTER_LAB_TROPHY_KEY in trophy_keys:
        return "👑+"
    if SUPPORTER_FOUNDER_TROPHY_KEY in trophy_keys:
        return "👑"
    return ""


def _feed_user_label_with_supporter_mark(db, user_id, fallback=None):
    label = str(fallback or _feed_user_label(db, user_id) or "SYSTEM").strip() or "SYSTEM"
    mark = _supporter_crown_mark_for_user(db, user_id)
    if mark and not label.lstrip().startswith("👑"):
        return f"{mark} {label}"
    return label


def _part_image_url(part_row):
    return url_for("static", filename=_part_image_rel(part_row))


def _feed_enemy_row(db, row, payload):
    enemy_key = str(payload.get("enemy_key") or "").strip()
    entity_type = str((row["entity_type"] if "entity_type" in row.keys() else "") or "").strip().lower()
    entity_id = row["entity_id"] if "entity_id" in row.keys() else None
    enemy_id = int(entity_id) if entity_type == "enemy" and entity_id else None
    return _resolve_enemy_display_row(
        db,
        enemy_key=enemy_key,
        enemy_id=enemy_id,
        enemy_name=str(payload.get("enemy_name") or "").strip(),
    )


def _feed_card_from_event(db, row):
    payload_raw = row["payload_json"] if "payload_json" in row.keys() else None
    try:
        payload = json.loads(payload_raw or "{}")
    except json.JSONDecodeError:
        payload = {}
    event_type = row["event_type"]
    card = {
        "id": int(row["id"]),
        "created_ts": int(row["created_at"] or 0),
        "event_type": event_type,
        "user_id": (int(row["user_id"]) if row["user_id"] is not None else None),
        "user_label": (
            _feed_user_label_with_supporter_mark(db, row["user_id"])
            if "user_id" in row.keys()
            else "SYSTEM"
        ),
        "time_jst": _format_jst_ts(row["created_at"]),
        "text": event_type,
        "image_url": None,
        "link_url": None,
        "headline": "WORLD LOG",
        "accent": "default",
        "meta_lines": [],
    }
    if event_type == AUDIT_EVENT_TYPES["BOSS_DEFEAT"]:
        actor_label = card["user_label"]
        boss_name = str(payload.get("enemy_name") or "").strip() or "ボス"
        robot_name = str(payload.get("robot_name") or "").strip()
        robot_instance_id = int(payload.get("robot_instance_id") or 0)
        story_suffix = robot_story_suffix(db, robot_instance_id) if robot_instance_id > 0 else ""
        area_label = str(payload.get("area_label") or "").strip()
        if not area_label and payload.get("area_key"):
            area_label = _boss_area_label(payload.get("area_key"))
        card["headline"] = "BOSS DEFEATED"
        card["accent"] = "boss"
        if robot_name:
            card["text"] = f"ボス撃破: {actor_label} の {robot_name}{story_suffix} が {boss_name} を討伐"
            card["meta_lines"].append(f"機体: {robot_name}")
        else:
            card["text"] = f"ボス撃破: {actor_label} が {boss_name} を討伐"
        card["meta_lines"].append(f"対象: {boss_name}")
        if area_label:
            card["text"] += f"（{area_label}）"
            card["meta_lines"].append(f"戦域: {area_label}")
        enemy_row = _feed_enemy_row(db, row, payload)
        if enemy_row:
            card["image_url"] = _enemy_static_url(enemy_row["image_path"])
        if robot_instance_id > 0:
            card["link_url"] = url_for("robot_detail", instance_id=robot_instance_id)
    elif event_type in {"STYLE_RANK_UP", "STYLE_MASTER"}:
        actor_label = card["user_label"]
        robot_name = str(payload.get("robot_name") or "機体").strip() or "機体"
        style_label = str(payload.get("style_label") or ROBOT_STYLE_LABELS.get(payload.get("style_key"), "思想")).strip()
        rank_label = str(payload.get("new_rank_label") or payload.get("rank_label") or "IV").strip()
        card["headline"] = "STYLE MASTER" if event_type == "STYLE_MASTER" else "STYLE RANK"
        card["accent"] = "weekly"
        card["text"] = f"{actor_label} の「{robot_name}」が {style_label}思想 {rank_label} に到達"
        card["meta_lines"] = [f"思想: {style_label}", f"Rank: {rank_label}"]
        robot_instance_id = int(payload.get("robot_instance_id") or 0)
        if robot_instance_id > 0:
            card["link_url"] = url_for("robot_detail", instance_id=robot_instance_id)
    elif event_type == AUDIT_EVENT_TYPES["LAB_LEVEL_MILESTONE"]:
        actor_label = card["user_label"]
        level = int(payload.get("milestone_level") or payload.get("level_after") or 0)
        rank_label = str(payload.get("rank_after") or get_lab_rank_label(level)).strip()
        card["headline"] = "LAB LEVEL"
        card["accent"] = "weekly"
        card["text"] = f"{actor_label}研究室が Lv.{level} に到達。{rank_label}として記録庫に登録されました。"
        card["meta_lines"] = [f"らぼLv.{level}", f"研究員ランク: {rank_label}"]
        card["link_url"] = url_for("world_view")
    elif event_type in TOWER_WORLD_EVENT_TYPES:
        actor_label = str(payload.get("display_name") or payload.get("username") or card["user_label"]).strip() or card["user_label"]
        floor = int(payload.get("floor") or payload.get("reached_floor") or 0)
        previous = int(payload.get("previous_best_floor") or 0)
        env_name = str(payload.get("environment_display_name") or "").strip()
        robot_name = str(payload.get("robot_name") or "ロボ").strip() or "ロボ"
        card["headline"] = "ASTRAL SPIRE"
        card["accent"] = "weekly"
        if event_type == "TOWER_MILESTONE_REACHED":
            card["text"] = f"{actor_label} の {robot_name} が観測塔 {floor}階に到達しました。"
        elif event_type == "TOWER_WEEKLY_TOP":
            card["text"] = f"{actor_label} が今週の観測塔トップに立ちました。到達階数: {floor}階"
        elif event_type == "TOWER_ALL_TIME_RECORD":
            card["text"] = f"{actor_label} が観測塔の最高到達記録を更新しました。到達階数: {floor}階"
        else:
            card["text"] = f"{actor_label} が観測塔の自己記録を更新しました。到達階数: {floor}階"
        card["meta_lines"] = [f"最高到達: {floor}階"]
        if previous > 0 and event_type == "TOWER_PERSONAL_BEST":
            card["meta_lines"].append(f"前回の自己最高: {previous}階")
        if env_name:
            card["meta_lines"].append(f"環境: {env_name}")
        card["link_url"] = url_for("tower_ranking")
    elif event_type == AUDIT_EVENT_TYPES["LAB_MINI_CREATE"]:
        actor_label = card["user_label"]
        species_key = str(payload.get("species_key") or "cerberus")
        species = _mini_robot_species_row(db, species_key)
        species_name = species["name_ja"] if species else "ミニロボ"
