@app.context_processor
def inject_quick_nav():
    if _is_trial_session() or not session.get("user_id"):
        return {"quick_nav": None}
    try:
        endpoint = request.endpoint or ""
        hidden_endpoints = {
            "index",
            "login",
            "register",
            "explore",
            "battle_result",
            "terms",
            "privacy",
            "commerce",
            "contact",
            "support",
            "static",
        }
        if endpoint in hidden_endpoints or endpoint.startswith("admin"):
            return {"quick_nav": None}
        db = get_db()
        user = db.execute(
            """
            SELECT id, is_admin, active_robot_id, last_explore_area_key, max_unlocked_layer, part_inventory_limit
            FROM users
            WHERE id = ?
            """,
            (int(session["user_id"]),),
        ).fetchone()
        if not user:
            return {"quick_nav": None}
        remain, _ = _explore_remaining_seconds_for_user(db, user, int(user["id"]))
        is_admin = bool(int(user["is_admin"] or 0) == 1)
        available_areas = [a for a in EXPLORE_AREAS if _is_area_unlocked(user, a["key"], db=db)]
        area_key = _default_explore_area_key(user, available_areas, db=db)
        ct_remain = 0 if is_admin else max(0, int(remain or 0))
        server_now = int(time.time())
        part_inventory_status = _part_inventory_status_payload(db, int(user["id"]), user)
        return {
            "quick_nav": {
                "ct_remain": ct_remain,
                "ct_ready_at": server_now + int(ct_remain),
                "server_now": server_now,
                "area_key": area_key,
                "can_direct_explore": bool(area_key and user["active_robot_id"]),
                "explore_submission_id": (_issue_explore_submission_id() if area_key and user["active_robot_id"] else ""),
                "show_market": bool(_market_can_access(db, user)),
                "part_inventory_status": part_inventory_status,
            }
        }
    except Exception:
        return {"quick_nav": None}


@app.before_request
def apply_safe_mode():
    if "safe" in request.args:
        session["safe_mode"] = request.args.get("safe") == "1"


@app.before_request
def assign_request_id():
    g.request_id = request.headers.get("X-Request-ID") or str(uuid.uuid4())


@app.before_request
def enforce_trial_mode_scope():
    if request.endpoint == "static" or request.path.startswith("/static/"):
        return None
    if not _is_trial_session():
        return None
    endpoint = request.endpoint or ""
    if endpoint in {"register", "login", "trial_start", "trial_end"}:
        return None
    if endpoint != "trial_finish" and _trial_finish_reason():
        return redirect(url_for("trial_finish"))
    if endpoint in TRIAL_ALLOWED_ENDPOINTS:
        return None
    session["message"] = "お試しプレイではこの機能は使えません。無料で始めると続きの機能を使えます。"
    return redirect(url_for("home"))


@app.before_request
def enforce_banned_user_logout():
    if request.endpoint == "static" or request.path.startswith("/static/"):
        return None
    user_id = session.get("user_id")
    if not user_id:
        return None
    db = get_db()
    row = db.execute(
        "SELECT id, username, is_admin, is_banned FROM users WHERE id = ?",
        (int(user_id),),
    ).fetchone()
    if not row:
        session.clear()
        return redirect(url_for("login", reason="expired"))
    username = _display_username_for_user_row(db, row)
    if username and session.get("username") != username:
        session["username"] = username
    if int(row["is_banned"] or 0) != 1:
        return None
    session.clear()
    flash("このアカウントは利用停止されています。", "error")
    return redirect(url_for("login"))


@app.before_request
def enforce_maintenance_mode():
    if _is_trial_session() or request.endpoint in {"trial_start", "trial_finish", "trial_end"}:
        return None
    mode = _maintenance_mode()
    if mode == "off":
        return None
    if request.endpoint == "static" or request.path.startswith("/static/"):
        return None
    if _maintenance_is_admin_viewer():
        return None
    if mode == "full":
        if _maintenance_should_allow_full_request():
            return None
        db = get_db()
        _audit_maintenance_block(db, "full")
        db.commit()
        return _maintenance_block_response("full")
    if not _maintenance_should_block_partial_request():
        return None
    db = get_db()
    _audit_maintenance_block(db, "partial")
    db.commit()
    return _maintenance_block_response("partial")


@app.before_request
def touch_user_last_seen():
    if request.endpoint == "static" or request.path.startswith("/static/"):
        return None
    user_id = session.get("user_id")
    if not user_id:
        return None
    now = _now_ts()
    try:
        db = get_db()
        row = db.execute("SELECT last_seen_at FROM users WHERE id = ?", (int(user_id),)).fetchone()
        last_seen_at = int((row["last_seen_at"] if row else 0) or 0)
        if now - last_seen_at < int(LAST_SEEN_TOUCH_INTERVAL_SECONDS):
            return None
        db.execute("UPDATE users SET last_seen_at = ? WHERE id = ?", (now, int(user_id)))
        db.commit()
    except Exception:
        app.logger.exception("user.last_seen_touch_failed user_id=%s", user_id)
    return None


def _presence_context_for_request():
    path = request.path or ""
    if (
        request.endpoint == "static"
        or path.startswith("/static/")
        or path.startswith("/api/")
        or path.startswith("/admin")
        or path.startswith("/healthz")
    ):
        return None
    method = request.method.upper()
    if path == "/home":
        return {"surface": "home", "action_key": "home.view"}
    if path == "/explore" and method == "POST":
        return {"surface": "explore", "action_key": "explore.start"}
    if path.startswith("/parts"):
        return {"surface": "parts", "action_key": "parts.view"}
    if path == "/build" and method == "GET":
        return {"surface": "build", "action_key": "build.view"}
    if path == "/build":
        return {"surface": "build", "action_key": "build.edit"}
    if path.startswith("/build/confirm"):
        return {"surface": "build", "action_key": "build.confirm"}
    if path.startswith("/lab/showcase"):
        return {"surface": "lab", "action_key": "lab.showcase"}
    if path.startswith("/lab/race/watch") or "/race/watch/" in path:
        return {"surface": "lab", "action_key": "lab.race.watch"}
    if path.startswith("/lab/race"):
        return {"surface": "lab", "action_key": "lab.race"}
    if path.startswith("/lab"):
        return {"surface": "lab", "action_key": "lab.view"}
    if path.startswith("/comms/world"):
        return {"surface": "comms", "action_key": "chat.post" if method == "POST" else "comms.world"}
    if path.startswith("/comms/rooms"):
        return {"surface": "comms", "action_key": "chat.post" if method == "POST" else "comms.rooms"}
    if path.startswith("/comms"):
        return {"surface": "comms", "action_key": "comms.view"}
    if path.startswith("/showcase"):
        return {"surface": "showcase", "action_key": "showcase.view"}
    if path.startswith("/world"):
        return {"surface": "world", "action_key": "world.view"}
    if path.startswith("/records"):
        return {"surface": "records", "action_key": "records.view"}
    return None


@app.before_request
def touch_user_presence():
    context = _presence_context_for_request()
    if not context:
        return None
    user_id = session.get("user_id")
    if not user_id:
        return None
    try:
        db = get_db()
        user = db.execute(
            "SELECT id, active_robot_id FROM users WHERE id = ?",
            (int(user_id),),
        ).fetchone()
        if not user:
            return None
        touch_presence(
            db,
            int(user["id"]),
            context["surface"],
            context["action_key"],
            path=request.path,
            room_key=(request.values.get("room_key") or request.values.get("room")),
            robot_instance_id=(int(user["active_robot_id"]) if user["active_robot_id"] else None),
        )
        db.commit()
    except Exception:
        app.logger.exception("presence.touch_failed user_id=%s path=%s", user_id, request.path)
    return None


@app.before_request
def enforce_release_gates():
    if request.endpoint == "static" or request.path.startswith("/static/"):
        return None
    if not request.path.startswith("/lab"):
        return None
    if request.path.startswith("/lab/mini-shogi"):
        return None
    user_id = session.get("user_id")
    if not user_id:
        return None
    db = get_db()
    user = db.execute("SELECT id, is_admin FROM users WHERE id = ?", (int(user_id),)).fetchone()
    if not user:
        return None
    return _release_gate_redirect(db, "lab", user_row=user)


@app.before_request
def auto_close_faction_war_weekly():
    if request.endpoint in {"static"}:
        return None
    if _is_trial_session() or request.endpoint in {"trial_start", "trial_finish", "trial_end"}:
        return None
    try:
        db = get_db()
        _ensure_faction_war_auto_close(db, _world_week_key())
    except Exception:
        # Auto-close is best effort and must not block gameplay.
        app.logger.exception("faction_war.auto_close_failed")
    return None


@app.after_request
def add_security_headers(response):
    is_admin_path = request.path.startswith("/admin/")
    # Temporary: /build preview still relies on inline style/CSS variable updates.
    # Once build preview stops mutating styles directly, remove this exception and restore strict CSP.
    is_build_path = request.path.startswith("/build")
    script_src = "script-src 'self' 'unsafe-inline'; " if is_admin_path else "script-src 'self'; "
    style_src = "style-src 'self' 'unsafe-inline'; " if (is_admin_path or is_build_path) else "style-src 'self'; "
    csp = (
        "default-src 'self'; "
        + script_src
        + style_src
        + "img-src 'self' data:; "
        + "font-src 'self'; "
        + "connect-src 'self'; "
        + "object-src 'none'; "
        + "base-uri 'self'; "
        + "frame-ancestors 'self'"
    )
    response.headers["Content-Security-Policy"] = csp
    if is_build_path:
        response.headers["Cache-Control"] = "no-store, max-age=0"
        response.headers["Pragma"] = "no-cache"
    return response


@app.errorhandler(404)
def handle_404(err):
    return render_template("404.html"), 404


@app.errorhandler(500)
def handle_500(err):
    return render_template("500.html"), 500


