@app.route("/client-error/js", methods=["POST"])
def client_error_js():
    payload = request.get_json(silent=True) or {}
    if not isinstance(payload, dict):
        payload = {"raw": str(payload)}
    safe_payload = {
        "page_name": str(payload.get("page_name") or payload.get("pageName") or "")[:80],
        "pathname": str(payload.get("pathname") or "")[:300],
        "full_url": str(payload.get("full_url") or payload.get("url") or request.url)[:600],
        "message": str(payload.get("message") or "")[:800],
        "source": str(payload.get("source") or "")[:400],
        "line": int(payload.get("line") or 0),
        "column": int(payload.get("column") or 0),
        "stack": str(payload.get("stack") or "")[:2000],
        "url": str(payload.get("url") or request.path)[:500],
        "user_agent": str(payload.get("userAgent") or request.headers.get("User-Agent") or "")[:600],
        "kind": str(payload.get("kind") or "window.onerror")[:80],
        "step": str(payload.get("step") or "")[:160],
        "last_step": str(payload.get("last_step") or payload.get("lastStep") or "")[:160],
        "body_class": str(payload.get("body_class") or payload.get("bodyClass") or "")[:300],
        "body_id": str(payload.get("body_id") or payload.get("bodyId") or "")[:120],
        "page_template": str(payload.get("page_template") or payload.get("pageTemplate") or "")[:120],
        "ready_state": str(payload.get("ready_state") or payload.get("readyState") or "")[:40],
        "important_dom_state": payload.get("important_dom_state") if isinstance(payload.get("important_dom_state"), dict) else {},
        "loaded_scripts": payload.get("loaded_scripts") if isinstance(payload.get("loaded_scripts"), list) else [],
        "request_id": str(payload.get("requestId") or getattr(g, "request_id", ""))[:120],
        "user_id": int(session.get("user_id")) if session.get("user_id") else None,
    }
    log_msg = (
        "[client-js] page=%s kind=%s step=%s user=%s path=%s msg=%s "
        "src=%s:%s:%s last_step=%s body_class=%s body_id=%s template=%s ready=%s dom=%s scripts=%s"
    )
    log_args = (
        safe_payload["page_name"] or "-",
        safe_payload["kind"],
        safe_payload["step"] or "-",
        safe_payload["user_id"] if safe_payload["user_id"] is not None else "-",
        safe_payload["pathname"] or request.path,
        safe_payload["message"][:180],
        safe_payload["source"][:120],
        safe_payload["line"],
        safe_payload["column"],
        safe_payload["last_step"] or "-",
        safe_payload["body_class"][:140],
        safe_payload["body_id"][:80],
        safe_payload["page_template"][:80],
        safe_payload["ready_state"] or "-",
        json.dumps(safe_payload["important_dom_state"], ensure_ascii=False)[:240],
        ",".join(str(x) for x in safe_payload["loaded_scripts"][:10])[:260],
    )
    kind = safe_payload["kind"]
    error_kinds = {"window.onerror", "unhandledrejection", "caught_exception"}
    is_known_home_page_syntax_cache = (
        kind == "window.onerror"
        and "invalid or unexpected token" in (safe_payload["message"] or "").lower()
        and "home_page_v2.js" in (safe_payload["source"] or "").lower()
        and safe_payload["line"] == 163
        and safe_payload["column"] == 20
    )
    if kind == "overlay-scan":
        extra = payload.get("extra") if isinstance(payload.get("extra"), dict) else {}
        app.logger.warning(log_msg, *log_args)
        app.logger.warning(
            "[client-js-overlay] tag=%s id=%s class=%s rect=%s zIndex=%s backgroundColor=%s",
            str(extra.get("tag") or ""),
            str(extra.get("id") or ""),
            str(extra.get("className") or ""),
            json.dumps(extra.get("rect") or {}, ensure_ascii=False),
            str(extra.get("zIndex") or ""),
            str(extra.get("backgroundColor") or ""),
        )
    elif is_known_home_page_syntax_cache:
        app.logger.warning(
            "[client-js-known] page=%s kind=%s msg=%s src=%s:%s:%s (treat_as_cache_or_legacy)",
            safe_payload["page_name"] or "-",
            safe_payload["kind"],
            safe_payload["message"][:180],
            safe_payload["source"][:120],
            safe_payload["line"],
            safe_payload["column"],
        )
        if safe_payload["stack"]:
            app.logger.warning("[client-js-known-stack] %s", safe_payload["stack"][:1800])
    elif kind in error_kinds:
        app.logger.error(log_msg, *log_args)
        if safe_payload["stack"]:
            app.logger.error("[client-js-stack] %s", safe_payload["stack"][:1800])
    elif kind == "init_step":
        app.logger.info(log_msg, *log_args)
    else:
        app.logger.warning(log_msg, *log_args)
    return ("", 204)


def _login_user_session(db, user_row):
    session.clear()
    session.permanent = True
    session["user_id"] = int(user_row["id"])
    session["username"] = _display_username_for_user_row(db, user_row)
    session["battle_log"] = []
    db.execute("UPDATE users SET last_seen_at = ? WHERE id = ?", (int(time.time()), int(user_row["id"])))
    db.execute(
        "INSERT INTO login_logs (user_id, username, created_at) VALUES (?, ?, ?)",
        (
            int(user_row["id"]),
            str(user_row["username"] or ""),
            now_str(),
        ),
    )
    db.commit()


@app.route("/auth/google/start")
def google_oauth_start():
    is_register_intent = request.args.get("intent") == "register"
    fallback_target = url_for(
        "register",
        mode=("register" if is_register_intent else "login"),
        ref=((request.args.get("ref") or "").strip().upper() or None),
        next=_oauth_safe_next_path(request.args.get("next")) or None,
    )
    if not _google_oauth_enabled():
        flash("Googleログインはまだ準備中です。", "notice")
        return redirect(fallback_target)
    ref_code = (request.args.get("ref") or "").strip().upper()
    next_path = _oauth_safe_next_path(request.args.get("next"))
    state = uuid.uuid4().hex
    nonce = uuid.uuid4().hex
    session["google_oauth_state"] = state
    session["google_oauth_nonce"] = nonce
    session["google_oauth_ref_code"] = ref_code
    session["google_oauth_next"] = next_path
    try:
        auth_url = _google_oauth_authorize_url(state=state, nonce=nonce)
    except Exception:
        app.logger.exception("google_oauth.start_failed")
        flash("Googleログインの準備に失敗しました。少し置いてからもう一度お試しください。", "error")
        return redirect(fallback_target)
    return redirect(auth_url)


@app.route("/auth/google/callback")
def google_oauth_callback():
    if not _google_oauth_enabled():
        flash("Googleログインはまだ準備中です。", "notice")
        return redirect(url_for("register", mode="login"))
    error_code = (request.args.get("error") or "").strip()
    if error_code:
        flash("Googleログインを完了できませんでした。", "notice")
        return redirect(url_for("register", mode="login"))
    expected_state = str(session.pop("google_oauth_state", "") or "")
    expected_nonce = str(session.pop("google_oauth_nonce", "") or "")
    ref_code = str(session.pop("google_oauth_ref_code", "") or "").strip().upper()
    next_path = _oauth_safe_next_path(session.pop("google_oauth_next", ""))
    state = (request.args.get("state") or "").strip()
    code = (request.args.get("code") or "").strip()
    if (not expected_state) or state != expected_state or not code:
        flash("Googleログインの確認に失敗しました。もう一度やり直してください。", "error")
        return redirect(url_for("register", mode="login"))
    try:
        token_payload = _google_oauth_exchange_code(code)
        access_token = str(token_payload.get("access_token") or "").strip()
        if not access_token:
            raise ValueError("missing_access_token")
        profile = _google_oauth_fetch_userinfo(access_token)
    except Exception:
        app.logger.exception("google_oauth.callback_failed")
        flash("Googleログインの処理に失敗しました。時間を置いてもう一度お試しください。", "error")
        return redirect(url_for("register", mode="login"))

    provider_user_id = str(profile.get("sub") or "").strip()
    email = str(profile.get("email") or "").strip()
    email_verified = bool(profile.get("email_verified"))
    if not expected_nonce or not provider_user_id or not email or not email_verified:
        flash("Googleアカウント情報を確認できませんでした。", "error")
        return redirect(url_for("register", mode="login"))

    db = get_db()
    identity = _find_user_identity(db, GOOGLE_OAUTH_PROVIDER, provider_user_id)
    user_row = None
    created_new_user = False
    if identity:
        user_row = db.execute("SELECT * FROM users WHERE id = ?", (int(identity["user_id"]),)).fetchone()
    if user_row:
        if int(user_row["is_banned"] or 0) == 1:
            flash("このアカウントは利用停止されています。", "error")
            return redirect(url_for("register", mode="login"))
        if int(user_row["is_admin_protected"] or 0) == 1:
            flash("このアカウントは通常のGoogleログインを利用できません。", "error")
            return redirect(url_for("register", mode="login"))
        _upsert_user_identity(
            db,
            user_id=int(user_row["id"]),
            provider=GOOGLE_OAUTH_PROVIDER,
            provider_user_id=provider_user_id,
            email=email,
            display_name=None,
            avatar_url=None,
        )
        db.commit()
    else:
        username = _build_unique_anonymous_google_username(db)
        anonymous_display_name = _google_default_display_name()
        is_admin = 1 if _is_main_admin_username(username) else 0
        cur = db.execute(
            """
            INSERT INTO users
            (username, display_name, password_hash, coins, created_at, last_seen_at, is_admin, is_admin_protected)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                username,
                anonymous_display_name,
                generate_password_hash(uuid.uuid4().hex),
                0,
                int(time.time()),
                int(time.time()),
                is_admin,
                is_admin,
            ),
        )
        user_id = int(cur.lastrowid)
        _ensure_user_invite_code(db, user_id)
        if ref_code:
            _attach_referral_if_valid(
                db,
                referred_user_id=user_id,
                referral_code=ref_code,
                request_ip=request.remote_addr,
            )
        initialize_new_user(db, user_id)
        _ensure_qol_entitlement(db, user_id)
        _upsert_user_identity(
            db,
            user_id=user_id,
            provider=GOOGLE_OAUTH_PROVIDER,
            provider_user_id=provider_user_id,
            email=email,
            display_name=None,
            avatar_url=None,
        )
        db.commit()
        user_row = db.execute("SELECT * FROM users WHERE id = ?", (user_id,)).fetchone()
        created_new_user = True

    if not user_row:
        flash("Googleログインに失敗しました。", "error")
        return redirect(url_for("register", mode="login"))

    _login_user_session(db, user_row)
    if created_new_user:
        session["just_registered"] = 1
        flash("Googleアカウントで登録しました。第1層からすぐ出撃できます。", "notice")
    if next_path:
        return redirect(next_path)
    return redirect(url_for("home"))


def _auth_mode_value(raw_mode):
    mode = str(raw_mode or "").strip().lower()
    return "login" if mode == "login" else "register"


def _auth_login_reason_message(reason):
    if str(reason or "").strip().lower() == "expired":
        return "セッションが期限切れです。もう一度ログインしてください。"
    return None


def _normalize_display_name(raw_value):
    text = re.sub(r"\s+", " ", str(raw_value or "").strip())
    return text


def _normalize_robot_name(raw_value):
    return re.sub(r"\s+", " ", str(raw_value or "").strip())


def _is_starter_robot_default_name(robot_name):
    normalized = _normalize_robot_name(robot_name).lower().replace(" ", "")
    return normalized in {name.replace(" ", "") for name in STARTER_ROBOT_DEFAULT_NAMES}


def _render_auth_gateway(
    db,
    *,
    auth_mode="register",
    ref_code="",
    next_path="",
    register_error=None,
    login_error=None,
    login_message=None,
):
    return render_template(
        "register.html",
        error=None,
        message=None,
        auth_mode=_auth_mode_value(auth_mode),
        register_error=register_error,
        login_error=login_error,
        login_message=login_message,
        ref_code=(str(ref_code or "").strip().upper()),
        next_path=(str(next_path or "").strip()),
        landing=_landing_world_snapshot(db),
    )


