TOWER_STAT_LABELS = {
    "hp": "耐久",
    "atk": "攻撃",
    "def": "防御",
    "spd": "素早さ",
    "acc": "命中",
    "cri": "会心",
}


def _tower_user_or_redirect(db):
    if not session.get("user_id"):
        flash("ログインすると観測塔に挑戦できます。", "notice")
        return None, redirect(url_for("login", next=request.path, reason="expired"))
    user = db.execute("SELECT * FROM users WHERE id = ?", (int(session["user_id"]),)).fetchone()
    if not user:
        session.clear()
        return None, redirect(url_for("login", next=request.path, reason="expired"))
    if not can_access_tower(user, is_public=_release_flag_is_public(db, "tower")):
        if not _release_flag_is_public(db, "tower") and int(user["is_admin"] or 0) != 1:
            flash("観測塔は現在、公開準備中です。", "notice")
            return user, redirect(url_for("home"))
        flash("観測塔は第4層に到達すると解放されます。", "notice")
        return user, redirect(url_for("home"))
    return user, None


def _tower_robot_view(db, row, cooling_by_robot=None):
    robot = _refresh_robot_instance_render_assets(db, row, log_label="tower_robot")
    if not robot:
        return None
    stat_obj = _compute_robot_stats_for_instance(db, int(robot["id"]))
    if not stat_obj:
        return None
    stats = stat_obj["stats"]
    top_stats = sorted(TOWER_STAT_LABELS.keys(), key=lambda key: int(stats.get(key) or 0), reverse=True)[:2]
    cooling = cooling_by_robot.get(int(robot["id"])) if cooling_by_robot else None
    return {
        "id": int(robot["id"]),
        "name": robot["name"],
        "image_url": _composed_image_url(robot["composed_image_path"], robot["updated_at"]) if robot["composed_image_path"] else url_for("static", filename="assets/placeholder_player.png"),
        "icon_url": url_for("static", filename=_safe_static_rel(robot["icon_32_path"]) if robot["icon_32_path"] else DEFAULT_BADGE_REL),
        "power": stat_obj["power"],
        "plus_total": sum(int(part.get("plus") or 0) for part in (stat_obj.get("parts") or [])),
        "stats": stats,
        "top_stats": [{"key": key, "label": TOWER_STAT_LABELS[key], "value": int(stats.get(key) or 0)} for key in top_stats],
        "archetype": stat_obj.get("archetype") or {},
        "style": stat_obj.get("robot_style") or {},
        "cooling": bool(cooling and int(cooling["used_in_current_cycle"] or 0) == 1),
    }


def _tower_robot_image_url(row):
    if not row:
        return url_for("static", filename="assets/placeholder_player.png")
    if row["composed_image_path"]:
        return _composed_image_url(row["composed_image_path"], row["updated_at"])
    if row["icon_32_path"]:
        return url_for("static", filename=_safe_static_rel(row["icon_32_path"]))
    return url_for("static", filename="assets/placeholder_player.png")


def _tower_battle_log_items(battle, robot_name):
    try:
        raw_logs = json.loads(battle["turn_logs_json"] or "[]")
    except (TypeError, ValueError, json.JSONDecodeError):
        raw_logs = []
    if not raw_logs:
        return [{"actor": "system", "text": "戦闘ログを取得できませんでした。"}]
    source = raw_logs[0] if isinstance(raw_logs[0], dict) else {}
    turns = max(1, int(source.get("turns") or battle["turn_count"] or 1))
    dealt = int(source.get("player_damage_total") or 0)
    taken = int(source.get("enemy_damage_total") or 0)
    enemy_name = str(source.get("enemy_name") or battle["enemy_name"] or "敵")
    result = str(source.get("result") or battle["battle_result"] or "")
    turn_events = [item for item in (source.get("battle_turn_logs") or []) if isinstance(item, dict)]
    if turn_events:
        items = []
        for item in turn_events:
            turn = max(1, int(item.get("turn") or 1))
            damage = max(0, int(item.get("damage") or 0))
            if str(item.get("actor") or "") == "enemy":
                items.append({"actor": "enemy", "text": f"{turn}T: {enemy_name} の攻撃。{robot_name} に合計 {damage} ダメージ。"})
            else:
                items.append({"actor": "player", "text": f"{turn}T: {robot_name} の攻撃。{enemy_name} に合計 {damage} ダメージ。"})
                if int(item.get("target_hp_after") or 0) <= 0:
                    items.append({"actor": "system", "text": "敵を撃破！"})
                    return items
        items.append({"actor": "system", "text": "敵を撃破！" if result == "win" else "挑戦終了。"})
        return items
    items = [{"actor": "player", "text": f"1T: {robot_name} の攻撃。{enemy_name} に合計 {dealt} ダメージ。"}]
    if taken > 0:
        items.append({"actor": "enemy", "text": f"{enemy_name} の反撃。{robot_name} に合計 {taken} ダメージ。"})
    else:
        items.append({"actor": "system", "text": f"{enemy_name} の反撃を受けずに押し切った。"})
    if turns > 1:
        items.append({"actor": "system", "text": f"{turns}T: 戦闘終了。"})
    items.append({"actor": "system", "text": "敵を撃破！" if result == "win" else "挑戦終了。"})
    return items


def _tower_battle_log_lines(battle, robot_name):
    return [item["text"] for item in _tower_battle_log_items(battle, robot_name)]


def _tower_battle_hp_state(battle, robot_stats):
    try:
        raw_logs = json.loads(battle["turn_logs_json"] or "[]")
    except (TypeError, ValueError, json.JSONDecodeError):
        raw_logs = []
    source = raw_logs[0] if raw_logs and isinstance(raw_logs[0], dict) else {}
    try:
        enemy_stats = json.loads(battle["enemy_scaled_stats_json"] or "{}")
    except (TypeError, ValueError, json.JSONDecodeError):
        enemy_stats = {}

    player_max = max(1, int(source.get("player_hp_max") or (robot_stats or {}).get("hp") or 1))
    enemy_max = max(1, int(source.get("enemy_hp_max") or enemy_stats.get("hp") or 1))
    player_start = max(1, int(source.get("player_hp_start") or player_max))
    enemy_start = max(1, int(source.get("enemy_hp_start") or enemy_max))
    dealt = int(source.get("player_damage_total") or 0)
    taken = int(source.get("enemy_damage_total") or 0)
    player_final = source.get("player_final_hp")
    enemy_final = source.get("enemy_final_hp")
    if player_final is None:
        player_final = max(0, player_start - taken)
    if enemy_final is None:
        enemy_final = max(0, enemy_start - dealt)
    player_final = max(0, min(player_max, int(player_final or 0)))
    enemy_final = max(0, min(enemy_max, int(enemy_final or 0)))
    return {
        "player_start": player_start,
        "player_max": player_max,
        "player_final": player_final,
        "enemy_start": enemy_start,
        "enemy_max": enemy_max,
        "enemy_final": enemy_final,
    }


def _tower_zone_label(floor):
    floor_value = max(1, int(floor or 1))
    if floor_value <= 10:
        return "下層観測区"
    if floor_value <= 20:
        return "霧界昇降区"
    if floor_value <= 30:
        return "重装隔壁区"
    if floor_value <= 40:
        return "暴走導管区"
    if floor_value <= 50:
        return "星層中枢区"
    return "深層未定義区"


def _tower_floor_rail(run_view, current_floor):
    current = max(1, int(current_floor or 1))
    max_floor = max(1, int((run_view or {}).get("max_floor_in_run") or TOWER_RUN_MAX_FLOOR))
    start_floor = ((current - 1) // 10) * 10 + 1
    end_floor = min(start_floor + 9, max_floor)
    reached = max(0, int((run_view or {}).get("reached_floor") or 0))
    nodes = []
    for floor in range(start_floor, end_floor + 1):
        state = "locked"
        if floor <= reached:
            state = "cleared"
        if floor == current:
            state = "current"
        nodes.append(
            {
                "floor": floor,
                "label": f"{floor}F",
                "state": state,
                "is_gate": floor == end_floor,
            }
        )
    return nodes


def _tower_squad_strip(run_view, active_robot_id=None):
    active_id = int(active_robot_id or 0)
    chips = []
    for robot in (run_view or {}).get("robots") or []:
        robot_id = int(robot.get("id") or 0)
        if active_id and robot_id == active_id:
            state = "active"
            label = "出撃中"
        elif robot.get("cooling"):
            state = "cooling"
            label = "休憩中"
        else:
            state = "ready"
            label = "待機"
        chips.append({"name": robot.get("name") or "ロボ", "state": state, "label": label})
    return chips


def _tower_next_floor_preview(run_view, next_enemy=None):
    if not run_view or run_view.get("status") != "active":
        return None
    cooling_names = [robot.get("name") for robot in run_view.get("robots") or [] if robot.get("cooling")]
    return {
        "floor": int(run_view.get("current_floor") or 1),
        "zone_label": _tower_zone_label(run_view.get("current_floor") or 1),
        "environment_label": ((run_view.get("environment") or {}).get("display_name") or "観測環境"),
        "cooling_names": [name for name in cooling_names if name],
        "enemy_name": (next_enemy or {}).get("name"),
    }


def _tower_battle_detail_view(db, battle):
    if not battle:
        return None
    robot = db.execute(
        "SELECT id, name, composed_image_path, icon_32_path, updated_at FROM robot_instances WHERE id = ?",
        (int(battle["robot_instance_id"] or 0),),
    ).fetchone()
    enemy = None
    if battle["enemy_id"]:
        enemy = db.execute("SELECT id, key, name_ja, image_path FROM enemies WHERE id = ?", (int(battle["enemy_id"]),)).fetchone()
    if not enemy and battle["enemy_key"]:
        enemy = db.execute("SELECT id, key, name_ja, image_path FROM enemies WHERE key = ? LIMIT 1", (str(battle["enemy_key"]),)).fetchone()
    robot_name = robot["name"] if robot else "使用ロボ"
    enemy_name = (enemy["name_ja"] if enemy and enemy["name_ja"] else battle["enemy_name"]) or "敵"
    robot_stats_obj = _compute_robot_stats_for_instance(db, int(robot["id"])) if robot else None
    hp_state = _tower_battle_hp_state(battle, (robot_stats_obj or {}).get("stats") or {})
    return {
        "id": int(battle["id"]),
        "floor": int(battle["floor"] or 1),
        "floor_label": f"{int(battle['floor'] or 1)}F",
        "zone_label": _tower_zone_label(battle["floor"] or 1),
        "result": battle["battle_result"],
        "result_label": "勝利" if battle["battle_result"] == "win" else "敗北",
        "tower_result_label": f"{int(battle['floor'] or 1)}F {'踏破' if battle['battle_result'] == 'win' else '撤退'}",
        "turn_count": int(battle["turn_count"] or 0),
        "robot_name": robot_name,
        "robot_id": int(robot["id"]) if robot else int(battle["robot_instance_id"] or 0),
        "robot_image_url": _tower_robot_image_url(robot),
        "enemy_name": enemy_name,
        "enemy_image_url": _enemy_static_url(
            enemy["image_path"] if enemy else None,
            fallback_url=url_for("static", filename="assets/placeholder_enemy.png"),
        ),
        "log_items": _tower_battle_log_items(battle, robot_name),
        "log_lines": _tower_battle_log_lines(battle, robot_name),
        "hp": hp_state,
        "robot_hp_start": hp_state["player_start"],
        "robot_hp_end": hp_state["player_final"],
        "robot_hp_max": hp_state["player_max"],
        "enemy_hp_start": hp_state["enemy_start"],
        "enemy_hp_end": hp_state["enemy_final"],
        "enemy_hp_max": hp_state["enemy_max"],
    }


def _tower_result_selected_battle(db, *, run_id, user_id, battle_id=0):
    if int(battle_id or 0) > 0:
        battle = db.execute(
            """
            SELECT *
            FROM tower_run_battles
            WHERE id = ? AND run_id = ? AND user_id = ?
            LIMIT 1
            """,
            (int(battle_id), int(run_id), int(user_id)),
        ).fetchone()
        if battle:
            return battle
    return db.execute(
        """
        SELECT *
        FROM tower_run_battles
        WHERE run_id = ? AND user_id = ?
        ORDER BY floor DESC, id DESC
        LIMIT 1
        """,
        (int(run_id), int(user_id)),
    ).fetchone()


def _tower_robot_choices(db, user_id, cooling_rows=None):
    cooling_by_robot = {int(row["robot_instance_id"]): row for row in (cooling_rows or [])}
    rows = db.execute(
        """
        SELECT id, name, composed_image_path, icon_32_path, updated_at, style_key
        FROM robot_instances
        WHERE user_id = ? AND status = 'active'
        ORDER BY updated_at DESC, id DESC
        """,
        (int(user_id),),
    ).fetchall()
    out = []
    for row in rows:
        item = _tower_robot_view(db, row, cooling_by_robot)
        if item:
            out.append(item)
    return out


def _tower_run_view(db, run):
    if not run:
        return None
    cooling_rows = get_tower_cooling(db, int(run["id"]))
    robots = {}
    for rid in (int(run["squad_robot_1_id"]), int(run["squad_robot_2_id"]), int(run["squad_robot_3_id"])):
        row = db.execute(
            "SELECT id, name, composed_image_path, icon_32_path, updated_at, style_key FROM robot_instances WHERE id = ?",
            (rid,),
        ).fetchone()
        if row:
            item = _tower_robot_view(db, row, {int(c["robot_instance_id"]): c for c in cooling_rows})
            if item:
                robots[rid] = item
    env = TOWER_ENVIRONMENT_BY_KEY.get(str(run["environment_key"] or ""), get_current_tower_environment(db))
    return {
        "id": int(run["id"]),
        "status": run["status"],
        "current_floor": int(run["current_floor"] or 1),
        "reached_floor": int(run["reached_floor"] or 0),
        "max_floor_in_run": int(run["max_floor_in_run"] or TOWER_RUN_MAX_FLOOR),
        "environment": env,
        "robots": [robots.get(rid) for rid in (int(run["squad_robot_1_id"]), int(run["squad_robot_2_id"]), int(run["squad_robot_3_id"])) if robots.get(rid)],
    }


def _tower_next_enemy_view(db, run):
    if not run:
        return None
    enemy = get_tower_enemy_for_floor(db, int(run["current_floor"] or 1), run["environment_key"], run["seed"])
    if not enemy:
        return None
    return {
        "name": enemy.get("name_ja") or enemy.get("key") or "敵",
        "image_url": _enemy_static_url(
            enemy.get("image_path"),
            fallback_url=url_for("static", filename="assets/placeholder_enemy.png"),
        ),
    }


def _home_tower_entry_visible(user, *, is_public):
    if can_see_tower_entry(user, is_public=is_public):
        return True
    if not user:
        return False
    try:
        if int(user["is_admin"] if hasattr(user, "keys") else user.get("is_admin") or 0) == 1:
            return True
    except Exception:
        return False
    if not is_public:
        return False
    try:
        max_layer = int(user["max_unlocked_layer"] if hasattr(user, "keys") else user.get("max_unlocked_layer") or 1)
    except Exception:
        max_layer = 1
    return max_layer >= int(TOWER_ACCESS_LAYER)


@app.route("/tower")
@login_required
def tower():
    db = get_db()
    user, blocked = _tower_user_or_redirect(db)
    if blocked:
        return blocked
    record = get_user_tower_record(db, int(user["id"]))
    env = get_current_tower_environment(db)
    active_run = db.execute(
        """
        SELECT *
        FROM tower_runs
        WHERE user_id = ? AND status = 'active'
        ORDER BY id DESC
        LIMIT 1
        """,
        (int(user["id"]),),
    ).fetchone()
    active_view = _tower_run_view(db, active_run) if active_run else None
    robots = _tower_robot_choices(db, int(user["id"]), get_tower_cooling(db, int(active_run["id"])) if active_run else None)
    return render_template(
        "tower.html",
        user=user,
        message=session.pop("message", None),
        environment=env,
        record=record,
        robots=robots,
        active_run=active_view,
        next_enemy=_tower_next_enemy_view(db, active_run) if active_run else None,
        stat_labels=TOWER_STAT_LABELS,
    )


@app.route("/tower/start", methods=["POST"])
@login_required
def tower_start():
    db = get_db()
    user, blocked = _tower_user_or_redirect(db)
    if blocked:
        return blocked
    robot_ids = [request.form.get("robot_1"), request.form.get("robot_2"), request.form.get("robot_3")]
    try:
        clean_ids = [int(x) for x in robot_ids if str(x or "").strip()]
    except (TypeError, ValueError):
        clean_ids = []
    if len(clean_ids) != 3:
        flash("挑戦するロボを3機選んでください。", "error")
        return redirect(url_for("tower"))
    active_run = db.execute(
        """
        SELECT id
        FROM tower_runs
        WHERE user_id = ? AND status = 'active'
        ORDER BY id DESC
        LIMIT 1
        """,
        (int(user["id"]),),
    ).fetchone()
    if active_run:
        flash("進行中の挑戦があります。先に続きを進めるか、終了してください。", "notice")
        return redirect(url_for("tower_result", run_id=int(active_run["id"])))
    result = create_tower_run(db, int(user["id"]), clean_ids, environment_key=get_current_tower_environment(db)["key"])
    if not result.get("ok"):
        reason = result.get("reason")
        if reason == "duplicate_robots":
            flash("同じ機体は重複選択できません。", "error")
        elif reason == "robots_not_found":
            flash("選択した機体を確認できませんでした。", "error")
        else:
            flash("挑戦を開始できませんでした。少し待ってからもう一度お試しください。", "error")
        db.rollback()
        return redirect(url_for("tower"))
    db.commit()
    return redirect(url_for("tower_result", run_id=int(result["run_id"])))


@app.route("/tower/battle", methods=["POST"])
@login_required
def tower_battle():
    db = get_db()
    user, blocked = _tower_user_or_redirect(db)
    if blocked:
        return blocked
    try:
        run_id = int(request.form.get("challenge_id") or request.form.get("run_id") or 0)
        robot_id = int(request.form.get("robot_instance_id") or 0)
    except (TypeError, ValueError):
        run_id = 0
        robot_id = 0
    run = get_tower_run(db, run_id, int(user["id"])) if run_id > 0 else None
    if not run:
        flash("挑戦データが見つかりません。", "error")
        return redirect(url_for("tower"))
    result = run_tower_battle(db, int(run["id"]), robot_id, _compute_robot_stats_for_instance)
    if not result.get("ok"):
        reason = result.get("reason")
        if reason == "robot_cooling":
            flash("そのロボは休憩中です。別のロボを選んでください。", "error")
        elif reason == "robot_not_in_squad":
            flash("選んだ3機以外のロボは出撃できません。", "error")
        elif reason == "run_not_active":
            flash("この挑戦は終了しています。", "notice")
        else:
            flash("戦闘を開始できませんでした。少し待ってからもう一度お試しください。", "error")
        db.rollback()
        return redirect(url_for("tower_result", run_id=int(run["id"])))
    db.commit()
    if result.get("status") == "completed":
        flash("10F踏破！今回の挑戦を完了しました。", "notice")
    elif result.get("status") == "failed":
        flash("挑戦を終了しました。ここまでの記録を確認できます。", "notice")
    battle_id = int(result.get("battle_id") or 0)
    if battle_id > 0:
        return redirect(url_for("tower_battle_view", battle_id=battle_id))
    return redirect(url_for("tower_result", run_id=int(run["id"])))


