@app.route("/market/part-inventory/expand", methods=["POST"])
@login_required
def market_part_inventory_expand():
    db = get_db()
    user_id = int(session["user_id"])
    user = db.execute("SELECT id, username, is_admin FROM users WHERE id = ?", (user_id,)).fetchone()
    if not user:
        session.clear()
        return redirect(url_for("login", reason="expired"))
    _market_require_access(db, user)
    try:
        expected_limit = int(request.form.get("current_limit") or 0)
    except Exception:
        expected_limit = 0
    try:
        row = db.execute(
            "SELECT id, coins, part_inventory_limit FROM users WHERE id = ?",
            (user_id,),
        ).fetchone()
        if not row:
            db.rollback()
            session.clear()
            return redirect(url_for("login", reason="expired"))
        before_limit = _part_inventory_limit_value(row["part_inventory_limit"])
        if expected_limit and expected_limit != before_limit:
            db.rollback()
            flash("所持枠の状態が変わりました。もう一度確認してください。", "error")
            return redirect(url_for("market"))
        price = _part_inventory_expand_price(before_limit)
        if price is None or before_limit >= int(PART_INVENTORY_EXPANSION_MAX_LIMIT):
            db.rollback()
            flash("パーツ所持枠は最大拡張済みです。", "notice")
            return redirect(url_for("market"))
        coins_before = int(row["coins"] or 0)
        if coins_before < int(price):
            db.rollback()
            flash("所持枠拡張に必要なコインが足りません。", "error")
            return redirect(url_for("market"))
        after_limit = min(int(PART_INVENTORY_EXPANSION_MAX_LIMIT), before_limit + int(PART_INVENTORY_EXPANSION_UNIT))
        coins_after = coins_before - int(price)
        cur = db.execute(
            """
            UPDATE users
            SET coins = ?, part_inventory_limit = ?
            WHERE id = ?
              AND COALESCE(part_inventory_limit, 60) = ?
              AND COALESCE(coins, 0) >= ?
            """,
            (int(coins_after), int(after_limit), int(user_id), int(before_limit), int(price)),
        )
        if int(cur.rowcount or 0) <= 0:
            db.rollback()
            flash("所持枠の状態が変わりました。もう一度確認してください。", "error")
            return redirect(url_for("market"))
        audit_log(
            db,
            AUDIT_EVENT_TYPES["PART_INVENTORY_EXPAND"],
            user_id=user_id,
            request_id=getattr(g, "request_id", None),
            action_key="part_inventory_expand",
            entity_type="user",
            entity_id=user_id,
            delta_coins=-int(price),
            payload={
                "user_id": int(user_id),
                "before_limit": int(before_limit),
                "after_limit": int(after_limit),
                "price": int(price),
                "coins_before": int(coins_before),
                "coins_after": int(coins_after),
            },
            ip=request.remote_addr,
        )
        db.commit()
    except Exception:
        db.rollback()
        app.logger.exception("market.part_inventory_expand_failed user_id=%s", user_id)
        flash("所持枠拡張に失敗しました。もう一度試してください。", "error")
        return redirect(url_for("market"))
    flash(f"パーツ所持枠を {after_limit} 枠に拡張しました。", "notice")
    return redirect(url_for("market"))


@app.route("/market/sell", methods=["POST"])
@login_required
def market_sell():
    db = get_db()
    user_id = int(session["user_id"])
    user = db.execute("SELECT id, username, is_admin FROM users WHERE id = ?", (user_id,)).fetchone()
    if not user:
        session.clear()
        return redirect(url_for("login", reason="expired"))
    _market_require_access(db, user)
    part_instance_id = request.form.get("part_instance_id", type=int)
    if not part_instance_id:
        flash("売却するパーツを選んでください。", "error")
        return redirect(url_for("market"))
    part_row = db.execute(
        """
        SELECT
            pi.*,
            rp.key,
            rp.display_name_ja,
            rp.rarity AS master_rarity,
            rp.element AS master_element,
            rp.image_path
        FROM part_instances pi
        JOIN robot_parts rp ON rp.id = pi.part_id
        WHERE pi.id = ? AND pi.user_id = ?
        LIMIT 1
        """,
        (int(part_instance_id), user_id),
    ).fetchone()
    if not part_row or str(part_row["status"] or "").strip().lower() != "inventory":
        flash("装備中のパーツは市場で売却できません。", "error")
        return redirect(url_for("market"))
    if int(part_row["locked"] or 0) == 1:
        flash("保護中のパーツは売却できません。先に保護を解除してください。", "error")
        return redirect(url_for("market"))
    value = _market_sell_value(part_row)
    before = int(db.execute("SELECT COALESCE(coins, 0) AS coins FROM users WHERE id = ?", (user_id,)).fetchone()["coins"] or 0)
    now_ts = int(time.time())
    db.execute(
        """
        INSERT INTO market_sell_history
        (user_id, part_instance_id, part_key, rarity, plus, price, created_at)
        VALUES (?, ?, ?, ?, ?, ?, ?)
        """,
        (
            user_id,
            int(part_instance_id),
            str(part_row["key"]),
            str(part_row["rarity"] or part_row["master_rarity"] or "N").upper(),
            int(part_row["plus"] or 0),
            int(value),
            now_ts,
        ),
    )
    db.execute(
        "UPDATE part_instances SET status = 'sold', updated_at = datetime('now') WHERE id = ? AND user_id = ? AND status = 'inventory'",
        (int(part_instance_id), user_id),
    )
    db.execute("UPDATE users SET coins = COALESCE(coins, 0) + ? WHERE id = ?", (int(value), user_id))
    audit_log(
        db,
        AUDIT_EVENT_TYPES["MARKET_SELL"],
        user_id=user_id,
        request_id=getattr(g, "request_id", None),
        action_key="market_sell",
        entity_type="part_instance",
        entity_id=int(part_instance_id),
        delta_coins=int(value),
        payload={
            "part_key": part_row["key"],
            "part_name": _part_display_name_ja(part_row),
            "rarity": str(part_row["rarity"] or part_row["master_rarity"] or "N").upper(),
            "plus": int(part_row["plus"] or 0),
            "coin_before": int(before),
            "coin_after": int(before + value),
        },
        ip=request.remote_addr,
    )
    db.commit()
    flash(f"{_part_display_name_ja(part_row)} を {int(value)} コインで売却しました。", "notice")
    return redirect(url_for("market"))


@app.route("/market/sell-bulk", methods=["POST"])
@login_required
def market_sell_bulk():
    db = get_db()
    user_id = int(session["user_id"])
    user = db.execute("SELECT id, username, is_admin FROM users WHERE id = ?", (user_id,)).fetchone()
    if not user:
        session.clear()
        return redirect(url_for("login", reason="expired"))
    _market_require_access(db, user)
    ids = _normalize_instance_id_values(request.form.getlist("part_instance_ids"), limit=80)
    if not ids:
        flash("まとめ売りするパーツを選んでください。", "error")
        return redirect(url_for("market"))
    marks = ",".join("?" for _ in ids)
    rows = db.execute(
        f"""
        SELECT
            pi.*,
            rp.key,
            rp.display_name_ja,
            rp.rarity AS master_rarity,
            rp.element AS master_element,
            rp.image_path
        FROM part_instances pi
        JOIN robot_parts rp ON rp.id = pi.part_id
        WHERE pi.user_id = ? AND pi.status = 'inventory' AND COALESCE(pi.locked, 0) = 0 AND pi.id IN ({marks})
        """,
        (user_id, *ids),
    ).fetchall()
    excluded_count = max(0, len(ids) - len(rows))
    if not rows:
        flash("売却できるパーツがありません。保護中・装備中のパーツは売却されません。", "error")
        return redirect(url_for("market"))
    total = sum(_market_sell_value(row) for row in rows)
    before = int(db.execute("SELECT COALESCE(coins, 0) AS coins FROM users WHERE id = ?", (user_id,)).fetchone()["coins"] or 0)
    row_ids = [int(row["id"]) for row in rows]
    now_ts = int(time.time())
    for row in rows:
        db.execute(
            """
            INSERT INTO market_sell_history
            (user_id, part_instance_id, part_key, rarity, plus, price, created_at)
            VALUES (?, ?, ?, ?, ?, ?, ?)
            """,
            (
                user_id,
                int(row["id"]),
                str(row["key"]),
                str(row["rarity"] or row["master_rarity"] or "N").upper(),
                int(row["plus"] or 0),
                int(_market_sell_value(row)),
                now_ts,
            ),
        )
    delete_marks = ",".join("?" for _ in row_ids)
    db.execute(
        f"UPDATE part_instances SET status = 'sold', updated_at = datetime('now') WHERE user_id = ? AND status = 'inventory' AND id IN ({delete_marks})",
        (user_id, *row_ids),
    )
    db.execute("UPDATE users SET coins = COALESCE(coins, 0) + ? WHERE id = ?", (int(total), user_id))
    audit_log(
        db,
        AUDIT_EVENT_TYPES["MARKET_SELL"],
        user_id=user_id,
        request_id=getattr(g, "request_id", None),
        action_key="market_sell_bulk",
        entity_type="part_instance",
        delta_coins=int(total),
        delta_count=len(rows),
        payload={
            "count": len(rows),
            "part_instance_ids": row_ids,
            "coin_before": int(before),
            "coin_after": int(before + total),
        },
        ip=request.remote_addr,
    )
    db.commit()
    extra = f" 保護中または対象外 {excluded_count} 個は売却対象から除外しました。" if excluded_count else ""
    flash(f"{len(rows)}個のパーツを {int(total)} コインで売却しました。{extra}", "notice")
    return redirect(url_for("market"))


@app.route("/market/buy/<int:listing_id>", methods=["POST"])
@login_required
def market_buy(listing_id):
    db = get_db()
    user_id = int(session["user_id"])
    user = db.execute("SELECT id, username, is_admin, coins, part_inventory_limit FROM users WHERE id = ?", (user_id,)).fetchone()
    if not user:
        session.clear()
        return redirect(url_for("login", reason="expired"))
    _market_require_access(db, user)
    day_key = _market_ensure_daily_listings(db, user_id)
    listing = db.execute(
        """
        SELECT ml.*, rp.id AS part_id, rp.key, rp.image_path, rp.display_name_ja, rp.element, rp.series, rp.rarity AS master_rarity
        FROM market_daily_listings ml
        JOIN robot_parts rp ON rp.key = ml.part_key
        WHERE ml.id = ? AND ml.user_id = ? AND ml.day_key = ?
        LIMIT 1
        """,
        (int(listing_id), user_id, day_key),
    ).fetchone()
    if not listing or int(listing["is_sold"] or 0) == 1:
        flash("この商品は購入できません。", "error")
        db.commit()
        return redirect(url_for("market"))
    price = int(listing["price"] or 0)
    coins_before = int(user["coins"] or 0)
    if coins_before < price:
        flash("コインが足りません。", "error")
        db.commit()
        return redirect(url_for("market"))
    if _inventory_space_remaining(db, user_id, user_row=user) <= 0:
        flash("所持枠がいっぱいです。不要なパーツを売却してから購入してください。", "error")
        db.commit()
        return redirect(url_for("market"))
    status = "inventory"
    part_master = dict(listing)
    part_master["id"] = int(listing["part_id"])
    part_instance_id = _create_part_instance_from_master(
        db,
        user_id,
        part_master,
        plus=int(listing["plus"] or 0),
        status=status,
    )
    now_ts = int(time.time())
    db.execute("UPDATE users SET coins = COALESCE(coins, 0) - ? WHERE id = ?", (price, user_id))
    db.execute(
        """
        INSERT INTO market_purchase_history
        (user_id, listing_id, part_instance_id, part_key, price, created_at)
        VALUES (?, ?, ?, ?, ?, ?)
        """,
        (
            user_id,
            int(listing_id),
            int(part_instance_id),
            str(listing["part_key"]),
            int(price),
            now_ts,
        ),
    )
    db.execute(
        """
        UPDATE market_daily_listings
        SET is_sold = 1,
            sold_to_user_id = ?,
            sold_at = ?,
            updated_at = ?
        WHERE id = ? AND user_id = ?
        """,
        (user_id, now_ts, now_ts, int(listing_id), user_id),
    )
    audit_log(
        db,
        AUDIT_EVENT_TYPES["MARKET_BUY"],
        user_id=user_id,
        request_id=getattr(g, "request_id", None),
        action_key="market_buy",
        entity_type="market_daily_listing",
        entity_id=int(listing_id),
        delta_coins=-price,
        payload={
            "listing_id": int(listing_id),
            "part_instance_id": int(part_instance_id),
            "part_key": listing["part_key"],
            "part_name": _part_display_name_ja(listing),
            "rarity": str(listing["rarity"] or "N").upper(),
            "plus": int(listing["plus"] or 0),
            "price": price,
            "storage_status": status,
            "coin_before": coins_before,
            "coin_after": coins_before - price,
        },
        ip=request.remote_addr,
    )
    db.commit()
    flash(f"{_part_display_name_ja(listing)} を {price} コインで購入しました。", "notice")
    return redirect(url_for("market"))


@app.route("/market/refresh", methods=["POST"])
@login_required
def market_refresh():
    db = get_db()
    user_id = int(session["user_id"])
    user = db.execute("SELECT id, username, is_admin, coins FROM users WHERE id = ?", (user_id,)).fetchone()
    if not user:
        session.clear()
        return redirect(url_for("login", reason="expired"))
    _market_require_access(db, user)
    day_key = _market_ensure_daily_listings(db, user_id)
    state = _market_user_state(db, user_id) or {}
    refresh_count = int(state.get("market_refresh_count_today") or 0)
    cost = _market_refresh_cost(refresh_count)
    coins_before = int(state.get("coins") or user["coins"] or 0)
    if coins_before < cost:
        flash("再入荷に必要なコインが足りません。", "error")
        db.commit()
        return redirect(url_for("market"))
    if cost > 0:
        db.execute("UPDATE users SET coins = COALESCE(coins, 0) - ? WHERE id = ?", (int(cost), user_id))
    now_ts = int(time.time())
    db.execute(
        """
        INSERT INTO market_refresh_history
        (user_id, day_key, refresh_index, cost, created_at)
        VALUES (?, ?, ?, ?, ?)
        """,
        (user_id, day_key, refresh_count + 1, int(cost), now_ts),
    )
    free_used_at = day_key if cost == 0 else state.get("market_free_refresh_used_at")
    db.execute(
        """
        UPDATE users
        SET market_refresh_count_today = COALESCE(market_refresh_count_today, 0) + 1,
            market_free_refresh_used_at = COALESCE(?, market_free_refresh_used_at),
            market_refresh_day_key = ?
        WHERE id = ?
        """,
        (free_used_at, day_key, user_id),
    )
    _market_generate_listings_for_user(db, user_id, day_key, replace=True)
    audit_log(
        db,
        AUDIT_EVENT_TYPES["MARKET_REFRESH"],
        user_id=user_id,
        request_id=getattr(g, "request_id", None),
        action_key="market_refresh",
        entity_type="market_daily_listings",
        delta_coins=-int(cost),
        payload={
            "day_key": day_key,
            "refresh_index": refresh_count + 1,
            "cost": int(cost),
            "coin_before": coins_before,
            "coin_after": coins_before - cost,
        },
        ip=request.remote_addr,
    )
    db.commit()
    if cost:
        flash(f"{cost} コインで市場を再入荷しました。", "notice")
    else:
        flash("無料で市場を再入荷しました。", "notice")
    return redirect(url_for("market"))


