@app.route("/champion")
@login_required
def champion_view():
    db = get_db()
    user = db.execute("SELECT * FROM users WHERE id = ?", (int(session["user_id"]),)).fetchone()
    if not user:
        session.clear()
        return redirect(url_for("login", reason="expired"))
    gate_redirect = _release_gate_redirect(
        db,
        "weekly_champion",
        user_row=user,
        user_id=int(user["id"]),
    )
    if gate_redirect is not None:
        db.commit()
        return gate_redirect

    snapshot = _ensure_current_weekly_champion_snapshot(
        db,
        request_id=getattr(g, "request_id", None),
        ip=request.remote_addr,
    )
    champion = _weekly_champion_view_model(
        db,
        snapshot,
        viewer_user_id=int(user["id"]),
    )
    active_robot = _get_active_robot(db, int(user["id"]))
    active_robot_stats = (
        _compute_robot_stats_for_instance(db, int(active_robot["id"]))
        if active_robot and active_robot.get("id")
        else None
    )
    active_robot_profile = _robot_profile_view(active_robot_stats) if active_robot_stats else None
    affinity_card = None
    if champion and active_robot_profile:
        affinity_card = _affinity_view_payload(
            get_type_affinity(
                _robot_battle_type_from_style(active_robot_profile),
                _robot_battle_type_from_style(champion.get("style_key")),
            ),
            subject_label="あなた",
            opponent_label="チャンプ",
            context="champion",
        )
    champion_history_rows = _weekly_champion_history_rows(db, limit=6)
    db.commit()
    return render_template(
        "champion.html",
        title="今週のチャンプ機体",
        user=user,
        champion=champion,
        champion_history_rows=champion_history_rows,
        active_robot=active_robot,
        active_robot_profile=active_robot_profile,
        active_robot_stats=active_robot_stats,
        affinity_card=affinity_card,
    )


@app.route("/champion/challenge", methods=["POST"])
@login_required
def champion_challenge():
    db = get_db()
    user = db.execute("SELECT * FROM users WHERE id = ?", (int(session["user_id"]),)).fetchone()
    if not user:
        session.clear()
        return redirect(url_for("login", reason="expired"))
    gate_redirect = _release_gate_redirect(
        db,
        "weekly_champion",
        user_row=user,
        user_id=int(user["id"]),
    )
    if gate_redirect is not None:
        db.commit()
        return gate_redirect

    snapshot = _ensure_current_weekly_champion_snapshot(
        db,
        request_id=getattr(g, "request_id", None),
        ip=request.remote_addr,
    )
    champion = _weekly_champion_view_model(
        db,
        snapshot,
        viewer_user_id=int(user["id"]),
    )
    if not snapshot or not champion:
        flash("今週のチャンプはまだ準備中です。", "notice")
        db.commit()
        return redirect(url_for("champion_view"))
    if int(champion.get("user_id") or 0) == int(user["id"]):
        flash("自分のチャンプ機体には挑戦できません。", "notice")
        db.commit()
        return redirect(url_for("champion_view"))

    active_robot = _get_active_robot(db, int(user["id"]))
    if not active_robot:
        flash("挑戦するには出撃機体を設定してください。", "notice")
        db.commit()
        return redirect(url_for("build"))

    challenger_payload = _build_champion_robot_payload(
        db,
        user_id=int(user["id"]),
        robot_instance_id=int(active_robot["id"]),
    )
    champion_snapshot_payload = _weekly_champion_snapshot_payload(snapshot)
    champion_enemy_payload = build_champion_enemy_payload(champion_snapshot_payload)
    if not challenger_payload or not champion_enemy_payload:
        flash("挑戦機体の読み込みに失敗しました。少し待ってから再挑戦してください。", "error")
        db.commit()
        return redirect(url_for("champion_view"))

    request_id = getattr(g, "request_id", None) or str(uuid.uuid4())
    player_type = _robot_battle_type_from_style(challenger_payload.get("style_key"))
    champion_type = _robot_battle_type_from_style(champion_enemy_payload.get("style_key") or champion.get("style_key"))
    type_affinity = get_type_affinity(player_type, champion_type)
    affinity_card = _affinity_view_payload(
        type_affinity,
        subject_label="あなた",
        opponent_label="チャンプ",
        context="champion",
    )
    audit_log(
        db,
        "audit.champ.battle.start",
        user_id=int(user["id"]),
        request_id=request_id,
        action_key="champion_battle_start",
        entity_type="robot_instance",
        entity_id=int(snapshot.get("robot_instance_id") or 0) or None,
        payload={
            "champion_snapshot_id": int(snapshot.get("id") or 0),
            "champion_robot_instance_id": int(snapshot.get("robot_instance_id") or 0),
            "challenger_robot_instance_id": int(active_robot["id"] or 0),
            "player_type": player_type,
            "champion_type": champion_type,
            "affinity_result": type_affinity.get("result"),
        },
        ip=request.remote_addr,
    )
    battle_result = run_champion_battle(
        {
            "name": str(challenger_payload.get("robot_name") or "あなた"),
            "stats": dict(challenger_payload.get("stats") or {}),
            "signature_label": str(challenger_payload.get("signature_label") or ""),
            "focus_labels": list(challenger_payload.get("focus_labels") or []),
            "style_key": str(challenger_payload.get("style_key") or "stable"),
        },
        champion_enemy_payload,
        max_turns=8,
    )
    reward_summary = _grant_champion_battle_rewards(
        db,
        user_id=int(user["id"]),
        champion_robot_id=int(snapshot.get("robot_instance_id") or 0),
        champion_user_id=int(snapshot.get("user_id") or 0),
        win=bool(battle_result.get("win")),
        request_id=request_id,
        ip=request.remote_addr,
    )
    battle_payload = {
        "week_key": str(snapshot.get("week_key") or champion_current_week_key()),
        "champion_snapshot_id": int(snapshot.get("id") or 0),
        "champion_user_id": int(snapshot.get("user_id") or 0),
        "champion_robot_instance_id": int(snapshot.get("robot_instance_id") or 0),
        "champion_robot_name": str(champion.get("robot_name") or champion_enemy_payload.get("name") or "チャンプ機体"),
        "champion_owner_name": str(champion.get("owner_name") or "unknown"),
        "challenger_user_id": int(user["id"]),
        "challenger_robot_instance_id": int(active_robot["id"] or 0),
        "challenger_robot_name": str(challenger_payload.get("robot_name") or active_robot.get("name") or "挑戦機"),
        "challenger_owner_name": str(challenger_payload.get("owner_name") or _display_username_for_user_row(db, user)),
        "result": ("win" if battle_result.get("win") else "lose"),
        "outcome": str(battle_result.get("outcome") or ""),
        "turn_count": int(battle_result.get("turn_count") or 0),
        "timeout": bool(battle_result.get("timeout")),
        "summary_label": str(battle_result.get("summary_label") or ""),
        "first_strike_mode": str(battle_result.get("first_strike_mode") or "RANDOM_FIRST"),
        "first_striker": str(battle_result.get("first_striker") or ""),
        "reward_coin": int(reward_summary.get("reward_coin") or 0),
        "reward_base_coin": int(reward_summary.get("base_coin") or 0),
        "reward_daily_bonus_coin": int(reward_summary.get("daily_bonus_coin") or 0),
        "reward_core": int(reward_summary.get("core_reward") or 0),
        "first_defeat": bool(reward_summary.get("first_defeat")),
        "daily_bonus_granted": bool(reward_summary.get("daily_bonus_granted")),
        "player_type": player_type,
        "champion_type": champion_type,
        "player_type_label": battle_type_label(player_type),
        "champion_type_label": battle_type_label(champion_type),
        "affinity_result": str(type_affinity.get("result") or "unknown"),
        "affinity_label": str(type_affinity.get("label") or "不明"),
    }
    db.execute(
        """
        INSERT INTO weekly_champion_battles (
            week_key,
            champion_snapshot_id,
            challenger_user_id,
            challenger_robot_instance_id,
            result,
            turn_count,
            created_at,
            request_id,
            payload_json
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
        """,
        (
            battle_payload["week_key"],
            int(snapshot.get("id") or 0),
            int(user["id"]),
            int(active_robot["id"] or 0),
            battle_payload["result"],
            battle_payload["turn_count"],
            _now_ts(),
            request_id,
            json.dumps(battle_payload, ensure_ascii=False),
        ),
    )
    stats_summary = _sync_weekly_champion_snapshot_counters(db, int(snapshot.get("id") or 0))
    battle_payload["challenge_count"] = int(stats_summary.get("challenge_count") or 0)
    battle_payload["defeat_count"] = int(stats_summary.get("defeat_count") or 0)
    battle_payload["champion_win_rate"] = int(stats_summary.get("champion_win_rate") or 0)

    audit_log(
        db,
        AUDIT_EVENT_TYPES["CHAMPION_CHALLENGE"],
        user_id=int(user["id"]),
        request_id=request_id,
        action_key="champion_challenge",
        entity_type="robot_instance",
        entity_id=int(snapshot.get("robot_instance_id") or 0) or None,
        payload=battle_payload,
        ip=request.remote_addr,
    )
    audit_log(
        db,
        "audit.champ.battle.end",
        user_id=int(user["id"]),
        request_id=request_id,
        action_key="champion_battle_end",
        entity_type="robot_instance",
        entity_id=int(snapshot.get("robot_instance_id") or 0) or None,
        payload={
            **battle_payload,
            "affinity": type_affinity,
        },
        ip=request.remote_addr,
    )
    audit_log(
        db,
        AUDIT_EVENT_TYPES["COIN_DELTA"],
        user_id=int(user["id"]),
        request_id=request_id,
        action_key="champion_challenge",
        delta_coins=int(reward_summary.get("reward_coin") or 0),
        payload={
            "champion_snapshot_id": int(snapshot.get("id") or 0),
            "result": str(battle_payload.get("result") or "lose"),
            "reward_coin": int(reward_summary.get("reward_coin") or 0),
            "base_coin": int(reward_summary.get("base_coin") or 0),
            "daily_bonus_coin": int(reward_summary.get("daily_bonus_coin") or 0),
        },
        ip=request.remote_addr,
    )
    if battle_result.get("win"):
        faction_event_type = "champ_upset" if type_affinity.get("result") == "disadvantage" else "champ_defeat"
        add_faction_points(
            db,
            int(user["id"]),
            faction_event_type,
            FACTION_POINTS[faction_event_type],
            counters=(
                {"champ_defeat_count": 1, "upset_count": 1}
                if faction_event_type == "champ_upset"
                else {"champ_defeat_count": 1}
            ),
            payload={
                "champion_snapshot_id": int(snapshot.get("id") or 0),
                "champion_robot_instance_id": int(snapshot.get("robot_instance_id") or 0),
                "affinity_result": type_affinity.get("result"),
            },
            create_log=True,
            week_key=_world_week_key(),
        )
        grant_robot_title(
            db,
            int(active_robot["id"]),
            "champion_breaker",
            source_event="champion_break",
            source_entity_type="weekly_champion_snapshot",
            source_entity_id=int(snapshot.get("id") or 0) or None,
        )
        defeat_payload = dict(battle_payload)
        defeat_payload.update(
            {
                "robot_image_url": challenger_payload.get("robot_image_url"),
                "challenger_name": str(challenger_payload.get("owner_name") or _display_username_for_user_row(db, user)),
                "affinity": type_affinity,
            }
        )
        audit_log(
            db,
            AUDIT_EVENT_TYPES["CHAMPION_DEFEAT"],
            user_id=int(user["id"]),
            request_id=request_id,
            action_key="champion_defeat",
            entity_type="robot_instance",
            entity_id=int(snapshot.get("robot_instance_id") or 0) or None,
            payload=defeat_payload,
            ip=request.remote_addr,
        )
        should_publish_champion_defeat = bool(
            reward_summary.get("first_defeat")
            or reward_summary.get("daily_bonus_granted")
            or type_affinity.get("result") == "disadvantage"
        )
        if should_publish_champion_defeat:
            audit_log(
                db,
                "CHAMPION_DEFEATED",
                user_id=int(user["id"]),
                request_id=request_id,
                action_key="champion_defeated_public",
                entity_type="robot_instance",
                entity_id=int(snapshot.get("robot_instance_id") or 0) or None,
                payload=defeat_payload,
                ip=request.remote_addr,
            )
        if reward_summary.get("first_defeat"):
            audit_log(
                db,
                "CHAMP_DEFEAT_FIRST",
                user_id=int(user["id"]),
                request_id=request_id,
                action_key="champ_defeat_first",
                entity_type="robot_instance",
                entity_id=int(snapshot.get("robot_instance_id") or 0) or None,
                payload=defeat_payload,
                ip=request.remote_addr,
            )
        if reward_summary.get("daily_bonus_granted"):
            audit_log(
                db,
                "CHAMP_DEFEAT_DAILY",
                user_id=int(user["id"]),
                request_id=request_id,
                action_key="champ_defeat_daily",
                entity_type="robot_instance",
                entity_id=int(snapshot.get("robot_instance_id") or 0) or None,
                payload=defeat_payload,
                ip=request.remote_addr,
            )
        if type_affinity.get("result") == "disadvantage":
            audit_log(
                db,
                "CHAMP_DEFEAT_UPSET",
                user_id=int(user["id"]),
                request_id=request_id,
                action_key="champ_defeat_upset",
                entity_type="robot_instance",
                entity_id=int(snapshot.get("robot_instance_id") or 0) or None,
                payload=defeat_payload,
                ip=request.remote_addr,
            )

    battle_short_replay_enabled = _battle_short_replay_open_for_viewer(
        db,
        user_row=user,
        user_id=int(user["id"]),
    )
    enemy_replay_stats = dict(champion_enemy_payload.get("stats") or {})
    enemy_replay_stats["trait"] = enemy_replay_stats.get("trait") or "normal"
    battle_cinematic = (
        _build_battle_replay_summary(
            area_key="weekly_champion",
            area_label="今週のチャンプ機体",
            enemy_name=str(champion.get("robot_name") or champion_enemy_payload.get("name") or "チャンプ機体"),
            enemy_image_url=(
                champion.get("robot_image_url")
                or champion_enemy_payload.get("image_url")
                or url_for("static", filename="assets/placeholder_enemy.png")
            ),
            player_name=str(challenger_payload.get("robot_name") or active_robot.get("name") or "あなた"),
            player_image_url=(
                challenger_payload.get("robot_image_url")
                or active_robot.get("image_url")
                or url_for("static", filename="assets/placeholder_player.png")
            ),
            player_stats=dict(challenger_payload.get("stats") or {}),
            enemy_stats=enemy_replay_stats,
            robot_style={"style_key": str(challenger_payload.get("style_key") or "stable")},
            turn_logs=list(battle_result.get("turn_logs") or []),
            outcome=str(battle_result.get("outcome") or ""),
            is_boss=False,
        )
        if battle_short_replay_enabled
        else None
    )
    result_summary = {
        "outcome": str(battle_result.get("outcome") or ("勝利" if battle_result.get("win") else "敗北")),
        "outcome_is_win": bool(battle_result.get("win")),
        "summary_heading": str(battle_result.get("summary_heading") or ("今回の勝ち筋" if battle_result.get("win") else "今回の崩れ筋")),
        "summary_label": str(battle_result.get("summary_label") or ""),
        "result_label": str(battle_result.get("result_label") or ("WIN" if battle_result.get("win") else "LOSE")),
        "turn_count": int(battle_result.get("turn_count") or 0),
        "timeout_decision_line": (
            str((battle_result.get("timeout_decision") or {}).get("result_line") or "")
            if battle_result.get("timeout")
            else ""
        ),
        "reward_coin": int(reward_summary.get("reward_coin") or 0),
        "reward_base_coin": int(reward_summary.get("base_coin") or 0),
        "reward_daily_bonus_coin": int(reward_summary.get("daily_bonus_coin") or 0),
        "reward_core": int(reward_summary.get("core_reward") or 0),
        "first_defeat": bool(reward_summary.get("first_defeat")),
        "daily_bonus_granted": bool(reward_summary.get("daily_bonus_granted")),
        "affinity_card": affinity_card,
        "battle_cinematic": battle_cinematic,
        "headline": ("今週のチャンプを撃破！" if battle_result.get("win") else "チャンプには届かなかった"),
        "subline": (
            f"今週{int(stats_summary.get('defeat_count') or 0)}人目の撃破者です。"
            if battle_result.get("win")
            else "今回は届かなかった。もう少し育てて再挑戦しよう。"
        ),
        "challenge_count": int(stats_summary.get("challenge_count") or 0),
        "defense_count": int(stats_summary.get("champion_win_count") or 0),
        "defeat_count": int(stats_summary.get("defeat_count") or 0),
        "champion_win_rate": int(stats_summary.get("champion_win_rate") or 0),
    }
    db.commit()
    return render_template(
        "champion_battle.html",
        title="チャンプ挑戦結果",
        champion=champion,
        challenger=challenger_payload,
        active_robot=active_robot,
        turn_logs=list(battle_result.get("turn_logs") or []),
        summary=result_summary,
        affinity_card=affinity_card,
        battle_cinematic=result_summary["battle_cinematic"],
        battle_log_mode=(str(user["battle_log_mode"] or "collapsed").strip().lower() if "battle_log_mode" in user.keys() else "collapsed"),
        battle_short_replay_enabled=battle_short_replay_enabled,
    )


def _faction_page_context(db, user):
    user_faction = _normalize_faction_key(user["faction"] if "faction" in user.keys() else None)
    counts = _faction_unlock_counts(db, user["id"])
    can_choose = bool((not user_faction) and _faction_unlock_ready(counts))
    member_counts = _faction_member_counts(db)
    recommended_faction = _faction_recommended_key(member_counts)
    current_week_key = _world_week_key()
    faction_weekly_event = get_current_faction_weekly_event(db, current_week_key)
    weekly_env = _world_current_environment(db)
    weekly_faction_key = _element_to_faction(weekly_env["element"]) if weekly_env else None
    faction_score_rows = _faction_score_rows(
        _faction_week_scores(db, current_week_key),
        member_counts,
        user_faction=user_faction,
        weekly_faction_key=weekly_faction_key,
    )
    faction_activity_rows = get_weekly_faction_activity(db, current_week_key)
    faction_weekly_report_rows = get_faction_weekly_report(db, current_week_key)
    my_faction_weekly_position = get_my_faction_weekly_position(db, user, current_week_key)
    faction_awards = get_faction_weekly_awards(db, user_faction, current_week_key) if user_faction else {}
    faction_weekly_bonus = can_claim_faction_weekly_bonus(db, int(user["id"]), current_week_key)
    faction_badges = get_user_faction_badges(db, int(user["id"]), limit=5)
    faction_titles = get_user_faction_titles(db, int(user["id"]), limit=8)
    equipped_faction_title = get_equipped_faction_title(db, int(user["id"]))
    equipped_shop_items = get_user_equipped_faction_shop_items(db, int(user["id"]))
    faction_shop_purchase_count = int(
        db.execute("SELECT COUNT(*) AS c FROM user_faction_shop_purchases WHERE user_id = ?", (int(user["id"]),)).fetchone()["c"]
        or 0
    )
    faction_weekly_missions = get_faction_weekly_missions(db, current_week_key)
    faction_guardians = get_faction_guardians_view(db, current_week_key)
    faction_guardians_by_key = {row["faction_key"]: row for row in faction_guardians}
    faction_guardian_duels = get_faction_guardian_duels_view(db, current_week_key)
    sync_faction_facility_materials(db, current_week_key)
    faction_facilities = get_faction_facilities_view(db, current_week_key)
    faction_facilities_by_key = {row["faction_key"]: row for row in faction_facilities}
    faction_territory_map = get_current_faction_territory_map(db, current_week_key)
    faction_territory_summary = get_faction_territory_summary(db, user_faction, current_week_key, refresh=False) if user_faction else None
    faction_title_highlights = get_weekly_faction_title_highlights(db, current_week_key, faction_key=user_faction, limit=8) if user_faction else []
    faction_representatives = get_faction_representatives_view(db, current_week_key)
    faction_representatives_by_key = {row["faction_key"]: row for row in faction_representatives}
    faction_representative_matches = get_faction_representative_matches_view(db, current_week_key)
    guardian_target_key = get_guardian_target_faction(user_faction, current_week_key) if user_faction else None
    guardian_contribution = get_user_guardian_contribution(db, int(user["id"]), current_week_key) if user_faction else None
    faction_strategy_status = get_faction_strategy_status(db, user_faction, current_week_key, user_id=int(user["id"])) if user_faction else None
    faction_weekly_quests = get_faction_weekly_quests(db, current_week_key, user_faction, user_id=int(user["id"])) if user_faction else []
    return {
        "user": user,
        "user_faction": user_faction,
        "can_choose": can_choose,
        "unlock_counts": counts,
        "unlock_progress_line": _faction_unlock_progress_line(counts),
        "unlock_progress_rows": _faction_unlock_progress_rows(counts),
        "faction_labels": FACTION_LABELS,
        "faction_weekly_event": faction_weekly_event,
        "faction_emblems": FACTION_EMBLEMS,
        "member_counts": member_counts,
        "recommended_faction": recommended_faction,
        "faction_score_rows": faction_score_rows,
        "faction_activity_rows": faction_activity_rows,
        "faction_weekly_report_rows": faction_weekly_report_rows,
        "my_faction_weekly_position": my_faction_weekly_position,
        "faction_awards": faction_awards,
        "faction_award_categories": [
            {**award_def, "entries": list(faction_awards.get(award_def["key"], []))}
            for award_def in FACTION_WEEKLY_AWARD_DEFS
        ],
        "faction_weekly_bonus": faction_weekly_bonus,
        "faction_badges": faction_badges,
        "faction_titles": faction_titles,
        "equipped_faction_title": equipped_faction_title,
        "equipped_shop_items": equipped_shop_items,
        "faction_shop_purchase_count": faction_shop_purchase_count,
        "faction_weekly_missions": faction_weekly_missions,
        "faction_guardians": faction_guardians,
        "my_faction_guardian": faction_guardians_by_key.get(user_faction) if user_faction else None,
        "my_guardian_target": faction_guardians_by_key.get(guardian_target_key) if guardian_target_key else None,
        "faction_guardian_duels": faction_guardian_duels,
        "faction_facilities": faction_facilities,
        "my_faction_facility": faction_facilities_by_key.get(user_faction) if user_faction else None,
        "my_facility_contribution": get_user_faction_facility_weekly_contribution(db, int(user["id"]), current_week_key) if user_faction else 0,
        "facility_contribution_ranking": get_faction_facility_weekly_contributors(db, user_faction, current_week_key, limit=5) if user_faction else [],
        "faction_territory_map": faction_territory_map,
        "faction_territory_summary": faction_territory_summary,
        "faction_title_highlights": faction_title_highlights,
        "faction_representatives": faction_representatives,
        "my_faction_representative": faction_representatives_by_key.get(user_faction) if user_faction else None,
        "faction_representative_matches": faction_representative_matches,
        "guardian_contribution": guardian_contribution,
        "guardian_contribution_ranking": get_faction_guardian_contribution_ranking(db, user_faction, current_week_key, limit=5) if user_faction else [],
        "guardian_logs": get_faction_guardian_logs_for_faction(db, user_faction, current_week_key, limit=10) if user_faction else [],
        "faction_strategy_status": faction_strategy_status,
        "faction_weekly_quests": faction_weekly_quests,
        "faction_strategy_defs": list(FACTION_STRATEGIES.values()),
        "faction_spotlight_rows": get_weekly_faction_members_spotlight(db, user_faction, limit=5, week_key=current_week_key) if user_faction else [],
        "current_week_key": current_week_key,
        "change_status": _faction_change_status(user),
        "cooldown_days": FACTION_CHANGE_COOLDOWN_DAYS,
        "minority_factions": _faction_minority_keys(member_counts),
        "user_is_admin": bool(user and "is_admin" in user.keys() and int(user["is_admin"] or 0) == 1),
        "faction_report_labels": FACTION_WEEKLY_REPORT_LABELS,
    }


@app.route("/faction")
@login_required
def faction_view():
    db = get_db()
    user = db.execute("SELECT * FROM users WHERE id = ?", (session["user_id"],)).fetchone()
    if not user:
        session.clear()
        return redirect(url_for("login"))
    context = _faction_page_context(db, user)
    db.commit()
    return render_template("faction.html", **context)


@app.route("/faction/shop")
@login_required
def faction_shop():
    db = get_db()
    user = db.execute("SELECT * FROM users WHERE id = ?", (session["user_id"],)).fetchone()
    if not user:
        session.clear()
        return redirect(url_for("login"))
    ensure_default_faction_shop_items(db)
    purchases = get_user_faction_shop_purchases(db, int(user["id"]))
    purchased_keys = {row["item_key"] for row in purchases}
    equipped = get_user_equipped_faction_shop_items(db, int(user["id"]))
    items = []
    for item in get_faction_shop_items(db):
        raw = _get_faction_shop_item_row(db, item["id"])
        can = can_purchase_faction_shop_item(db, int(user["id"]), int(item["id"])) if raw else {"ok": False, "reason": "商品が見つかりません。"}
        items.append(_faction_shop_item_view_row(raw, purchased=item["item_key"] in purchased_keys, can_purchase=can, equipped_slot=(equipped.get(item["item_key"]) or {}).get("slot_key")) if raw else item)
    db.commit()
    return render_template(
        "faction_shop.html",
        user=user,
        user_faction=_normalize_faction_key(user["faction"] if "faction" in user.keys() else None),
        faction_labels=FACTION_LABELS,
        item_type_labels=FACTION_SHOP_ITEM_TYPES,
        items=items,
        purchases=purchases,
        equipped=equipped,
        message=session.pop("message", None),
    )


