@app.route("/milestone/claim", methods=["POST"])
@login_required
def milestone_claim():
    db = get_db()
    user = db.execute("SELECT * FROM users WHERE id = ?", (session["user_id"],)).fetchone()
    _ensure_qol_entitlement(db, user["id"])
    milestone_key = request.form.get("milestone_key", "").strip()
    robot_name = request.form.get("robot_name", "").strip()
    if not milestone_key or not robot_name:
        session["message"] = "受取にはロボ名の入力が必要です。"
        return redirect(url_for("home"))
    m = db.execute(
        "SELECT * FROM robot_milestones WHERE milestone_key = ? AND active = 1",
        (milestone_key,),
    ).fetchone()
    if not m:
        session["message"] = "無効なマイルストーンです。"
        return redirect(url_for("home"))
    claimed = db.execute(
        "SELECT 1 FROM user_milestone_claims WHERE user_id = ? AND milestone_key = ?",
        (user["id"], milestone_key),
    ).fetchone()
    if claimed:
        session["message"] = "このマイルストーンは受取済みです。"
        return redirect(url_for("home"))
    metric_value = user[m["metric"]] if m["metric"] in user.keys() else 0
    if metric_value < m["threshold_value"]:
        session["message"] = "受取条件を満たしていません。"
        return redirect(url_for("home"))
    limits = _effective_limits(db, user)
    instance_count = db.execute(
        "SELECT COUNT(*) AS c FROM robot_instances WHERE user_id = ? AND status != 'decomposed'",
        (user["id"],),
    ).fetchone()["c"]
    if instance_count >= limits["robot_slots"]:
        session["message"] = "保存枠が上限です。分解して枠を空けてください。"
        return redirect(url_for("home"))
    instance_id = _create_robot_instance(
        db,
        user["id"],
        robot_name,
        m["reward_head_key"],
        m["reward_r_arm_key"],
        m["reward_l_arm_key"],
        m["reward_legs_key"],
    )
    db.execute(
        """
        INSERT INTO user_milestone_claims (user_id, milestone_key, robot_instance_id, claimed_at)
        VALUES (?, ?, ?, ?)
        """,
        (user["id"], milestone_key, instance_id, int(time.time())),
    )
    db.commit()
    session["message"] = "完成ロボを受け取りました。開発支援のQoL拡張で保存枠を増やせます。"
    return redirect(url_for("home"))


def _part_lock_redirect_params():
    selected_part_type = _normalize_part_type_filter(request.form.get("part_type"))
    selected_frame_type = str(request.form.get("frame_type") or "").strip().lower()
    if selected_frame_type not in {"", *FRAME_TYPE_DEF_BY_KEY.keys()}:
        selected_frame_type = ""
    selected_rarity = str(request.form.get("rarity") or "").strip().upper()
    if selected_rarity not in {"", "N", "R", "SR", "SSR", "UR"}:
        selected_rarity = ""
    selected_series_key = str(request.form.get("series_key") or "").strip()
    selected_sort = _normalize_parts_sort(request.form.get("sort"))
    page_raw = request.form.get("page", "1")
    try:
        page = max(1, int(page_raw))
    except (TypeError, ValueError):
        page = 1
    params = {}
    if selected_part_type:
        params["part_type"] = selected_part_type
    if selected_frame_type:
        params["frame_type"] = selected_frame_type
    if selected_rarity:
        params["rarity"] = selected_rarity
    if selected_series_key:
        params["series_key"] = selected_series_key
    if selected_sort != "recommended":
        params["sort"] = selected_sort
    if page > 1:
        params["page"] = page
    return params


def _parts_anchor_redirect(params, part_instance_id):
    return redirect(url_for("parts", **(params or {})) + f"#part-{int(part_instance_id)}")


def _part_lock_redirect(part_instance_id, params=None):
    return_to = _relative_redirect_target(request.form.get("return_to"), "")
    if return_to:
        return redirect(return_to)
    return _parts_anchor_redirect(params or {}, part_instance_id)


def _part_lock_row(db, user_id, part_instance_id):
    return db.execute(
        """
        SELECT
            pi.id, pi.rarity, pi.plus, pi.locked, pi.status,
            rp.key, rp.key AS part_key, rp.display_name_ja, rp.image_path, rp.part_type
        FROM part_instances pi
        JOIN robot_parts rp ON rp.id = pi.part_id
        WHERE pi.id = ? AND pi.user_id = ?
        LIMIT 1
        """,
        (int(part_instance_id), int(user_id)),
    ).fetchone()


def _audit_part_lock_change(db, *, user_id, part_row, locked):
    audit_log(
        db,
        AUDIT_EVENT_TYPES["PART_LOCK"] if locked else AUDIT_EVENT_TYPES["PART_UNLOCK"],
        user_id=int(user_id),
        request_id=getattr(g, "request_id", None),
        action_key=("part_lock" if locked else "part_unlock"),
        entity_type="part_instance",
        entity_id=int(part_row["id"]),
        payload={
            "part_instance_id": int(part_row["id"]),
            "part_key": str(part_row["part_key"] or ""),
            "part_name": _part_display_name_ja(part_row),
            "rarity": str(part_row["rarity"] or "N").upper(),
            "plus": int(part_row["plus"] or 0),
            "locked": 1 if locked else 0,
        },
        ip=request.remote_addr,
    )


@app.route("/parts/<int:part_instance_id>/lock", methods=["POST"])
@login_required
def part_lock(part_instance_id):
    db = get_db()
    user_id = int(session["user_id"])
    redirect_params = _part_lock_redirect_params()
    part_row = _part_lock_row(db, user_id, part_instance_id)
    if not part_row:
        flash("保護するパーツが見つかりません。", "error")
        return redirect(_relative_redirect_target(request.form.get("return_to"), url_for("parts", **redirect_params)))
    db.execute(
        "UPDATE part_instances SET locked = 1, updated_at = datetime('now') WHERE id = ? AND user_id = ?",
        (int(part_instance_id), user_id),
    )
    _audit_part_lock_change(db, user_id=user_id, part_row=part_row, locked=True)
    db.commit()
    flash("パーツを保護しました。", "notice")
    return _part_lock_redirect(part_instance_id, redirect_params)


