@app.route("/parts/discard", methods=["POST"])
@login_required
def parts_discard():
    db = get_db()
    selected_part_type = _normalize_part_type_filter(request.form.get("part_type"))
    selected_frame_type = str(request.form.get("frame_type") or "").strip().lower()
    if selected_frame_type not in {"", *FRAME_TYPE_DEF_BY_KEY.keys()}:
        selected_frame_type = ""
    selected_sort = _normalize_parts_sort(request.form.get("sort"))
    try:
        page = max(1, int(request.form.get("page", "1")))
    except (TypeError, ValueError):
        page = 1
    redirect_params = {}
    if selected_part_type:
        redirect_params["part_type"] = selected_part_type
    if selected_frame_type:
        redirect_params["frame_type"] = selected_frame_type
    if selected_sort != "recommended":
        redirect_params["sort"] = selected_sort
    if page > 1:
        redirect_params["page"] = page
    confirm = request.form.get("confirm")
    if confirm != "yes":
        session["message"] = "完全削除の確認が必要です。コインは増えず、元に戻せません。"
        return redirect(url_for("parts", **redirect_params))
    instance_ids = request.form.getlist("instance_ids")
    valid_instance_ids = [pid for pid in instance_ids if pid.isdigit()]
    if valid_instance_ids:
        placeholders = ",".join(["?"] * len(valid_instance_ids))
        cur = db.execute(
            f"DELETE FROM part_instances WHERE user_id = ? AND status = 'inventory' AND COALESCE(locked, 0) = 0 AND id IN ({placeholders})",
            [session["user_id"], *valid_instance_ids],
        )
        db.commit()
        deleted_count = int(cur.rowcount or 0)
        skipped_count = max(0, len(valid_instance_ids) - deleted_count)
        if skipped_count > 0:
            session["message"] = f"{deleted_count} 件の個体パーツを完全削除しました。装備中・保護中または対象外 {skipped_count} 件は残しています。"
        else:
            session["message"] = f"{deleted_count} 件の個体パーツを完全削除しました。"
        return redirect(url_for("parts", **redirect_params))

    part_keys = [k.strip() for k in request.form.getlist("part_keys") if k.strip()]
    if part_keys:
        placeholders = ",".join(["?"] * len(part_keys))
        cur = db.execute(
            f"DELETE FROM user_parts_inventory WHERE user_id = ? AND part_key IN ({placeholders})",
            [session["user_id"], *part_keys],
        )
        db.commit()
        session["message"] = f"{cur.rowcount} 件の旧在庫パーツを完全削除しました。"
        return redirect(url_for("parts", **redirect_params))

    part_ids = request.form.getlist("part_ids")
    single_id = request.form.get("part_id")
    if single_id:
        part_ids.append(single_id)
    valid_ids = [pid for pid in part_ids if pid.isdigit()]
    if not valid_ids:
        session["message"] = "完全削除の対象が選択されていません。"
        return redirect(url_for("parts", **redirect_params))
    placeholders = ",".join(["?"] * len(valid_ids))
    cur = db.execute(
        f"DELETE FROM user_parts_inventory WHERE user_id = ? AND id IN ({placeholders})",
        [session["user_id"], *valid_ids],
    )
    db.commit()
    session["message"] = f"{cur.rowcount} 件のパーツを完全削除しました。"
    return redirect(url_for("parts", **redirect_params))


