@app.route("/battle/result")
@login_required
def battle_result():
    user_id = int(session["user_id"])
    db = get_db()
    session.pop("last_battle_result", None)
    saved = _load_battle_result_cache(db, user_id, session.get("last_battle_result_id"))
    if not saved or not saved.get("summary"):
        flash("戦闘結果を再表示できませんでした。", "error")
        return redirect(url_for("home"))
    user = db.execute(
        "SELECT id, is_admin, part_inventory_limit FROM users WHERE id = ?",
        (user_id,),
    ).fetchone()
    if not user:
        return redirect(url_for("login"))
    summary = _refresh_battle_result_summary(db, user_id, user, saved.get("summary") or {})
    active_robot_view = _get_active_robot(db, user_id)
    return render_template(
        "battle.html",
        state={"active": 0, "enemy_name": summary.get("enemy_name", "謎の敵"), "enemy_hp": 0},
        log=[],
        log_entries=[],
        message=None,
        new_robot=None,
        explore_mode=True,
        explore_area_key=str(saved.get("area_key") or "layer_1"),
        explore_area_label=str(saved.get("area_label") or ""),
        active_robot=active_robot_view,
        no_active_robot=False,
        turn_logs=[],
        summary=summary,
        battle_log_mode="collapsed",
        battle_ritual_overlay_enabled=False,
        battle_short_replay_enabled=False,
    )


@app.route("/share/boss", methods=["POST"])
@login_required
def share_boss_defeat():
    db = get_db()
    user_id = int(session["user_id"])
    user = db.execute("SELECT username FROM users WHERE id = ?", (user_id,)).fetchone()
    enemy_key = (request.form.get("enemy_key") or "").strip()
    enemy_name = (request.form.get("enemy_name") or "未知のボス").strip()
    area_key = (request.form.get("area_key") or "").strip()
    area_label = (request.form.get("area_label") or _boss_area_label(area_key) or area_key or "不明エリア").strip()
    robot_id_raw = (request.form.get("robot_id") or "").strip()
    robot_name = (request.form.get("robot_name") or "").strip()
    robot_id = int(robot_id_raw) if robot_id_raw.isdigit() else None
    if robot_id:
        robot = db.execute(
            "SELECT id, name FROM robot_instances WHERE id = ? AND user_id = ?",
            (robot_id, user_id),
        ).fetchone()
        if robot:
            robot_name = (robot["name"] or robot_name).strip()
        else:
            robot_id = None
    payload = {
        "share_type": "boss_defeat",
        "enemy_key": enemy_key,
        "enemy_name": enemy_name,
        "area_key": area_key,
        "area_label": area_label,
        "robot_id": robot_id,
        "robot_name": robot_name,
        "user_id": user_id,
        "username": (user["username"] if user and user["username"] else session.get("username", "unknown")),
        "game_url": _public_game_root_url(),
    }
    share_text = build_share_text("share.boss.defeat", payload)
    audit_log(
        db,
        AUDIT_EVENT_TYPES["SHARE_CLICK"],
        user_id=user_id,
        request_id=getattr(g, "request_id", None),
        action_key="share",
        entity_type="enemy",
        entity_id=None,
        payload=payload,
        ip=request.remote_addr,
    )
    db.commit()
    intent_url = "https://x.com/intent/tweet?" + urlencode({"text": share_text})
    return redirect(intent_url)


