@app.route("/share/robot/<int:robot_instance_id>")
def share_robot_public(robot_instance_id):
    db = get_db()
    row = db.execute(
        """
        SELECT
            ri.id, ri.user_id, ri.name, ri.personality, ri.composed_image_path, ri.icon_32_path,
            ri.combat_mode, ri.updated_at, ri.style_key, ri.style_stats_json, ri.is_public,
            u.username, u.display_name, u.is_admin, u.max_unlocked_layer
        FROM robot_instances ri
        JOIN users u ON u.id = ri.user_id
        WHERE ri.id = ?
          AND ri.status = 'active'
          AND COALESCE(ri.is_public, 1) = 1
        LIMIT 1
        """,
        (int(robot_instance_id),),
    ).fetchone()
    if not row:
        abort(404)
    robot = _refresh_robot_instance_render_assets(db, row, log_label="share_robot_public") or dict(row)
    stat_obj = _compute_robot_stats_for_instance(db, int(robot["id"]))
    profile = _robot_profile_view(stat_obj) if stat_obj else None
    profile_label = str((profile or {}).get("signature_label") or "").strip()
    profile_battle_line = str((profile or {}).get("battle_style_line") or "").strip()
    share_url = _absolute_public_url(url_for("share_robot_public", robot_instance_id=int(robot["id"])))
    image_url = (
        _absolute_public_url(_composed_image_url(robot.get("composed_image_path"), robot.get("updated_at")))
        if robot.get("composed_image_path")
        else _share_default_image_url()
    )
    owner_name = _display_username(
        str(row["username"] or "").strip(),
        display_name=str(row["display_name"] or "").strip(),
        is_admin=bool(int(row["is_admin"] or 0)),
    )
    robot_name = str(robot.get("name") or "相棒ロボ").strip()
    title = f"{robot_name} | ロボらぼ"
    return render_template(
        "share_robot.html",
        title=title,
        og_title=title,
        og_description="ロボらぼで育てた機体を公開中",
        og_image=image_url,
        og_url=share_url,
        share_url=share_url,
        robot=robot,
        owner_name=owner_name,
        profile_label=profile_label,
        profile_battle_line=profile_battle_line,
        max_layer=int(row["max_unlocked_layer"] or 1),
        image_url=image_url,
    )


@app.route("/robots")
@login_required
def robots():
    db = get_db()
    user = db.execute("SELECT * FROM users WHERE id = ?", (session["user_id"],)).fetchone()
    _ensure_qol_entitlement(db, user["id"])
    show_decomposed = request.args.get("show_decomposed", "0") == "1"
    where = "ri.user_id = ?"
    params = [session["user_id"]]
    if not show_decomposed:
        where += " AND ri.status != 'decomposed'"
    instances = db.execute(
        f"""
        SELECT ri.*, rip.head_key, rip.r_arm_key, rip.l_arm_key, rip.legs_key
        FROM robot_instances ri
        JOIN robot_instance_parts rip ON rip.robot_instance_id = ri.id
        WHERE {where}
        ORDER BY ri.updated_at DESC
        """,
        params,
    ).fetchall()
    instances = [dict(r) for r in instances]
    weekly_env = _world_current_environment(db)
    weekly_element = weekly_env["element"] if weekly_env else None
    for idx, inst in enumerate(instances):
        inst = _refresh_robot_instance_render_assets(db, inst, log_label="robots")
        if not inst:
            continue
        instances[idx] = inst
        raw_name = (inst.get("name") or "").strip()
        if not raw_name or re.fullmatch(r"Robot\s*#\d+", raw_name):
            inst["display_name"] = "無名ロボ"
        else:
            inst["display_name"] = raw_name
        stat_obj = _compute_robot_stats_for_instance(db, inst["id"])
        if stat_obj:
            inst["final_stats"] = stat_obj["stats"]
            inst["power"] = stat_obj["power"]
            inst["set_bonus"] = stat_obj["set_bonus"]
            inst["is_mixed_frame"] = bool(stat_obj.get("is_mixed_frame"))
            inst["archetype"] = stat_obj.get("archetype")
            inst["robot_profile"] = _robot_profile_view(stat_obj)
        else:
            inst["final_stats"] = None
            inst["power"] = None
            inst["set_bonus"] = None
            inst["is_mixed_frame"] = bool(int(inst.get("is_mixed_frame") or 0))
            inst["archetype"] = None
            inst["robot_profile"] = _robot_profile_view(None)
        inst["weekly_fit"] = _robot_weekly_fit(db, inst["id"], weekly_element) if weekly_element else False
    limits = _effective_limits(db, user)
    used_all = db.execute(
        "SELECT COUNT(*) AS c FROM robot_instances WHERE user_id = ? AND status != 'decomposed'",
        (session["user_id"],),
    ).fetchone()["c"]
    used_display = min(used_all, limits["robot_slots"])
    overflow = max(0, used_all - limits["robot_slots"])
    message = session.pop("message", None)
    decompose_blocked = bool(session.pop("robot_decompose_blocked", None))
    return render_template(
        "robots.html",
        instances=instances,
        message=message,
        decompose_blocked=decompose_blocked,
        limits=limits,
        active_robot_id=user["active_robot_id"],
        weekly_element=weekly_element,
        show_decomposed=show_decomposed,
        used_all=used_all,
        used_display=used_display,
        overflow=overflow,
    )


@app.route("/robots/<int:instance_id>")
@login_required
def robot_detail(instance_id):
    db = get_db()
    user_id = int(session["user_id"])
    row = db.execute(
        """
        SELECT
            ri.*,
            rip.head_key,
            rip.r_arm_key,
            rip.l_arm_key,
            rip.legs_key,
            rip.decor_asset_id,
            u.username AS owner_name,
            u.max_unlocked_layer AS owner_max_unlocked_layer
        FROM robot_instances ri
        JOIN robot_instance_parts rip ON rip.robot_instance_id = ri.id
        JOIN users u ON u.id = ri.user_id
        WHERE ri.id = ?
          AND ri.status = 'active'
          AND (ri.user_id = ? OR COALESCE(ri.is_public, 1) = 1)
        """,
        (int(instance_id), user_id),
    ).fetchone()
    if not row:
        abort(404)
    robot = dict(row)
    robot["frame_type"] = _normalize_frame_type(robot.get("frame_type"))
    robot["frame_label"] = _frame_type_label(robot["frame_type"])
    # Robot detail should always reflect latest part offsets/alignment.
    # Re-compose here to avoid stale composed_image_path from prior cache states.
    try:
        rel = _compose_instance_image(db, robot, robot)
        if rel:
            robot["composed_image_path"] = rel
            latest = db.execute("SELECT updated_at FROM robot_instances WHERE id = ?", (robot["id"],)).fetchone()
            robot["updated_at"] = int(latest["updated_at"] or 0) if latest else int(time.time())
    except Exception:
        app.logger.exception("robot_detail.compose_failed instance_id=%s", instance_id)
        if not robot.get("composed_image_path"):
            rel = _compose_instance_image(db, robot, robot)
            robot["composed_image_path"] = rel
            latest = db.execute("SELECT updated_at FROM robot_instances WHERE id = ?", (robot["id"],)).fetchone()
            robot["updated_at"] = int(latest["updated_at"] or 0) if latest else int(time.time())
    robot["image_url"] = _composed_image_url(robot.get("composed_image_path"), robot.get("updated_at"))
    stat_obj = _compute_robot_stats_for_instance(db, int(robot["id"]))
    robot["final_stats"] = stat_obj["stats"] if stat_obj else None
    robot["power"] = stat_obj["power"] if stat_obj else None
    robot["set_bonus"] = stat_obj["set_bonus"] if stat_obj else None
    robot["set_bonus_view"] = _set_bonus_view_for_loadout(
        (stat_obj or {}).get("parts"),
        (stat_obj or {}).get("set_bonus"),
        disabled_reason="自由編成の混成ロボはセットボーナスなし" if (stat_obj or {}).get("is_mixed_frame") else None,
    )
    robot["series_view"] = (
        _series_bonus_view_for_loadout(
            db,
            (stat_obj or {}).get("parts"),
            series_calc=stat_obj,
            progress_layer=int(robot.get("owner_max_unlocked_layer") or 1),
        )
        if _series_system_enabled_for_user(db, user_id=int(robot["user_id"]))
        else None
    )
    robot["archetype"] = stat_obj.get("archetype") if stat_obj else None
    robot["robot_profile"] = _robot_profile_view(stat_obj)
    robot["style_state"] = (
        _robot_style_state_for_view(db, int(robot["id"]), stat_obj=stat_obj)
        if stat_obj
        else None
    )
    if robot.get("decor_asset_id"):
        decor_row = db.execute(
            "SELECT key, name_ja FROM robot_decor_assets WHERE id = ?",
            (int(robot["decor_asset_id"]),),
        ).fetchone()
        robot["decor_name"] = decor_row["name_ja"] if decor_row else None
    else:
        robot["decor_name"] = None

    part_rows = db.execute(
        """
        SELECT part_type, key, display_name_ja, rarity, element, series
        FROM robot_parts
        WHERE key IN (?, ?, ?, ?)
        """,
        (
            robot.get("head_key"),
            robot.get("r_arm_key"),
            robot.get("l_arm_key"),
            robot.get("legs_key"),
        ),
    ).fetchall()
    part_by_key = {str(r["key"]): dict(r) for r in part_rows}

    def _slot_line(label, key):
        row = part_by_key.get(str(key or ""))
        if row:
            name = _part_display_name_ja(row)
            series_badge = _series_badge_payload(row.get("series"))
        else:
            name = str(key or "-")
            series_badge = None
        return {
            "slot_label": label,
            "part_name": name,
            "part_key": str(key or "-"),
            "series_badge": series_badge,
        }

    robot_composition = [
        _slot_line("頭部", robot.get("head_key")),
        _slot_line("右腕", robot.get("r_arm_key")),
        _slot_line("左腕", robot.get("l_arm_key")),
        _slot_line("脚部", robot.get("legs_key")),
        {"slot_label": "装飾", "part_name": (robot.get("decor_name") or "なし"), "part_key": None},
    ]
    weekly_env = _world_current_environment(db)
    weekly_element = weekly_env["element"] if weekly_env else None
    weekly_fit = _robot_weekly_fit(db, int(robot["id"]), weekly_element) if weekly_element else False
    history = _robot_history_row(db, int(robot["id"]))
    title_summary = robot_title_summary(db, int(robot["id"]))
    primary_title_view = title_summary.get("primary")
    primary_title_label = (
        primary_title_view.get("label")
        if primary_title_view
        else _robot_primary_title(db, int(robot["id"]))
    )
    titles = db.execute(
        """
        SELECT rt.key, rt.name_ja, rt.desc_ja, rt.sort_order, rtu.unlocked_at
        FROM robot_title_unlocks rtu
        JOIN robot_titles rt ON rt.id = rtu.title_id
        WHERE rtu.robot_id = ? AND rt.is_active = 1
        ORDER BY rt.sort_order ASC, rtu.unlocked_at DESC
        """,
        (int(robot["id"]),),
    ).fetchall()
    achievements = db.execute(
        """
        SELECT id, type, title, body, enemy_key, enemy_name, week_key, created_at
        FROM robot_achievements
        WHERE robot_id = ?
        ORDER BY created_at DESC, id DESC
        LIMIT 60
        """,
        (int(robot["id"]),),
    ).fetchall()
    db.commit()
    return render_template(
        "robot_detail.html",
        robot=robot,
        robot_composition=robot_composition,
        history=history,
        titles=titles,
        title_summary=title_summary,
        robot_story_titles=title_summary.get("titles") or [],
        achievements=achievements,
        weekly_env=weekly_env,
        weekly_fit=weekly_fit,
        primary_title=primary_title_label,
        can_share=(int(robot["user_id"]) == user_id),
        can_maintain=(int(robot["user_id"]) == user_id),
    )


@app.route("/robots/<int:instance_id>/maintenance", methods=["GET", "POST"])
@login_required
def robot_maintenance(instance_id):
    db = get_db()
    user_id = int(session["user_id"])
    user = db.execute("SELECT * FROM users WHERE id = ?", (user_id,)).fetchone()
    robot_row = db.execute(
        """
        SELECT
            ri.*,
            rip.*
        FROM robot_instances ri
        JOIN robot_instance_parts rip ON rip.robot_instance_id = ri.id
        WHERE ri.id = ?
          AND ri.user_id = ?
          AND ri.status = 'active'
        """,
        (int(instance_id), user_id),
    ).fetchone()
    if not robot_row:
        abort(404)

    robot = dict(robot_row)
    active_mapping = _ensure_robot_instance_part_instances(db, int(instance_id)) or {}
    parts_row = db.execute(
        "SELECT * FROM robot_instance_parts WHERE robot_instance_id = ?",
        (int(instance_id),),
    ).fetchone()
    if not parts_row:
        abort(404)

    slot = _normalize_maintenance_slot(request.values.get("slot"))
    slot_tabs = [
        {
            "slot": item["slot"],
            "label": item["label"],
            "is_active": item["slot"] == slot,
            "url": url_for("robot_maintenance", instance_id=int(instance_id), slot=item["slot"]),
        }
        for item in ROBOT_MAINTENANCE_SLOT_DEFS
    ]

    current_rows = _part_instance_display_rows(
        db,
        [
            active_mapping.get("head"),
            active_mapping.get("r_arm"),
            active_mapping.get("l_arm"),
            active_mapping.get("legs"),
        ],
    )
    current_rows_by_id = {int(row["instance_id"]): row for row in current_rows}
    current_part_items = {}
    slot_key_to_part_type = {
        "head": "HEAD",
        "r_arm": "RIGHT_ARM",
        "l_arm": "LEFT_ARM",
        "legs": "LEGS",
    }
    for mapping_key, part_type in slot_key_to_part_type.items():
        current_row = current_rows_by_id.get(int(active_mapping.get(mapping_key) or 0))
        if current_row:
            current_part_items[part_type] = _build_picker_part_item(current_row)

    current_payloads = {
        part_type: _robot_payload_from_part_picker_item(item)
        for part_type, item in current_part_items.items()
        if item
    }
    series_progress_layer = _series_progress_layer_for_user(db, user_id)
    series_bonus_defs = (
        _load_series_bonus_defs(db, active_only=True)
        if _series_system_enabled_for_user(db, user_id=user_id)
        else {}
    )
    current_estimate = (
        compute_robot_stats(
            list(current_payloads.values()),
            series_bonus_defs=series_bonus_defs,
            series_progress_layer=series_progress_layer,
        )
        if len(current_payloads) == 4
        else None
    )
    current_robot_stats = {
        "hp": int((current_estimate or {}).get("stats", {}).get("hp") or 0),
        "atk": int((current_estimate or {}).get("stats", {}).get("atk") or 0),
        "def": int((current_estimate or {}).get("stats", {}).get("def") or 0),
        "spd": int((current_estimate or {}).get("stats", {}).get("spd") or 0),
        "acc": int((current_estimate or {}).get("stats", {}).get("acc") or 0),
        "cri": int((current_estimate or {}).get("stats", {}).get("cri") or 0),
        "power": float((current_estimate or {}).get("power") or 0.0),
    }
    current_profile = _robot_profile_from_estimate(current_estimate)
    robot["robot_profile"] = current_profile
    robot["power"] = current_robot_stats["power"]
    robot["final_stats"] = (current_estimate or {}).get("stats")
    robot["set_bonus"] = (current_estimate or {}).get("set_bonus")
    robot["image_url"] = _composed_image_url(robot.get("composed_image_path"), robot.get("updated_at"))
    robot["frame_type"] = _normalize_frame_type(robot.get("frame_type"))
    robot["frame_label"] = _frame_type_label(robot["frame_type"])

    decor_assets = db.execute(
        """
        SELECT rda.id, rda.key, rda.name_ja, rda.image_path
        FROM user_decor_inventory udi
        JOIN robot_decor_assets rda ON rda.id = udi.decor_asset_id
        WHERE udi.user_id = ? AND rda.is_active = 1
        ORDER BY udi.acquired_at DESC, rda.id DESC
        """,
        (user_id,),
    ).fetchall()
    decor_assets = [
        {
            **dict(row),
            "display_image_path": _decor_image_rel(row["image_path"], row["key"]),
            "image_url": url_for("static", filename=_decor_image_rel(row["image_path"], row["key"]), v=APP_VERSION),
        }
        for row in decor_assets
    ]
    owned_decor_ids = {int(item["id"]) for item in decor_assets}
    current_decor_rows = _robot_instance_decor_rows(
        db,
        int(instance_id),
        legacy_decor_id=parts_row["decor_asset_id"] if "decor_asset_id" in parts_row.keys() else None,
    )
    if request.method == "POST" and getattr(db, "in_transaction", False):
        # Legacy robots can be backfilled with part_instance ids above. Commit that
        # repair before opening the explicit maintenance transaction.
        db.commit()

    if request.method == "POST":
        slot = _normalize_maintenance_slot(request.form.get("slot"))
        slot_def = ROBOT_MAINTENANCE_SLOT_DEF_BY_KEY[slot]
        request_id = getattr(g, "request_id", None)
        current_label = slot_def["label"]
        if slot == "DECOR":
            slot_raw = (request.form.get("decor_slot_index") or "0").strip()
            decor_slot_index = int(slot_raw) if slot_raw.isdigit() else -1
            if decor_slot_index < 0 or decor_slot_index >= MAX_ROBOT_DECOR_SLOTS:
                flash("装飾スロットが不正です。", "error")
                return redirect(url_for("robot_maintenance", instance_id=instance_id, slot=slot))
            decor_raw = (request.form.get("decor_asset_id") or "").strip().lower()
            next_decor_id = None if decor_raw in {"", "0", "none"} else (int(decor_raw) if decor_raw.isdigit() else None)
            if decor_raw not in {"", "0", "none"} and next_decor_id is None:
                flash("装飾候補が不正です。", "error")
                return redirect(url_for("robot_maintenance", instance_id=instance_id, slot=slot))
            if next_decor_id is not None and int(next_decor_id) not in owned_decor_ids:
                flash("装飾候補が見つかりません。", "error")
                return redirect(url_for("robot_maintenance", instance_id=instance_id, slot=slot))
            default_offset = _default_robot_decor_offset(decor_slot_index)
            before_row = next((row for row in current_decor_rows if int(row["slot_index"] or 0) == decor_slot_index), None)
            before_decor_id = int(before_row["id"]) if before_row else None
            before_offset = {
                "x": int(before_row["offset_x"] or 0) if before_row else default_offset["x"],
                "y": int(before_row["offset_y"] or 0) if before_row else default_offset["y"],
            }
            next_offset = {
                "x": _clamp_robot_decor_offset(request.form.get("offset_x") if "offset_x" in request.form else default_offset["x"]),
                "y": _clamp_robot_decor_offset(request.form.get("offset_y") if "offset_y" in request.form else default_offset["y"]),
            }
            if before_decor_id == next_decor_id and before_offset == next_offset:
                flash("装飾はすでにその構成です。", "notice")
                return redirect(url_for("robot_maintenance", instance_id=instance_id, slot=slot))
            try:
                db.execute("BEGIN IMMEDIATE")
                now_ts = int(time.time())
                if next_decor_id is None:
                    db.execute(
                        "DELETE FROM robot_instance_decors WHERE robot_instance_id = ? AND slot_index = ?",
                        (int(instance_id), decor_slot_index),
                    )
                else:
                    db.execute(
                        """
                        INSERT INTO robot_instance_decors (
                            robot_instance_id, decor_asset_id, slot_index, offset_x, offset_y, created_at, updated_at
                        )
                        VALUES (?, ?, ?, ?, ?, ?, ?)
                        ON CONFLICT(robot_instance_id, slot_index)
                        DO UPDATE SET decor_asset_id = excluded.decor_asset_id,
                                      offset_x = excluded.offset_x,
                                      offset_y = excluded.offset_y,
                                      updated_at = excluded.updated_at
                        """,
                        (
                            int(instance_id),
                            int(next_decor_id),
                            decor_slot_index,
                            int(next_offset["x"]),
                            int(next_offset["y"]),
                            now_ts,
                            now_ts,
                        ),
                    )
                first_decor = db.execute(
                    """
                    SELECT decor_asset_id
                    FROM robot_instance_decors
                    WHERE robot_instance_id = ?
                    ORDER BY slot_index ASC
                    LIMIT 1
                    """,
                    (int(instance_id),),
                ).fetchone()
                db.execute(
                    "UPDATE robot_instance_parts SET decor_asset_id = ? WHERE robot_instance_id = ?",
                    (int(first_decor["decor_asset_id"]) if first_decor else None, int(instance_id)),
                )
                refreshed_parts = db.execute(
                    "SELECT * FROM robot_instance_parts WHERE robot_instance_id = ?",
                    (int(instance_id),),
                ).fetchone()
                _compose_instance_assets_no_commit(db, int(instance_id), refreshed_parts)
                audit_log(
                    db,
                    AUDIT_EVENT_TYPES["ROBOT_MAINTENANCE"],
                    user_id=user_id,
                    request_id=request_id,
                    action_key="maintenance",
                    entity_type="robot_instance",
                    entity_id=int(instance_id),
                    payload={
                        "robot_instance_id": int(instance_id),
                        "robot_name": robot.get("name"),
                        "changed_slots": ["DECOR"],
                        "decor_slot_index": decor_slot_index,
                        "before_part_ids": {"DECOR": before_decor_id},
                        "after_part_ids": {"DECOR": next_decor_id},
                        "before_offsets": {"DECOR": before_offset},
                        "after_offsets": {"DECOR": next_offset},
                        "stat_delta": {"power": 0, "hp": 0, "atk": 0, "def": 0, "spd": 0, "acc": 0, "cri": 0},
                        "power_delta": 0,
                    },
                    ip=request.remote_addr,
                )
                db.commit()
            except Exception:
                db.rollback()
                app.logger.exception("robot_maintenance.decor_failed instance_id=%s", instance_id)
                flash("機体整備の更新に失敗しました。", "error")
                return redirect(url_for("robot_maintenance", instance_id=instance_id, slot=slot))
            flash("機体整備を更新しました。", "notice")
            return redirect(url_for("robot_maintenance", instance_id=instance_id, slot=slot))

        selected_id_raw = (request.form.get("part_instance_id") or "").strip()
        if not selected_id_raw.isdigit():
            flash(f"{current_label}の候補を選んでください。", "error")
            return redirect(url_for("robot_maintenance", instance_id=instance_id, slot=slot))
        selected_id = int(selected_id_raw)
        current_id = int(parts_row[slot_def["instance_col"]] or 0)
        if selected_id == current_id:
            flash("その部位はすでに現在装備です。", "notice")
            return redirect(url_for("robot_maintenance", instance_id=instance_id, slot=slot))

        selected_row = db.execute(
            """
            SELECT
                pi.id AS instance_id,
                pi.plus,
                pi.status,
                pi.w_hp, pi.w_atk, pi.w_def, pi.w_spd, pi.w_acc, pi.w_cri,
                pi.rarity AS instance_rarity,
                pi.element AS instance_element,
                pi.series AS instance_series,
                rp.part_type, rp.key, rp.series, rp.frame_type, rp.series_key, rp.series_label, rp.image_path, rp.offset_x, rp.offset_y,
                rp.rarity, rp.element, rp.display_name_ja
            FROM part_instances pi
            JOIN robot_parts rp ON rp.id = pi.part_id
            WHERE pi.id = ? AND pi.user_id = ? AND rp.is_active = 1
              AND (pi.status = 'inventory' OR pi.id = ?)
            LIMIT 1
            """,
            (selected_id, user_id, current_id),
        ).fetchone()
        if not selected_row or _norm_part_type(selected_row["part_type"]) != slot_def["part_type"]:
            flash("整備候補が見つかりません。", "error")
            return redirect(url_for("robot_maintenance", instance_id=instance_id, slot=slot))
        if _normalize_frame_type(selected_row["frame_type"]) != robot["frame_type"]:
            flash("選択したパーツのフレームタイプが合っていません。", "error")
            return redirect(url_for("robot_maintenance", instance_id=instance_id, slot=slot))

        selected_item = _build_picker_part_item(selected_row)
        candidate_payloads = dict(current_payloads)
        candidate_payloads[slot_def["part_type"]] = _robot_payload_from_part_picker_item(selected_item)
        candidate_estimate = compute_robot_stats(
            list(candidate_payloads.values()),
            series_bonus_defs=series_bonus_defs,
            series_progress_layer=series_progress_layer,
        )
        candidate_stats = {
            "hp": int((candidate_estimate or {}).get("stats", {}).get("hp") or 0),
            "atk": int((candidate_estimate or {}).get("stats", {}).get("atk") or 0),
            "def": int((candidate_estimate or {}).get("stats", {}).get("def") or 0),
            "spd": int((candidate_estimate or {}).get("stats", {}).get("spd") or 0),
            "acc": int((candidate_estimate or {}).get("stats", {}).get("acc") or 0),
            "cri": int((candidate_estimate or {}).get("stats", {}).get("cri") or 0),
            "power": float((candidate_estimate or {}).get("power") or 0.0),
        }
        stat_delta = {key: int(candidate_stats[key] - current_robot_stats[key]) for key in ("hp", "atk", "def", "spd", "acc", "cri")}
        power_delta = int(round(candidate_stats["power"] - current_robot_stats["power"]))

        try:
            db.execute("BEGIN IMMEDIATE")
            returned_status = _return_part_instance_to_pool(db, user_id, current_id, user_row=user)
            db.execute(
                "UPDATE part_instances SET status = 'equipped', updated_at = datetime('now') WHERE id = ? AND user_id = ?",
                (selected_id, user_id),
            )
            db.execute(
                f"UPDATE robot_instance_parts SET {slot_def['instance_col']} = ?, {slot_def['key_col']} = ? WHERE robot_instance_id = ?",
                (selected_id, str(selected_row["key"]), int(instance_id)),
            )
            refreshed_parts = db.execute(
                "SELECT * FROM robot_instance_parts WHERE robot_instance_id = ?",
                (int(instance_id),),
            ).fetchone()
            _compose_instance_assets_no_commit(db, int(instance_id), refreshed_parts)
            audit_log(
                db,
                AUDIT_EVENT_TYPES["ROBOT_MAINTENANCE"],
                user_id=user_id,
                request_id=request_id,
                action_key="maintenance",
                entity_type="robot_instance",
                entity_id=int(instance_id),
                payload={
                    "robot_instance_id": int(instance_id),
                    "robot_name": robot.get("name"),
                    "changed_slots": [slot],
                    "before_part_ids": {slot: current_id},
                    "after_part_ids": {slot: selected_id},
                    "before_part_keys": {slot: str(parts_row[slot_def["key_col"]] or "")},
                    "after_part_keys": {slot: str(selected_row["key"] or "")},
                    "returned_status": returned_status,
                    "stat_delta": {**stat_delta, "power": power_delta},
                    "power_delta": power_delta,
                },
                ip=request.remote_addr,
            )
            _record_insect_robot_completion_if_needed(
                db,
                user_id,
                int(instance_id),
                robot_name=robot.get("name"),
                request_id=request_id,
                ip=request.remote_addr,
            )
            db.commit()
        except Exception:
            db.rollback()
            app.logger.exception("robot_maintenance.part_failed instance_id=%s slot=%s", instance_id, slot)
            flash("機体整備の更新に失敗しました。", "error")
            return redirect(url_for("robot_maintenance", instance_id=instance_id, slot=slot))
        flash(f"{current_label}を整備しました。", "notice")
        return redirect(url_for("robot_maintenance", instance_id=instance_id, slot=slot))

    maintenance_slot = ROBOT_MAINTENANCE_SLOT_DEF_BY_KEY[slot]
    maintenance_candidates = []
    maintenance_stat_rows = []
    decor_options = []
    current_decor_slots = []
    current_decor_by_slot = {}
    for row in current_decor_rows:
        slot_index = int(row["slot_index"] or 0) if "slot_index" in row.keys() else 0
        if slot_index < 0 or slot_index >= MAX_ROBOT_DECOR_SLOTS:
            continue
        item = {
            "slot_index": slot_index,
            "slot_label": f"装飾{slot_index + 1}",
            "decor_asset_id": int(row["id"]),
            "label": str(row["name_ja"] or row["key"] or "装飾"),
            "image_url": url_for("static", filename=_decor_image_rel(row["image_path"], row["key"]), v=APP_VERSION),
            "offset_x": int(row["offset_x"] or 0) if "offset_x" in row.keys() else _default_robot_decor_offset(slot_index)["x"],
            "offset_y": int(row["offset_y"] or 0) if "offset_y" in row.keys() else _default_robot_decor_offset(slot_index)["y"],
        }
        current_decor_by_slot[slot_index] = item
    for slot_index in range(MAX_ROBOT_DECOR_SLOTS):
        default_offset = _default_robot_decor_offset(slot_index)
        current = current_decor_by_slot.get(slot_index)
        current_decor_slots.append(
            current
            or {
                "slot_index": slot_index,
                "slot_label": f"装飾{slot_index + 1}",
                "decor_asset_id": 0,
                "label": "なし",
                "image_url": "",
                "offset_x": default_offset["x"],
                "offset_y": default_offset["y"],
            }
        )
    current_decor_id = current_decor_slots[0]["decor_asset_id"] if current_decor_slots else None
    if slot == "DECOR":
        decor_options.append(
            {
                "id": 0,
                "label": "装飾なし",
                "image_url": "",
            }
        )
        for item in decor_assets:
            decor_options.append(
                {
                    "id": int(item["id"]),
                    "label": str(item["name_ja"] or item["key"] or "装飾"),
                    "image_url": item["image_url"],
                }
            )
    else:
        current_part_type = maintenance_slot["part_type"]
        current_item = current_part_items.get(current_part_type)
        inventory_rows = db.execute(
            """
            WITH inv AS (
                SELECT
                    pi.id AS instance_id,
                    pi.plus,
                    pi.w_hp, pi.w_atk, pi.w_def, pi.w_spd, pi.w_acc, pi.w_cri,
                    pi.rarity AS instance_rarity,
                    pi.element AS instance_element,
                    pi.series AS instance_series,
                    pi.status,
                    rp.part_type, rp.key, rp.series, rp.frame_type, rp.series_key, rp.series_label, rp.image_path, rp.offset_x, rp.offset_y,
                    rp.rarity, rp.element, rp.display_name_ja
                FROM part_instances pi
                JOIN robot_parts rp ON rp.id = pi.part_id
                WHERE pi.user_id = ? AND pi.status = 'inventory' AND rp.is_active = 1 AND rp.part_type = ?
                  AND COALESCE(rp.frame_type, 'normal') = ?
            ),
            ranked AS (
                SELECT
                    inv.*,
                    COUNT(*) OVER (PARTITION BY inv.key, inv.plus) AS qty,
                    ROW_NUMBER() OVER (PARTITION BY inv.key, inv.plus ORDER BY inv.instance_id ASC) AS rn
                FROM inv
            )
            SELECT *
            FROM ranked
            ORDER BY
                plus DESC,
                CASE UPPER(COALESCE(instance_rarity, rarity, 'N'))
                    WHEN 'UR' THEN 5
                    WHEN 'SSR' THEN 4
                    WHEN 'SR' THEN 3
                    WHEN 'R' THEN 2
                    ELSE 1
                END DESC,
                instance_id ASC
            """,
            (user_id, current_part_type, robot["frame_type"]),
        ).fetchall()
        if current_item:
            maintenance_candidates.append(
                {
                    **current_item,
                    "is_current": True,
                    "robot_stat_rows": _build_stat_comparison_rows(current_robot_stats, current_robot_stats),
                    "robot_profile": current_profile,
                }
            )
        for row in inventory_rows:
            item = _build_picker_part_item(row, compare_item=current_item)
            candidate_payloads = dict(current_payloads)
            candidate_payloads[current_part_type] = _robot_payload_from_part_picker_item(item)
            candidate_estimate = compute_robot_stats(
                list(candidate_payloads.values()),
                series_bonus_defs=series_bonus_defs,
                series_progress_layer=series_progress_layer,
            )
            candidate_stats = {
                "hp": int((candidate_estimate or {}).get("stats", {}).get("hp") or 0),
                "atk": int((candidate_estimate or {}).get("stats", {}).get("atk") or 0),
                "def": int((candidate_estimate or {}).get("stats", {}).get("def") or 0),
                "spd": int((candidate_estimate or {}).get("stats", {}).get("spd") or 0),
                "acc": int((candidate_estimate or {}).get("stats", {}).get("acc") or 0),
                "cri": int((candidate_estimate or {}).get("stats", {}).get("cri") or 0),
                "power": float((candidate_estimate or {}).get("power") or 0.0),
            }
            item["is_current"] = False
            item["robot_stat_rows"] = _build_stat_comparison_rows(current_robot_stats, candidate_stats)
            item["robot_profile"] = _robot_profile_from_estimate(candidate_estimate)
            maintenance_candidates.append(item)
        maintenance_stat_rows = _build_stat_comparison_rows(current_robot_stats, current_robot_stats)

    return render_template(
        "robot_maintenance.html",
        robot=robot,
        current_profile=current_profile,
        current_part_items=current_part_items,
        slot_tabs=slot_tabs,
        selected_slot=slot,
        maintenance_slot=maintenance_slot,
        maintenance_candidates=maintenance_candidates,
        decor_options=decor_options,
        current_decor_id=current_decor_id,
        current_decor_slots=current_decor_slots,
        max_robot_decor_slots=MAX_ROBOT_DECOR_SLOTS,
        robot_decor_offset_min=ROBOT_DECOR_OFFSET_MIN,
        robot_decor_offset_max=ROBOT_DECOR_OFFSET_MAX,
        maintenance_stat_rows=maintenance_stat_rows,
    )


@app.route("/robots/<int:instance_id>/activate", methods=["POST"])
@login_required
def robot_instance_activate(instance_id):
    db = get_db()
    target = db.execute(
        "SELECT id FROM robot_instances WHERE id = ? AND user_id = ? AND status = 'active'",
        (instance_id, session["user_id"]),
    ).fetchone()
    if not target:
        session["message"] = "出撃機体に設定できるロボが見つかりません。"
        return redirect(url_for("robots"))
    db.execute("UPDATE users SET active_robot_id = ? WHERE id = ?", (instance_id, session["user_id"]))
    db.commit()
    session["message"] = f"出撃機体を #{instance_id} に設定しました。"
    return redirect(url_for("robots"))


@app.route("/robots/<int:instance_id>/share", methods=["POST"])
@login_required
def robot_share(instance_id):
    db = get_db()
    row = db.execute(
        """
        SELECT id, user_id, name
        FROM robot_instances
        WHERE id = ? AND user_id = ? AND status = 'active'
        """,
        (int(instance_id), int(session["user_id"])),
    ).fetchone()
    if not row:
        session["message"] = "共有対象のロボが見つかりません。"
        return redirect(url_for("robots"))
    title_summary = robot_title_summary(db, int(row["id"]))
    primary_title_view = title_summary.get("primary")
    primary_title = (
        primary_title_view.get("label")
        if primary_title_view
        else _robot_primary_title(db, int(row["id"]))
    )
    detail_url = url_for("robot_detail", instance_id=int(row["id"]))
    msg = f"相棒共有：{row['name']}《{primary_title}》 {detail_url}"
    db.execute(
        "INSERT INTO chat_messages (user_id, username, message, created_at) VALUES (?, ?, ?, ?)",
        (int(session["user_id"]), session.get("username", "unknown"), msg[:200], now_str()),
    )
    audit_log(
        db,
        AUDIT_EVENT_TYPES["ROBOT_SHARE"],
        user_id=int(session["user_id"]),
        request_id=getattr(g, "request_id", None),
        action_key="robot_share",
        entity_type="robot_instance",
        entity_id=int(row["id"]),
        payload={
            "robot_instance_id": int(row["id"]),
            "primary_title": primary_title,
            "detail_url": detail_url,
        },
        ip=request.remote_addr,
    )
    db.commit()
    session["message"] = "全体チャットへ共有しました。"
    return redirect(url_for("robot_detail", instance_id=int(row["id"])))


@app.route("/robots/<int:instance_id>/toggle_public", methods=["POST"])
@login_required
def robot_toggle_public(instance_id):
    db = get_db()
    row = db.execute(
        "SELECT id, is_public FROM robot_instances WHERE id = ? AND user_id = ?",
        (int(instance_id), int(session["user_id"])),
    ).fetchone()
    if not row:
        abort(404)
    next_value = 0 if int(row["is_public"] or 0) == 1 else 1
    db.execute("UPDATE robot_instances SET is_public = ?, updated_at = ? WHERE id = ?", (next_value, int(time.time()), int(instance_id)))
    db.commit()
    session["message"] = ("展示を公開しました。" if next_value == 1 else "展示を非公開にしました。")
    return redirect(url_for("robot_detail", instance_id=int(instance_id)))


@app.route("/robot-instance/<int:instance_id>/decompose", methods=["POST"])
@login_required
def robot_instance_decompose(instance_id):
    db = get_db()
    row = db.execute(
        """
        SELECT ri.*, rip.head_key, rip.r_arm_key, rip.l_arm_key, rip.legs_key
        FROM robot_instances ri
        JOIN robot_instance_parts rip ON rip.robot_instance_id = ri.id
        WHERE ri.id = ? AND ri.user_id = ?
        """,
        (instance_id, session["user_id"]),
    ).fetchone()
    if not row or row["status"] == "decomposed":
        session["message"] = "分解対象が見つかりません。"
        return redirect(url_for("robots"))
    rip = db.execute(
        "SELECT * FROM robot_instance_parts WHERE robot_instance_id = ?",
        (instance_id,),
    ).fetchone()
    user_row = db.execute("SELECT id, part_inventory_limit FROM users WHERE id = ?", (session["user_id"],)).fetchone()
    return_part_count = _robot_decompose_return_part_count(rip, row)
    inventory_count = _count_part_inventory(db, int(session["user_id"]))
    inventory_limit = int(user_row["part_inventory_limit"] or 0) if user_row else 0
    if inventory_limit > 0 and inventory_count + return_part_count > inventory_limit:
        audit_log(
            db,
            AUDIT_EVENT_TYPES.get("ROBOT_DECOMPOSE_BLOCKED", "audit.robot.decompose.blocked"),
            user_id=session["user_id"],
            request_id=getattr(g, "request_id", None),
            action_key="decompose_blocked",
            entity_type="robot_instance",
            entity_id=instance_id,
            payload={
                "robot_instance_id": int(instance_id),
                "inventory_count": int(inventory_count),
                "inventory_limit": int(inventory_limit),
                "return_count": int(return_part_count),
                "reason": "inventory_limit",
            },
            ip=request.remote_addr,
        )
        db.commit()
        session["message"] = "所持パーツがいっぱいのため、このロボは分解できません。先に不要なパーツを整理してください。"
        session["robot_decompose_blocked"] = True
        return redirect(url_for("robots"))
    _ensure_robot_instance_part_instances(db, instance_id)
    rip = db.execute(
        "SELECT * FROM robot_instance_parts WHERE robot_instance_id = ?",
        (instance_id,),
    ).fetchone()
    restored = 0
    restored_ids = []
    for col in ("head_part_instance_id", "r_arm_part_instance_id", "l_arm_part_instance_id", "legs_part_instance_id"):
        if col in rip.keys() and rip[col]:
            _return_part_instance_to_pool(db, session["user_id"], rip[col], user_row=user_row)
            restored += 1
            restored_ids.append(int(rip[col]))
    if restored == 0:
        for ptype, pkey in [
            ("HEAD", row["head_key"]),
            ("RIGHT_ARM", row["r_arm_key"]),
            ("LEFT_ARM", row["l_arm_key"]),
            ("LEGS", row["legs_key"]),
        ]:
            _add_part_drop(
                db,
                session["user_id"],
                part_type=ptype,
                part_key=pkey,
                source="decompose",
                robot_instance_id=row["id"],
            )
            audit_log(
                db,
                AUDIT_EVENT_TYPES["INVENTORY_DELTA"],
                user_id=session["user_id"],
                request_id=getattr(g, "request_id", None),
                action_key="decompose",
                entity_type="part_key",
                entity_id=None,
                delta_count=1,
                payload={"reason": "decompose_fallback_drop", "part_type": ptype, "part_key": pkey, "robot_instance_id": row["id"]},
                ip=request.remote_addr,
            )
    db.execute(
        "UPDATE robot_instances SET status = 'decomposed', decomposed_at = ?, updated_at = ? WHERE id = ?",
        (int(time.time()), int(time.time()), instance_id),
    )
    audit_log(
        db,
        AUDIT_EVENT_TYPES["ROBOT_DECOMPOSE"],
        user_id=session["user_id"],
        request_id=getattr(g, "request_id", None),
        action_key="decompose",
        entity_type="robot_instance",
        entity_id=instance_id,
        payload={
            "robot_instance_id": instance_id,
            "robot_name": row["name"],
            "restored_count": restored if restored else 4,
            "restored_part_instance_ids": restored_ids,
            "fallback_drop": restored == 0,
        },
        ip=request.remote_addr,
    )
    if restored_ids:
        for pid in restored_ids:
            audit_log(
                db,
                AUDIT_EVENT_TYPES["INVENTORY_DELTA"],
                user_id=session["user_id"],
                request_id=getattr(g, "request_id", None),
                action_key="decompose",
                entity_type="part_instance",
                entity_id=pid,
                delta_count=1,
                payload={"reason": "decompose_restore", "robot_instance_id": instance_id},
                ip=request.remote_addr,
            )
    db.commit()
    session["message"] = f"ロボ「{row['name']}」を分解し、パーツへ戻しました（名称は記録に保持）。"
    return redirect(url_for("robots"))


@app.route("/fusion", methods=["GET", "POST"])
@login_required
def fusion():
    db = get_db()
    user_id = session["user_id"]
    message = None

    if request.method == "POST":
        ids = request.form.getlist("robot_id")
        if len(ids) != 2:
            message = "2体選択してください。"
        else:
            r1 = db.execute(
                "SELECT * FROM user_robots WHERE id = ? AND user_id = ?", (ids[0], user_id)
            ).fetchone()
            r2 = db.execute(
                "SELECT * FROM user_robots WHERE id = ? AND user_id = ?", (ids[1], user_id)
            ).fetchone()
            if not r1 or not r2:
                message = "選択が無効です。"
            else:
                new_head = random.choice([r1["head"], r2["head"]])
                new_right = random.choice([r1["right_arm"], r2["right_arm"]])
                new_left = random.choice([r1["left_arm"], r2["left_arm"]])
                new_legs = random.choice([r1["legs"], r2["legs"]])
                db.execute("DELETE FROM user_robots WHERE id IN (?, ?)", (r1["id"], r2["id"]))
                db.execute(
                    "INSERT INTO user_robots (user_id, head, right_arm, left_arm, legs, obtained_at) VALUES (?, ?, ?, ?, ?, ?)",
                    (user_id, new_head, new_right, new_left, new_legs, int(time.time())),
                )
                db.commit()
                message = "合成成功！ 新ロボを獲得。"

    robots = db.execute(
        "SELECT * FROM user_robots WHERE user_id = ? ORDER BY obtained_at DESC", (user_id,)
    ).fetchall()
    return render_template("fusion.html", robots=robots, message=message)


@app.route("/build", methods=["GET", "POST"])
@login_required
def build():
    if _is_trial_session():
        state = _trial_state()
        result = None
        if request.method == "POST":
            build_key = (request.form.get("build_key") or "").strip()
            selected = None
            current = None
            for part in state.get("parts") or []:
                if part.get("id") == build_key and not part.get("equipped"):
                    selected = part
                    break
            if selected:
                for part in state.get("parts") or []:
                    if part.get("equipped") and part.get("part_type") == selected.get("part_type"):
                        current = part
                        break
                if current:
                    current["equipped"] = False
                    current["status_label"] = "所持中"
                    selected["equipped"] = True
                    selected["status_label"] = "装備中"
            state["built"] = True
            state["step"] = "done"
            if selected:
                state["robot"]["summary"] = f"{selected.get('name', '新しいパーツ')}を試した構成です。"
            else:
                state["robot"]["summary"] = "今の構成のまま、もう一度出撃できます。"
            _trial_compose_robot_image(state)
            result = {
                "title": "組み替え完了",
                "body": "新しい構成で、もう一度出撃してみよう。",
            }
            _save_trial_state(state)
        return _render_trial_build(result=result)
    db = get_db()
    user_id = session["user_id"]
    now = int(time.time())
    audit_log(
        db,
        EVENT_BUILD_VIEW,
        user_id=int(user_id),
        request_id=getattr(g, "request_id", None),
        action_key="daily_research.build_view",
        entity_type="page",
        payload={"task_date": get_day_key()},
        ip=request.remote_addr,
    )
    db.commit()
    requested_frame_type = (request.args.get("build_mode") or request.args.get("frame_type") or "").strip()
    selected_frame_type = _normalize_build_frame_mode(requested_frame_type or "normal")
    series_progress_layer = _series_progress_layer_for_user(db, user_id)
    series_system_enabled = _series_system_enabled_for_user(db, user_id=user_id)
    series_bonus_defs = _load_series_bonus_defs(db, active_only=True) if series_system_enabled else {}
    active_robot = _get_active_robot(db, user_id)
    saved_robot_rows = db.execute(
        """
        SELECT id, name, frame_type, COALESCE(is_mixed_frame, 0) AS is_mixed_frame, build_frame_mode, composed_image_path, icon_32_path, updated_at
        FROM robot_instances
        WHERE user_id = ? AND status != 'decomposed'
        ORDER BY
            CASE WHEN id = (SELECT active_robot_id FROM users WHERE id = ?) THEN 0 ELSE 1 END,
            updated_at DESC,
            id DESC
        """,
        (int(user_id), int(user_id)),
    ).fetchall()
    requested_build_mode = (request.args.get("mode") or request.form.get("mode") or "").strip().lower()
    if requested_build_mode not in {"new", "modify"}:
        requested_build_mode = "modify" if active_robot else "new"
    build_mode = requested_build_mode
    base_robot_id_raw = (request.args.get("base_robot_id") or request.form.get("base_robot_id") or "").strip()
    base_robot_id = int(base_robot_id_raw) if base_robot_id_raw.isdigit() else None
    if build_mode == "modify" and not base_robot_id and active_robot:
        base_robot_id = int(active_robot["id"])
    base_robot = None
    if build_mode == "modify" and base_robot_id:
        base_robot = db.execute(
            """
            SELECT *
            FROM robot_instances
            WHERE id = ? AND user_id = ? AND status != 'decomposed'
            """,
            (int(base_robot_id), int(user_id)),
        ).fetchone()
    if build_mode == "modify" and not base_robot:
        if active_robot:
            base_robot = active_robot
            base_robot_id = int(active_robot["id"])
        else:
            build_mode = "new"
            base_robot_id = None
    compare_robot = base_robot if build_mode == "modify" and base_robot else active_robot
    if not requested_frame_type and compare_robot:
        compare_robot_dict = dict(compare_robot)
        selected_frame_type = (
            FREE_BUILD_FRAME_MODE
            if int(compare_robot_dict.get("is_mixed_frame") or 0)
            else _normalize_build_frame_mode(
                compare_robot_dict.get("build_frame_mode") or compare_robot_dict.get("frame_type"),
                default=selected_frame_type,
            )
        )
    current_part_items = {"HEAD": None, "RIGHT_ARM": None, "LEFT_ARM": None, "LEGS": None}
    if compare_robot:
        active_mapping = _ensure_robot_instance_part_instances(db, int(compare_robot["id"])) or {}
        current_rows = _part_instance_display_rows(
            db,
            [
                active_mapping.get("head"),
                active_mapping.get("r_arm"),
                active_mapping.get("l_arm"),
                active_mapping.get("legs"),
            ],
        )
        current_rows_by_id = {int(row["instance_id"]): row for row in current_rows}
        slot_to_mapping_key = {
            "HEAD": "head",
            "RIGHT_ARM": "r_arm",
            "LEFT_ARM": "l_arm",
            "LEGS": "legs",
        }
        for part_type, mapping_key in slot_to_mapping_key.items():
            current_row = current_rows_by_id.get(int(active_mapping.get(mapping_key) or 0))
            if current_row:
                current_part_items[part_type] = _build_picker_part_item(current_row)
    frame_filter_sql = ""
    owned_params = [user_id]
    if selected_frame_type != FREE_BUILD_FRAME_MODE:
        frame_filter_sql = "AND COALESCE(rp.frame_type, 'normal') = ?"
        owned_params.append(selected_frame_type)
    owned_rows = db.execute(
        f"""
        WITH inv AS (
            SELECT
                pi.id AS instance_id,
                pi.plus,
                pi.w_hp, pi.w_atk, pi.w_def, pi.w_spd, pi.w_acc, pi.w_cri,
                pi.rarity AS instance_rarity,
                pi.element AS instance_element,
                pi.series AS instance_series,
                rp.part_type, rp.key, rp.series, rp.frame_type, rp.series_key, rp.series_label, rp.image_path, rp.offset_x, rp.offset_y,
                rp.rarity, rp.element, rp.display_name_ja
            FROM part_instances pi
            JOIN robot_parts rp ON rp.id = pi.part_id
            WHERE pi.user_id = ? AND pi.status = 'inventory' AND rp.is_active = 1
              {frame_filter_sql}
        ),
        ranked AS (
            SELECT
                inv.*,
                COUNT(*) OVER (PARTITION BY inv.key, inv.plus) AS qty,
                ROW_NUMBER() OVER (PARTITION BY inv.key, inv.plus ORDER BY inv.instance_id ASC) AS rn
            FROM inv
        )
        SELECT *
        FROM ranked
        ORDER BY
            part_type ASC,
            plus DESC,
            CASE UPPER(COALESCE(instance_rarity, rarity, 'N'))
                WHEN 'UR' THEN 5
                WHEN 'SSR' THEN 4
                WHEN 'SR' THEN 3
                WHEN 'R' THEN 2
                ELSE 1
            END DESC,
            COALESCE(instance_element, element, 'NORMAL') ASC,
            COALESCE(instance_series, series, '') ASC,
            instance_id ASC
        """,
        owned_params,
    ).fetchall()
    part_groups = {"HEAD": [], "RIGHT_ARM": [], "LEFT_ARM": [], "LEGS": []}
    for row in owned_rows:
        compare_item = current_part_items.get(str(row["part_type"] or "").strip())
        item = _build_picker_part_item(row, compare_item=compare_item)
        part_groups[row["part_type"]].append(item)

    slot_param_map = {
        "HEAD": "head_key",
        "RIGHT_ARM": "r_arm_key",
        "LEFT_ARM": "l_arm_key",
        "LEGS": "legs_key",
    }
    missing_part_types = [
        _part_type_ui_label(part_type)
        for part_type in slot_param_map.keys()
        if not part_groups[part_type]
    ]
    selected_slot_values = {}
    selected_parts = {}
    selected_payloads = []
    selected_offsets = _build_offset_payload_from_values(request.values)
    message = session.pop("message", None)
    for part_type, param in slot_param_map.items():
        options = part_groups[part_type]
        picked_raw = (request.values.get(param) or "").strip()
        picked_id = int(picked_raw) if picked_raw.isdigit() else None
        option = next((o for o in options if int(o["instance_id"]) == picked_id), None) if picked_id is not None else None
        if option is None and options and build_mode == "new":
            option = options[0]
        selected_slot_values[param] = int(option["instance_id"]) if option else None
        display_option = option or (current_part_items.get(part_type) if build_mode == "modify" else None)
        selected_parts[part_type] = display_option
        if display_option:
            selected_payloads.append(
                {
                    "part_type": display_option.get("part_type"),
                    "key": display_option.get("key"),
                    "series": (display_option.get("instance_series") or display_option.get("series")),
                    "frame_type": display_option.get("frame_type"),
                    "rarity": (display_option.get("instance_rarity") or display_option.get("rarity") or "N"),
                    "element": (display_option.get("instance_element") or display_option.get("element") or "NORMAL"),
                    "plus": int(display_option.get("plus") or 0),
                    "w_hp": display_option.get("w_hp"),
                    "w_atk": display_option.get("w_atk"),
                    "w_def": display_option.get("w_def"),
                    "w_spd": display_option.get("w_spd"),
                    "w_acc": display_option.get("w_acc"),
                    "w_cri": display_option.get("w_cri"),
                }
            )

    estimate = (
        compute_robot_stats(
            selected_payloads,
            series_bonus_defs=series_bonus_defs,
            series_progress_layer=series_progress_layer,
            disable_set_bonus=len({p.get("frame_type") for p in selected_payloads if p.get("frame_type")}) > 1,
        )
        if len(selected_payloads) == 4
        else None
    )
    candidate_frame_types = sorted({str(p.get("frame_type") or "normal") for p in selected_payloads}) if len(selected_payloads) == 4 else []
    candidate_is_mixed_frame = len(candidate_frame_types) > 1
    decor_assets = db.execute(
        """
        SELECT rda.id, rda.key, rda.name_ja, rda.image_path
        FROM user_decor_inventory udi
        JOIN robot_decor_assets rda ON rda.id = udi.decor_asset_id
        WHERE udi.user_id = ? AND rda.is_active = 1
        ORDER BY udi.acquired_at DESC, rda.id DESC
        """,
        (user_id,),
    ).fetchall()
    decor_assets = [
        {
            **dict(row),
            "display_image_path": _decor_image_rel(row["image_path"], row["key"]),
        }
        for row in decor_assets
    ]
    decor_id_raw = (request.values.get("decor_asset_id") or "").strip()
    selected_decor_id = int(decor_id_raw) if decor_id_raw.isdigit() else None
    if selected_decor_id and not any(int(d["id"]) == selected_decor_id for d in decor_assets):
        selected_decor_id = None
    selected_decor = next((d for d in decor_assets if int(d["id"]) == int(selected_decor_id)), None) if selected_decor_id else None
    candidate_build_style = _robot_style_from_final_stats(estimate["stats"]) if estimate else {
        "style_key": "stable",
        "style_label": ROBOT_STYLE_LABELS["stable"],
        "style_description": _robot_style_description("stable"),
        "reason": "判定対象パーツ不足",
        "style_scores": {"stable": 0.0, "desperate": 0.0, "burst": 0.0},
        "legacy_build_type": "STABLE",
    }
    candidate_style_state = _style_view_from_stats(estimate["stats"]) if estimate else None
    current_robot_stats_obj = _compute_robot_stats_for_instance(db, compare_robot["id"]) if compare_robot else None
    current_robot_stats = {
        "hp": int(current_robot_stats_obj["stats"]["hp"]) if current_robot_stats_obj else 0,
        "atk": int(current_robot_stats_obj["stats"]["atk"]) if current_robot_stats_obj else 0,
        "def": int(current_robot_stats_obj["stats"]["def"]) if current_robot_stats_obj else 0,
        "spd": int(current_robot_stats_obj["stats"]["spd"]) if current_robot_stats_obj else 0,
        "acc": int(current_robot_stats_obj["stats"]["acc"]) if current_robot_stats_obj else 0,
        "cri": int(current_robot_stats_obj["stats"]["cri"]) if current_robot_stats_obj else 0,
        "power": float(current_robot_stats_obj["power"]) if current_robot_stats_obj else 0.0,
    }
    candidate_robot_stats = {
        "hp": int(estimate["stats"]["hp"]) if estimate else 0,
        "atk": int(estimate["stats"]["atk"]) if estimate else 0,
        "def": int(estimate["stats"]["def"]) if estimate else 0,
        "spd": int(estimate["stats"]["spd"]) if estimate else 0,
        "acc": int(estimate["stats"]["acc"]) if estimate else 0,
        "cri": int(estimate["stats"]["cri"]) if estimate else 0,
        "power": float(estimate["power"]) if estimate else 0.0,
    }
    stat_comparison_rows = _build_stat_comparison_rows(current_robot_stats, candidate_robot_stats)
    current_build_style = (
        current_robot_stats_obj.get("robot_style")
        if current_robot_stats_obj and current_robot_stats_obj.get("robot_style")
        else {
            "style_key": "stable",
            "style_label": ROBOT_STYLE_LABELS["stable"],
            "style_description": _robot_style_description("stable"),
            "reason": "未設定",
            "style_scores": {"stable": 0.0, "desperate": 0.0, "burst": 0.0},
            "legacy_build_type": "STABLE",
        }
    )
    current_style_state = (
        _robot_style_state_for_view(db, int(compare_robot["id"]), stat_obj=current_robot_stats_obj)
        if compare_robot and current_robot_stats_obj
        else None
    )
    candidate_set_bonus_view = _set_bonus_view_for_loadout(
        selected_payloads,
        (estimate or {}).get("set_bonus"),
        disabled_reason="自由編成の混成ロボはセットボーナスなし" if candidate_is_mixed_frame else None,
    )
    candidate_series_view = (
        _series_bonus_view_for_loadout(
            db,
            selected_payloads,
            series_calc=estimate,
            progress_layer=series_progress_layer,
        )
        if series_system_enabled
        else None
    )
    current_set_bonus_view = _set_bonus_view_for_loadout(
        (current_robot_stats_obj or {}).get("parts"),
        (current_robot_stats_obj or {}).get("set_bonus"),
        disabled_reason="自由編成の混成ロボはセットボーナスなし" if (current_robot_stats_obj or {}).get("is_mixed_frame") else None,
    )
    current_series_view = (
        _series_bonus_view_for_loadout(
            db,
            (current_robot_stats_obj or {}).get("parts"),
            series_calc=current_robot_stats_obj,
            progress_layer=(current_robot_stats_obj or {}).get("series_progress_layer") or series_progress_layer,
        )
        if series_system_enabled
        else None
    )
    boss_alert_status = _home_boss_alert_status(db, user_id, now_ts=now)
    boss_alert_hint = _boss_alert_recommendation_context(boss_alert_status)
    if current_style_state:
        db.commit()
    user_row = db.execute("SELECT * FROM users WHERE id = ?", (int(user_id),)).fetchone()
    build_limits = _effective_limits(db, user_row)
    robot_instance_count = int(
        db.execute(
            "SELECT COUNT(*) AS c FROM robot_instances WHERE user_id = ? AND status != 'decomposed'",
            (int(user_id),),
        ).fetchone()["c"]
        or 0
    )
    robot_slot_limit = int(build_limits["robot_slots"])
    robot_slot_used = min(robot_instance_count, robot_slot_limit)
    robot_slot_full = robot_instance_count >= robot_slot_limit

    return render_template(
        "build.html",
        part_groups=part_groups,
        missing_part_types=missing_part_types,
        selected_frame_type=selected_frame_type,
        frame_type_defs=BUILD_FRAME_MODE_DEFS,
        frame_type_filters=_build_frame_mode_filter_rows(
            selected_frame_type,
            "build",
            extra_params={"mode": build_mode, "base_robot_id": base_robot_id},
        ),
        candidate_is_mixed_frame=candidate_is_mixed_frame,
        candidate_frame_types=candidate_frame_types,
        selected_slot_values=selected_slot_values,
        selected_parts=selected_parts,
        current_part_items=current_part_items,
        saved_robot_rows=saved_robot_rows,
        build_mode=build_mode,
        base_robot=base_robot,
        base_robot_id=base_robot_id,
        estimate=estimate,
        decor_assets=decor_assets,
        selected_decor_id=selected_decor_id,
        candidate_build_style=candidate_build_style,
        current_build_style=current_build_style,
        candidate_style_state=candidate_style_state,
        current_style_state=current_style_state,
        candidate_set_bonus_view=candidate_set_bonus_view,
        current_set_bonus_view=current_set_bonus_view,
        candidate_series_view=candidate_series_view,
        current_series_view=current_series_view,
        current_robot_stats=current_robot_stats,
        stat_comparison_rows=stat_comparison_rows,
        selected_offsets=selected_offsets,
        message=message,
        build_offset_control_defs=BUILD_OFFSET_CONTROL_DEFS,
        build_offset_min=BUILD_PART_OFFSET_MIN,
        build_offset_max=BUILD_PART_OFFSET_MAX,
        build_scale_min=BUILD_PART_SCALE_MIN,
        build_scale_max=BUILD_PART_SCALE_MAX,
        build_scale_step=BUILD_PART_SCALE_STEP,
        boss_alert_active=boss_alert_hint["boss_alert_active"],
        boss_type=boss_alert_hint["boss_type"],
        recommended_build=boss_alert_hint["recommended_build"],
        recommended_text=boss_alert_hint["recommended_text"],
        robot_slot_used=robot_slot_used,
        robot_slot_limit=robot_slot_limit,
        robot_slot_full=robot_slot_full,
        set_bonus_table=SET_BONUS_TABLE,
        element_label_map=ELEMENT_LABEL_MAP,
    )


@app.route("/build/confirm", methods=["POST"])
@login_required
def build_confirm():
    db = get_db()
    user = db.execute("SELECT * FROM users WHERE id = ?", (session["user_id"],)).fetchone()
    robot_name = request.form.get("robot_name", "").strip()
    selected_offsets = _build_offset_payload_from_values(request.form)
    selected_frame_type = _normalize_build_frame_mode(request.form.get("build_mode") or request.form.get("frame_type"))
    build_mode = (request.form.get("mode") or "new").strip().lower()
    if build_mode not in {"new", "modify"}:
        build_mode = "new"
    base_robot_id_raw = (request.form.get("base_robot_id") or "").strip()
    base_robot_id = int(base_robot_id_raw) if base_robot_id_raw.isdigit() else None
    head_choice = (request.form.get("head_key") or "").strip()
    r_arm_choice = (request.form.get("r_arm_key") or "").strip()
    l_arm_choice = (request.form.get("l_arm_key") or "").strip()
    legs_choice = (request.form.get("legs_key") or "").strip()
    decor_asset_id_raw = (request.form.get("decor_asset_id") or "").strip()
    decor_asset_id = int(decor_asset_id_raw) if decor_asset_id_raw.isdigit() else None
    combat_mode = _normalize_combat_mode(request.form.get("combat_mode"))

    def _build_redirect():
        if build_mode == "modify":
            return redirect(url_for("build", mode="modify", base_robot_id=base_robot_id or "", frame_type=selected_frame_type))
        return redirect(url_for("build", mode="new", frame_type=selected_frame_type))

    base_robot = None
    base_mapping = {}
    if build_mode == "modify":
        if not base_robot_id:
            session["message"] = "改造する保存中ロボを選んでください。"
            return _build_redirect()
        base_robot = db.execute(
            """
            SELECT *
            FROM robot_instances
            WHERE id = ? AND user_id = ? AND status != 'decomposed'
            """,
            (int(base_robot_id), int(user["id"])),
        ).fetchone()
        if not base_robot:
            session["message"] = "改造する保存中ロボが見つかりません。"
            return _build_redirect()
        base_mapping = _ensure_robot_instance_part_instances(db, int(base_robot["id"])) or {}
        if not all(base_mapping.get(slot) for slot in ("head", "r_arm", "l_arm", "legs")):
            session["message"] = "改造元ロボのパーツ情報が不足しています。"
            return _build_redirect()

    if build_mode == "new" and not all([head_choice, r_arm_choice, l_arm_choice, legs_choice]):
        session["message"] = "全カテゴリから1つずつ選択してください。"
        return _build_redirect()
    slot_defs = {
        "head": {"expected_type": "HEAD", "choice": head_choice},
        "r_arm": {"expected_type": "RIGHT_ARM", "choice": r_arm_choice},
        "l_arm": {"expected_type": "LEFT_ARM", "choice": l_arm_choice},
        "legs": {"expected_type": "LEGS", "choice": legs_choice},
    }

    def _resolve_selected_part_instance(choice_raw, expected_type):
        choice = str(choice_raw or "").strip()
        if not choice:
            return None
        if choice.isdigit():
            row = db.execute(
                """
                SELECT pi.id, pi.status, rp.key, rp.part_type, COALESCE(rp.frame_type, 'normal') AS frame_type
                FROM part_instances pi
                JOIN robot_parts rp ON rp.id = pi.part_id
                WHERE pi.id = ? AND pi.user_id = ? AND pi.status = 'inventory' AND rp.is_active = 1
                """,
                (int(choice), user["id"]),
            ).fetchone()
            if not row:
                return None
            if _norm_part_type(row["part_type"]) != expected_type:
                return None
            return {
                "id": int(row["id"]),
                "key": row["key"],
                "part_type": _norm_part_type(row["part_type"]),
                "frame_type": _normalize_frame_type(row["frame_type"]),
            }
        # Backward-compatible key fallback.
        row = db.execute(
            """
            SELECT pi.id, pi.status, rp.key, rp.part_type, COALESCE(rp.frame_type, 'normal') AS frame_type
            FROM part_instances pi
            JOIN robot_parts rp ON rp.id = pi.part_id
            WHERE pi.user_id = ? AND pi.status = 'inventory' AND rp.key = ? AND rp.is_active = 1
            ORDER BY pi.plus DESC, pi.id ASC
            LIMIT 1
            """,
            (user["id"], choice),
        ).fetchone()
        if row and _norm_part_type(row["part_type"]) == expected_type:
            return {
                "id": int(row["id"]),
                "key": row["key"],
                "part_type": _norm_part_type(row["part_type"]),
                "frame_type": _normalize_frame_type(row["frame_type"]),
            }
        legacy_id = _take_or_materialize_part_instance(db, user["id"], choice)
        if not legacy_id:
            return None
        legacy_row = db.execute(
            """
            SELECT pi.id, pi.status, rp.key, rp.part_type, COALESCE(rp.frame_type, 'normal') AS frame_type
            FROM part_instances pi
            JOIN robot_parts rp ON rp.id = pi.part_id
            WHERE pi.id = ? AND pi.user_id = ? AND rp.is_active = 1
            """,
            (legacy_id, user["id"]),
        ).fetchone()
        if (
            not legacy_row
            or _norm_part_type(legacy_row["part_type"]) != expected_type
            or str(legacy_row["status"] or "inventory").strip().lower() != "inventory"
        ):
            return None
        return {
            "id": int(legacy_row["id"]),
            "key": legacy_row["key"],
            "part_type": _norm_part_type(legacy_row["part_type"]),
            "frame_type": _normalize_frame_type(legacy_row["frame_type"]),
        }

    resolved_slots = {}
    for slot_name, cfg in slot_defs.items():
        resolved = _resolve_selected_part_instance(cfg["choice"], cfg["expected_type"])
        if not resolved and build_mode == "modify":
            base_slot_id = base_mapping.get(slot_name)
            if base_slot_id:
                base_row = db.execute(
                    """
                    SELECT pi.id, pi.status, rp.key, rp.part_type, COALESCE(rp.frame_type, 'normal') AS frame_type
                    FROM part_instances pi
                    JOIN robot_parts rp ON rp.id = pi.part_id
                    WHERE pi.id = ? AND pi.user_id = ? AND rp.is_active = 1
                    """,
                    (int(base_slot_id), int(user["id"])),
                ).fetchone()
                if base_row and _norm_part_type(base_row["part_type"]) == cfg["expected_type"]:
                    resolved = {
                        "id": int(base_row["id"]),
                        "key": base_row["key"],
                        "part_type": _norm_part_type(base_row["part_type"]),
                        "frame_type": _normalize_frame_type(base_row["frame_type"]),
                        "clone_from_base": True,
                    }
        if not resolved:
            session["message"] = "無効化されたパーツは組み立てに使用できません。"
            return _build_redirect()
        resolved_slots[slot_name] = resolved
    if len({resolved_slots["head"]["id"], resolved_slots["r_arm"]["id"], resolved_slots["l_arm"]["id"], resolved_slots["legs"]["id"]}) != 4:
        session["message"] = "同じ個体を複数部位へは設定できません。"
        return _build_redirect()
    selected_frame_types = {resolved_slots[key]["frame_type"] for key in ("head", "r_arm", "l_arm", "legs")}
    is_free_build = selected_frame_type == FREE_BUILD_FRAME_MODE
    is_mixed_frame = len(selected_frame_types) > 1
    if not is_free_build and (len(selected_frame_types) != 1 or selected_frame_type not in selected_frame_types):
        session["message"] = "選択中の編成モードでは、このパーツ同士を組み合わせられません。自由編成を選ぶと、異なる型のパーツも組み合わせられます。"
        return _build_redirect()
    robot_frame_type = resolved_slots["head"]["frame_type"] if is_mixed_frame else next(iter(selected_frame_types))

    head_key = resolved_slots["head"]["key"]
    r_arm_key = resolved_slots["r_arm"]["key"]
    l_arm_key = resolved_slots["l_arm"]["key"]
    legs_key = resolved_slots["legs"]["key"]
    if combat_mode == "berserk" and not _has_any_active_boss_alert(db, user["id"]):
        session["message"] = "背水モードはボス警報中のみ選択可能"
        return _build_redirect()
    if decor_asset_id is not None:
        decor = db.execute(
            """
            SELECT rda.id
            FROM robot_decor_assets rda
            JOIN user_decor_inventory udi ON udi.decor_asset_id = rda.id
            WHERE rda.id = ? AND rda.is_active = 1 AND udi.user_id = ?
            """,
            (decor_asset_id, user["id"]),
        ).fetchone()
        if not decor:
            session["message"] = "装飾が無効です。選び直してください。"
            return _build_redirect()
    if not robot_name:
        next_id_row = db.execute(
            "SELECT COALESCE(MAX(id), 0) + 1 AS next_id FROM robot_instances"
        ).fetchone()
        robot_name = f"Robot #{next_id_row['next_id']}"
    limits = _effective_limits(db, user)
    active_count = db.execute(
        "SELECT COUNT(*) AS c FROM robot_instances WHERE user_id = ? AND status != 'decomposed'",
        (user["id"],),
    ).fetchone()["c"]
    if active_count >= limits["robot_slots"]:
        flash(
            f"保存枠がいっぱいです。不要なロボを整理してください（{int(active_count)}/{int(limits['robot_slots'])}）。",
            "error",
        )
        return _build_redirect()
    try:
        db.execute("BEGIN IMMEDIATE")
        selected = {
            "head": int(resolved_slots["head"]["id"]),
            "r_arm": int(resolved_slots["r_arm"]["id"]),
            "l_arm": int(resolved_slots["l_arm"]["id"]),
            "legs": int(resolved_slots["legs"]["id"]),
        }
        if build_mode == "modify":
            for slot_name in ("head", "r_arm", "l_arm", "legs"):
                if resolved_slots[slot_name].get("clone_from_base"):
                    cloned_id = _clone_part_instance_for_user(db, int(resolved_slots[slot_name]["id"]), int(user["id"]))
                    if not cloned_id:
                        raise ValueError("改造元パーツの複製に失敗しました。")
                    selected[slot_name] = int(cloned_id)
        if not all(selected.values()):
            missing = [k for k, v in selected.items() if not v]
            raise ValueError(f"在庫不足: {', '.join(missing)}")

        instance_id = _create_robot_instance(
            db,
            user["id"],
            robot_name,
            head_key,
            r_arm_key,
            l_arm_key,
            legs_key,
            decor_asset_id=decor_asset_id,
            status="active",
            combat_mode=combat_mode,
            frame_type=robot_frame_type,
            is_mixed_frame=is_mixed_frame,
            build_frame_mode=selected_frame_type,
            offsets=selected_offsets,
        )
        _equip_part_instances_on_robot(db, instance_id, selected)
        parts = {
            "head_key": head_key,
            "r_arm_key": r_arm_key,
            "l_arm_key": l_arm_key,
            "legs_key": legs_key,
            "decor_asset_id": decor_asset_id,
            **selected_offsets,
        }
        _compose_instance_assets_no_commit(db, instance_id, parts)
        _ensure_robot_title_master_rows(db)
        _grant_robot_title_by_key(db, robot_id=int(instance_id), title_key="title_boot")
        style_state = _ensure_style_snapshot(
            db,
            int(instance_id),
            force=True,
            audit_context={
                "user_id": int(user["id"]),
                "request_id": getattr(g, "request_id", None),
                "action_key": "build_confirm",
                "ip": request.remote_addr,
            },
        )
        db.execute("UPDATE users SET active_robot_id = ? WHERE id = ?", (instance_id, user["id"]))
        week_key = _world_week_key()
        build_element = _build_element_from_keys(db, head_key, r_arm_key, l_arm_key, legs_key)
        _world_counter_inc(db, week_key, f"builds_{build_element}", 1)
        consumed_ids = [selected["head"], selected["r_arm"], selected["l_arm"], selected["legs"]]
        audit_log(
            db,
            AUDIT_EVENT_TYPES["BUILD_CONFIRM"],
            user_id=user["id"],
            request_id=getattr(g, "request_id", None),
            action_key="build_confirm",
            entity_type="robot_instance",
            entity_id=instance_id,
            payload={
                "robot_instance_id": instance_id,
                "robot_name": robot_name,
                "head_key": head_key,
                "r_arm_key": r_arm_key,
                "l_arm_key": l_arm_key,
                "legs_key": legs_key,
                "decor_asset_id": decor_asset_id,
                "combat_mode": combat_mode,
                "build_mode": selected_frame_type,
                "frame_types": sorted(selected_frame_types),
                "is_mixed_frame": bool(is_mixed_frame),
                "set_bonus_enabled": not bool(is_mixed_frame),
                "offsets": dict(selected_offsets),
                "consumed_part_instance_ids": consumed_ids,
                "style": {
                    "current_key": style_state.get("current_key"),
                    "next_key": style_state.get("next_key"),
                    "scores": style_state.get("scores"),
                },
            },
            ip=request.remote_addr,
        )
        add_faction_points(
            db,
            int(user["id"]),
            "build",
            FACTION_POINTS["build"],
            counters={"build_count": 1},
            payload={"robot_instance_id": int(instance_id), "robot_name": robot_name},
            create_log=True,
            week_key=week_key,
        )
        grant_lab_exp(
            db,
            int(user["id"]),
            "build.confirm",
            15,
            source_entity_type="robot_instance",
            source_entity_id=int(instance_id),
            payload={"robot_name": robot_name},
        )
        _record_insect_robot_completion_if_needed(
            db,
            int(user["id"]),
            int(instance_id),
            robot_name=robot_name,
            request_id=getattr(g, "request_id", None),
            ip=request.remote_addr,
        )
        for pid in consumed_ids:
            audit_log(
                db,
                AUDIT_EVENT_TYPES["INVENTORY_DELTA"],
                user_id=user["id"],
                request_id=getattr(g, "request_id", None),
                action_key="build_confirm",
                entity_type="part_instance",
                entity_id=pid,
                delta_count=-1,
                payload={"reason": "build_confirm_consume", "robot_instance_id": instance_id},
                ip=request.remote_addr,
            )
        evaluate_referral_qualification(db, user["id"], request_ip=request.remote_addr)
        db.commit()
    except Exception as exc:
        db.rollback()
        session["message"] = str(exc)
        return _build_redirect()
    session["message"] = "機体を改造しました。" if build_mode == "modify" else "完成ロボを登録し、出撃機体に設定しました。"
    return redirect(url_for("robots"))


@app.route("/robots/<int:instance_id>/rename", methods=["POST"])
@login_required
def robot_instance_rename(instance_id):
    db = get_db()
    user = db.execute("SELECT * FROM users WHERE id = ?", (session["user_id"],)).fetchone()
    new_name = request.form.get("robot_name", "").strip()
    rename_cost = 500
    if not new_name:
        session["message"] = "新しいロボ名を入力してください。"
        return redirect(url_for("robots"))
    target = db.execute(
        "SELECT id, name FROM robot_instances WHERE id = ? AND user_id = ?",
        (instance_id, user["id"]),
    ).fetchone()
    if not target:
        session["message"] = "改名対象が見つかりません。"
        return redirect(url_for("robots"))
    if user["coins"] < rename_cost:
        session["message"] = f"コイン不足です（改名コスト {rename_cost}）。"
        return redirect(url_for("robots"))
    db.execute("UPDATE users SET coins = coins - ? WHERE id = ?", (rename_cost, user["id"]))
    db.execute(
        "UPDATE robot_instances SET name = ?, updated_at = ? WHERE id = ?",
        (new_name, int(time.time()), instance_id),
    )
    audit_log(
        db,
        AUDIT_EVENT_TYPES["ROBOT_RENAME"],
        user_id=user["id"],
        request_id=getattr(g, "request_id", None),
        action_key="rename",
        entity_type="robot_instance",
        entity_id=instance_id,
        delta_coins=-rename_cost,
        payload={
            "robot_instance_id": instance_id,
            "old_name": target["name"],
            "new_name": new_name,
            "coin_cost": rename_cost,
        },
        ip=request.remote_addr,
    )
    audit_log(
        db,
        AUDIT_EVENT_TYPES["COIN_DELTA"],
        user_id=user["id"],
        request_id=getattr(g, "request_id", None),
        action_key="rename",
        entity_type="robot_instance",
        entity_id=instance_id,
        delta_coins=-rename_cost,
        payload={"source": "rename", "coin_cost": rename_cost},
        ip=request.remote_addr,
    )
    db.commit()
    session["message"] = f"ロボ名を変更しました（-{rename_cost} コイン）。"
    return redirect(url_for("robots"))


@app.route("/showcase")
@login_required
def showcase():
    db = get_db()
    user = db.execute("SELECT * FROM users WHERE id = ?", (session["user_id"],)).fetchone()
    sort_key = (request.args.get("sort") or "new").strip().lower()
    if sort_key == "likes":
        sort_key = "like"
    if sort_key not in SHOWCASE_SORT_OPTIONS:
        sort_key = "new"
    _ensure_qol_entitlement(db, user["id"])
    limits = _effective_limits(db, user)
    _ensure_showcase_slots(db, user["id"], limits["showcase_slots"])
    rows = _showcase_rows(db, user["id"])
    robots = db.execute(
        "SELECT id, name, status, composed_image_path FROM robot_instances WHERE user_id = ? AND status != 'decomposed' ORDER BY updated_at DESC",
        (user["id"],),
    ).fetchall()
    public_rows = _showcase_query_rows(
        db,
        user_id=int(user["id"]),
        sort_key=sort_key,
        limit=80,
    )
    db.commit()
    return render_template(
        "showcase.html",
        rows=rows,
        robots=robots,
        limits=limits,
        public_rows=public_rows,
        sort_key=sort_key,
        sort_options=tuple(SHOWCASE_SORT_OPTIONS),
        sort_defs=SHOWCASE_SORT_DEFS,
    )


@app.route("/showcase/set", methods=["POST"])
@login_required
def showcase_set():
    db = get_db()
    user = db.execute("SELECT * FROM users WHERE id = ?", (session["user_id"],)).fetchone()
    _ensure_qol_entitlement(db, user["id"])
    limits = _effective_limits(db, user)
    _ensure_showcase_slots(db, user["id"], limits["showcase_slots"])
    try:
        slot_no = int(request.form.get("slot_no", "0"))
    except ValueError:
        slot_no = 0
    robot_instance_id = request.form.get("robot_instance_id")
    if slot_no < 1 or slot_no > limits["showcase_slots"]:
        session["message"] = "無効なロボ展示枠です。"
        return redirect(url_for("showcase"))
    if robot_instance_id:
        target = db.execute(
            "SELECT id FROM robot_instances WHERE id = ? AND user_id = ?",
            (robot_instance_id, user["id"]),
        ).fetchone()
        if not target:
            session["message"] = "設定対象のロボが見つかりません。"
            return redirect(url_for("showcase"))
        db.execute(
            "UPDATE user_showcase SET robot_instance_id = ? WHERE user_id = ? AND slot_no = ?",
            (robot_instance_id, user["id"], slot_no),
        )
    else:
        db.execute(
            "UPDATE user_showcase SET robot_instance_id = NULL WHERE user_id = ? AND slot_no = ?",
            (user["id"], slot_no),
        )
    db.commit()
    session["message"] = "ロボ展示を更新しました。"
    return redirect(url_for("showcase"))


@app.route("/showcase/buy_slot", methods=["POST"])
@login_required
def showcase_buy_slot():
    db = get_db()
    user = db.execute("SELECT * FROM users WHERE id = ?", (session["user_id"],)).fetchone()
    _ensure_qol_entitlement(db, user["id"])
    ent = db.execute("SELECT * FROM qol_entitlements WHERE user_id = ?", (user["id"],)).fetchone()
    current = ent["showcase_slots"]
    if current >= 3:
        session["message"] = "ロボ展示枠は最大です。"
        return redirect(url_for("showcase"))
    next_slot = current + 1
    price = 5_000 if next_slot == 2 else 15_000
    if user["coins"] < price:
        session["message"] = f"コイン不足です（必要 {price}）。"
        return redirect(url_for("showcase"))
    db.execute("UPDATE users SET coins = coins - ? WHERE id = ?", (price, user["id"]))
    db.execute(
        "UPDATE qol_entitlements SET showcase_slots = ?, updated_at = ? WHERE user_id = ?",
        (next_slot, int(time.time()), user["id"]),
    )
    _ensure_showcase_slots(db, user["id"], next_slot)
    audit_log(
        db,
        AUDIT_EVENT_TYPES["SHOWCASE_EXPAND"],
        user_id=user["id"],
        request_id=getattr(g, "request_id", None),
        action_key="showcase_expand",
        entity_type="user",
        entity_id=user["id"],
        delta_coins=-price,
        delta_count=1,
        payload={
            "from_slots": current,
            "to_slots": next_slot,
            "coin_cost": price,
        },
        ip=request.remote_addr,
    )
    audit_log(
        db,
        AUDIT_EVENT_TYPES["COIN_DELTA"],
        user_id=user["id"],
        request_id=getattr(g, "request_id", None),
        action_key="showcase_expand",
        delta_coins=-price,
        payload={"source": "showcase_expand", "coin_cost": price},
        ip=request.remote_addr,
    )
    db.commit()
    session["message"] = f"ロボ展示枠を拡張しました（-{price} コイン）。"
    return redirect(url_for("showcase"))


@app.route("/battle_simulation/robot/<int:robot_id>", methods=["POST"])
@login_required
def battle_simulation(robot_id):
    db = get_db()
    user = db.execute("SELECT * FROM users WHERE id = ?", (int(session["user_id"]),)).fetchone()
    if not user:
        session.clear()
        return redirect(url_for("login", reason="expired"))

    sort_key = (request.form.get("sort") or request.args.get("sort") or "new").strip().lower()
    if sort_key == "likes":
        sort_key = "like"
    if sort_key not in SHOWCASE_SORT_OPTIONS:
        sort_key = "new"

    target = db.execute(
        """
        SELECT id, user_id, name
        FROM robot_instances
        WHERE id = ? AND status = 'active' AND COALESCE(is_public, 1) = 1
        """,
        (int(robot_id),),
    ).fetchone()
    if not target:
        abort(404)

    active_robot = _get_active_robot(db, int(user["id"]))
    if not active_robot:
        flash("対戦するには出撃機体を設定してください。", "notice")
        db.commit()
        return redirect(url_for("build"))

    challenger_payload = _build_champion_robot_payload(
        db,
        user_id=int(user["id"]),
        robot_instance_id=int(active_robot["id"]),
    )
    target_payload = _build_champion_robot_payload(
        db,
        user_id=int(target["user_id"]),
        robot_instance_id=int(target["id"]),
    )
    if not challenger_payload or not target_payload:
        flash("対戦機体の読み込みに失敗しました。少し待ってから再挑戦してください。", "error")
        db.commit()
        return redirect(url_for("showcase", sort=sort_key))

    battle_result = run_champion_battle(
        {
            "name": str(challenger_payload.get("robot_name") or "あなた"),
            "stats": dict(challenger_payload.get("stats") or {}),
            "signature_label": str(challenger_payload.get("signature_label") or ""),
            "focus_labels": list(challenger_payload.get("focus_labels") or []),
        },
        {
            "name": str(target_payload.get("robot_name") or "展示ロボ"),
            "stats": dict(target_payload.get("stats") or {}),
            "signature_label": str(target_payload.get("signature_label") or ""),
            "focus_labels": list(target_payload.get("focus_labels") or []),
        },
        max_turns=8,
    )

    request_id = getattr(g, "request_id", None) or str(uuid.uuid4())
    today_start, today_end = _jst_day_bounds()
    rewarded_today = bool(
        db.execute(
            """
            SELECT 1
            FROM world_events_log
            WHERE user_id = ?
              AND event_type = ?
              AND entity_type = 'robot_instance'
              AND entity_id = ?
              AND COALESCE(delta_coins, 0) > 0
              AND created_at >= ?
              AND created_at < ?
            LIMIT 1
            """,
            (
                int(user["id"]),
                AUDIT_EVENT_TYPES["SHOWCASE_BATTLE"],
                int(target["id"]),
                int(today_start),
                int(today_end),
            ),
        ).fetchone()
    )
    reward_coin = 0
    self_target = int(target["user_id"]) == int(user["id"])
    if bool(battle_result.get("win")) and not rewarded_today and not self_target:
        reward_coin = max(0, int(SHOWCASE_BATTLE_WIN_REWARD_COINS or 0))
    if reward_coin > 0:
        db.execute(
            "UPDATE users SET coins = coins + ? WHERE id = ?",
            (int(reward_coin), int(user["id"])),
        )

    battle_payload = {
        "challenger_user_id": int(user["id"]),
        "challenger_owner_name": str(challenger_payload.get("owner_name") or _display_username_for_user_row(db, user)),
        "challenger_robot_instance_id": int(active_robot["id"]),
        "challenger_robot_name": str(challenger_payload.get("robot_name") or active_robot.get("name") or "挑戦機"),
        "challenger_robot_image_url": challenger_payload.get("robot_image_url"),
        "target_user_id": int(target_payload.get("user_id") or target["user_id"]),
        "target_owner_name": str(target_payload.get("owner_name") or "unknown"),
        "target_robot_instance_id": int(target["id"]),
        "target_robot_name": str(target_payload.get("robot_name") or target["name"] or "展示ロボ"),
        "target_robot_image_url": target_payload.get("robot_image_url"),
        "result": ("win" if battle_result.get("win") else "lose"),
        "outcome": str(battle_result.get("outcome") or ""),
        "turn_count": int(battle_result.get("turn_count") or 0),
        "timeout": bool(battle_result.get("timeout")),
        "summary_label": str(battle_result.get("summary_label") or ""),
        "first_strike_mode": str(battle_result.get("first_strike_mode") or "RANDOM_FIRST"),
        "first_striker": str(battle_result.get("first_striker") or ""),
        "reward_coin": int(reward_coin),
        "reward_already_granted_today": bool(rewarded_today),
        "self_target": bool(self_target),
    }
    audit_log(
        db,
        AUDIT_EVENT_TYPES["SHOWCASE_BATTLE"],
        user_id=int(user["id"]),
        request_id=request_id,
        action_key="showcase_battle",
        entity_type="robot_instance",
        entity_id=int(target["id"]),
        delta_coins=int(reward_coin),
        payload=battle_payload,
        ip=request.remote_addr,
    )
    if reward_coin > 0:
        audit_log(
            db,
            AUDIT_EVENT_TYPES["COIN_DELTA"],
            user_id=int(user["id"]),
            request_id=request_id,
            action_key="showcase_battle",
            entity_type="robot_instance",
            entity_id=int(target["id"]),
            delta_coins=int(reward_coin),
            payload={
                "source": "showcase_battle",
                "target_robot_instance_id": int(target["id"]),
                "result": battle_payload["result"],
                "reward_coin": int(reward_coin),
            },
            ip=request.remote_addr,
        )

    battle_short_replay_enabled = _battle_short_replay_open_for_viewer(
        db,
        user_row=user,
        user_id=int(user["id"]),
    )
    enemy_replay_stats = dict(target_payload.get("stats") or {})
    enemy_replay_stats["trait"] = enemy_replay_stats.get("trait") or "normal"
    battle_cinematic = (
        _build_battle_replay_summary(
            area_key="showcase_battle",
            area_label="ロボ展示模擬戦",
            enemy_name=str(target_payload.get("robot_name") or "展示ロボ"),
            enemy_image_url=target_payload.get("robot_image_url") or url_for("static", filename="assets/placeholder_enemy.png"),
            player_name=str(challenger_payload.get("robot_name") or active_robot.get("name") or "あなた"),
            player_image_url=challenger_payload.get("robot_image_url") or active_robot.get("image_url") or url_for("static", filename="assets/placeholder_player.png"),
            player_stats=dict(challenger_payload.get("stats") or {}),
            enemy_stats=enemy_replay_stats,
            robot_style={"style_key": str(challenger_payload.get("style_key") or "stable")},
            turn_logs=list(battle_result.get("turn_logs") or []),
            outcome=str(battle_result.get("outcome") or ""),
            is_boss=False,
        )
        if battle_short_replay_enabled
        else None
    )
    result_summary = {
        "outcome": str(battle_result.get("outcome") or ("勝利" if battle_result.get("win") else "敗北")),
        "outcome_is_win": bool(battle_result.get("win")),
        "summary_heading": str(battle_result.get("summary_heading") or ("今回の勝ち筋" if battle_result.get("win") else "今回の崩れ筋")),
        "summary_label": str(battle_result.get("summary_label") or ""),
        "result_label": str(battle_result.get("result_label") or ("WIN" if battle_result.get("win") else "LOSE")),
        "turn_count": int(battle_result.get("turn_count") or 0),
        "timeout_decision_line": (
            str((battle_result.get("timeout_decision") or {}).get("result_line") or "")
            if battle_result.get("timeout")
            else ""
        ),
        "reward_coin": int(reward_coin),
        "reward_already_granted_today": bool(rewarded_today),
        "battle_cinematic": battle_cinematic,
        "headline": ("展示ロボに勝利" if battle_result.get("win") else "展示ロボに敗北"),
        "subline": (
            f"腕試し報酬として {int(reward_coin)} コインを獲得しました。"
            if reward_coin > 0
            else (
                "自分の機体との腕試しではコイン報酬はありません。"
                if battle_result.get("win") and self_target
                else ("今日はこの相手の勝利報酬を受け取り済みです。" if battle_result.get("win") and rewarded_today else "機体を調整して再挑戦できます。")
            )
        ),
    }
    opponent = {
        "robot_instance_id": int(target["id"]),
        "robot_name": str(target_payload.get("robot_name") or "展示ロボ"),
        "owner_name": str(target_payload.get("owner_name") or "unknown"),
        "robot_image_url": target_payload.get("robot_image_url"),
        "signature_label": str(target_payload.get("signature_label") or ""),
        "focus_label_line": str(target_payload.get("focus_label_line") or ""),
        "trait_summary": str(target_payload.get("trait_summary") or ""),
    }
    db.commit()
    return render_template(
        "showcase_battle.html",
        title="展示ロボ模擬戦",
        opponent=opponent,
        challenger=challenger_payload,
        active_robot=active_robot,
        turn_logs=list(battle_result.get("turn_logs") or []),
        summary=result_summary,
        battle_cinematic=result_summary["battle_cinematic"],
        battle_log_mode=(str(user["battle_log_mode"] or "collapsed").strip().lower() if "battle_log_mode" in user.keys() else "collapsed"),
        battle_short_replay_enabled=battle_short_replay_enabled,
        sort_key=sort_key,
    )


@app.route("/showcase/<int:robot_id>/like", methods=["POST"])
@login_required
def showcase_like(robot_id):
    db = get_db()
    row = db.execute(
        """
        SELECT id
        FROM robot_instances
        WHERE id = ? AND status = 'active' AND COALESCE(is_public, 1) = 1
        """,
        (int(robot_id),),
    ).fetchone()
    if not row:
        abort(404)
    existing = db.execute(
        """
        SELECT id
        FROM showcase_votes
        WHERE robot_id = ? AND user_id = ? AND vote_type = 'like'
        LIMIT 1
        """,
        (int(robot_id), int(session["user_id"])),
    ).fetchone()
    if existing:
        db.execute("DELETE FROM showcase_votes WHERE id = ?", (int(existing["id"]),))
        toggled_on = False
    else:
        db.execute(
            """
            INSERT INTO showcase_votes (robot_id, user_id, vote_type, created_at)
            VALUES (?, ?, 'like', ?)
            ON CONFLICT(robot_id, user_id, vote_type) DO NOTHING
            """,
            (int(robot_id), int(session["user_id"]), int(time.time())),
        )
        toggled_on = True
    audit_log(
        db,
        AUDIT_EVENT_TYPES["SHOWCASE_LIKE"],
        user_id=int(session["user_id"]),
        request_id=getattr(g, "request_id", None),
        action_key="showcase_like",
        entity_type="robot_instance",
        entity_id=int(robot_id),
        delta_count=(1 if toggled_on else -1),
        payload={"robot_id": int(robot_id), "vote_type": "like", "toggled_on": bool(toggled_on)},
        ip=request.remote_addr,
    )
    db.commit()
    sort_key = (request.form.get("sort") or request.args.get("sort") or "new").strip().lower()
    if sort_key == "likes":
        sort_key = "like"
    if sort_key not in SHOWCASE_SORT_OPTIONS:
        sort_key = "new"
    return redirect(url_for("showcase", sort=sort_key))


def _mini_robot_species_row(db, species_key=MINI_ROBOT_INITIAL_SPECIES_KEY):
    return db.execute(
        "SELECT * FROM mini_robot_species WHERE species_key = ?",
        (str(species_key or MINI_ROBOT_INITIAL_SPECIES_KEY),),
    ).fetchone()


def _mini_robot_row_value(row, key, default=None):
    if not row or not hasattr(row, "keys") or key not in row.keys():
        return default
    value = row[key]
    return default if value is None else value


def _mini_robot_image_rel(species_key, state_key="normal"):
    species = str(species_key or MINI_ROBOT_INITIAL_SPECIES_KEY).strip()
    state = str(state_key or "normal").strip()
    if state not in MINI_ROBOT_STATE_LABELS:
        state = "normal"
    rel = f"mini_robots/{species}/{state}.png"
    if os.path.exists(_static_abs(rel)):
        return rel
    fallback = f"mini_robots/{species}/normal.png"
    if os.path.exists(_static_abs(fallback)):
        return fallback
    cerberus = "mini_robots/cerberus/normal.png"
    if os.path.exists(_static_abs(cerberus)):
        return cerberus
    return "assets/placeholder_enemy.png"


def _mini_robot_image_url(species_key, state_key="normal"):
    return _versioned_static_url(
        _mini_robot_image_rel(species_key, state_key),
        fallback_url=url_for("static", filename="assets/placeholder_enemy.png"),
    )


def _mini_robot_species_choices(db):
    rows = db.execute(
        """
        SELECT *
        FROM mini_robot_species
        WHERE is_active = 1
        ORDER BY CASE species_key WHEN 'cerberus' THEN 1 WHEN 'phoenix' THEN 2 WHEN 'hydra' THEN 3 WHEN 'sphinx' THEN 4 ELSE 9 END
        """
    ).fetchall()
    choices = []
    for row in rows:
        meta = MINI_ROBOT_SPECIES_META.get(row["species_key"], {})
        choices.append(
            {
                "species_key": row["species_key"],
                "name": meta.get("name") or row["name_ja"],
                "short_name": meta.get("short_name") or row["name_ja"],
                "description": meta.get("description") or row["description"],
                "personality": meta.get("personality") or "性格は調査中。",
                "image_url": _mini_robot_image_url(row["species_key"], "normal"),
            }
        )
    return choices


def _mini_robot_pick_initial_traits(species_key, *, seed=None):
    rng = random.Random(seed) if seed is not None else random
    species = str(species_key or MINI_ROBOT_INITIAL_SPECIES_KEY)
    evolution_candidates = MINI_ROBOT_EVOLUTION_SEEDS.get(species) or (f"{species}_default",)
    return {
        "personality_key": rng.choice(MINI_ROBOT_PERSONALITY_KEYS),
        "growth_type": rng.choice(MINI_ROBOT_GROWTH_TYPES),
        "behavior_seed": rng.randint(1, 999999),
        "evolution_seed": rng.choice(evolution_candidates),
        "favorite_time_band": rng.choice(MINI_ROBOT_TIME_BANDS),
        "instinct": rng.randint(1, 3),
    }


def _backfill_mini_robot_internal_fields(db):
    try:
        rows = db.execute("SELECT * FROM user_mini_robots").fetchall()
    except Exception:
        return
    for row in rows:
        row_id = int(row["id"])
        species_key = str(_mini_robot_row_value(row, "species_key", MINI_ROBOT_INITIAL_SPECIES_KEY))
        seed = f"mini-backfill:{row_id}:{species_key}"
        traits = _mini_robot_pick_initial_traits(species_key, seed=seed)
        last_care_date = _mini_robot_day_key_from_ts(row["last_cared_at"]) if int(row["last_cared_at"] or 0) > 0 else None
        care_count = int(
            db.execute(
                "SELECT COUNT(*) AS c FROM mini_robot_logs WHERE mini_robot_id = ? AND event_type = 'care'",
                (row_id,),
            ).fetchone()["c"]
            or 0
        )
        updates = {}
        for key in ("personality_key", "growth_type", "evolution_seed", "favorite_time_band"):
            if not str(_mini_robot_row_value(row, key, "") or "").strip():
                updates[key] = traits[key]
        if int(_mini_robot_row_value(row, "behavior_seed", 0) or 0) <= 0:
            updates["behavior_seed"] = traits["behavior_seed"]
        if int(_mini_robot_row_value(row, "instinct", 0) or 0) <= 0:
            updates["instinct"] = traits["instinct"]
        for key in ("trust", "curiosity", "stress", "consecutive_care_days"):
            if _mini_robot_row_value(row, key) is None:
                updates[key] = 0
        if int(_mini_robot_row_value(row, "care_count", 0) or 0) <= 0 and care_count > 0:
            updates["care_count"] = care_count
        if not str(_mini_robot_row_value(row, "last_care_date", "") or "").strip() and last_care_date:
            updates["last_care_date"] = last_care_date
        if not str(_mini_robot_row_value(row, "last_state_reason", "") or "").strip():
            updates["last_state_reason"] = "backfilled"
        if updates:
            assignments = ", ".join([f"{key} = ?" for key in updates])
            db.execute(
                f"UPDATE user_mini_robots SET {assignments} WHERE id = ?",
                [*updates.values(), row_id],
            )


def _mini_robot_add_log(db, *, user_id, mini_robot_id, event_type, message, payload=None, created_at=None):
    now_ts = int(created_at or _now_ts())
    db.execute(
        """
        INSERT INTO mini_robot_logs (user_id, mini_robot_id, event_type, message, payload_json, created_at)
        VALUES (?, ?, ?, ?, ?, ?)
        """,
        (
            int(user_id),
            int(mini_robot_id),
            str(event_type),
            str(message or ""),
            json.dumps(payload or {}, ensure_ascii=False) if payload else None,
            now_ts,
        ),
    )
    stale_ids = [
        int(row["id"])
        for row in db.execute(
            """
            SELECT id
            FROM mini_robot_logs
            WHERE mini_robot_id = ?
            ORDER BY created_at DESC, id DESC
            LIMIT -1 OFFSET 10
            """,
            (int(mini_robot_id),),
        ).fetchall()
    ]
    if stale_ids:
        marks = ",".join(["?"] * len(stale_ids))
        db.execute(f"DELETE FROM mini_robot_logs WHERE id IN ({marks})", stale_ids)


def _get_user_mini_robot(db, user_id):
    user_id = int(user_id)
    return db.execute(
        """
        SELECT mr.*, s.name_ja, s.description, s.type_key, s.image_normal, s.image_blink, s.image_happy, s.image_sleep
        FROM user_mini_robots mr
        JOIN mini_robot_species s ON s.species_key = mr.species_key
        WHERE mr.user_id = ?
        ORDER BY mr.created_at ASC, mr.id ASC
        LIMIT 1
        """,
        (user_id,),
    ).fetchone()


def _create_user_mini_robot(db, user_id, species_key=MINI_ROBOT_INITIAL_SPECIES_KEY):
    user_id = int(user_id)
    requested_key = str(species_key or MINI_ROBOT_INITIAL_SPECIES_KEY).strip()
    species = _mini_robot_species_row(db, requested_key)
    if not species or int(species["is_active"] or 0) != 1:
        species = _mini_robot_species_row(db, MINI_ROBOT_INITIAL_SPECIES_KEY)
    if not species:
        raise RuntimeError("mini robot species seed missing")
    existing = _get_user_mini_robot(db, user_id)
    if existing:
        return existing, False
    now_ts = _now_ts()
    traits = _mini_robot_pick_initial_traits(species["species_key"])
    cur = db.execute(
        """
        INSERT INTO user_mini_robots
        (
            user_id, species_key, nickname, stage, affection, stability, energy, mood, growth_exp,
            current_state, personality_key, growth_type, behavior_seed, evolution_seed, trust,
            curiosity, instinct, stress, care_count, consecutive_care_days, favorite_time_band,
            last_state_reason, created_at
        )
        VALUES (?, ?, ?, 'child', 0, 50, 60, 50, 0, 'normal', ?, ?, ?, ?, 0, 0, ?, 0, 0, 0, ?, 'created', ?)
        """,
        (
            user_id,
            species["species_key"],
            f"{species['name_ja']}幼体",
            traits["personality_key"],
            traits["growth_type"],
            int(traits["behavior_seed"]),
            traits["evolution_seed"],
            int(traits["instinct"]),
            traits["favorite_time_band"],
            now_ts,
        ),
    )
    mini_robot_id = int(cur.lastrowid)
    db.execute(
        """
        INSERT OR IGNORE INTO user_mini_robot_profiles (user_id, active_mini_robot_id, updated_at)
        VALUES (?, ?, ?)
        """,
        (user_id, mini_robot_id, now_ts),
    )
    db.execute(
        """
        INSERT OR IGNORE INTO mini_tactics_teams
        (user_id, slot_1_mini_robot_id, slot_2_mini_robot_id, slot_3_mini_robot_id, updated_at)
        VALUES (?, ?, NULL, NULL, ?)
        """,
        (user_id, mini_robot_id, now_ts),
    )
    _mini_robot_add_log(
        db,
        user_id=user_id,
        mini_robot_id=mini_robot_id,
        event_type="create",
        message=f"{species['name_ja']}が、ポッドの中で小さく動いた。",
        payload={"state": "normal", "reason": "created", **traits},
        created_at=now_ts,
    )
    audit_log(
        db,
        AUDIT_EVENT_TYPES["LAB_MINI_CREATE"],
        user_id=user_id,
        request_id=getattr(g, "request_id", None),
        action_key="lab_mini_create",
        entity_type="mini_robot",
        entity_id=mini_robot_id,
        payload={
            "mini_robot_id": mini_robot_id,
            "species_key": species["species_key"],
            "stage": MINI_ROBOT_STAGE_CHILD,
            "personality_key": traits["personality_key"],
            "growth_type": traits["growth_type"],
            "evolution_seed": traits["evolution_seed"],
            "favorite_time_band": traits["favorite_time_band"],
        },
        ip=request.remote_addr,
    )
    return _get_user_mini_robot(db, user_id), True


def _ensure_user_mini_robot(db, user_id):
    row = _get_user_mini_robot(db, user_id)
    if row:
        return row, False
    return _create_user_mini_robot(db, user_id, MINI_ROBOT_INITIAL_SPECIES_KEY)


def _mini_robot_day_key_from_ts(ts):
    if not ts:
        return ""
    return _jst_day_key_from_ts(int(ts))


def _mini_robot_cared_today(robot_row, now_ts=None):
    now = _now_ts() if now_ts is None else int(now_ts)
    last_care_date = str(_mini_robot_row_value(robot_row, "last_care_date", "") or "").strip()
    if last_care_date:
        return last_care_date == _jst_day_key_from_ts(now)
    return _mini_robot_day_key_from_ts(robot_row["last_cared_at"]) == _jst_day_key_from_ts(now)


def _mini_robot_time_band(now_ts=None):
    now = _now_ts() if now_ts is None else int(now_ts)
    hour = datetime.fromtimestamp(now, JST).hour
    if 5 <= hour <= 10:
        return "morning"
    if 11 <= hour <= 15:
        return "day"
    if 16 <= hour <= 20:
        return "evening"
    return "night"


def _mini_robot_state_for_time(robot_row, *, time_band=None, now_ts=None, observe=False):
    now = _now_ts() if now_ts is None else int(now_ts)
    band = time_band or _mini_robot_time_band(now)
    personality = str(_mini_robot_row_value(robot_row, "personality_key", "") or "")
    favorite = str(_mini_robot_row_value(robot_row, "favorite_time_band", "") or "")
    behavior_seed = int(_mini_robot_row_value(robot_row, "behavior_seed", 0) or 0)
    if band == "night":
        return "sleep", "night_sleep"
    if personality == "sleepy":
        rng = random.Random(f"mini-sleepy:{int(robot_row['id'])}:{behavior_seed}:{band}:{now // 3600}")
        if rng.randint(1, 100) <= (65 if observe else 40):
            return "sleep", f"time_{band}"
    if favorite and favorite == band:
        rng = random.Random(f"mini-favorite:{int(robot_row['id'])}:{behavior_seed}:{band}:{now // 900}")
        return ("blink", "favorite_time") if rng.randint(1, 100) <= 35 else ("normal", "favorite_time")
    rng = random.Random(f"mini-blink:{int(robot_row['id'])}:{behavior_seed}:{band}:{now // 7}")
    if rng.randint(1, 5) == 1:
        return "blink", "random_blink"
    return "normal", f"time_{band}" if observe else "normal_idle"


def _mini_robot_display_state(robot_row, *, force_state=None, now_ts=None):
    if force_state in MINI_ROBOT_STATE_LABELS:
        return str(force_state)
    now = _now_ts() if now_ts is None else int(now_ts)
    if _mini_robot_cared_today(robot_row, now):
        return "sleep"
    last_cared_at = int(robot_row["last_cared_at"] or 0)
    if last_cared_at and now - last_cared_at >= 36 * 3600:
        return "sleep"
    state, _reason = _mini_robot_state_for_time(robot_row, now_ts=now)
    return state


def _mini_robot_view(db, robot_row, *, force_state=None):
    state = _mini_robot_display_state(robot_row, force_state=force_state)
    logs = db.execute(
        """
        SELECT event_type, message, payload_json, created_at
        FROM mini_robot_logs
        WHERE mini_robot_id = ?
        ORDER BY created_at DESC, id DESC
        LIMIT 10
        """,
        (int(robot_row["id"]),),
    ).fetchall()
    growth_exp = int(robot_row["growth_exp"] or 0)
    return {
        "id": int(robot_row["id"]),
        "species_key": robot_row["species_key"],
        "species_name": robot_row["name_ja"],
        "description": robot_row["description"],
        "nickname": robot_row["nickname"],
        "stage": robot_row["stage"],
        "stage_label": MINI_ROBOT_STAGE_LABELS.get(robot_row["stage"], robot_row["stage"]),
        "state": state,
        "state_label": MINI_ROBOT_STATE_LABELS.get(state, state),
        "image_url": _mini_robot_image_url(robot_row["species_key"], state),
        "mood_label": "ごきげん" if int(robot_row["mood"] or 0) >= 70 else "ふつう" if int(robot_row["mood"] or 0) >= 40 else "しずか",
        "affection": int(robot_row["affection"] or 0),
        "energy": int(robot_row["energy"] or 0),
        "stability": int(robot_row["stability"] or 0),
        "mood": int(robot_row["mood"] or 0),
        "growth_exp": growth_exp,
        "growth_percent": min(100, growth_exp),
        "growth_note": "最初の反応を待っています。",
        "cared_today": _mini_robot_cared_today(robot_row),
        "personality_public_label": "調査中",
        "debug": {
            "personality_key": _mini_robot_row_value(robot_row, "personality_key", ""),
            "growth_type": _mini_robot_row_value(robot_row, "growth_type", ""),
            "behavior_seed": int(_mini_robot_row_value(robot_row, "behavior_seed", 0) or 0),
            "evolution_seed": _mini_robot_row_value(robot_row, "evolution_seed", ""),
            "trust": int(_mini_robot_row_value(robot_row, "trust", 0) or 0),
            "curiosity": int(_mini_robot_row_value(robot_row, "curiosity", 0) or 0),
            "instinct": int(_mini_robot_row_value(robot_row, "instinct", 0) or 0),
            "stress": int(_mini_robot_row_value(robot_row, "stress", 0) or 0),
            "care_count": int(_mini_robot_row_value(robot_row, "care_count", 0) or 0),
            "consecutive_care_days": int(_mini_robot_row_value(robot_row, "consecutive_care_days", 0) or 0),
            "favorite_time_band": _mini_robot_row_value(robot_row, "favorite_time_band", ""),
            "last_state_reason": _mini_robot_row_value(robot_row, "last_state_reason", ""),
        },
        "logs": [
            {
                "event_type": row["event_type"],
                "message": row["message"],
                "created_text": _format_jst_ts(row["created_at"]),
            }
            for row in logs
        ],
    }


def _mini_robot_catalog_rows(db, user_id):
    owned = {
        row["species_key"]
        for row in db.execute(
            "SELECT species_key FROM user_mini_robots WHERE user_id = ?",
            (int(user_id),),
        ).fetchall()
    }
    rows = []
    for species in db.execute(
        """
        SELECT *
        FROM mini_robot_species
        ORDER BY CASE species_key WHEN 'cerberus' THEN 1 WHEN 'phoenix' THEN 2 WHEN 'hydra' THEN 3 WHEN 'sphinx' THEN 4 ELSE 9 END
        """
    ).fetchall():
        is_owned = species["species_key"] in owned
        meta = MINI_ROBOT_SPECIES_META.get(species["species_key"], {})
        rows.append(
            {
                "species_key": species["species_key"],
                "name_ja": species["name_ja"],
                "description": species["description"] if is_owned else None,
                "personality_label": meta.get("personality") if is_owned else None,
                "is_owned": bool(is_owned),
                "unlocked": bool(is_owned),
                "image_url": _mini_robot_image_url(species["species_key"], "normal"),
            }
        )
    return rows


