def _mini_tactics_sanitize_ai_type(value):
    value = str(value or "").strip()
    return value if value in MINI_TACTICS_AI_LABELS else None


def _mini_tactics_sanitize_weapon_type(value):
    value = str(value or "").strip()
    return value if value in MINI_TACTICS_WEAPON_LABELS else None


def _mini_tactics_role_preview(ai_type, weapon_type):
    return MINI_TACTICS_ROLE_PREVIEWS.get((ai_type, weapon_type), "汎用戦術")


def _mini_tactics_ai_for_species(species_key):
    stats = MINI_TACTICS_SPECIES_STATS.get(str(species_key or "cerberus"), MINI_TACTICS_SPECIES_STATS["cerberus"])
    return str(stats["ai_type"])


def _mini_tactics_weapon_for_species(species_key):
    stats = MINI_TACTICS_SPECIES_STATS.get(str(species_key or "cerberus"), MINI_TACTICS_SPECIES_STATS["cerberus"])
    return str(stats["weapon_type"])


def _mini_tactics_weapon_range(weapon_type):
    return 1 if weapon_type == "melee" else 2


def _mini_tactics_ai_for_robot(robot_row):
    species_key = str(_mini_robot_row_value(robot_row, "species_key", "cerberus") or "cerberus")
    return MINI_TACTICS_SPECIES_STATS.get(species_key, MINI_TACTICS_SPECIES_STATS["cerberus"])["ai_type"]


def _mini_tactics_owned_rows(db, user_id):
    return db.execute(
        """
        SELECT mr.*, s.name_ja, s.description, s.type_key, s.image_normal, s.image_blink, s.image_happy, s.image_sleep
        FROM user_mini_robots mr
        JOIN mini_robot_species s ON s.species_key = mr.species_key
        WHERE mr.user_id = ?
        ORDER BY mr.created_at ASC, mr.id ASC
        """,
        (int(user_id),),
    ).fetchall()


def _mini_tactics_unit_from_robot(robot_row, slot_index):
    species_key = str(_mini_robot_row_value(robot_row, "species_key", "cerberus") or "cerberus")
    stats = MINI_TACTICS_SPECIES_STATS.get(species_key, MINI_TACTICS_SPECIES_STATS["cerberus"])
    stage = str(_mini_robot_row_value(robot_row, "stage", "child") or "child")
    growth_bonus = 1 if stage not in {"child", "幼体"} else 0
    hp = int(stats["hp"]) + growth_bonus
    state_key = str(_mini_robot_row_value(robot_row, "current_state", "normal") or "normal")
    nickname = str(_mini_robot_row_value(robot_row, "nickname", "") or _mini_robot_row_value(robot_row, "name_ja", "ミニロボ"))
    return {
        "unit_id": f"owned_mini_{int(robot_row['id'])}",
        "side": "ally",
        "name": nickname,
        "species_key": species_key,
        "x": 0,
        "y": int(slot_index) + 1,
        "hp": hp,
        "max_hp": hp,
        "atk": int(stats["atk"]) + growth_bonus,
        "def": int(stats["def"]),
        "spd": int(stats["spd"]),
        "defeated": False,
        "ai_type": _mini_tactics_ai_for_robot(robot_row),
        "weapon_type": str(stats["weapon_type"]),
        "range": int(stats["range"]),
        "image_path": _mini_robot_image_rel(species_key, state_key),
        "direction": "right",
        "source": "owned",
        "mini_robot_id": int(robot_row["id"]),
    }


def _mini_tactics_saved_slot_ids(db, user_id):
    return [slot["mini_robot_id"] for slot in _mini_tactics_saved_slots(db, user_id)]


def _mini_tactics_default_slot_positions():
    return [(0, 1), (0, 2), (0, 3)]


def _mini_tactics_saved_slots(db, user_id):
    team = db.execute(
        """
        SELECT *
        FROM mini_tactics_teams
        WHERE user_id = ?
        """,
        (int(user_id),),
    ).fetchone()
    if team:
        slots = []
        for index, key in enumerate(("slot_1", "slot_2", "slot_3")):
            default_x, default_y = _mini_tactics_default_slot_positions()[index]
            slots.append(
                {
                    "slot": index + 1,
                    "mini_robot_id": int(team[f"{key}_mini_robot_id"]) if team[f"{key}_mini_robot_id"] is not None else None,
                    "x": int(team[f"{key}_x"] if f"{key}_x" in team.keys() and team[f"{key}_x"] is not None else default_x),
                    "y": int(team[f"{key}_y"] if f"{key}_y" in team.keys() and team[f"{key}_y"] is not None else default_y),
                    "ai_type": _mini_tactics_sanitize_ai_type(team[f"{key}_ai_type"] if f"{key}_ai_type" in team.keys() else None),
                    "weapon_type": _mini_tactics_sanitize_weapon_type(
                        team[f"{key}_weapon_type"] if f"{key}_weapon_type" in team.keys() else None
                    ),
                }
            )
        return slots

    profile = db.execute(
        "SELECT active_mini_robot_id FROM user_mini_robot_profiles WHERE user_id = ?",
        (int(user_id),),
    ).fetchone()
    active_id = int(profile["active_mini_robot_id"]) if profile and profile["active_mini_robot_id"] is not None else None
    return [
        {
            "slot": index + 1,
            "mini_robot_id": active_id if index == 0 else None,
            "x": x,
            "y": y,
            "ai_type": None,
            "weapon_type": None,
        }
        for index, (x, y) in enumerate(_mini_tactics_default_slot_positions())
    ]


def _mini_tactics_team_rows(db, user_id):
    owned_rows = _mini_tactics_owned_rows(db, user_id)
    by_id = {int(row["id"]): row for row in owned_rows}
    ordered_ids = []
    for row_id in _mini_tactics_saved_slot_ids(db, user_id):
        if row_id is not None and int(row_id) in by_id and int(row_id) not in ordered_ids:
            ordered_ids.append(int(row_id))
    for row in owned_rows:
        row_id = int(row["id"])
        if len(ordered_ids) >= 3:
            break
        if row_id not in ordered_ids:
            ordered_ids.append(row_id)
    return [by_id[row_id] for row_id in ordered_ids[:3]]


def _mini_tactics_team_units_for_user(db, user_id):
    owned_rows = _mini_tactics_owned_rows(db, user_id)
    by_id = {int(row["id"]): row for row in owned_rows}
    rental_units = build_rental_ally_units()
    team_units = []
    used_ids = set()
    saved_slots = _mini_tactics_saved_slots(db, user_id)
    for index, slot in enumerate(saved_slots[:3]):
        row_id = slot["mini_robot_id"]
        unit = None
        if row_id is not None and int(row_id) in by_id and int(row_id) not in used_ids:
            unit = _mini_tactics_unit_from_robot(by_id[int(row_id)], index)
            used_ids.add(int(row_id))
        if unit is None:
            unit = dict(rental_units[index % len(rental_units)])
            unit["name"] = f"レンタル{unit['name']}"
        unit["x"] = int(slot["x"])
        unit["y"] = int(slot["y"])
        if slot.get("ai_type"):
            unit["ai_type"] = slot["ai_type"]
        if slot.get("weapon_type"):
            unit["weapon_type"] = slot["weapon_type"]
            unit.pop("range", None)
            unit.pop("attack_range", None)
        team_units.append(unit)

    while len(team_units) < 3:
        index = len(team_units)
        unit = dict(rental_units[index % len(rental_units)])
        unit["name"] = f"レンタル{unit['name']}"
        team_units.append(unit)

    return team_units[:3]


def _mini_tactics_team_view(db, user_id):
    units = _mini_tactics_team_units_for_user(db, user_id)
    rows = []
    for index, unit in enumerate(units):
        ai_type = _mini_tactics_sanitize_ai_type(unit.get("ai_type")) or _mini_tactics_ai_for_species(unit.get("species_key"))
        weapon_type = _mini_tactics_sanitize_weapon_type(unit.get("weapon_type")) or _mini_tactics_weapon_for_species(
            unit.get("species_key")
        )
        rows.append(
            {
                "slot": index + 1,
                "name": unit["name"],
                "species_key": unit["species_key"],
                "ai_type": ai_type,
                "ai_label": MINI_TACTICS_AI_LABELS.get(ai_type, ai_type),
                "weapon_type": weapon_type,
                "weapon_label": MINI_TACTICS_WEAPON_LABELS.get(weapon_type, weapon_type),
                "role_preview": _mini_tactics_role_preview(ai_type, weapon_type),
                "range": int(unit.get("range") or unit.get("attack_range") or _mini_tactics_weapon_range(weapon_type)),
                "hp": unit["hp"],
                "atk": unit["atk"],
                "def": unit["def"],
                "spd": int(unit.get("spd") or 0),
                "x": int(unit.get("x") or 0),
                "y": int(unit.get("y") or 0),
                "source": unit.get("source") or "owned",
                "mini_robot_id": unit.get("mini_robot_id"),
                "image_url": url_for("static", filename=unit["image_path"]) if unit.get("image_path") else None,
            }
        )
    return rows


def _mini_tactics_placement_rows():
    map_payload = build_initial_map()
    rows = []
    for y, tile_row in enumerate(map_payload.get("tiles") or []):
        row = []
        for x, tile in enumerate(tile_row):
            terrain = str(tile.get("terrain") or "floor")
            row.append(
                {
                    "x": int(x),
                    "y": int(y),
                    "terrain": terrain,
                    "placeable": int(x) <= 2 and terrain != "wall",
                }
            )
        rows.append(row)
    return rows


def _mini_tactics_parse_slot_positions(form):
    positions = []
    map_payload = build_initial_map()
    for index, (default_x, default_y) in enumerate(_mini_tactics_default_slot_positions(), start=1):
        raw_x = (form.get(f"slot_{index}_x") or str(default_x)).strip()
        raw_y = (form.get(f"slot_{index}_y") or str(default_y)).strip()
        if not raw_x.isdigit() or not raw_y.isdigit():
            return None, "配置座標が不正です。"
        x = int(raw_x)
        y = int(raw_y)
        if x < 0 or x > 2 or y < 0 or y > 4:
            return None, "配置は味方側エリアにしてください。"
        if is_wall(map_payload, x, y):
            return None, "壁マスには配置できません。"
        positions.append((x, y))
    if len(set(positions)) != len(positions):
        return None, "同じマスに複数配置できません。"
    return positions, None


