@app.route("/admin/lab/mini-tactics/manual/<int:battle_id>/action", methods=["POST"])
@login_required
def admin_lab_mini_tactics_manual_action(battle_id):
    db = get_db()
    if not _is_admin_user(session["user_id"]):
        return abort(404)
    wants_json = bool(request.is_json or request.headers.get("X-Requested-With") == "fetch")
    row = db.execute("SELECT * FROM mini_tactics_battles WHERE id = ?", (int(battle_id),)).fetchone()
    if not row:
        return abort(404)
    mode = str(row["mode"] if "mode" in row.keys() else "")
    if mode not in {"manual_board", "mini_shogi_4x4", "mini_shogi_3x4"}:
        return abort(404)
    try:
        board_state = json.loads(row["board_state_json"] or "{}")
        map_payload = json.loads(row["map_json"] or "{}")
        action_log = json.loads(row["action_log_json"] or "[]")
    except json.JSONDecodeError:
        return abort(500)
    payload = request.get_json(silent=True) if request.is_json else None
    form_payload = payload if isinstance(payload, dict) else request.form

    def _payload_value(key):
        value = form_payload.get(key) if hasattr(form_payload, "get") else None
        return "" if value is None else str(value)

    def _action_error(message):
        if wants_json:
            return jsonify({"ok": False, "error": str(message), "board_state": board_state}), 400
        flash(str(message), "error")
        return redirect(url_for("admin_lab_mini_tactics_manual", battle_id=int(battle_id)))

    actor_unit_id = (_payload_value("actor_unit_id") or "").strip()
    action_type = (_payload_value("action_type") or "").strip()
    piece_type = (_payload_value("piece_type") or "").strip()
    target_unit_id = (_payload_value("target_unit_id") or "").strip() or None
    move_to = None
    move_x = (_payload_value("to_x") or _payload_value("move_x") or "").strip()
    move_y = (_payload_value("to_y") or _payload_value("move_y") or "").strip()
    if move_x and move_y:
        try:
            move_to = {"x": int(move_x), "y": int(move_y)}
        except ValueError:
            return _action_error("移動先が不正です。")
    if mode in {"mini_shogi_4x4", "mini_shogi_3x4"}:
        if action_type == "move":
            target_unit_id = None
        elif action_type == "attack":
            move_to = None
        elif action_type == "deploy_capsule":
            target_unit_id = None
        elif not action_type:
            action_type = "attack" if target_unit_id else "move"
        if action_type in {"move", "deploy_capsule"} and not move_to:
            return _action_error("移動先が不正です。")
        if action_type == "attack" and not target_unit_id:
            return _action_error("攻撃対象が不正です。")
    if mode in {"mini_shogi_4x4", "mini_shogi_3x4"}:
        next_state, logs, error = apply_manual_action(
            board_state,
            {
                "actor_unit_id": actor_unit_id,
                "action_type": action_type,
                "piece_type": piece_type,
                "move_to": move_to,
                "target_unit_id": target_unit_id,
            },
        )
    else:
        next_state, logs, error = apply_manual_turn_action(
            board_state,
            actor_unit_id,
            move_to=move_to,
            target_unit_id=target_unit_id,
            attack_first=(_payload_value("attack_first") or "") == "1",
            map_payload=map_payload,
        )
    if error:
        return _action_error(error)
    action_log.extend(logs)
    result = next_state.get("result")
    db.execute(
        """
        UPDATE mini_tactics_battles
        SET status = ?,
            board_state_json = ?,
            action_log_json = ?,
            units_json = ?,
            current_turn_side = ?,
            turn_number = ?,
            result = ?
        WHERE id = ?
        """,
        (
            "finished" if result else "manual_active",
            json.dumps(next_state, ensure_ascii=False, separators=(",", ":")),
            json.dumps(action_log, ensure_ascii=False, separators=(",", ":")),
            json.dumps(next_state.get("units") or [], ensure_ascii=False, separators=(",", ":")),
            str(next_state.get("current_turn_side") or "ally"),
            int(next_state.get("turn_number") or 1),
            result,
            int(battle_id),
        ),
    )
    db.commit()
    if wants_json:
        refreshed_units = next_state.get("units") or []
        ally_units = [
            unit
            for unit in refreshed_units
            if unit.get("side") == "ally" and not unit.get("defeated") and unit.get("unit_type") != "core"
        ]
        if mode in {"mini_shogi_4x4", "mini_shogi_3x4"}:
            options_by_unit = {
                str(unit.get("unit_id") or ""): mini_shogi_4x4_action_options(next_state, unit.get("unit_id"))
                for unit in ally_units
            }
            capsule_options = mini_shogi_4x4_capsule_options(next_state, "ally")
            zoc_cells = mini_shogi_4x4_zoc_cells(next_state, "ally")
            threat_cells = mini_shogi_4x4_threat_cells("ally", next_state)
        else:
            options_by_unit = {
                str(unit.get("unit_id") or ""): manual_action_options(next_state, unit.get("unit_id"), map_payload)
                for unit in ally_units
            }
            capsule_options = {}
            zoc_cells = []
            threat_cells = []
        return jsonify(
            {
                "ok": True,
                "board_state": next_state,
                "action_sequence": next_state.get("last_action_sequence") or [],
                "message": logs[-1].get("text") if logs else "",
                "result": result,
                "action_log": action_log,
                "options_by_unit": options_by_unit,
                "capsule_options": capsule_options,
                "zoc_cells": zoc_cells,
                "threat_cells": threat_cells,
            }
        )
    return redirect(url_for("admin_lab_mini_tactics_manual", battle_id=int(battle_id)))


def _render_mini_tactics_manual(
    row,
    *,
    mini_shogi_public=False,
    playable_side="ally",
    can_act=True,
    action_url=None,
    state_url=None,
    invite_url=None,
    is_online_battle=False,
    turn_message=None,
    updated_at=None,
):
    try:
        map_payload = json.loads(row["map_json"] or "{}")
        board_state = json.loads(row["board_state_json"] or "{}")
        action_log = json.loads(row["action_log_json"] or "[]")
    except json.JSONDecodeError:
        return abort(500)
    units_payload = board_state.get("units") or []
    unit_assets = {}
    for unit in units_payload:
        image_path = str(unit.get("image_path") or "").strip()
        if image_path and os.path.exists(_static_abs(image_path)):
            unit_assets[str(unit.get("unit_id") or "")] = url_for("static", filename=image_path, v=APP_VERSION)
    ally_units = [
        unit
        for unit in units_payload
        if unit.get("side") == "ally" and not unit.get("defeated") and unit.get("unit_type") != "core"
    ]
    playable_units = [
        unit
        for unit in units_payload
        if unit.get("side") == playable_side and not unit.get("defeated") and unit.get("unit_type") != "core"
    ]
    mode = str(row["mode"] if "mode" in row.keys() else "")
    if mode in {"mini_shogi_4x4", "mini_shogi_3x4"}:
        options_by_unit = {
            str(unit.get("unit_id") or ""): mini_shogi_4x4_action_options(board_state, unit.get("unit_id"))
            for unit in playable_units
        }
        capsule_options = mini_shogi_4x4_capsule_options(board_state, playable_side)
        zoc_cells = mini_shogi_4x4_zoc_cells(board_state, playable_side)
        threat_cells = mini_shogi_4x4_threat_cells(playable_side, board_state)
    else:
        options_by_unit = {
            str(unit.get("unit_id") or ""): manual_action_options(board_state, unit.get("unit_id"), map_payload)
            for unit in playable_units
        }
        capsule_options = {}
        zoc_cells = []
        threat_cells = []
    client_board_state = board_state
    if mode == "mini_shogi_3x4":
        def _public_board_payload(value):
            if isinstance(value, dict):
                return {
                    str(key): _public_board_payload(item)
                    for key, item in value.items()
                    if key not in {"mode"}
                }
            if isinstance(value, list):
                return [_public_board_payload(item) for item in value]
            return value

        client_board_state = _public_board_payload(board_state)
    return render_template(
        "admin_lab_mini_tactics_manual.html",
        battle=row,
        map_payload=map_payload,
        board_state=board_state,
        client_board_state=client_board_state,
        units_payload=units_payload,
        action_log=action_log,
        unit_assets=unit_assets,
        ally_units=ally_units,
        playable_side=playable_side,
        mini_shogi_public=mini_shogi_public,
        can_act=can_act,
        action_url=action_url,
        state_url=state_url,
        invite_url=invite_url,
        is_online_battle=is_online_battle,
        turn_message=turn_message,
        updated_at=updated_at or (row["updated_at"] if "updated_at" in row.keys() else 0),
        options_by_unit=options_by_unit,
        capsule_options=capsule_options,
        zoc_cells=zoc_cells,
        threat_cells=threat_cells,
        manual_mode=mode,
    )


