@app.route("/dex/enemies")
@login_required
def enemy_dex():
    db = get_db()
    rows = db.execute(
        """
        SELECT d.enemy_key, d.first_seen_at, d.first_defeated_at, d.seen_count, d.defeat_count,
               e.name_ja, e.image_path, e.tier, e.element, e.faction, e.is_boss
        FROM user_enemy_dex d
        LEFT JOIN enemies e ON e.key = d.enemy_key
        WHERE d.user_id = ?
        ORDER BY d.seen_count DESC, d.enemy_key ASC
        """,
        (session["user_id"],),
    ).fetchall()
    cards = []
    for row in rows:
        display_enemy = _resolve_enemy_display_row(db, enemy_key=row["enemy_key"], enemy_name=row["name_ja"])
        display_name = (
            str(display_enemy["name_ja"] or "").strip()
            if display_enemy and str(display_enemy["name_ja"] or "").strip()
            else str(row["name_ja"] or "").strip()
        )
        name_ja = display_name if int(row["defeat_count"] or 0) > 0 else "？？？"
        image_path = display_enemy["image_path"] if display_enemy else row["image_path"]
        image_url = _enemy_static_url(image_path)
        is_boss = (
            bool(int(display_enemy["is_boss"] or 0))
            if display_enemy is not None
            else bool(int(row["is_boss"] or 0))
        )
        cards.append(
            {
                "enemy_key": row["enemy_key"],
                "name_ja": name_ja,
                "seen_count": int(row["seen_count"] or 0),
                "defeat_count": int(row["defeat_count"] or 0),
                "is_boss": is_boss,
                "image_url": image_url,
            }
        )
    return render_template("enemy_dex.html", cards=cards)


